STUDY.stbbEn = {"exsolutions": [{"cls": "iii", "unit": 1, "title": "Apostrophe ('s)", "display": "Apostrophe ('s)", "reading": "My English Book 3, Unit 1, Language Practice", "lesson": [{"t": "h", "x": "Apostrophe ('s)"}, {"t": "p", "x": "We use 's to show that something belongs to somebody. It is a short way of saying 'of'."}, {"t": "def", "x": "The apostrophe ('s) shows possession. It tells us who owns a thing. 'The ball of Ali' is the same as 'Ali's ball'."}, {"t": "h", "x": "Rule 1. Add 's to a person's name"}, {"t": "rule", "x": "To show that a thing belongs to a person, add 's to the person's name."}, {"t": "ex", "x": "Ali's bag. Sana's book. The teacher's pen."}, {"t": "h", "x": "Rule 2. 's comes after the owner"}, {"t": "rule", "x": "The 's comes after the name of the owner, and then comes the thing that is owned."}, {"t": "ex", "x": "This is Ahmed's bat. That is Mary's doll. This is the cat's milk."}, {"t": "h", "x": "Rule 3. Do not use 's for a thing that is not owned"}, {"t": "rule", "x": "Use 's only when one person or animal owns the thing. Do not add 's to every word."}, {"t": "ex", "x": "The colour of the parrot is green. The parrot's colour is green. (Both are correct.)"}, {"t": "rl", "x": "This is Bilal's school bag. That is Ayesha's lunch box. The dog's tail is long. My father's car is white."}, {"t": "rl", "x": "At home, my mother's cooking is very tasty. My brother's cricket bat is new. The baby's shoes are small."}, {"t": "rl", "x": "In the market, the shopkeeper's shop is near our school. The farmer's mangoes are sweet. The baker's bread is fresh."}, {"t": "note", "x": "Remember: 's is not the same as the plural s. 'Boys' means more than one boy. 'Boy's' means something that belongs to one boy."}], "sections": [{"num": "1", "name": "Rewrite the sentences using 's for the underlined words", "exercises": [{"label": "Rewrite the sentences using 's for the underlined words", "items": [{"q": "Example: The colour of a parrot is green.", "a": "The parrot's colour is green. (Example given in the book.)"}, {"q": "1. The trunk of an elephant is long.", "a": "The elephant's trunk is long."}, {"q": "2. The roar of a lion is loud.", "a": "The lion's roar is loud."}, {"q": "3. The neck of a giraffe is long.", "a": "The giraffe's neck is long."}, {"q": "4. The home of a bird is a nest.", "a": "The bird's home is a nest."}]}]}, {"num": "2", "name": "Answer the questions using the words from the box", "exercises": [{"label": "Answer the questions using the words from the box", "items": [{"q": "Example: Whose skipping rope is it? It is ___ skipping rope.", "a": "It is Salma's skipping rope. (Example given in the book.)"}, {"q": "1. Whose football is it? It is ___ football.", "a": "It is Farid's football."}, {"q": "2. Whose purse is it? It is ___ purse.", "a": "It is mother's purse."}, {"q": "3. Whose camera is it? It is ___ camera.", "a": "It is father's camera."}, {"q": "4. Whose car is it? It is the ___ car.", "a": "It is the family's car."}, {"q": "5. Whose radio is it? It is the ___ radio.", "a": "It is the family's radio."}]}]}], "words": [{"w": "apostrophe", "sd": "اعراب", "syn": "the sign ' used in writing"}, {"w": "possession", "sd": "ملڪيت", "syn": "owning something"}, {"w": "owner", "sd": "مالڪ", "syn": "the person who owns a thing"}]}, {"cls": "iii", "unit": 2, "title": "Pronouns and Possessive Pronouns", "display": "Pronouns and Possessive Pronouns", "reading": "My English Book 3, Unit 1, Language Practice", "lesson": [{"t": "h", "x": "Pronouns and Possessive Pronouns"}, {"t": "p", "x": "A pronoun is a word we use in place of a noun. We use pronouns so that we do not say the same name again and again."}, {"t": "def", "x": "A pronoun is a word used in place of a noun. I, you, he, she, it, we, they are pronouns."}, {"t": "h", "x": "Rule 1. Use a pronoun in place of a name"}, {"t": "rule", "x": "When we have already named a person, we can use a pronoun for that person in the next sentence."}, {"t": "ex", "x": "Ali is my friend. He is a good boy. Sana is my sister. She is in Class III."}, {"t": "h", "x": "Rule 2. Possessive pronouns show ownership"}, {"t": "rule", "x": "A possessive pronoun shows that something belongs to somebody. Mine, yours, his, hers, ours, theirs are possessive pronouns."}, {"t": "ex", "x": "This book is mine. That bag is yours. The bat is his. The doll is hers. The house is ours. The toys are theirs."}, {"t": "h", "x": "Rule 3. Match the pronoun with the person"}, {"t": "rule", "x": "Use 'his' for a boy or a man, 'her' or 'hers' for a girl or a woman, 'its' for a thing or an animal, 'their' or 'theirs' for many people."}, {"t": "ex", "x": "Ahmed lost his pen. Ayesha lost her book. The dog wagged its tail. The boys lost their ball."}, {"t": "rl", "x": "This is my bat. The bat is mine. That is your book. The book is yours. Ali has a bag. The bag is his."}, {"t": "rl", "x": "At school, the teacher said, 'This pencil is mine.' At home, my sister said, 'That doll is mine, not yours.'"}, {"t": "rl", "x": "In the market, I bought a kite. The kite is mine. My friend bought a ball. The ball is his."}, {"t": "note", "x": "Do not write an apostrophe in possessive pronouns. Write 'its', 'hers', 'theirs' — not 'it's', 'her's' or 'their's'."}], "sections": [{"num": "1", "name": "I. Match the pronouns with their possessive forms", "exercises": [{"label": "I. Match the pronouns with their possessive forms", "items": [{"q": "I", "a": "Mine. (Example given in the book.)"}, {"q": "You", "a": "Yours."}, {"q": "He", "a": "His."}, {"q": "She", "a": "Her."}, {"q": "It", "a": "Its."}, {"q": "They", "a": "Theirs."}]}]}, {"num": "2", "name": "II. Complete the sentences by filling mine, yours, ours, theirs, theirs", "exercises": [{"label": "II. Complete the sentences by filling mine, yours, ours, theirs, theirs", "items": [{"q": "Example: The ball is Farid's. The ball is his.", "a": "The ball is his. (Example given in the book.)"}, {"q": "1. It's your hat. It's ___.", "a": "It's yours."}, {"q": "2. It's my car. It's ___.", "a": "It's mine."}, {"q": "3. It's our house. It's ___.", "a": "It's ours."}, {"q": "4. They're his trousers. They're ___.", "a": "They're his."}, {"q": "5. It's their anniversary. It's ___.", "a": "It's theirs."}, {"q": "6. They're your CD's; They're ___.", "a": "They're yours."}]}]}, {"num": "3", "name": "III. Complete the dialogue. Fill in the blanks with possessive pronoun", "exercises": [{"label": "III. Complete the dialogue. Fill in the blanks with possessive pronoun", "items": [{"q": "Amna: Let me see. I think it is ___ (Samina's).", "a": "Hers."}, {"q": "Ahmed: Is it not ___?", "a": "Yours."}, {"q": "Amna: No. It's not ___. But I gave this to Javeria.", "a": "Mine."}, {"q": "Ahmed: Oh, yes! It is ___.", "a": "Hers. (Javeria's.)"}, {"q": "Javeria: Oh! Wallet is ___. Please give me.", "a": "Mine."}]}]}], "words": [{"w": "pronoun", "sd": "ضمير", "syn": "a word used in place of a noun"}, {"w": "possessive pronoun", "sd": "ملڪيتي ضمير", "syn": "a pronoun that shows ownership"}, {"w": "mine", "sd": "منھنجو", "syn": "belonging to me"}]}, {"cls": "iii", "unit": 3, "title": "Imperative Sentences", "display": "Imperative Sentences", "reading": "My English Book 3, Unit 2, Language Practice", "lesson": [{"t": "h", "x": "Imperative Sentences"}, {"t": "p", "x": "An imperative sentence tells somebody to do something, or tells somebody not to do something. It gives an order, a request or advice."}, {"t": "def", "x": "An imperative sentence gives an order, a request, or advice. It usually begins with a verb."}, {"t": "h", "x": "Rule 1. An imperative sentence begins with a verb"}, {"t": "rule", "x": "An imperative sentence begins with the verb. The subject 'you' is understood and is not written."}, {"t": "ex", "x": "Open the door. Sit down. Brush your teeth. Wash your hands."}, {"t": "h", "x": "Rule 2. Use 'Do not' or 'Don't' for a negative order"}, {"t": "rule", "x": "To tell somebody not to do something, begin with 'Do not' or 'Don't' and then the verb."}, {"t": "ex", "x": "Do not throw rubbish on the ground. Don't run in the classroom. Do not waste water."}, {"t": "h", "x": "Rule 3. Use 'please' for a polite request"}, {"t": "rule", "x": "Add 'please' to make an order into a polite request."}, {"t": "ex", "x": "Please sit down. Please give me your book. Please open the window."}, {"t": "rl", "x": "At school, the teacher says, 'Open your books.' At home, my mother says, 'Wash your hands before lunch.'"}, {"t": "rl", "x": "In the market, my father says, 'Hold my hand.' On the cricket ground, the captain says, 'Catch the ball!'"}, {"t": "rl", "x": "My grandmother says, 'Please help your sister.' My friend says, 'Do not shout in the class.'"}, {"t": "note", "x": "An imperative sentence ends with a full stop, or with a mark of exclamation (!) if the order is strong."}], "sections": [{"num": "1", "name": "I. Write three things your parents generally tell you to do", "exercises": [{"label": "I. Write three things your parents generally tell you to do", "items": [{"q": "My parents tell me to do the following: Example: Brush your teeth after meals. 1. ___ 2. ___ 3. ___", "a": "1. Wash your hands before meals. 2. Eat fresh food. 3. Drink clean water. (Model answer.)"}]}]}, {"num": "2", "name": "II. Write three things your parents generally tell you not to do", "exercises": [{"label": "II. Write three things your parents generally tell you not to do", "items": [{"q": "My parents tell me: Example: Do not throw rubbish on the ground. 1. ___ 2. ___ 3. ___", "a": "1. Do not waste food. 2. Do not eat between meals. 3. Do not play in dirty water. (Model answer.)"}]}]}], "words": [{"w": "imperative sentence", "sd": "حڪم وارو جملو", "syn": "a sentence that gives an order or advice"}, {"w": "order", "sd": "حڪم", "syn": "telling somebody to do something"}, {"w": "request", "sd": "گذراش", "syn": "asking somebody politely to do something"}]}, {"cls": "iii", "unit": 4, "title": "Articles A and An and Singular and Plural Nouns", "display": "Articles A and An and Singular and Plural Nouns", "reading": "My English Book 3, Unit 2, Language Practice", "lesson": [{"t": "h", "x": "Articles A and An and Singular and Plural Nouns"}, {"t": "p", "x": "In this lesson we learn two things: when to use 'a' and 'an', and how to make a noun plural."}, {"t": "def", "x": "A and an are articles. We use them before a singular noun. A noun is singular when it names one thing, and plural when it names more than one thing."}, {"t": "h", "x": "Rule 1. Use 'a' before a consonant sound"}, {"t": "rule", "x": "Use 'a' before a word that begins with a consonant sound."}, {"t": "ex", "x": "a book, a ball, a pen, a school, a dog, a potato."}, {"t": "h", "x": "Rule 2. Use 'an' before a vowel sound"}, {"t": "rule", "x": "Use 'an' before a word that begins with a vowel sound (a, e, i, o, u)."}, {"t": "ex", "x": "an apple, an egg, an eye, an elephant, an orange, an umbrella."}, {"t": "h", "x": "Rule 3. Add 's' to make most plurals"}, {"t": "rule", "x": "To name more than one thing, add 's' to most nouns."}, {"t": "ex", "x": "book — books, pen — pens, girl — girls, dog — dogs."}, {"t": "h", "x": "Rule 4. Add 'es' after s, x, ch or sh"}, {"t": "rule", "x": "For nouns that end with s, x, ch or sh, add 'es' to make the plural."}, {"t": "ex", "x": "glass — glasses, box — boxes, bush — bushes, watch — watches, bunch — bunches."}, {"t": "rl", "x": "At school, I have a pen and an eraser. I have two pens and three books in my bag."}, {"t": "rl", "x": "At home, my mother bought an apple and a mango. She bought two apples and three mangoes from the market."}, {"t": "rl", "x": "On the cricket ground, I saw a bat and a ball. The boys had two bats and five balls."}, {"t": "note", "x": "Some nouns change in a special way: man — men, woman — women, child — children, foot — feet, tooth — teeth."}], "sections": [{"num": "1", "name": "Using A and An", "exercises": [{"label": "Using A and An", "items": [{"q": "1. ___ potato has ___ eye but it cannot see with it.", "a": "A potato has an eye but it cannot see with it."}, {"q": "2. Jamil wanted ___ apple.", "a": "Jamil wanted an apple."}, {"q": "3. ___ elephant can eat ___ peanut, but it will still be hungry.", "a": "An elephant can eat a peanut, but it will still be hungry."}, {"q": "4. I saw ___ egg in the nest. ___ little bird came out of it.", "a": "I saw an egg in the nest. A little bird came out of it."}]}]}, {"num": "2", "name": "Items: Singular and Plural Nouns", "exercises": [{"label": "Items: Singular and Plural Nouns", "items": [{"q": "For nouns that end with s, x, ch or sh, add [es] to name more than one. Give the plurals of: glass, box, bush, bunch.", "a": "[[T]]One|More than one;;glass|glasses;;box|boxes;;bush|bushes;;bunch|bunches[[/T]]"}, {"q": "1. I had one ___ of milk and two ___ of juice. (glass/glasses)", "a": "I had one glass of milk and two glasses of juice."}, {"q": "2. There were three ___ on the table but one ___ fell down. (box/boxes)", "a": "There were three boxes on the table but one box fell down."}, {"q": "3. All the paint ___ are in one box. (brush/brushes)", "a": "All the paint brushes are in one box."}, {"q": "4. All the ___ are sweet. (peach/peaches)", "a": "All the peaches are sweet."}, {"q": "5. There is one ___ on your shirt. (patch/patches)", "a": "There is one patch on your shirt."}]}]}], "words": [{"w": "article", "sd": "حرف تنڪير", "syn": "a word like a or an used before a noun"}, {"w": "singular", "sd": "واحد", "syn": "naming one thing"}, {"w": "plural", "sd": "جمع", "syn": "naming more than one thing"}, {"w": "vowel", "sd": "سُر", "syn": "the letters a, e, i, o, u"}]}, {"cls": "iii", "unit": 5, "title": "Noun Gender and Proper Nouns", "display": "Noun Gender and Proper Nouns", "reading": "My English Book 3, Unit 3, Language Practice", "lesson": [{"t": "h", "x": "Noun Gender and Proper Nouns"}, {"t": "p", "x": "Nouns have gender: masculine for males and feminine for females. Some nouns have special names. Those are proper nouns."}, {"t": "def", "x": "Gender tells us if a noun is masculine (male) or feminine (female). A proper noun is the special name of a person, place or thing, and it begins with a capital letter."}, {"t": "h", "x": "Rule 1. Masculine and feminine nouns go in pairs"}, {"t": "rule", "x": "Many nouns have a masculine form and a feminine form."}, {"t": "ex", "x": "man — woman, boy — girl, father — mother, brother — sister, son — daughter, uncle — aunt, cock — hen, bull — cow, horse — mare, lion — lioness, tiger — tigress."}, {"t": "h", "x": "Rule 2. A proper noun begins with a capital letter"}, {"t": "rule", "x": "The special name of a person, a place, a day or a month is a proper noun. Always begin it with a capital letter."}, {"t": "ex", "x": "Ali, Sana, Karachi, Lahore, Pakistan, Friday, November, Eid-ul-Fitr, Christmas."}, {"t": "h", "x": "Rule 3. A common noun does not begin with a capital letter"}, {"t": "rule", "x": "A common noun names a thing in general, like boy, city, school, book. It does not begin with a capital letter unless it starts a sentence."}, {"t": "ex", "x": "boy, girl, city, school, book, dog — common nouns. Ali, Karachi, Friday — proper nouns."}, {"t": "rl", "x": "At school, my teacher is a woman and my friend Ahmed is a boy. My school is in Karachi."}, {"t": "rl", "x": "At home, my father and mother live with my grandfather and grandmother. My sister's name is Ayesha."}, {"t": "rl", "x": "In the market, the farmer sells milk from his cow. The lion in the zoo is the king of animals, and the lioness is with him."}, {"t": "note", "x": "The names of days, months and holidays are proper nouns too: Monday, January, Eid, Diwali."}], "sections": [{"num": "1", "name": "1. Match column A with column B", "exercises": [{"label": "1. Match column A with column B", "items": [{"q": "man", "a": "Woman."}, {"q": "father", "a": "Mother."}, {"q": "boy", "a": "Girl."}, {"q": "brother", "a": "Sister."}, {"q": "son", "a": "Daughter."}, {"q": "uncle", "a": "Aunt."}, {"q": "grandfather", "a": "Grandmother."}, {"q": "cock", "a": "Hen."}, {"q": "bull", "a": "Cow."}, {"q": "ram", "a": "Sheep."}, {"q": "horse", "a": "Mare."}, {"q": "lion", "a": "Lioness."}, {"q": "tiger", "a": "Tigress."}, {"q": "peacock", "a": "Peahen."}]}]}, {"num": "2", "name": "2. Underline the male and female nouns in the sentences below and write them in the correct column", "exercises": [{"label": "2. Underline the male and female nouns in the sentences below and write them in the correct column", "items": [{"q": "1. The boy and girl are going to school.", "a": "Male: boy. Female: girl."}, {"q": "2. Her father is helping her mother in kitchen.", "a": "Male: father. Female: mother."}, {"q": "3. My grandfather is ninety years old.", "a": "Male: grandfather. Female: —"}, {"q": "4. My grandmother tells us a story everyday.", "a": "Male: — Female: grandmother."}, {"q": "5. The hen and the cock take care of their chicks.", "a": "Male: cock. Female: hen."}, {"q": "6. The farmer was milking a cow.", "a": "Male: farmer. Female: cow."}, {"q": "7. Uncle showed us a tiger at the zoo.", "a": "Male: uncle, tiger. Female: —"}, {"q": "8. The lion and the lioness were in a cage.", "a": "Male: lion. Female: lioness."}, {"q": "9. A ram has horns.", "a": "Male: ram. Female: —"}]}]}, {"num": "3", "name": "4. Choose the words from the box below to complete the sentences. Box: Divali, Friday, November", "exercises": [{"label": "4. Choose the words from the box below to complete the sentences. Box: Divali, Friday, November", "items": [{"q": "1. Hindus have a holiday called ___.", "a": "Hindus have a holiday called Divali."}, {"q": "2. It is celebrated in ___.", "a": "It is celebrated in November."}, {"q": "3. The last ___ of Ramzan is called Juma-tul-Wida.", "a": "The last Friday of Ramzan is called Juma-tul-Wida."}]}]}], "words": [{"w": "gender", "sd": "جنس", "syn": "whether a noun is masculine or feminine"}, {"w": "masculine", "sd": "مذڪر", "syn": "male"}, {"w": "feminine", "sd": "مؤنث", "syn": "female"}, {"w": "proper noun", "sd": "اسم خاص", "syn": "the special name of a person, place or thing"}, {"w": "common noun", "sd": "اسم عام", "syn": "a general name, not a special name"}]}, {"cls": "iii", "unit": 6, "title": "Countable and Uncountable Nouns", "display": "Countable and Uncountable Nouns", "reading": "My English Book 3, Unit 3, Language Practice", "lesson": [{"t": "h", "x": "Countable and Uncountable Nouns"}, {"t": "p", "x": "Some nouns can be counted. Some nouns cannot be counted. We must know the difference."}, {"t": "def", "x": "A countable noun is a noun we can count: one book, two books. An uncountable noun is a noun we cannot count: water, milk, rice."}, {"t": "h", "x": "Rule 1. Countable nouns have a plural"}, {"t": "rule", "x": "Countable nouns can be singular or plural. We can say one pen and two pens."}, {"t": "ex", "x": "book — books, glass — glasses, boy — boys, mango — mangoes."}, {"t": "h", "x": "Rule 2. Uncountable nouns have no plural"}, {"t": "rule", "x": "Uncountable nouns are things like water, milk, sugar, rice, oil and sand. We do not add 's' to them, and we do not say 'two waters'."}, {"t": "ex", "x": "water, milk, rice, sugar, oil, salt, tea, flour."}, {"t": "h", "x": "Rule 3. Use 'some' and 'much' with uncountable nouns"}, {"t": "rule", "x": "We say 'some water' and 'much water'. We do not count them with numbers."}, {"t": "ex", "x": "I want some milk. There is much water in the jug. Give me some rice."}, {"t": "rl", "x": "At school, I have three books and two pens. They are countable. My water bottle has water in it. Water is uncountable."}, {"t": "rl", "x": "At home, my mother cooks rice for us. Rice is uncountable. She gives me an apple. Apples are countable."}, {"t": "rl", "x": "In the market, the shopkeeper sells sugar and oil. Sugar and oil are uncountable. He also sells mangoes. Mangoes are countable."}, {"t": "note", "x": "Some nouns can be both: 'glass' as a thing to drink from is countable, but 'glass' as the material of a window is uncountable."}], "sections": [{"num": "1", "name": "Countable and Uncountable nouns", "exercises": [{"label": "Countable and Uncountable nouns", "items": [{"q": "Which of the nouns given in a box are countable? Write them in the correct column in the chart below: books, glass, ice, pencils, bags, milk, bottles, music, songs, wood, milk, desk.", "a": "[[T]]Countable Nouns|Uncountable Nouns;;books|ice;;glass|milk;;pencils|music;;bags|wood;;bottles|;;songs|;;desk|[[/T]]"}]}]}, {"num": "2", "name": "Plural nouns", "exercises": [{"label": "Plural nouns", "items": [{"q": "The words in bold letters indicate one or more than one nouns. Put them in the correct box. People are enjoying themselves in the park. One person is reading. Some men and women are sitting in the grass. A man is selling ice-cream. A woman is looking at the children on the swing. A child is playing with a ball.", "a": "[[T]]One|More than one;;person|people;;man|men;;woman|women;;child|children[[/T]]"}]}]}, {"num": "3", "name": "2. Match singular nouns with plural nouns to make pairs", "exercises": [{"label": "2. Match singular nouns with plural nouns to make pairs", "items": [{"q": "foot", "a": "Feet."}, {"q": "man", "a": "Men."}, {"q": "child", "a": "Children."}, {"q": "goose", "a": "Geese."}, {"q": "woman", "a": "Women."}]}]}], "words": [{"w": "countable noun", "sd": "ڳڻپ جوڳو اسم", "syn": "a noun we can count"}, {"w": "uncountable noun", "sd": "اڻڳڻپ جوڳو اسم", "syn": "a noun we cannot count"}]}, {"cls": "iii", "unit": 7, "title": "Simple Present Tense", "display": "Simple Present Tense", "reading": "My English Book 3, Unit 5, Language Practice", "lesson": [{"t": "h", "x": "Simple Present Tense"}, {"t": "p", "x": "The simple present tense tells us about things that happen every day, things that happen again and again, and things that are always true."}, {"t": "def", "x": "The simple present tense is used for daily habits, routines, and things that are always true."}, {"t": "h", "x": "Rule 1. Use the simple present for daily routines"}, {"t": "rule", "x": "Use the simple present tense for things we do every day."}, {"t": "ex", "x": "I get up early in the morning. My father goes to work. My mother cooks food. We go to school."}, {"t": "h", "x": "Rule 2. Add 's' or 'es' with he, she and it"}, {"t": "rule", "x": "With he, she and it, add 's' or 'es' to the verb."}, {"t": "ex", "x": "He plays cricket. She reads a book. It rains in July. Ali goes to school. Sana watches TV."}, {"t": "h", "x": "Rule 3. Use the simple present for things that are always true"}, {"t": "rule", "x": "Use the simple present tense for facts that are always true."}, {"t": "ex", "x": "The sun rises in the east. Birds fly. Fish swim in water. The earth moves round the sun."}, {"t": "rl", "x": "Every morning, I get up early, brush my teeth and go to school. My father buys bread from the market."}, {"t": "rl", "x": "At home, my mother cooks rice every day. My sister helps her. My brother plays cricket in the evening."}, {"t": "rl", "x": "In our village, the farmers grow wheat. The sun shines in the day. The stars shine at night."}, {"t": "note", "x": "Do not add 's' with I, we, you and they: 'I play', 'We play', 'You play', 'They play' — but 'He plays', 'She plays', 'It plays'."}], "sections": [{"num": "1", "name": "Activity I: Write down two things Mother, Kashif, and Marya do every morning", "exercises": [{"label": "Activity I: Write down two things Mother, Kashif, and Marya do every morning", "items": [{"q": "Father: Example: 1. Father gets up early in the morning. 2. He buys things to eat.", "a": "Father gets up early in the morning. He buys things to eat. (Example given in the book.)"}, {"q": "Mother: 1. ___ 2. ___", "a": "1. Mother gets up early in the morning. 2. Mother makes breakfast."}, {"q": "Kashif and Marya: 1. ___ 2. ___", "a": "1. Kashif and Marya wash up and say their prayers. 2. Kashif and Marya get ready for school."}]}]}, {"num": "2", "name": "Activity II: Some things happen all the time, everywhere. Join with a line and make correct sentences", "exercises": [{"label": "Activity II: Some things happen all the time, everywhere. Join with a line and make correct sentences", "items": [{"q": "Birds — ___", "a": "Birds fly."}, {"q": "Fish — ___", "a": "Fish swim."}, {"q": "The wind — ___", "a": "The wind blows."}, {"q": "The sun — ___", "a": "The sun shines."}, {"q": "A dog — ___", "a": "A dog barks."}]}]}, {"num": "3", "name": "Activity III: Write some routine action sentences", "exercises": [{"label": "Activity III: Write some routine action sentences", "items": [{"q": "Example: Birds fly. 1. ___ 2. ___ 3. ___ 4. ___ 5. ___", "a": "1. Aeroplanes fly. 2. Fish swim. 3. The sun shines. 4. The wind blows. 5. A dog barks. (Model answer.)"}]}]}], "words": [{"w": "tense", "sd": "زمان", "syn": "the form of the verb that shows time"}, {"w": "simple present tense", "sd": "زمان حال سادو", "syn": "the tense for daily habits and true facts"}, {"w": "routine", "sd": "روز جو ڪم", "syn": "things we do every day"}]}, {"cls": "iii", "unit": 8, "title": "Was, Were and Past Tense Verbs", "display": "Was, Were and Past Tense Verbs", "reading": "My English Book 3, Unit 6, Language Practice", "lesson": [{"t": "h", "x": "Was, Were and Past Tense Verbs"}, {"t": "p", "x": "The past tense tells us about things that happened before now — yesterday, last week, last year. 'Was' and 'were' are past forms of 'is', 'am' and 'are'."}, {"t": "def", "x": "The past tense is used for actions that are finished. Was and were are the past forms of is, am and are."}, {"t": "h", "x": "Rule 1. Use 'was' with I, he, she and it"}, {"t": "rule", "x": "Use 'was' with I, he, she and it."}, {"t": "ex", "x": "I was at school yesterday. He was happy. She was in the park. It was cold."}, {"t": "h", "x": "Rule 2. Use 'were' with you, we and they"}, {"t": "rule", "x": "Use 'were' with you, we and they."}, {"t": "ex", "x": "You were late. We were at home. They were in the garden. The boys were happy."}, {"t": "h", "x": "Rule 3. Add 'ed' to most verbs for the past"}, {"t": "rule", "x": "For most verbs, add 'ed' to make the past tense."}, {"t": "ex", "x": "play — played, laugh — laughed, finish — finished, look — looked, jump — jumped."}, {"t": "h", "x": "Rule 4. Some verbs change in a special way"}, {"t": "rule", "x": "Some verbs do not take 'ed'. They change in a special way: go — went, drink — drank, see — saw, eat — ate."}, {"t": "ex", "x": "go — went, come — came, drink — drank, eat — ate, see — saw, take — took."}, {"t": "rl", "x": "Yesterday, I was in the park. My friends were with me. We played cricket and laughed a lot."}, {"t": "rl", "x": "At home, my mother cooked biryani yesterday. My father went to the market. We ate together."}, {"t": "rl", "x": "Last Sunday, we went to my uncle's house. The children played in the garden. It was a happy day."}, {"t": "note", "x": "Use 'was' for one person or thing and 'were' for more than one: 'She was ill' but 'They were ill'."}], "sections": [{"num": "1", "name": "2. Complete the sentences using was/were", "exercises": [{"label": "2. Complete the sentences using was/were", "items": [{"q": "1. I ___ at school yesterday.", "a": "I was at school yesterday."}, {"q": "2. They ___ at the park yesterday.", "a": "They were at the park yesterday."}, {"q": "3. It ___ a very hot day.", "a": "It was a very hot day."}, {"q": "4. ___ you at home yesterday? Yes, I ___.", "a": "Were you at home yesterday? Yes, I was."}, {"q": "5. ___ you sleeping yesterday? No, I ___.", "a": "Were you sleeping yesterday? No, I wasn't."}, {"q": "6. ___ the children playing in the park? Yes, they ___.", "a": "Were the children playing in the park? Yes, they were."}]}]}, {"num": "2", "name": "More Verbs: Read the following sentences and underline the past form of the verbs", "exercises": [{"label": "More Verbs: Read the following sentences and underline the past form of the verbs", "items": [{"q": "1. They planned a picnic for Friday.", "a": "Planned. (Past form of plan.)"}, {"q": "2. Father purchased some chairs for the picnic.", "a": "Purchased. (Past form of purchase.)"}, {"q": "3. Her father looked for some tools.", "a": "Looked. (Past form of look.)"}, {"q": "4. He paid for the tools.", "a": "Paid. (Past form of pay.)"}, {"q": "5. He counted the money.", "a": "Counted. (Past form of count.)"}]}]}, {"num": "3", "name": "II. a. Write the past forms of the following verbs", "exercises": [{"label": "II. a. Write the past forms of the following verbs", "items": [{"q": "Example: Look — Looked. (Example given in the book.)", "a": "Look — Looked. (Example given in the book.)"}, {"q": "b. Write the past forms of the following verbs: dance, bathe, intend, struggle, detect, convey, scold, paste, blame, roar.", "a": "[[T]]Present|Past;;dance|danced;;bathe|bathed;;intend|intended;;struggle|struggled;;detect|detected;;convey|conveyed;;scold|scolded;;paste|pasted;;blame|blamed;;roar|roared[[/T]]"}]}]}], "words": [{"w": "past tense", "sd": "زمان ماضي", "syn": "the tense for finished actions"}, {"w": "was", "sd": "هو (ماضي)", "syn": "past form of is and am"}, {"w": "were", "sd": "هئا (ماضي)", "syn": "past form of are"}]}, {"cls": "iv", "unit": 1, "title": "Nouns: Proper and Common", "display": "Nouns: Proper and Common", "reading": "My English Book 4, Unit 1, Grammar", "lesson": [{"t": "h", "x": "Nouns: Proper and Common"}, {"t": "p", "x": "A noun is a naming word. It names a person, a place, an animal or a thing. Nouns are of two kinds: proper nouns and common nouns."}, {"t": "def", "x": "A noun is a word that names a person, place, animal or thing. A proper noun is a special name. A common noun is a general name."}, {"t": "h", "x": "Rule 1. A proper noun is a special name"}, {"t": "rule", "x": "A proper noun is the special name of a person, a place or a thing. It always begins with a capital letter."}, {"t": "ex", "x": "Ali, Sana, Karachi, Lahore, Pakistan, the River Indus, Mount Everest, Friday."}, {"t": "h", "x": "Rule 2. A common noun is a general name"}, {"t": "rule", "x": "A common noun names a person, place or thing in general. It does not begin with a capital letter."}, {"t": "ex", "x": "boy, girl, city, river, school, book, dog, teacher, mountain."}, {"t": "h", "x": "Rule 3. Every proper noun has a common noun"}, {"t": "rule", "x": "A proper noun belongs to a common noun family. Karachi is a city. Ali is a boy. The Indus is a river."}, {"t": "ex", "x": "Karachi — city. Ali — boy. Sana — girl. Lahore — city. The Indus — river."}, {"t": "rl", "x": "At school, my teacher's name is Miss Fatima. Miss Fatima is a teacher. Our school is in Haseeja Mahar."}, {"t": "rl", "x": "At home, my brother Ahmed is a boy. My sister Ayesha is a girl. We live in Pakistan."}, {"t": "rl", "x": "In the market, I saw a dog and a cat. The dog's name is Tommy. Tommy is a dog."}, {"t": "note", "x": "The names of days and months are proper nouns too: Monday, January, Ramadan."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Read the text “Friends” given below. Underline the proper nouns and circle the common nouns in the story.", "a": "Proper Nouns: Shiharu, Japan, Sarah, Turkey, Tokyo, Istanbul, Iqbal, Tahir. Common Nouns: girl, country, city, boy."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "From the text above, write down the proper nouns in the column below. Then write down their common nouns in the next column. Two have been filled as examples. Do not repeat the same name.", "a": "[[T]]Proper Noun|Common Noun;;Shiharu|girl;;Japan|country;;Sarah|girl;;Turkey|country;;Tokyo|city;;Istanbul|city;;Iqbal|boy;;Tahir|boy[[/T]] (The two examples filled in the book are Istanbul — city and Shiharu — girl.)"}]}]}], "words": [{"w": "noun", "sd": "اسم", "syn": "a word that names a person, place, animal or thing"}, {"w": "proper noun", "sd": "اسم خاص", "syn": "the special name of a person, place or thing"}, {"w": "common noun", "sd": "اسم عام", "syn": "a general name, not a special name"}]}, {"cls": "iv", "unit": 2, "title": "Pronouns and Linking Words", "display": "Pronouns and Linking Words", "reading": "My English Book 4, Unit 1, Grammar", "lesson": [{"t": "h", "x": "Pronouns and Linking Words"}, {"t": "p", "x": "A pronoun stands in place of a noun. Linking words join two sentences or two ideas."}, {"t": "def", "x": "A pronoun is a word used in place of a noun. Linking words like and, but, because and so join sentences."}, {"t": "h", "x": "Rule 1. Use a pronoun in place of a noun"}, {"t": "rule", "x": "Use he for a boy or a man, she for a girl or a woman, it for a thing or an animal, they for many people or things."}, {"t": "ex", "x": "Ahmed is my friend. He is kind. Sana is my sister. She is tall. This is a book. It is new. The boys are playing. They are happy."}, {"t": "h", "x": "Rule 2. 'And' joins two same ideas"}, {"t": "rule", "x": "Use 'and' to join two things that go together."}, {"t": "ex", "x": "I like mangoes and oranges. Ali is tall and strong. I bought a pen and a book."}, {"t": "h", "x": "Rule 3. 'But' joins two different ideas"}, {"t": "rule", "x": "Use 'but' to join two ideas that are different."}, {"t": "ex", "x": "I like mangoes but I do not like oranges. He is rich but he is not happy. The pen is small but it writes well."}, {"t": "h", "x": "Rule 4. 'Because' and 'so' show a reason"}, {"t": "rule", "x": "Use 'because' to give a reason and 'so' to show the result."}, {"t": "ex", "x": "I stayed at home because I was ill. I was ill, so I stayed at home. He ran fast because he was late."}, {"t": "rl", "x": "At school, Ali and Ahmed play together. Ali is fast but Ahmed is strong. Ahmed was late, so he ran to school."}, {"t": "rl", "x": "At home, my mother cooks rice and curry. I like rice because it is tasty. My sister is small but she is clever."}, {"t": "rl", "x": "In the market, my father bought apples and bananas. The apples were sweet but the bananas were not ripe."}, {"t": "note", "x": "Choose the pronoun that matches the noun: a boy takes 'he', a girl takes 'she', many boys take 'they'."}], "sections": [{"num": "1", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Pronouns are words that are used in place of nouns. Match the word or group of words on the left with the matching pronoun on the right: 1. Pasha and I", "a": "c. we"}, {"q": "Match the word or group of words on the left with the matching pronoun on the right: 2. Jamila", "a": "e. she"}, {"q": "Match the word or group of words on the left with the matching pronoun on the right: 3. Fakhir", "a": "a. he"}, {"q": "Match the word or group of words on the left with the matching pronoun on the right: 4. the big truck", "a": "b. it"}, {"q": "Match the word or group of words on the left with the matching pronoun on the right: 5. Khadija and Maryam", "a": "d. they"}]}]}, {"num": "2", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "From the list of pronouns given below, pick one that can replace the underlined word(s) in each sentence. (You can use one pronoun only once.) She, Them, It, They, Us, Him, We, Her, He — 1. Jamil likes reading books.", "a": "He"}, {"q": "Pick one pronoun that can replace the underlined word(s): 2. Jamil and Kamal enjoy playing cricket.", "a": "They"}, {"q": "Pick one pronoun that can replace the underlined word(s): 3. Jasmeen will go to church on Sunday.", "a": "She"}, {"q": "Pick one pronoun that can replace the underlined word(s): 4. Humaira will go to the shop with Sonia.", "a": "Her (replaces “Sonia”)"}, {"q": "Pick one pronoun that can replace the underlined word(s): 5. The Match will be played tomorrow evening.", "a": "It"}, {"q": "Pick one pronoun that can replace the underlined word(s): 6. Fareed and I will be sitting in the front row.", "a": "We"}, {"q": "Pick one pronoun that can replace the underlined word(s): 7. Fareed will go with Jamil's parents.", "a": "them"}, {"q": "Pick one pronoun that can replace the underlined word(s): 8. Please give me and my sister some food!", "a": "us"}, {"q": "Pick one pronoun that can replace the underlined word(s): 9. The teacher gave Samad good marks.", "a": "him"}]}]}, {"num": "3", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "We use words like but, because, and, so, to join sentences. Read the paragraph below. Fill the blanks with a correct word from the box, to complete the paragraph. Box: and, so, because, but — Saifullah was an old man ______ he had lots of energy. The reason he was healthy was ______ he always ate healthy food and washed his hands. He loved eating chicken ______ bread. One day he was sick ______ he did not go to the fields. He sent his son, Arif, to plough the land.", "a": "Saifullah was an old man but he had lots of energy. The reason he was healthy was because he always ate healthy food and washed his hands. He loved eating chicken and bread. One day he was sick so he did not go to the fields. He sent his son, Arif, to plough the land."}]}]}, {"num": "4", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Now use the 4 linking words in the box above to complete the following 4 sentences about yourself: 1. I do not like peaches ______ I like ______.", "a": "I do not like peaches but I like mangoes. (Model answer.)"}, {"q": "Use the linking words to complete the sentences about yourself: 2. I love eating fruits ______ I love eating ______.", "a": "I love eating fruits and I love eating vegetables. (Model answer.)"}, {"q": "Use the linking words to complete the sentences about yourself: 3. My mother loves me ______ I ______.", "a": "My mother loves me because I help her at home. (Model answer.)"}, {"q": "Use the linking words to complete the sentences about yourself: 4. Yesterday I did my homework ______ my teacher ______.", "a": "Yesterday I did my homework so my teacher was happy. (Model answer.)"}]}]}], "words": [{"w": "pronoun", "sd": "ضمير", "syn": "a word used in place of a noun"}, {"w": "linking word", "sd": "ڳنڍڻ وارو لفظ", "syn": "a word that joins sentences or ideas"}]}, {"cls": "iv", "unit": 3, "title": "Verbs: Action Verbs and Be Verbs", "display": "Verbs: Action Verbs and Be Verbs", "reading": "My English Book 4, Unit 2, Grammar", "lesson": [{"t": "h", "x": "Verbs: Action Verbs and Be Verbs"}, {"t": "p", "x": "A verb is a doing word. It tells us what a person or a thing does. 'Be' verbs (is, am, are, was, were) join the subject to the rest of the sentence, and they also help other verbs."}, {"t": "def", "x": "A verb is a word that shows an action or a state. Action verbs show what somebody does. Be verbs are is, am, are, was and were."}, {"t": "h", "x": "Rule 1. An action verb shows what somebody does"}, {"t": "rule", "x": "Action verbs tell us what a person or an animal does: run, eat, play, read, write, swim, jump, sing."}, {"t": "ex", "x": "The boy runs. The girl reads a book. The dog barks. The birds sing."}, {"t": "h", "x": "Rule 2. Use 'is' with he, she and it"}, {"t": "rule", "x": "Use 'is' with one person or thing: he is, she is, it is, Ali is, the dog is."}, {"t": "ex", "x": "He is my friend. She is a teacher. It is a cat. Ali is happy."}, {"t": "h", "x": "Rule 3. Use 'am' with I and 'are' with you, we and they"}, {"t": "rule", "x": "Use 'am' only with I. Use 'are' with you, we and they."}, {"t": "ex", "x": "I am a student. You are my friend. We are happy. They are players."}, {"t": "h", "x": "Rule 4. A be verb can help another verb"}, {"t": "rule", "x": "A be verb can help a verb that ends in 'ing': is playing, am reading, are going."}, {"t": "ex", "x": "He is playing cricket. I am reading a book. They are going to school."}, {"t": "rl", "x": "At school, the boys play cricket. I am in Class IV. My teacher is kind. We are learning English."}, {"t": "rl", "x": "At home, my mother is cooking food. My father is reading a newspaper. My sister is singing a song."}, {"t": "rl", "x": "In the market, the shopkeeper is selling fruit. The children are buying sweets. I am holding my father's hand."}, {"t": "note", "x": "Remember: 'is' for one, 'are' for many, 'am' only for I."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Look at the picture and write the verb that can be used to describe each picture. The verbs are given below in a jumbled order: open, rest, eat, fly, drink, kick", "a": "The six verbs are: open, rest, eat, fly, drink, kick. (Match each verb to its picture in the book.)"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Read the “Do” and “Don'ts” section of the Reading Text, section 2.2, on page 22 and search the verbs. List them in the same order that they have been written in the text. List of Do's:", "a": "1) put 2) obey 3) remove 4) stay 5) scream 6) go"}, {"q": "Read the “Do” and “Don'ts” section and list the verbs in the same order. List of Don'ts:", "a": "1) play 2) open 3) play 4) point 5) stand 6) listen"}]}]}, {"num": "3", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Write a “be verb” in the blank to complete each sentence: 1) Jamila and Azra ______ good friends.", "a": "are"}, {"q": "Write a “be verb” in the blank: 2) The teachers ______ looking at the paintings.", "a": "are"}, {"q": "Write a “be verb” in the blank: 3) I ______ tired, so I ______ going to sleep.", "a": "am, am"}, {"q": "Write a “be verb” in the blank: 4) My cat ______ drinking milk.", "a": "is"}, {"q": "Write a “be verb” in the blank: 5) I ______ fasting today.", "a": "am"}, {"q": "Write a “be verb” in the blank: 6) She ______ a cute baby.", "a": "is"}, {"q": "Write a “be verb” in the blank: 7) The bird ______ flying in the sky.", "a": "is"}]}]}, {"num": "4", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Fill in the following blanks using “be” as a helping verb: We ______ planning to have an Eid Milan party.", "a": "are"}, {"q": "Fill in the blank using “be” as a helping verb: I ______ cleaning my class for the party.", "a": "am"}, {"q": "Fill in the blank using “be” as a helping verb: Some of my friends ______ helping me.", "a": "are"}, {"q": "Fill in the blank using “be” as a helping verb: One of my friends ______ making an invitation card for the principal and teachers.", "a": "is"}, {"q": "Fill in the blank using “be” as a helping verb: Three of my classmates ______ decorating the class.", "a": "are"}, {"q": "Fill in the blank using “be” as a helping verb: We ______ enjoying ourselves.", "a": "are"}, {"q": "Fill in the blank using “be” as a helping verb: We ______ going to share our food with each other.", "a": "are"}, {"q": "Fill in the blank using “be” as a helping verb: One of my friends ______ going to share jokes and we ______ going to play games today.", "a": "is, are"}, {"q": "Fill in the blank using “be” as a helping verb: Our teacher ______ helping us so that we can have a great party.", "a": "is"}]}]}], "words": [{"w": "verb", "sd": "فعل", "syn": "a word that shows an action or a state"}, {"w": "action verb", "sd": "ڪم وارو فعل", "syn": "a verb that shows what somebody does"}, {"w": "be verb", "sd": "ٿيڻ وارو فعل", "syn": "is, am, are, was, were"}, {"w": "helping verb", "sd": "مددگار فعل", "syn": "a verb that helps the main verb"}]}, {"cls": "iv", "unit": 4, "title": "Present Continuous Tense", "display": "Present Continuous Tense", "reading": "My English Book 4, Unit 3, Grammar", "lesson": [{"t": "h", "x": "Present Continuous Tense"}, {"t": "p", "x": "The present continuous tense tells us about an action that is happening right now."}, {"t": "def", "x": "The present continuous tense is used for an action happening now. We make it with is, am or are and the verb with 'ing'."}, {"t": "h", "x": "Rule 1. Make it with is/am/are + verb + ing"}, {"t": "rule", "x": "Use is, am or are with the verb + ing: is playing, am reading, are going."}, {"t": "ex", "x": "I am reading. He is playing. She is cooking. We are going. They are eating."}, {"t": "h", "x": "Rule 2. Use it for an action happening now"}, {"t": "rule", "x": "Use the present continuous tense when the action is happening at this very moment."}, {"t": "ex", "x": "Look! It is raining. The baby is crying. The teacher is writing on the board."}, {"t": "h", "x": "Rule 3. Use it for a plan that is fixed"}, {"t": "rule", "x": "We also use it for a plan that is already fixed for today or tomorrow."}, {"t": "ex", "x": "We are going to Karachi tomorrow. I am visiting my uncle on Sunday."}, {"t": "rl", "x": "At school, the teacher is teaching us English now. The boys are writing in their notebooks."}, {"t": "rl", "x": "At home, my mother is cooking biryani. My father is watching the news. I am doing my homework."}, {"t": "rl", "x": "On the cricket ground, Ali is batting and Ahmed is bowling. The boys are playing well today."}, {"t": "note", "x": "Do not forget the be verb: say 'He is playing', not 'He playing'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Helping verbs (is, am and are) are used to write sentences where the verb has 'ing'. From the box below pick one part of the sentence from column 1, one from column 2, and one from column 3 and write complete sentences in your notebook. (You can select each part from column 1, 2 and 3 only once.) Example: They are walking on the street.", "a": "They are walking on the street. We are eating bananas. You are going to the mosque for prayers. It is very busy in cleaning home. He is mending a pair of shoes. The cobbler is going to Larkana to visit their relatives. The barber is cutting my hair. Ahmed and Faraz are reading the Holy Quran. (Model answer — the book's column phrases pair awkwardly; see flags.)"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Read what Bilquis does in the morning. Look at the order in which she does everything. After reading the text above put Bilquis's activities in the morning in an order. Remember to put the linking words (after, then, finally and first), as these show the order of events: ______, I get on the bus and go to school.", "a": "Finally, I get on the bus and go to school."}, {"q": "Put Bilquis's activities in the morning in an order: ______, breakfast, I brush my teeth and make my lunch.", "a": "After breakfast, I brush my teeth and make my lunch."}, {"q": "Put Bilquis's activities in the morning in an order: ______, I eat breakfast.", "a": "Then, I eat breakfast."}, {"q": "Put Bilquis's activities in the morning in an order: ______, I get dressed.", "a": "Next, I get dressed."}, {"q": "Put Bilquis's activities in the morning in an order: ______, I get out of bed.", "a": "First, I get out of bed."}]}]}], "words": [{"w": "present continuous tense", "sd": "زمان حال جاري", "syn": "the tense for an action happening now"}]}, {"cls": "iv", "unit": 5, "title": "WH Questions", "display": "WH Questions", "reading": "My English Book 4, Unit 3, Grammar", "lesson": [{"t": "h", "x": "WH Questions"}, {"t": "p", "x": "WH questions are questions that begin with what, where, when, who, why or how. They ask for information."}, {"t": "def", "x": "A WH question begins with a WH word: what, where, when, who, why or how. It asks for information, not just yes or no."}, {"t": "h", "x": "Rule 1. 'What' asks about a thing or an action"}, {"t": "rule", "x": "Use 'what' to ask about a thing or an action."}, {"t": "ex", "x": "What is Sania doing? She is baking a cake. What are you reading? I am reading a story book."}, {"t": "h", "x": "Rule 2. 'Where' asks about a place"}, {"t": "rule", "x": "Use 'where' to ask about a place."}, {"t": "ex", "x": "Where is Sania baking a cake? In the kitchen. Where is your book? In my bag."}, {"t": "h", "x": "Rule 3. 'When' asks about a time"}, {"t": "rule", "x": "Use 'when' to ask about a time."}, {"t": "ex", "x": "When is Sania baking a cake? In the morning. When are you going to Lahore? Tomorrow."}, {"t": "h", "x": "Rule 4. 'Who' asks about a person, 'why' asks about a reason"}, {"t": "rule", "x": "Use 'who' to ask about a person and 'why' to ask about a reason."}, {"t": "ex", "x": "Who is baking a cake? Sania. Why are you laughing? Because I am happy."}, {"t": "rl", "x": "At school, the teacher asks, 'What are you doing?' I say, 'I am doing my homework.'"}, {"t": "rl", "x": "At home, my mother asks, 'Where is your book?' I say, 'My book is in my bag.'"}, {"t": "rl", "x": "In the market, my father asks, 'When are we going home?' I say, 'We are going home now.'"}, {"t": "note", "x": "A WH question ends with a question mark (?)."}], "sections": [{"num": "1", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Make three questions for each sentence given below. The questions should begin with “what”, ”where” and “when”. 1) Sania is baking a cake in the kitchen in the morning.", "a": "What is Sania doing in the kitchen in the morning? When is Sania baking a cake in the kitchen? Where is Sania baking a cake in the morning?"}, {"q": "Make three questions (what, where, when) for: 2) Asad is writing a letter in the class during his lesson.", "a": "What is Asad doing in the class during his lesson? When is Asad writing a letter in the class? Where is Asad writing a letter during his lesson?"}, {"q": "Make three questions (what, where, when) for: 3) Tahir is reading a book in the library in the afternoon.", "a": "What is Tahir doing in the library in the afternoon? When is Tahir reading a book in the library? Where is Tahir reading a book in the afternoon? (The book's Answers section spells the name “Taher” — see flags.)"}, {"q": "Make three questions (what, where, when) for: 4) Maryam is sewing a dress in the living room at night.", "a": "What is Maryam doing in the living room at night? When is Maryam sewing a dress in the living room? Where is Maryam sewing a dress at night?"}, {"q": "Make three questions (what, where, when) for: 5) Zohra is playing a flute in the garden in the evening.", "a": "What is Zohra doing in the garden in the evening? When is Zohra playing a flute in the garden? Where is Zohra playing a flute in the evening? (The book's Answers section spells the name “Zahra” — see flags.)"}]}]}, {"num": "2", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Make two questions for each sentence given below. The questions should begin with “who” and “why”. 1) Sania is baking a cake because it is her sister's birthday.", "a": "Who is baking a cake because it is her sister's birthday? Why is Sania baking a cake?"}, {"q": "Make two questions (who, why) for: 2) Asad is writing a letter because he has to finish his classwork.", "a": "Who is writing a letter because he has to finish his classwork? Why is Asad writing a letter?"}, {"q": "Make two questions (who, why) for: 3) Tahir is reading a book because he has to do homework.", "a": "Who is reading a book because he has to do homework? Why is Tahir reading a book? (The book's Answers section spells the name “Taher” — see flags.)"}, {"q": "Make two questions (who, why) for: 4) Maryam is sewing a dress because she wants to wear it at a wedding.", "a": "Who is sewing a dress because she wants to wear it at a wedding? Why is Maryam sewing a dress?"}, {"q": "Make two questions (who, why) for: 5) Zohra is playing a flute because she is learning to play it.", "a": "Who is playing a flute because she is learning to play it? Why is Zohra playing a flute? (The book's Answers section spells the name “Zahra” — see flags.)"}]}]}, {"num": "3", "name": "Exercise 8", "exercises": [{"label": "Exercise 8", "items": [{"q": "Your friend gives you the following answers. Write down the questions that you asked. Each question will begin with a different “wh” word. Q 1. What are you doing? Ans: I am doing my homework.", "a": "What are you doing? (Given in the book.)"}, {"q": "Write the question for this answer. Ans: My book is in my bag.", "a": "Where is your book?"}, {"q": "Write the question for this answer. Ans: I am going to Lahore tomorrow.", "a": "When are you going to Lahore?"}, {"q": "Write the question for this answer. Ans: I am laughing because I am happy.", "a": "Why are you laughing?"}, {"q": "Write the question for this answer. Ans: I am eating a mango.", "a": "Which fruit are you eating? (The book asks for a different “wh” word for each question; “what” would also fit here, as in Q 1 — see flags.)"}, {"q": "Write the question for this answer. Ans: My best friend is my mother.", "a": "Who is your best friend?"}]}]}], "words": [{"w": "WH question", "sd": "سوالي جملو", "syn": "a question that begins with what, where, when, who, why or how"}]}, {"cls": "iv", "unit": 6, "title": "Adjectives and Their Degrees", "display": "Adjectives and Their Degrees", "reading": "My English Book 4, Unit 4, Grammar", "lesson": [{"t": "h", "x": "Adjectives and Their Degrees"}, {"t": "p", "x": "An adjective is a word that describes a noun. It tells us about the size, colour, shape or quality of a thing. Adjectives have three degrees: positive, comparative and superlative."}, {"t": "def", "x": "An adjective describes a noun. The three degrees of an adjective are positive, comparative and superlative."}, {"t": "h", "x": "Rule 1. An adjective tells us more about a noun"}, {"t": "rule", "x": "An adjective tells us about the size, colour or quality of a noun."}, {"t": "ex", "x": "a big house, a red pen, a tall boy, a sweet mango, a long pencil, a short story."}, {"t": "h", "x": "Rule 2. The comparative compares two things"}, {"t": "rule", "x": "Use the comparative degree (adjective + er + than) to compare two things."}, {"t": "ex", "x": "Ahmed is taller than Shiraz. The apple tree is bigger than the guava tree. The moon is brighter than a bulb."}, {"t": "h", "x": "Rule 3. The superlative compares more than two things"}, {"t": "rule", "x": "Use the superlative degree (the + adjective + est) to compare one thing with all the others."}, {"t": "ex", "x": "Sameer is the tallest boy. The mango tree is the biggest. The sun is the brightest."}, {"t": "h", "x": "Rule 4. Some adjectives change in a special way"}, {"t": "rule", "x": "Some adjectives do not take 'er' and 'est'. They change: good — better — best, bad — worse — worst."}, {"t": "ex", "x": "good — better — best, bad — worse — worst, little — less — least, much — more — most."}, {"t": "rl", "x": "At school, Ali is tall. Ahmed is taller than Ali. Bilal is the tallest boy in our class."}, {"t": "rl", "x": "At home, my bag is big. My brother's bag is bigger than mine. My father's bag is the biggest."}, {"t": "rl", "x": "In the market, this mango is sweet. That mango is sweeter than this one. The mango in that shop is the sweetest."}, {"t": "note", "x": "Use 'than' after the comparative: 'taller than', 'bigger than', 'better than'. Use 'the' before the superlative: 'the tallest', 'the biggest'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Read the dialogue and then complete the table that follows by selecting the adjectives used in the dialogue to show the size and colour of the things given in the table.", "a": "[[T]]Things|Size|Colour;;birds|tiny|yellow;;tree|tall|green;;river|large|blue;;sea|calm|blue;;mountains|huge|snow-covered (white);;streams|small|white[[/T]]"}]}]}, {"num": "2", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Complete the sentences under the pictures by adding the positive, comparative, and superlative degrees of these words: small, long, big, high, tall, bright. The first one has been done as an example. i) Ahmed is a tall boy. ii) Ahmed is taller than Shiraz. iii) Sameer is the tallest boy.", "a": "i) Ahmed is a tall boy. ii) Ahmed is taller than Shiraz. iii) Sameer is the tallest boy. (Example given in the book.)"}, {"q": "Complete the sentences under the pictures by adding the positive, comparative, and superlative degrees: i) The apple tree is ______. ii) The apple tree is ______ than the guava tree. iii) The mango tree is the ______.", "a": "i) The apple tree is big. ii) The apple tree is bigger than the guava tree. iii) The mango tree is the biggest."}, {"q": "Complete the sentences under the pictures: i) This bulb is ______. ii) The moon is ______ than a bulb. iii) The sun is the ______.", "a": "i) This bulb is bright. ii) The moon is brighter than a bulb. iii) The sun is the brightest."}, {"q": "Complete the sentences under the pictures: i) This is a ______ black duck. ii) This white duck is ______ than the black duck. iii) The pink duck is the ______ duck.", "a": "i) This is a small black duck. ii) This white duck is smaller than the black duck. iii) The pink duck is the smallest duck."}, {"q": "Complete the sentences under the pictures: i) A kite is flying ______. ii) A bird is flying ______ than the kite. iii) An airplane is flying at the ______ level.", "a": "i) A kite is flying high. ii) A bird is flying higher than the kite. iii) An airplane is flying at the highest level."}, {"q": "Complete the sentences under the pictures: i) Asiya has ______ black hair. ii) Asma has ______ hair than Asiya. iii) Anum has the ______ hair.", "a": "i) Asiya has long black hair. ii) Asma has longer hair than Asiya. iii) Anum has the longest hair."}]}]}, {"num": "3", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Describe three of your class fellows by writing about their height (tall/short), shoes size (small/large) and age (young/old), in comparison to each other. For example: Who is young? Who is younger? And who is the youngest?", "a": "Ali is young. Ahmed is younger than Ali. Bilal is the youngest. Ali's shoes are small. Ahmed's shoes are smaller than Ali's. Bilal's shoes are the smallest. Ali is tall. Ahmed is taller than Ali. Bilal is the tallest. (Model answer.)"}]}]}], "words": [{"w": "adjective", "sd": "صفت", "syn": "a word that describes a noun"}, {"w": "positive degree", "sd": "سادو درجو", "syn": "the simple form of an adjective"}, {"w": "comparative degree", "sd": "تقابلي درجو", "syn": "the form used to compare two things"}, {"w": "superlative degree", "sd": "اعليٰ درجو", "syn": "the form used to compare one thing with all the others"}]}, {"cls": "iv", "unit": 7, "title": "Contractions", "display": "Contractions", "reading": "My English Book 4, Unit 4, Grammar", "lesson": [{"t": "h", "x": "Contractions"}, {"t": "p", "x": "A contraction is a short form of two words. We join two words and use an apostrophe (') in place of the missing letters."}, {"t": "def", "x": "A contraction is the short form of two words joined together. An apostrophe takes the place of the missing letters."}, {"t": "h", "x": "Rule 1. Join the two words and drop some letters"}, {"t": "rule", "x": "To make a contraction, join two words, drop one or more letters, and put an apostrophe where the letters were dropped."}, {"t": "ex", "x": "I am — I'm, you are — you're, he is — he's, she is — she's, it is — it's, we are — we're, they are — they're."}, {"t": "h", "x": "Rule 2. Contractions with 'not'"}, {"t": "rule", "x": "With 'not', the contraction ends in n't: cannot — can't, do not — don't, will not — won't, is not — isn't, are not — aren't, did not — didn't."}, {"t": "ex", "x": "I can't swim. She doesn't like milk. They don't play here. He won't come today."}, {"t": "h", "x": "Rule 3. Contractions with 'will' and 'would'"}, {"t": "rule", "x": "With 'will', the contraction ends in 'll: I will — I'll, you will — you'll, he will — he'll. With 'would', it ends in 'd: I would — I'd."}, {"t": "ex", "x": "I'll go to school. You'll see him. He'd like a book. She'd come tomorrow."}, {"t": "rl", "x": "At school, my friend says, 'I'm in Class IV.' The teacher says, 'Don't make a noise.'"}, {"t": "rl", "x": "At home, my mother says, 'It's time for lunch.' I say, 'I can't eat now, I'll eat later.'"}, {"t": "rl", "x": "In the market, the shopkeeper says, 'That's a good price.' My father says, 'We won't buy it today.'"}, {"t": "note", "x": "Do not mix up 'it's' (it is) with 'its' (belonging to it). 'It's a dog' but 'The dog wagged its tail'."}], "sections": [{"num": "1", "name": "Practice", "exercises": [{"label": "Practice (made from the rules — no exercise in the book for this topic)", "items": [{"q": "Use the rules in this lesson to make three sentences of your own about your school day.", "a": "Answers will differ. Check your sentences against the rules above."}]}]}], "words": [{"w": "contraction", "sd": "مخفف", "syn": "the short form of two words joined together"}, {"w": "apostrophe", "sd": "اعراب", "syn": "the sign ' used in writing"}]}, {"cls": "iv", "unit": 8, "title": "Past Continuous Tense, Can and Will", "display": "Past Continuous Tense, Can and Will", "reading": "My English Book 4, Unit 5, Grammar", "lesson": [{"t": "h", "x": "Past Continuous Tense, Can and Will"}, {"t": "p", "x": "In this lesson we learn three things: the past continuous tense, can and cannot, and the future with will."}, {"t": "def", "x": "The past continuous tense tells us about an action that was going on at a time in the past. 'Can' shows ability. 'Will' shows the future."}, {"t": "h", "x": "Rule 1. Make the past continuous with was/were + verb + ing"}, {"t": "rule", "x": "Use was or were with the verb + ing: was playing, were reading, was cooking."}, {"t": "ex", "x": "When I phoned my friends, they were playing. Yesterday at six, I was preparing my lesson. The kids were playing in the garden."}, {"t": "h", "x": "Rule 2. Use 'was' with I, he, she and it"}, {"t": "rule", "x": "Use 'was' with I, he, she and it, and 'were' with you, we and they."}, {"t": "ex", "x": "I was reading. She was cooking. We were eating. They were playing."}, {"t": "h", "x": "Rule 3. 'Can' shows ability, 'cannot' shows no ability"}, {"t": "rule", "x": "Use 'can' to say what somebody is able to do, and 'cannot' (can't) to say what somebody is not able to do."}, {"t": "ex", "x": "I can read books. I can play ludo. I can't swim. I can't ride a horse. Can you write with this pen? Yes, I can."}, {"t": "h", "x": "Rule 4. Use 'will' with the verb for the future"}, {"t": "rule", "x": "Use 'will' with the verb to talk about the future."}, {"t": "ex", "x": "We will go tomorrow. They will buy a new house. My mother will cook my favourite dish tomorrow. You will be very happy."}, {"t": "rl", "x": "Yesterday at six, I was doing my homework when my friend came. I can play cricket, but I can't play hockey."}, {"t": "rl", "x": "At home, my mother was cooking when I came home. Tomorrow, we will visit my grandmother."}, {"t": "rl", "x": "In the market, the shopkeeper was selling fruit. I can buy a book, and I will read it at home."}, {"t": "note", "x": "After can, could and will, use the verb without 's', 'ed' or 'ing': 'I can play', 'I will go' — not 'I can plays' or 'I will went'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Put the verbs in the correct form (past progressive). The first one has been done as an example. 1. When I phoned my friends, they (play) were playing monopoly. 2. Yesterday at six I (prepare) ______ dinner.", "a": "was preparing"}, {"q": "Put the verbs in the correct form (past progressive): 3. The kids (play) ______ in the garden.", "a": "were playing"}, {"q": "Put the verbs in the correct form (past progressive): 4. I (practice) ______ for the qirat competition when you came home.", "a": "was practising"}, {"q": "Put the verbs in the correct form (past progressive): 5. We (cycle) ______ the whole day yesterday.", "a": "were cycling"}, {"q": "Put the verbs in the correct form (past progressive): 6. While Danial (work) ______ in his room, his friends (swim) ______ in the pool.", "a": "was working, were swimming"}, {"q": "Put the verbs in the correct form (past progressive): 7. I told them that I (tell) ______ the truth but they did not listen to me.", "a": "was telling"}, {"q": "Put the verbs in the correct form (past progressive): 8. Most of the time we (sit) ______ in the park.", "a": "were sitting"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Choose words from the list below to complete the following dialogue: watch, play, read, clean, enjoy, cook, have, work, wash, try. Marvi: What were all of you doing yesterday? Rano: I ______ the house.", "a": "was cleaning"}, {"q": "Choose words from the list to complete the dialogue: Marvi: I ______ the clothes in the morning.", "a": "was washing"}, {"q": "Choose words from the list to complete the dialogue: Rano: My mother ______ the food.", "a": "was cooking"}, {"q": "Choose words from the list to complete the dialogue: Marvi: My mother ______ in the fields.", "a": "was working"}, {"q": "Choose words from the list to complete the dialogue: Rano: And my sisters ______ with the baby.", "a": "were playing"}, {"q": "Choose words from the list to complete the dialogue: Marvi: My sister and I ______ books in the afternoon.", "a": "were reading"}, {"q": "Choose words from the list to complete the dialogue: Rano: My mother and I ______ to finish the work so that we could visit grandmother.", "a": "were trying"}, {"q": "Choose words from the list to complete the dialogue: Marvi: We ______ television in the evening.", "a": "were watching"}, {"q": "Choose words from the list to complete the dialogue: Rano: It seems you ______ a good time.", "a": "were having"}, {"q": "Choose words from the list to complete the dialogue: Marvi: Yes, we ______ ourselves.", "a": "were enjoying"}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Put the following words in the correct order. Remember to use capital letters in the beginning and to add a full stop or question mark at the end. 1. Arabic cannot speak I ______", "a": "I cannot speak Arabic. (The book's Answers section prints “Arabiac” — see flags.)"}, {"q": "Put the words in the correct order: 2. you me time can please tell the ______", "a": "Can you please tell me the time?"}, {"q": "Put the words in the correct order: 3. foot ball can I play ______", "a": "Can I play football?"}, {"q": "Put the words in the correct order: 4. she but can can't dance she sing ______", "a": "She can't dance but she can sing. OR She can't sing but she can dance."}, {"q": "Put the words in the correct order: 5. swim they can 100 metres ______", "a": "Can they swim 100 metres?"}, {"q": "Put the words in the correct order: 6. you cannot with I come ______", "a": "I cannot come with you."}]}]}, {"num": "4", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Complete these sentences with can or can't. Abdullah: Hi Zoha! What's that? Zoha: It's my magic pen. Abdullah: (1) ______ you write with it?", "a": "can"}, {"q": "Complete the sentence with can or can't: Zoha: Yes, I (2) ______.", "a": "can"}, {"q": "Complete the sentence with can or can't: Abdullah: Wow! I cannot see what you have written! Zoha: (3) ______ you see now?", "a": "can"}, {"q": "Complete the sentence with can or can't: Abdullah: Yes, I (4) ______, but I (5) ______ understand how it works?", "a": "can, can't"}, {"q": "Complete the sentence with can or can't: Zoha: Oh! I (6) ______ tell you. When we put light on the writing it will glow and you (7) ______ see it.", "a": "can, can (The book's Answers section says “can't” for (7), but that would contradict “it will glow” — see flags.)"}, {"q": "Complete the sentence with can or can't: Abdullah: Zoha (8) ______ I also try?", "a": "Can"}, {"q": "Complete the sentence with can or can't: Zoha: Sure you (9) ______, but you (10) ______ keep it forever!", "a": "can, can't"}]}]}, {"num": "5", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "When we talk about the future we use ‘will’ with the verb. Example: We (go) will go tomorrow. Fill the following blanks using ‘will’ with the given verb. 1. They (buy) ______ a new house next year.", "a": "will buy"}, {"q": "Fill the blank using ‘will’ with the given verb: 2. You (get) ______ a lot of money on Eid day.", "a": "will get"}, {"q": "Fill the blank using ‘will’ with the given verb: 3. My mother (cook) ______ my favourite dish tomorrow.", "a": "will cook"}, {"q": "Fill the blank using ‘will’ with the given verb: 4. The teacher (take) ______ us to the park on Saturday.", "a": "will take"}, {"q": "Fill the blank using ‘will’ with the given verb: 5. The train (leave) ______ at 8 o'clock.", "a": "will leave"}]}]}, {"num": "6", "name": "Exercise 8", "exercises": [{"label": "Exercise 8", "items": [{"q": "Saeed, 18 years old, asked an old palmist (a person who reads lines on our hands) about his future. Here is what he told him. Write down the complete sentences using 'will' with the verb to show what will happen in the future. The first sentence has been done as an example. 1. You (be) very happy.", "a": "You will be very happy. (Given in the book.)"}, {"q": "Write the complete sentence using 'will': 2. You (get) a lot of money.", "a": "You will get a lot of money."}, {"q": "Write the complete sentence using 'will': 3. You (buy) a beautiful house.", "a": "You will buy a beautiful house."}, {"q": "Write the complete sentence using 'will': 4. Your friends (be) jealous of you.", "a": "Your friends will be jealous of you."}, {"q": "Write the complete sentence using 'will': 5. You (meet) a beautiful girl.", "a": "You will meet a beautiful girl."}, {"q": "Write the complete sentence using 'will': 6. You (marry) her.", "a": "You will marry her."}, {"q": "Write the complete sentence using 'will': 7. You (travel) around the world.", "a": "You will travel around the world."}, {"q": "Write the complete sentence using 'will': 8. People (serve) you.", "a": "People will serve you."}, {"q": "Write the complete sentence using 'will': 9. They (not refuse) you anything.", "a": "They will not refuse you anything."}, {"q": "Write the complete sentence using 'will': 10. But all this (happen) only when you are 70 years old!", "a": "But all this will happen only when you are 70 years old!"}]}]}], "words": [{"w": "past continuous tense", "sd": "زمان ماضي جاري", "syn": "the tense for an action going on in the past"}, {"w": "ability", "sd": "قابليت", "syn": "what somebody is able to do"}, {"w": "future", "sd": "مستقبل", "syn": "the time that is yet to come"}]}, {"cls": "v", "unit": 1, "title": "Proper and Common Nouns", "display": "Proper and Common Nouns", "reading": "My English Book 5, Unit 1, Grammar", "lesson": [{"t": "h", "x": "Proper and Common Nouns"}, {"t": "p", "x": "A noun names a person, place, animal or thing. A proper noun is a special name. A common noun is a general name."}, {"t": "def", "x": "A proper noun is the special name of a person, place or thing. A common noun is a general name for a person, place or thing."}, {"t": "h", "x": "Rule 1. A proper noun begins with a capital letter"}, {"t": "rule", "x": "Always begin a proper noun with a capital letter."}, {"t": "ex", "x": "Nazo, Ali, Sana, Karachi, Lahore, Pakistan, the River Indus, Friday, Eid."}, {"t": "h", "x": "Rule 2. A common noun begins with a small letter"}, {"t": "rule", "x": "A common noun does not begin with a capital letter, unless it starts a sentence."}, {"t": "ex", "x": "girl, boy, city, river, school, wolf, teacher, book."}, {"t": "h", "x": "Rule 3. Find the proper noun and its common noun"}, {"t": "rule", "x": "Every proper noun has a common noun. Nazo is a girl. Karachi is a city. The Indus is a river."}, {"t": "ex", "x": "Nazo — girl, Ali — boy, Karachi — city, Lahore — city, the Indus — river, a wolf — animal."}, {"t": "rl", "x": "At school, my teacher Miss Ayesha is a teacher. Our school is in a village. The village is Haseeja Mahar."}, {"t": "rl", "x": "At home, my sister Nazo is a girl. My brother is a boy. We live in Pakistan."}, {"t": "rl", "x": "In the market, I saw a wolf in a story book. The wolf is an animal. The shopkeeper is a man."}, {"t": "note", "x": "The names of people, cities, rivers, days and months are proper nouns."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Write the proper noun and its common noun from the story 'I'll Help You': wolf", "a": "Proper noun: Jabir — Common noun: wolf. (The example in the book prints \"Jabbir\"; the story spells it \"Jabir\". See the flags file.)"}, {"q": "Write the proper noun and its common noun from the story 'I'll Help You': lamb", "a": "Proper noun: Memna — Common noun: lamb."}, {"q": "Write the proper noun and its common noun from the story 'I'll Help You': cat", "a": "Proper noun: Mano — Common noun: cat."}, {"q": "Write the proper noun and its common noun from the story 'I'll Help You': dog", "a": "Proper noun: Moti — Common noun: dog."}, {"q": "Write the proper noun and its common noun from the story 'I'll Help You': horse", "a": "Proper noun: Kumet — Common noun: horse."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Fill in the blanks with a correct proper noun and common noun. Common noun: girl", "a": "Proper noun: Salma — Common noun: girl. (Model answer — any girl's name is correct.)"}, {"q": "Fill in the blanks with a correct proper noun and common noun. Proper noun: Naeem", "a": "Proper noun: Naeem — Common noun: boy."}, {"q": "Fill in the blanks with a correct proper noun and common noun. Common noun: city", "a": "Proper noun: Lahore — Common noun: city. (Model answer — any city's name is correct.)"}, {"q": "Fill in the blanks with a correct proper noun and common noun. Proper noun: Arabian", "a": "Proper noun: Arabian — Common noun: sea."}, {"q": "Fill in the blanks with a correct proper noun and common noun. Common noun: boy", "a": "Proper noun: Ali — Common noun: boy. (Model answer — any boy's name is correct.)"}, {"q": "Fill in the blanks with a correct proper noun and common noun. Proper noun: Indus", "a": "Proper noun: Indus — Common noun: river."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Write a sentence about Nazo. (Inner circle 1: Nazo; outer circle 1: sleeping)", "a": "Nazo is sleeping."}, {"q": "Write a sentence about Fahim. (Inner circle 2: Fahim; outer circle 2: swimming)", "a": "Fahim is swimming."}, {"q": "Write a sentence about Farhan. (Inner circle 3: Farhan; outer circle 3: reading)", "a": "Farhan is reading."}, {"q": "Write a sentence about Bachal. (Inner circle 4: Bachal; outer circle 4: eating apples)", "a": "Bachal is eating apples."}, {"q": "Write a sentence about Rabia. (Inner circle 5: Rabia; outer circle 5: writing)", "a": "Rabia is writing."}, {"q": "Write a sentence about Natasha. (Inner circle 6: Natasha; outer circle 6: drinking)", "a": "Natasha is drinking."}, {"q": "Write a sentence about Imran. (Inner circle 7: Imran; outer circle 7: playing football)", "a": "Imran is playing football."}, {"q": "Write a sentence about Najma. (Inner circle 8: Najma; outer circle 8: skipping)", "a": "Najma is skipping. (Example given in the book.)"}]}]}, {"num": "4", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Look around in your classroom and write a sentence about what is happening. (Model sentence 1)", "a": "The teacher is writing on the black board. (Example given in the book.)"}, {"q": "Look around in your classroom and write a sentence about what is happening. (Model sentence 2)", "a": "The students are reading their books."}, {"q": "Look around in your classroom and write a sentence about what is happening. (Model sentence 3)", "a": "Ali is writing in his notebook."}, {"q": "Look around in your classroom and write a sentence about what is happening. (Model sentence 4)", "a": "Sara is cleaning the blackboard."}, {"q": "Look around in your classroom and write a sentence about what is happening. (Model sentence 5)", "a": "The peon is sweeping the classroom."}]}]}], "words": [{"w": "proper noun", "sd": "اسم خاص", "syn": "the special name of a person, place or thing"}, {"w": "common noun", "sd": "اسم عام", "syn": "a general name, not a special name"}]}, {"cls": "v", "unit": 2, "title": "Contractions", "display": "Contractions", "reading": "My English Book 5, Unit 1, Grammar", "lesson": [{"t": "h", "x": "Contractions"}, {"t": "p", "x": "A contraction is the short form of two words. We join the words and put an apostrophe where letters are dropped."}, {"t": "def", "x": "A contraction is the short form of two words joined together, with an apostrophe in place of the missing letters."}, {"t": "h", "x": "Rule 1. Contractions with 'will'"}, {"t": "rule", "x": "With 'will', the short form ends in 'll: I will — I'll, you will — you'll, he will — he'll, she will — she'll, it will — it'll, we will — we'll, they will — they'll."}, {"t": "ex", "x": "I'll go tomorrow. You'll see him. He'll come soon. We'll play cricket."}, {"t": "h", "x": "Rule 2. Contractions with 'not'"}, {"t": "rule", "x": "With 'not', the short form ends in n't: cannot — can't, do not — don't, will not — won't, is not — isn't, are not — aren't."}, {"t": "ex", "x": "I can't swim. She doesn't like milk. They don't play here. He won't come today."}, {"t": "h", "x": "Rule 3. Contractions with 'is', 'am' and 'are'"}, {"t": "rule", "x": "I am — I'm, you are — you're, he is — he's, she is — she's, it is — it's, we are — we're, they are — they're."}, {"t": "ex", "x": "I'm in Class V. He's my friend. It's a nice day. We're happy."}, {"t": "rl", "x": "At school, my friend says, 'I'm in Class V.' The teacher says, 'Don't make a noise.'"}, {"t": "rl", "x": "At home, my mother says, 'It's time for lunch.' I say, 'I'll eat later.'"}, {"t": "rl", "x": "In the market, the shopkeeper says, 'That's a good price.' My father says, 'We won't buy it today.'"}, {"t": "note", "x": "Do not mix up 'it's' (it is) with 'its' (belonging to it)."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Match the two words with their short form: it will", "a": "it will — it'll. (Example given in the book.)"}, {"q": "Match the two words with their short form: I am", "a": "I am — I'm."}, {"q": "Match the two words with their short form: that is", "a": "that is — that's."}, {"q": "Match the two words with their short form: I will", "a": "I will — I'll."}, {"q": "Match the two words with their short form: do not", "a": "do not — don't."}, {"q": "Match the two words with their short form: I have", "a": "I have — I've."}, {"q": "Match the two words with their short form: we are", "a": "we are — we're."}, {"q": "Match the two words with their short form: he will", "a": "he will — he'll."}, {"q": "Match the two words with their short form: we will", "a": "we will — we'll."}, {"q": "Match the two words with their short form: he is", "a": "he is — he's."}, {"q": "Match the two words with their short form: you are", "a": "you are — you're."}, {"q": "Match the two words with their short form: she is", "a": "she is — she's."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Fill in the blank with the correct short form: David: When are you going to Larkana? Saeed: ___ be going there tomorrow.", "a": "Saeed: I'll be going there tomorrow."}, {"q": "Fill in the blank with the correct short form: David: Have you packed your things? Saeed: ___ asked my mother to do so.", "a": "Saeed: I've asked my mother to do so."}, {"q": "Fill in the blank with the correct short form: Saeed: ___ also going.", "a": "Saeed: She's also going."}, {"q": "Fill in the blank with the correct short form: Saeed: In fact, ___ all going.", "a": "Saeed: In fact, we're all going."}, {"q": "Fill in the blank with the correct short form: David: What will you do with your goat? Saeed: ___ be kept in my uncle's yard.", "a": "Saeed: It'll be kept in my uncle's yard."}, {"q": "Fill in the blank with the correct short form: David: When will you come back? Saeed: I ___ know.", "a": "Saeed: I don't know."}, {"q": "Fill in the blank with the correct short form: Saeed: ___ probably come back after two weeks.", "a": "Saeed: I'll probably come back after two weeks."}, {"q": "Fill in the blank with the correct short form: Saeed: But my brother has only one week's holiday, so ___ come back earlier.", "a": "Saeed: But my brother has only one week's holiday, so he'll come back earlier."}, {"q": "Fill in the blank with the correct short form: David: ___ so lucky.", "a": "David: You're so lucky."}, {"q": "Fill in the blank with the correct short form: David: ___ go to Sialkot next year with my mother to visit grandfather.", "a": "David: We'll go to Sialkot next year with my mother to visit grandfather."}]}]}], "words": [{"w": "contraction", "sd": "مخفف", "syn": "the short form of two words joined together"}]}, {"cls": "v", "unit": 3, "title": "Singular and Plural Nouns and Noun Gender", "display": "Singular and Plural Nouns and Noun Gender", "reading": "My English Book 5, Unit 2, Grammar", "lesson": [{"t": "h", "x": "Singular and Plural Nouns and Noun Gender"}, {"t": "p", "x": "A noun is singular when it names one thing and plural when it names more than one. Nouns also have gender: masculine or feminine."}, {"t": "def", "x": "A singular noun names one thing. A plural noun names more than one thing. Gender tells us if a noun is masculine (male) or feminine (female)."}, {"t": "h", "x": "Rule 1. Add 's' to make most plurals"}, {"t": "rule", "x": "Add 's' to most nouns to make them plural."}, {"t": "ex", "x": "book — books, pen — pens, girl — girls, boy — boys, mango — mangoes."}, {"t": "h", "x": "Rule 2. Some plurals change the word"}, {"t": "rule", "x": "Some nouns change in the plural: tooth — teeth, foot — feet, man — men, woman — women, child — children."}, {"t": "ex", "x": "tooth — teeth, foot — feet, man — men, woman — women, child — children, mouse — mice."}, {"t": "h", "x": "Rule 3. Masculine and feminine nouns"}, {"t": "rule", "x": "Masculine nouns name males and feminine nouns name females."}, {"t": "ex", "x": "boy — girl, man — woman, father — mother, brother — sister, son — daughter, king — queen, cock — hen, bull — cow."}, {"t": "h", "x": "Rule 4. Common gender"}, {"t": "rule", "x": "Some nouns can be both masculine and feminine. They are of common gender: teacher, student, child, doctor, friend."}, {"t": "ex", "x": "My teacher is a woman. His teacher is a man. The child is a boy. The child is a girl."}, {"t": "rl", "x": "At school, there are twenty boys and fifteen girls in my class. My teacher is a woman. Our headmaster is a man."}, {"t": "rl", "x": "At home, my father is a man and my mother is a woman. I have one brother and two sisters."}, {"t": "rl", "x": "In the market, the farmer sells mangoes. One mango is sweet. Ten mangoes are sweeter. The milkman brings milk every day."}, {"t": "note", "x": "Add 'es' after s, x, ch or sh: glass — glasses, box — boxes, watch — watches, bush — bushes."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Match the singular in column A with the plural in column B. tooth", "a": "one tooth — many teeth. (Example given in the book.)"}, {"q": "Match the singular in column A with the plural in column B. mouse", "a": "one mouse — many mice."}, {"q": "Match the singular in column A with the plural in column B. ox", "a": "one ox — many oxen."}, {"q": "Match the singular in column A with the plural in column B. woman", "a": "one woman — many women."}, {"q": "Match the singular in column A with the plural in column B. goose", "a": "one goose — many geese."}, {"q": "Match the singular in column A with the plural in column B. child", "a": "one child — many children."}, {"q": "Match the singular in column A with the plural in column B. foot", "a": "one foot — many feet."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: boy", "a": "boy — M. (Given in the book.)"}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: lady", "a": "lady — F. (Given in the book.)"}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: captain", "a": "captain — C. (Given in the book.)"}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: grandmother", "a": "grandmother — F."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: postman", "a": "postman — M."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: aunt", "a": "aunt — F."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: principal", "a": "principal — C."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: woman", "a": "woman — F."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: player", "a": "player — C."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: father", "a": "father — M."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: uncle", "a": "uncle — M."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: cleaner", "a": "cleaner — C."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: girl", "a": "girl — F."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: doctor", "a": "doctor — C."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: brother", "a": "brother — M."}, {"q": "Write M (Masculine), F (Feminine) or C (Common) for the word: writer", "a": "writer — C."}]}]}], "words": [{"w": "singular", "sd": "واحد", "syn": "naming one thing"}, {"w": "plural", "sd": "جمع", "syn": "naming more than one thing"}, {"w": "masculine", "sd": "مذڪر", "syn": "male"}, {"w": "feminine", "sd": "مؤنث", "syn": "female"}, {"w": "common gender", "sd": "عام جنس", "syn": "a noun that can be male or female"}]}, {"cls": "v", "unit": 4, "title": "Past Continuous Tense", "display": "Past Continuous Tense", "reading": "My English Book 5, Unit 2, Grammar", "lesson": [{"t": "h", "x": "Past Continuous Tense"}, {"t": "p", "x": "The past continuous tense tells us about an action that was going on at a time in the past."}, {"t": "def", "x": "The past continuous tense is used for an action that was in progress at a time in the past. We make it with was or were and the verb with 'ing'."}, {"t": "h", "x": "Rule 1. Make it with was/were + verb + ing"}, {"t": "rule", "x": "Use was or were with the verb + ing."}, {"t": "ex", "x": "I was reading. He was playing. She was cooking. We were eating. They were going."}, {"t": "h", "x": "Rule 2. Use 'was' with I, he, she and it"}, {"t": "rule", "x": "Use 'was' with I, he, she and it, and 'were' with you, we and they."}, {"t": "ex", "x": "I was sleeping. She was singing. We were playing. They were watching TV."}, {"t": "h", "x": "Rule 3. Use it with a time in the past"}, {"t": "rule", "x": "The past continuous goes with a time in the past: at 6 o'clock, yesterday morning, last Sunday, at 8 o'clock."}, {"t": "ex", "x": "What was Saleem doing last Sunday? At 6 a.m. he was sleeping. At 8 a.m. he was going to school."}, {"t": "rl", "x": "Yesterday morning at 8 o'clock, I was going to school. My brother was playing cricket."}, {"t": "rl", "x": "At home last night, my mother was cooking food and my father was reading a newspaper."}, {"t": "rl", "x": "In the market yesterday, the shopkeepers were selling fruit. The children were buying sweets."}, {"t": "note", "x": "The past continuous tells us what was happening; the simple past tells us what happened: 'I was reading when he came.'"}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "What was Saleem doing last Sunday? At 6:00 a.m.", "a": "At 6.00 a.m. he was washing his face. (Example given in the book.)"}, {"q": "What was Saleem doing last Sunday? At 7:00 p.m. (printed on the morning side)", "a": "At 7.00 p.m. he was drinking tea. (The diagram prints '7:00 p.m. Drinking tea' on the morning side; it is probably 7:00 a.m. See the flags file.)"}, {"q": "What was Saleem doing last Sunday? At 8:00 a.m.", "a": "At 8.00 a.m. he was reading a book."}, {"q": "What was Saleem doing last Sunday? At 9:00 a.m.", "a": "At 9.00 a.m. he was polishing his shoes."}, {"q": "What was Saleem doing last Sunday? At 6:00 p.m.", "a": "At 6.00 p.m. he was playing hockey."}, {"q": "What was Saleem doing last Sunday? At 7:00 p.m.", "a": "At 7.00 p.m. he was watching T.V."}, {"q": "What was Saleem doing last Sunday? At 8:00 p.m.", "a": "At 8.00 p.m. he was writing a letter."}, {"q": "What was Saleem doing last Sunday? At 9:00 p.m.", "a": "At 9.00 p.m. he was doing his homework."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Answer using the past continuous tense: What were you doing at 8:00 a.m. yesterday morning? (go to school)", "a": "I was going to school at 8:00 o'clock. (Example given in the book.)"}, {"q": "Answer using the past continuous tense: What were you doing at 10:00 a.m. yesterday morning? (sit in the class)", "a": "I was sitting in the class at 10:00 o'clock."}, {"q": "Answer using the past continuous tense: What were you doing at 11:00 a.m. yesterday morning? (do my work)", "a": "I was doing my work at 11:00 o'clock."}, {"q": "Answer using the past continuous tense: What was your mother doing at 5:00 p.m. yesterday evening? (cook food)", "a": "She was cooking food at 5:00 o'clock."}, {"q": "Answer using the past continuous tense: What was your mother doing at 6:00 p.m. yesterday evening? (wash dishes)", "a": "She was washing dishes at 6:00 o'clock."}, {"q": "Answer using the past continuous tense: What was your mother doing at 7:00 p.m. yesterday evening? (sleep)", "a": "She was sleeping at 7:00 o'clock."}]}]}, {"num": "3", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Ask your friend: What were you doing at 9:00 p.m. yesterday morning? (as printed)", "a": "I was sleeping at 9:00 a.m. yesterday morning. (The book prints '9:00 p.m. yesterday morning'; it is probably 9:00 a.m. See the flags file.)"}, {"q": "Ask your friend: What were you doing at 3:00 p.m. yesterday afternoon?", "a": "I was playing cricket at 3:00 p.m. yesterday afternoon."}, {"q": "Ask your friend: What were you doing at 7:00 p.m. yesterday evening?", "a": "I was watching TV at 7:00 p.m. yesterday evening."}]}]}], "words": [{"w": "past continuous tense", "sd": "زمان ماضي جاري", "syn": "the tense for an action going on in the past"}]}, {"cls": "v", "unit": 5, "title": "Prepositions and Asking Permission with May", "display": "Prepositions and Asking Permission with May", "reading": "My English Book 5, Unit 2, Grammar", "lesson": [{"t": "h", "x": "Prepositions and Asking Permission with May"}, {"t": "p", "x": "A preposition is a word that shows the place or position of a thing. 'May' is used to ask for permission politely."}, {"t": "def", "x": "A preposition shows where a thing is: in, on, under, near, behind, between. 'May' is used to ask for permission."}, {"t": "h", "x": "Rule 1. Prepositions show place"}, {"t": "rule", "x": "Use in, on, under, near, behind, between and in front of to show where a thing is."}, {"t": "ex", "x": "The book is on the table. The ball is under the chair. The school is near the mosque. Ali is behind Ahmed."}, {"t": "h", "x": "Rule 2. Use 'in' for a big place and 'at' for a small place"}, {"t": "rule", "x": "Use 'in' for a city or a country, and 'at' for a small place like a school or a house."}, {"t": "ex", "x": "I live in Karachi. He is at school. She is at home. We live in Pakistan."}, {"t": "h", "x": "Rule 3. Ask permission with 'May I'"}, {"t": "rule", "x": "To ask for permission, say 'May I' and then the verb."}, {"t": "ex", "x": "May I come in? May I try to make a pot? May I go out to play? May I drink some water?"}, {"t": "h", "x": "Rule 4. Answer with 'Yes, you may' or 'No, you may not'"}, {"t": "rule", "x": "Answer a 'May I' question with 'Yes, you may' or 'No, you may not'."}, {"t": "ex", "x": "May I come in? Yes, you may. May I go out? No, you may not. It is raining."}, {"t": "rl", "x": "At school, the book is on my desk and my bag is under it. I ask, 'May I go to drink water?' The teacher says, 'Yes, you may.'"}, {"t": "rl", "x": "At home, the cat is under the table. My mother is in the kitchen. I ask, 'May I play outside?' She says, 'Yes, you may.'"}, {"t": "rl", "x": "In the market, the shop is near the mosque. The fruit is in the basket. I ask my father, 'May I buy a kite?' He says, 'Yes, you may.'"}, {"t": "note", "x": "'May' is more polite than 'can' when we ask for permission."}], "sections": [{"num": "1", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Pick the correct answer to the question: May I try to make a pot?", "a": "No, you need a lot of practice before you can make a pot. (Answer 1 — example given in the book.)"}, {"q": "Pick the correct answer to the question: Can I put these pots in the sun?", "a": "Yes, you can help your aunt by putting the pots in the sun. (Answer 2.)"}, {"q": "Pick the correct answer to the question: Can we play now, Sara?", "a": "No, we will play after I have made patterns on the bowl. (Answer 3.)"}, {"q": "Pick the correct answer to the question: Can I go with Uncle Jumman, Saleh?", "a": "Yes, please go with him. I'll finish painting this bowl then I'll play with you. (Answer 4.)"}, {"q": "Pick the correct answer to the question: May I see what's inside the kiln?", "a": "Yes, but don't go too near because the kiln is very hot. (Answer 5.)"}, {"q": "Pick the correct answer to the question: Can I help you make the clay paste, Uncle Jumman?", "a": "Yes, you can help by putting water in the clay while I mix it. (Answer 6.)"}]}]}, {"num": "2", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Write three questions that you can ask your teacher to get permission to do something. (One should begin with 'may' and one with 'can'.)", "a": "1. May I come in, please?\n2. Can I borrow your book, please?\n3. May I go to the washroom, please?"}, {"q": "Write three questions that you can ask your parents to get permission to do something. (One should begin with 'may' and one with 'can'.)", "a": "1. May I go out to play, please?\n2. Can I watch TV, please?\n3. May I eat an ice cream, please?"}]}]}, {"num": "3", "name": "Exercise 8", "exercises": [{"label": "Exercise 8", "items": [{"q": "Fill in the blank with the correct preposition: Allah Wasayo's house is ______ the fields.", "a": "Allah Wasayo's house is near the fields. (Example given in the book.)"}, {"q": "Fill in the blank with the correct preposition: The mosque is ______ the house.", "a": "The mosque is in front of the house."}, {"q": "Fill in the blank with the correct preposition: While walking ______ the field he sees the sun rising in the east.", "a": "While walking towards the field he sees the sun rising in the east."}, {"q": "Fill in the blank with the correct preposition: He meets Bachal ______ the corner of the path.", "a": "He meets Bachal at the corner of the path."}, {"q": "Fill in the blank with the correct preposition: Both of them work hard ______ the fields all day.", "a": "Both of them work hard in the fields all day."}, {"q": "Fill in the blank with the correct preposition: In the evening Allah Wasayo and Bachal walk ______ their home.", "a": "In the evening Allah Wasayo and Bachal walk towards their home."}, {"q": "Fill in the blank with the correct preposition: Allah Wasayo is thankful ______ Allah for a safe and peaceful day.", "a": "Allah Wasayo is thankful to Allah for a safe and peaceful day."}]}]}], "words": [{"w": "preposition", "sd": "حرف جر", "syn": "a word that shows the place or position of a thing"}, {"w": "permission", "sd": "اجازت", "syn": "allowing somebody to do something"}]}, {"cls": "v", "unit": 6, "title": "Degrees of Adjectives", "display": "Degrees of Adjectives", "reading": "My English Book 5, Units 3, 4 and 5, Grammar", "lesson": [{"t": "h", "x": "Degrees of Adjectives"}, {"t": "p", "x": "Adjectives have three degrees: positive, comparative and superlative. We use them to compare things."}, {"t": "def", "x": "The positive degree is the simple form. The comparative degree compares two things. The superlative degree compares one thing with all the others."}, {"t": "h", "x": "Rule 1. The positive degree is the simple form"}, {"t": "rule", "x": "The positive degree is the adjective itself: tall, short, big, small, happy, good."}, {"t": "ex", "x": "Ali is tall. The mango is sweet. She is happy."}, {"t": "h", "x": "Rule 2. Add 'er' and 'than' for the comparative"}, {"t": "rule", "x": "To compare two things, add 'er' to the adjective and use 'than' after it."}, {"t": "ex", "x": "Shamim is taller than me. The donkey is shorter than the camel. Ali is older than Ahmed."}, {"t": "h", "x": "Rule 3. Add 'est' and 'the' for the superlative"}, {"t": "rule", "x": "To compare one thing with all the others, use 'the' and add 'est' to the adjective."}, {"t": "ex", "x": "Bilal is the tallest boy. Arif is the heaviest student. This is the easiest sum."}, {"t": "h", "x": "Rule 4. Long adjectives use 'more' and 'most'"}, {"t": "rule", "x": "For long adjectives, use 'more' for the comparative and 'most' for the superlative."}, {"t": "ex", "x": "beautiful — more beautiful — most beautiful, useful — more useful — most useful, difficult — more difficult — most difficult."}, {"t": "h", "x": "Rule 5. Some adjectives change in a special way"}, {"t": "rule", "x": "Some adjectives do not take 'er' and 'est': good — better — best, bad — worse — worst, little — less — least."}, {"t": "ex", "x": "good — better — best, bad — worse — worst, much — more — most."}, {"t": "rl", "x": "At school, Ali is tall. Ahmed is taller than Ali. Bilal is the tallest boy in our class."}, {"t": "rl", "x": "At home, my bag is heavy. My brother's bag is heavier than mine. My father's bag is the heaviest."}, {"t": "rl", "x": "In the market, this mango is sweet. That mango is sweeter. The mango in that shop is the sweetest of all."}, {"t": "note", "x": "Use 'than' after the comparative and 'the' before the superlative."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Read the text and answer: Which one is taller, the donkey or the camel? (Text: Samad went to Karachi to visit his cousin Ahmed. Ahmed lived in a flat on the first floor. In the evening Samad and Ahmed stood on the balcony and looked at the traffic on the road below. There were all sorts of carts, cars and buses on the road. Samad: Look at the camel cart. It is bigger than the donkey cart. Ahmed: Yes. That is because the camel is taller than the donkey. Samad: And the camel cart is also moving slower than the donkey cart. Ahmed: Carts are never very fast. I like cars because they are smaller and faster than buses. Samad: I also like cars but they cost a lot of money. Ahmed: Yes, they do. But bicycles are cheaper, so I will buy a bicycle first. Perhaps, I will have a car of my own one day.)", "a": "The camel is taller than the donkey. (Example given in the book.)"}, {"q": "Read the text and answer: Which one is bigger, a camel cart or a donkey cart?", "a": "The camel cart is bigger than the donkey cart."}, {"q": "Read the text and answer: Which one moves slower, a camel cart or a donkey cart?", "a": "The camel cart moves slower than the donkey cart."}, {"q": "Read the text and answer: Which is smaller, a bus or a car?", "a": "A car is smaller than a bus."}, {"q": "Read the text and answer: Which one moves faster, a bus or a car?", "a": "A car moves faster than a bus."}, {"q": "Read the text and answer: Which one is cheaper, a car or a bicycle?", "a": "A bicycle is cheaper than a car."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Read the facts below and fill in the blanks with the words given, using the 'er' + than form:\n[[T]]S.No.|Physical Feature|Size;;1.|Atlantic Ocean|large;;2.|Indian Ocean|small;;3.|River Nile|long;;4.|River Indus|short;;5.|Mount Everest|high;;6.|K2|low[[/T]]\nExample: The Atlantic Ocean is ______ than the Indian Ocean. (large)", "a": "The Atlantic Ocean is larger than the Indian Ocean. (Example given in the book.)"}, {"q": "Fill in the blank using the 'er' + than form: The Mount Everest is ______ than K2. (high)", "a": "The Mount Everest is higher than K2."}, {"q": "Fill in the blank using the 'er' + than form: The River Indus is ______ than the River Nile. (short)", "a": "The River Indus is shorter than the River Nile."}, {"q": "Fill in the blank using the 'er' + than form: The Indian Ocean is ______ than the Atlantic Ocean. (small)", "a": "The Indian Ocean is smaller than the Atlantic Ocean."}, {"q": "Fill in the blank using the 'er' + than form: The River Nile is ______ than the River Indus. (long)", "a": "The River Nile is longer than the River Indus."}, {"q": "Fill in the blank using the 'er' + than form: K2 is ______ than Mount Everest. (low)", "a": "K2 is lower than Mount Everest."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Write six complete sentences using taller / shorter / older / younger. Example: Shamim is taller than me.", "a": "Shamim is taller than me. (Example given in the book.)"}, {"q": "Write a sentence using 'taller': Ali / taller / me", "a": "Ali is taller than me."}, {"q": "Write a sentence using 'shorter': Sara / shorter / me", "a": "Sara is shorter than me."}, {"q": "Write a sentence using 'older': Ahmed / older / me", "a": "Ahmed is older than me."}, {"q": "Write a sentence using 'younger': Fatima / younger / me", "a": "Fatima is younger than me."}, {"q": "Write a sentence using 'taller': Bilal / taller / Ali", "a": "Bilal is taller than Ali."}, {"q": "Write a sentence using 'younger': Ayesha / younger / Sara", "a": "Ayesha is younger than Sara."}]}]}, {"num": "4", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Complete the table of degrees of adjectives: tall", "a": "1. tall — taller — tallest."}, {"q": "Complete the table of degrees of adjectives: clean", "a": "2. clean — cleaner — cleanest."}, {"q": "Complete the table of degrees of adjectives: pretty", "a": "3. pretty — prettier — prettiest."}, {"q": "Complete the table of degrees of adjectives: small", "a": "4. small — smaller — smallest."}, {"q": "Complete the table of degrees of adjectives: slow", "a": "5. slow — slower — slowest."}, {"q": "Complete the table of degrees of adjectives: dirty", "a": "6. dirty — dirtier — dirtiest."}, {"q": "Complete the table of degrees of adjectives: sweet", "a": "7. sweet — sweeter — sweetest."}, {"q": "Complete the table of degrees of adjectives: fast", "a": "8. fast — faster — fastest."}, {"q": "Complete the table of degrees of adjectives: tasty", "a": "9. tasty — tastier — tastiest."}, {"q": "Complete the table of degrees of adjectives: short", "a": "10. short — shorter — shortest."}]}]}, {"num": "5", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Fill in the gaps in the table with the correct word from the list: happy, least, beautiful, better, bad, more useful, early, most, less, worse, earliest, more, happier, most useful, best, most beautiful. Row 1: good — ______ — ______", "a": "1. good — better — best. (Word list: happy, least, beautiful, better, bad, more useful, early, most, less, worse, earliest, more, happier, most useful, best, most beautiful.)"}, {"q": "Complete the table row: bad — ______ — ______", "a": "2. bad — worse — worst."}, {"q": "Complete the table row: early — ______ — ______", "a": "3. early — earlier — earliest."}, {"q": "Complete the table row: many — ______ — ______", "a": "4. many — more — most."}, {"q": "Complete the table row: little — ______ — ______", "a": "5. little — lesser — least. (The word list in the book gives 'less' but the table needs 'little' for this row; 'little' is not in the list. See the flags file.)"}, {"q": "Complete the table row: useful — ______ — ______", "a": "6. useful — more useful — most useful."}, {"q": "Complete the table row: happy — ______ — ______", "a": "7. happy — happier — happiest."}, {"q": "Complete the table row: beautiful — ______ — ______", "a": "8. beautiful — more beautiful — most beautiful."}]}]}, {"num": "6", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Read the table and complete the sentence with the superlative degree:\n[[T]]Student|Weight|Height|Marks|Runs;;Arif Rahim|62 kg|4'8\"|509|143;;Bachal Allahyar|79 kg|4'4\"|583|109;;Latif Memon|74 kg|4'9\"|533|179;;Nasir Mureed|69 kg|4'2\"|574|184;;Peer Bakhsh|63 kg|4'5\"|594|112[[/T]]\nBachal Allahyar is the ______ boy in the class.", "a": "Bachal Allahyar is the heaviest boy in the class. (Example given in the book.)"}, {"q": "Complete the sentence with the superlative degree: Peer Bakhsh got the ______ marks in the class.", "a": "Peer Bakhsh got the highest marks in the class."}, {"q": "Complete the sentence with the superlative degree: Bachal Allahyar scored the ______ runs in the class match.", "a": "Bachal Allahyar scored the lowest runs in the class match."}, {"q": "Complete the sentence with the superlative degree: Nasir Mureed is the ______ student in the class.", "a": "Nasir Mureed is the shortest student in the class."}, {"q": "Complete the sentence with the superlative degree: Arif Rahim got the ______ marks in the class.", "a": "Arif Rahim got the lowest marks in the class."}, {"q": "Complete the sentence with the superlative degree: Nasir Mureed scored the ______ runs in the class match.", "a": "Nasir Mureed scored the highest runs in the class match."}, {"q": "Complete the sentence with the superlative degree: Latif Memon is the ______ student in the class.", "a": "Latif Memon is the tallest student in the class."}, {"q": "Complete the sentence with the superlative degree: Arif Rahim is the ______ boy in the class.", "a": "Arif Rahim is the lightest boy in the class."}]}]}], "words": [{"w": "adjective", "sd": "صفت", "syn": "a word that describes a noun"}, {"w": "positive degree", "sd": "سادو درجو", "syn": "the simple form of an adjective"}, {"w": "comparative degree", "sd": "تقابلي درجو", "syn": "the form used to compare two things"}, {"w": "superlative degree", "sd": "اعليٰ درجو", "syn": "the form used to compare one thing with all the others"}]}, {"cls": "v", "unit": 7, "title": "WH Questions and Short Answers", "display": "WH Questions and Short Answers", "reading": "My English Book 5, Unit 3, Grammar", "lesson": [{"t": "h", "x": "WH Questions and Short Answers"}, {"t": "p", "x": "WH questions begin with what, where, when, who or why. Short answers answer a question in a few words."}, {"t": "def", "x": "A WH question asks for information. A short answer answers it briefly, with the verb and the subject."}, {"t": "h", "x": "Rule 1. Make a WH question from a sentence"}, {"t": "rule", "x": "To ask a WH question, put the WH word first, then the verb, then the subject."}, {"t": "ex", "x": "The children are eating mangoes. What are the children eating? They are eating mangoes. Where are the children eating? In the garden."}, {"t": "h", "x": "Rule 2. 'What' asks about a thing, 'where' about a place"}, {"t": "rule", "x": "Use 'what' for a thing or an action, 'where' for a place, 'when' for a time, 'who' for a person, 'why' for a reason."}, {"t": "ex", "x": "What are you doing? I am reading. Where are you going? I am going to school. When will you come? Tomorrow. Who is he? He is Ali. Why are you late? Because I was ill."}, {"t": "h", "x": "Rule 3. Give a short answer"}, {"t": "rule", "x": "Answer a question briefly: 'What are the children eating?' — 'Mangoes.' 'Are you going to school?' — 'Yes, I am.'"}, {"t": "ex", "x": "What are you eating? Rice. Where is Ali? At home. Are you happy? Yes, I am."}, {"t": "rl", "x": "At school, the teacher asks, 'What are you doing?' I say, 'I am writing.' She asks, 'Where is your book?' I say, 'In my bag.'"}, {"t": "rl", "x": "At home, my mother asks, 'When will you come back?' I say, 'At five o'clock.' My father asks, 'Who is your friend?' I say, 'Ahmed.'"}, {"t": "rl", "x": "In the market, the shopkeeper asks, 'What do you want?' I say, 'A kite.' He asks, 'Why do you want it?' I say, 'To play with my friends.'"}, {"t": "note", "x": "A question ends with a question mark (?)."}], "sections": [{"num": "1", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Re-arrange the words to make a question: the children are what doing", "a": "What are the children doing? (Example given in the book.)"}, {"q": "Re-arrange the words to make a question: your mother going where is", "a": "Where is your mother going?"}, {"q": "Re-arrange the words to make a question: the little girl is what eating", "a": "What is the little girl eating?"}, {"q": "Re-arrange the words to make a question: book this why you are reading", "a": "Why are you reading this book?"}, {"q": "Re-arrange the words to make a question: my house are you when coming to", "a": "When are you coming to my house?"}, {"q": "Re-arrange the words to make a question: brother your is why crying", "a": "Why is your brother crying?"}, {"q": "Re-arrange the words to make a question: can you get how good marks", "a": "How can you get good marks?"}, {"q": "Re-arrange the words to make a question: your grandmother does live where", "a": "Where does your grandmother live?"}, {"q": "Re-arrange the words to make a question: favourite colour is what your", "a": "What is your favourite colour?"}, {"q": "Re-arrange the words to make a question: sad is why the little girl", "a": "Why is the little girl sad?"}, {"q": "Re-arrange the words to make a question: today is your mother how feeling", "a": "How is your mother feeling today?"}]}]}, {"num": "2", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Write a short answer to the question: What are the children eating?", "a": "The children are eating food. (Example given in the book.)"}, {"q": "Write a short answer to the question: Where does he live?", "a": "He lives in Badin. (Example given in the book.)"}, {"q": "Write a short answer to the question: Where is your mother going?", "a": "My mother is going to the market."}, {"q": "Write a short answer to the question: What is the little girl eating?", "a": "The little girl is eating food."}, {"q": "Write a short answer to the question: Why are you reading this book?", "a": "I am reading this book because it is interesting."}, {"q": "Write a short answer to the question: When are you coming to my house?", "a": "I am coming to your house tomorrow."}, {"q": "Write a short answer to the question: Why is your brother crying?", "a": "My brother is crying because he is hurt."}, {"q": "Write a short answer to the question: How can you get good marks?", "a": "I can get good marks by working hard."}, {"q": "Write a short answer to the question: Where does your grandmother live?", "a": "My grandmother lives in Karachi."}, {"q": "Write a short answer to the question: What is your favourite colour?", "a": "My favourite colour is green."}, {"q": "Write a short answer to the question: Why is the little girl sad?", "a": "The little girl is sad because she lost her doll."}, {"q": "Write a short answer to the question: How is your mother feeling today?", "a": "My mother is feeling well today."}]}]}], "words": [{"w": "WH question", "sd": "سوالي جملو", "syn": "a question that begins with what, where, when, who, why or how"}, {"w": "short answer", "sd": "مختصر جواب", "syn": "a brief answer to a question"}]}, {"cls": "v", "unit": 8, "title": "Articles A, An and The", "display": "Articles A, An and The", "reading": "My English Book 5, Unit 3, Grammar", "lesson": [{"t": "h", "x": "Articles A, An and The"}, {"t": "p", "x": "A, an and the are articles. We use 'a' and 'an' for one thing in general, and 'the' for a special or known thing."}, {"t": "def", "x": "An article is a word used before a noun. 'A' and 'an' are used for one thing in general. 'The' is used for a special or known thing."}, {"t": "h", "x": "Rule 1. Use 'a' before a consonant sound"}, {"t": "rule", "x": "Use 'a' before a word that begins with a consonant sound."}, {"t": "ex", "x": "a book, a pen, a dress, a boy, a country."}, {"t": "h", "x": "Rule 2. Use 'an' before a vowel sound"}, {"t": "rule", "x": "Use 'an' before a word that begins with a vowel sound (a, e, i, o, u)."}, {"t": "ex", "x": "an apple, an egg, an eye, an elephant, an umbrella, an hour."}, {"t": "h", "x": "Rule 3. Use 'the' for a special or known thing"}, {"t": "rule", "x": "Use 'the' when we talk about a special or known thing, or when there is only one of it."}, {"t": "ex", "x": "The sun rises in the east. The River Indus is the longest river in Pakistan. The book on the table is mine. Pakistan is a big country. The Arabian Sea is in the south."}, {"t": "h", "x": "Rule 4. Use no article before a general plural or uncountable noun"}, {"t": "rule", "x": "Do not use an article before a general plural or uncountable noun."}, {"t": "ex", "x": "Boys play cricket. Milk is good for health. I like mangoes."}, {"t": "rl", "x": "At school, I have a pen and an eraser. The pen is blue. The teacher is in the classroom."}, {"t": "rl", "x": "At home, my mother bought a dress. The dress is red. She gave me an apple."}, {"t": "rl", "x": "In the market, I saw the moon in the sky. The sun is hot. A shopkeeper sells fruit."}, {"t": "note", "x": "Use 'the' the second time we talk about a thing: 'I saw a dog. The dog was black.'"}], "sections": [{"num": "1", "name": "Practice", "exercises": [{"label": "Practice (made from the rules — no exercise in the book for this topic)", "items": [{"q": "Use the rules in this lesson to make three sentences of your own about your school day.", "a": "Answers will differ. Check your sentences against the rules above."}]}]}], "words": [{"w": "article", "sd": "حرف تنڪير", "syn": "a word like a, an or the used before a noun"}, {"w": "definite article", "sd": "حرف تنڪير خاص", "syn": "the article 'the'"}, {"w": "indefinite article", "sd": "حرف تنڪير عام", "syn": "the articles 'a' and 'an'"}]}, {"cls": "v", "unit": 9, "title": "Possessive Adjectives", "display": "Possessive Adjectives", "reading": "My English Book 5, Unit 4, Grammar", "lesson": [{"t": "h", "x": "Possessive Adjectives"}, {"t": "p", "x": "A possessive adjective comes before a noun and shows who owns the noun."}, {"t": "def", "x": "A possessive adjective is a word like my, your, his, her, its, our or their. It comes before a noun and shows ownership."}, {"t": "h", "x": "Rule 1. A possessive adjective comes before a noun"}, {"t": "rule", "x": "A possessive adjective always comes before a noun. It never stands alone."}, {"t": "ex", "x": "my book, your pen, his bat, her doll, its tail, our house, their toys."}, {"t": "h", "x": "Rule 2. Match the possessive adjective with the owner"}, {"t": "rule", "x": "Use 'my' for I, 'your' for you, 'his' for he, 'her' for she, 'its' for it, 'our' for we, 'their' for they."}, {"t": "ex", "x": "I have a book. My book is new. Ali has a bat. His bat is new. Sana has a doll. Her doll is new."}, {"t": "h", "x": "Rule 3. Do not mix up possessive adjectives and possessive pronouns"}, {"t": "rule", "x": "A possessive adjective needs a noun after it (my book). A possessive pronoun stands alone (The book is mine)."}, {"t": "ex", "x": "This is my pen. The pen is mine. This is her bag. The bag is hers. This is our house. The house is ours."}, {"t": "rl", "x": "At school, this is my book and that is your book. His bag is red and her bag is blue."}, {"t": "rl", "x": "At home, my mother cooks our food. The dog wags its tail. Their house is near our house."}, {"t": "rl", "x": "In the market, the shopkeeper sells his fruit. I buy mangoes with my money."}, {"t": "note", "x": "Do not write an apostrophe in possessive adjectives: 'its', not 'it's'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Rewrite the jumbled sentence in the correct order and underline the possessive adjective: near house my he lives (Example given in the book.)", "a": "He lives near my house. (The possessive adjective 'my' is underlined in the book.)"}, {"q": "Rewrite the jumbled sentence in the correct order and underline the possessive adjective: with his mother was walking the little boy", "a": "The little boy was walking with his mother. (The possessive adjective 'his' is underlined in the book.)"}, {"q": "Rewrite the jumbled sentence in the correct order and underline the possessive adjectives: my book has lost her new sister", "a": "Her new sister has lost my book. (The possessive adjectives 'Her' and 'my' are underlined in the book.)"}, {"q": "Rewrite the jumbled sentence in the correct order and underline the possessive adjective: lahore have gone to their parents", "a": "Their parents have gone to Lahore. (The possessive adjective 'Their' is underlined in the book.)"}, {"q": "Rewrite the jumbled sentence in the correct order and underline the possessive adjectives: with her was angry her teacher", "a": "Her teacher was angry with her. (The possessive adjectives 'Her' and 'her' are underlined in the book.)"}, {"q": "Rewrite the jumbled sentence in the correct order and underline the possessive adjectives: good friends are my brother and your brother", "a": "My brother and your brother are good friends. (The possessive adjectives 'My' and 'your' are underlined in the book.)"}, {"q": "Rewrite the jumbled sentence in the correct order and underline the possessive adjective: sold our old car we have", "a": "We have sold our old car. (The possessive adjective 'our' is underlined in the book.)"}, {"q": "Rewrite the jumbled sentence in the correct order and underline the possessive adjective: its paw the cat is licking", "a": "The cat is licking its paw. (The possessive adjective 'its' is underlined in the book.)"}]}]}], "words": [{"w": "possessive adjective", "sd": "ملڪيتي صفت", "syn": "a word like my or his that comes before a noun and shows ownership"}, {"w": "possessive pronoun", "sd": "ملڪيتي ضمير", "syn": "a pronoun like mine or hers that stands alone"}]}, {"cls": "v", "unit": 10, "title": "Used To", "display": "Used To", "reading": "My English Book 5, Unit 4, Grammar", "lesson": [{"t": "h", "x": "Used To"}, {"t": "p", "x": "We use 'used to' to talk about a habit or a thing that happened often in the past but does not happen now."}, {"t": "def", "x": "'Used to' + verb is used for a past habit or a past thing that is finished now."}, {"t": "h", "x": "Rule 1. Use 'used to' for a past habit"}, {"t": "rule", "x": "Use 'used to' with the verb to talk about something we did often in the past."}, {"t": "ex", "x": "I used to play in the street when I was small. My grandmother used to tell me stories. We used to live in a village."}, {"t": "h", "x": "Rule 2. 'Used to' is always in the past"}, {"t": "rule", "x": "'Used to' always talks about the past. Do not use it for the present."}, {"t": "ex", "x": "Rani's grandmother used to be very naughty. (She is not naughty now.) My father used to walk to school. (He does not walk now.)"}, {"t": "h", "x": "Rule 3. After 'used to', use the verb without 's' or 'ed'"}, {"t": "rule", "x": "After 'used to', use the first form of the verb."}, {"t": "ex", "x": "I used to play. She used to read. They used to go to school. He used to drink milk."}, {"t": "rl", "x": "When I was in Class I, I used to play with toys. Now I play cricket."}, {"t": "rl", "x": "At home, my grandmother used to cook on a stove. Now she cooks on a gas cooker."}, {"t": "rl", "x": "In our village, my grandfather used to walk to the market. Now he rides a bicycle."}, {"t": "note", "x": "Do not write 'use to' for the past habit. The past form is always 'used to'."}], "sections": [{"num": "1", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Write a sentence with 'used to': Rani's grandmother / be very naughty", "a": "Rani's grandmother used to be very naughty."}, {"q": "Write a sentence with 'used to': Rani's grandmother / climb trees", "a": "Rani's grandmother used to climb trees."}, {"q": "Write a sentence with 'used to': Rani's grandmother / waste a lot of water", "a": "Rani's grandmother used to waste a lot of water."}]}]}, {"num": "2", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Write five sentences about what you used to do when you were in Class I / II / III. (Sentence 1)", "a": "When I was in Class One I used to collect feathers. (Example given in the book.)"}, {"q": "Write five sentences about what you used to do when you were in Class I / II / III. (Sentence 2)", "a": "When I was in Class One I used to play with toys."}, {"q": "Write five sentences about what you used to do when you were in Class I / II / III. (Sentence 3)", "a": "When I was in Class One I used to drink milk every morning."}, {"q": "Write five sentences about what you used to do when you were in Class I / II / III. (Sentence 4)", "a": "When I was in Class Two I used to ride a bicycle."}, {"q": "Write five sentences about what you used to do when you were in Class I / II / III. (Sentence 5)", "a": "When I was in Class Two I used to watch cartoons."}]}]}, {"num": "3", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Write ten sentences about what your grandparents and parents used to do when they were of your age. (Sentence 1)", "a": "My grandfather used to walk to school every day. (Example given in the book.)"}, {"q": "Write ten sentences about what your grandparents and parents used to do when they were of your age. (Sentence 2)", "a": "My grandfather used to play hockey in his school."}, {"q": "Write ten sentences about what your grandparents and parents used to do when they were of your age. (Sentence 3)", "a": "My grandmother used to cook food on a mud stove."}, {"q": "Write ten sentences about what your grandparents and parents used to do when they were of your age. (Sentence 4)", "a": "My grandmother used to tell us stories at night."}, {"q": "Write ten sentences about what your grandparents and parents used to do when they were of your age. (Sentence 5)", "a": "My grandmother used to wear a long frock."}, {"q": "Write ten sentences about what your grandparents and parents used to do when they were of your age. (Sentence 6)", "a": "My father used to read books in the evening."}, {"q": "Write ten sentences about what your grandparents and parents used to do when they were of your age. (Sentence 7)", "a": "My father used to help his father in the fields."}, {"q": "Write ten sentences about what your grandparents and parents used to do when they were of your age. (Sentence 8)", "a": "My mother used to go to school on foot."}, {"q": "Write ten sentences about what your grandparents and parents used to do when they were of your age. (Sentence 9)", "a": "My mother used to play hide and seek with her friends."}, {"q": "Write ten sentences about what your grandparents and parents used to do when they were of your age. (Sentence 10)", "a": "My mother used to drink milk every morning."}]}]}], "words": [{"w": "used to", "sd": "عادت هئي", "syn": "a phrase for a past habit that is finished now"}, {"w": "habit", "sd": "عادت", "syn": "something we do often"}]}, {"cls": "v", "unit": 11, "title": "Main and Helping Verbs", "display": "Main and Helping Verbs", "reading": "My English Book 5, Unit 4, Grammar", "lesson": [{"t": "h", "x": "Main and Helping Verbs"}, {"t": "p", "x": "In a sentence, the main verb shows the action. A helping verb helps the main verb. Together they make the verb part of the sentence."}, {"t": "def", "x": "The main verb shows the action. A helping verb (is, am, are, was, were, do, does, did, can, will) helps the main verb."}, {"t": "h", "x": "Rule 1. The main verb shows the action"}, {"t": "rule", "x": "The main verb tells us what the subject does."}, {"t": "ex", "x": "I do my work on time. She reads a book. They play cricket. He writes a letter."}, {"t": "h", "x": "Rule 2. A helping verb comes before the main verb"}, {"t": "rule", "x": "A helping verb comes before the main verb: is reading, was playing, will go, can swim, do work."}, {"t": "ex", "x": "I am reading a book. She was playing. He will go to school. I can swim. Do you like mangoes?"}, {"t": "h", "x": "Rule 3. 'Do' can be a main verb or a helping verb"}, {"t": "rule", "x": "'Do' is a main verb when it shows the action: 'I do my work.' It is a helping verb when it helps another verb: 'Do you like mangoes?' 'I do not like milk.'"}, {"t": "ex", "x": "I do my homework. (main verb) Do you do your homework? (helping verb) She does not play here. (helping verb)"}, {"t": "h", "x": "Rule 4. Find the main verb and the helping verb"}, {"t": "rule", "x": "In 'I am reading a book', 'reading' is the main verb and 'am' is the helping verb. In 'She will come', 'come' is the main verb and 'will' is the helping verb."}, {"t": "ex", "x": "I always do my work on time. (do = main verb) I am doing my work. (doing = main verb, am = helping verb)"}, {"t": "rl", "x": "At school, I do my work on time. My teacher is checking our notebooks. She will give us the results tomorrow."}, {"t": "rl", "x": "At home, my mother is cooking food. I can help her. My father does the shopping."}, {"t": "rl", "x": "In the market, the shopkeeper is selling fruit. I do not buy unripe mangoes. He will give me a discount."}, {"t": "note", "x": "A sentence can have one verb (main verb only) or two verbs (helping verb + main verb)."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Write M (main verb) or H (helping verb) for the sentence: I always do my work on time.", "a": "M — 'do' is used as a main verb in this sentence. (Example given in the book: I always do my work on time.)"}, {"q": "Write M (main verb) or H (helping verb) for the sentence: They do not talk loudly in the class.", "a": "H — 'do' is used as a helping verb in this sentence. (Example given in the book: They do not talk loudly in the class.)"}, {"q": "Write M (main verb) or H (helping verb) for the sentence: We have two cows and five goats.", "a": "M — 'have' is used as a main verb in this sentence. (Example given in the book: We have two cows and five goats.)"}, {"q": "Write M (main verb) or H (helping verb) for the sentence: You have eaten two bananas.", "a": "H — 'have' is used as a helping verb in this sentence. (Example given in the book: You have eaten two bananas.)"}, {"q": "Write M (main verb) or H (helping verb) for the sentence: We must always do as our parents tell us.", "a": "M — 'do' is used as a main verb in this sentence."}, {"q": "Write M (main verb) or H (helping verb) for the sentence: They have finished their work before time.", "a": "H — 'have' is used as a helping verb in this sentence."}, {"q": "Write M (main verb) or H (helping verb) for the sentence: She is a nice person and does many good things.", "a": "M — 'does' is used as a main verb in this sentence."}, {"q": "Write M (main verb) or H (helping verb) for the sentence: Our teacher has said that she will take our test next week.", "a": "H — 'has' is used as a helping verb in this sentence."}, {"q": "Write M (main verb) or H (helping verb) for the sentence: The doctors have agreed to work in villages once every week.", "a": "H — 'have' is used as a helping verb in this sentence."}, {"q": "Write M (main verb) or H (helping verb) for the sentence: You do your homework now and play in the evening.", "a": "M — 'do' is used as a main verb in this sentence."}, {"q": "Write M (main verb) or H (helping verb) for the sentence: My father does not drink tea at night.", "a": "H — 'does' is used as a helping verb in this sentence."}, {"q": "Write M (main verb) or H (helping verb) for the sentence: The soldiers do their duty and help us in all difficult times.", "a": "M — 'do' is used as a main verb in this sentence."}, {"q": "Write M (main verb) or H (helping verb) for the sentence: I have not paid my school fees as yet.", "a": "H — 'have' is used as a helping verb in this sentence."}, {"q": "Write M (main verb) or H (helping verb) for the sentence: My grandfather has a big house in the village.", "a": "M — 'has' is used as a main verb in this sentence."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Write two sentences using 'do' as a main verb. (Sentence 1)", "a": "'do' as a main verb: I do my homework every day."}, {"q": "Write two sentences using 'do' as a main verb. (Sentence 2)", "a": "'do' as a main verb: She does her work on time."}, {"q": "Write two sentences using 'do' as a helping verb. (Sentence 1)", "a": "'do' as a helping verb: Do you play cricket?"}, {"q": "Write two sentences using 'do' as a helping verb. (Sentence 2)", "a": "'do' as a helping verb: She does not eat meat."}, {"q": "Write two sentences using 'have' as a main verb. (Sentence 1)", "a": "'have' as a main verb: I have two brothers."}, {"q": "Write two sentences using 'have' as a main verb. (Sentence 2)", "a": "'have' as a main verb: He has a new bicycle."}, {"q": "Write two sentences using 'have' as a helping verb. (Sentence 1)", "a": "'have' as a helping verb: I have finished my work."}, {"q": "Write two sentences using 'have' as a helping verb. (Sentence 2)", "a": "'have' as a helping verb: She has gone to school."}]}]}], "words": [{"w": "main verb", "sd": "اصل فعل", "syn": "the verb that shows the action"}, {"w": "helping verb", "sd": "مددگار فعل", "syn": "a verb that helps the main verb"}]}, {"cls": "vi", "unit": 1, "title": "Must, Must Not, Should and Should Not", "display": "Must, Must Not, Should and Should Not", "reading": "My English Book 6, Unit 1, Language Practice", "lesson": [{"t": "h", "x": "Must, Must Not, Should and Should Not"}, {"t": "p", "x": "We use 'must' for a rule that we have to follow, and 'should' for good advice. 'Must not' and 'should not' tell us what we must not do and what we should not do."}, {"t": "def", "x": "'Must' shows a rule or a strong duty. 'Should' shows advice. 'Must not' forbids something. 'Should not' advises against something."}, {"t": "h", "x": "Rule 1. Use 'must' for a rule"}, {"t": "rule", "x": "Use 'must' when something is a rule or a duty that we have to follow."}, {"t": "ex", "x": "We must follow the park rules. You must come to school on time. You must wear your school uniform. We must protect our public places."}, {"t": "h", "x": "Rule 2. Use 'must not' to forbid something"}, {"t": "rule", "x": "Use 'must not' (mustn't) when something is not allowed."}, {"t": "ex", "x": "You must not write on the walls. You must not throw trash in the park. You must not shout in class."}, {"t": "h", "x": "Rule 3. Use 'should' for advice"}, {"t": "rule", "x": "Use 'should' to give good advice."}, {"t": "ex", "x": "You should respect your teachers. You should keep your classroom clean. We should teach others to keep public places clean. You should treat animals kindly."}, {"t": "h", "x": "Rule 4. Use 'should not' to advise against something"}, {"t": "rule", "x": "Use 'should not' (shouldn't) to advise somebody not to do something."}, {"t": "ex", "x": "You should not throw your ice cream wrapper on the ground. You should not throw rubbish in the streets. You should not waste water."}, {"t": "h", "x": "Rule 5. After must and should, use the verb without 's' or 'ed'"}, {"t": "rule", "x": "After must, must not, should and should not, use the first form of the verb."}, {"t": "ex", "x": "You must come. You should go. He must not shout. She should not waste."}, {"t": "rl", "x": "At school, we must come on time and we must wear our uniform. We should listen to our teacher."}, {"t": "rl", "x": "At home, I should help my mother. I must not waste food. I should keep my room clean."}, {"t": "rl", "x": "In the market, we must not throw rubbish on the road. We should use a dustbin. We must follow the rules of the park."}, {"t": "note", "x": "'Must' is stronger than 'should'. A rule uses 'must'; advice uses 'should'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Work in pairs and find out all the statements using should/should not and must/must not from the reading text in section 1.1. Fill them in the table below. Write the statements using should/should not.", "a": "Should/should not statements from the reading text: 1. You should not throw your ice cream wrapper on the ground, Hamza! 2. If we want a clean and beautiful Pakistan, we should try and make it one. 3. We should teach others how to keep the public places clean. 4. You should use it wisely! (This Public Park is for your benefit.)"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Work in groups of four. In your notebooks, write ADVICE at the top of one page and RULES at the top of another page. Now discuss in your groups and write at least five pieces of advice that you can give to your friends. Write five pieces of advice.", "a": "Model advice (using should/should not): 1. You should treat animals kindly. (Example given in the book.) 2. You should respect your teachers and elders. 3. You should keep your classroom clean. 4. You should not throw rubbish in the streets. 5. You should help your friends in their studies. 6. You should not waste water. (Any sensible advice is acceptable.)"}, {"q": "Similarly, write five rules that your friends must follow.", "a": "Model rules (using must/must not): 1. You must not shout in class. (Example given in the book.) 2. You must come to school on time. 3. You must wear your school uniform. 4. You must not write on the walls of the school. 5. You must listen to your teacher. 6. You must not run in the classroom. (Any sensible rules are acceptable.)"}]}]}], "words": [{"w": "must", "sd": "ضرور", "syn": "shows a rule or strong duty"}, {"w": "should", "sd": "گهرجي", "syn": "shows advice"}, {"w": "advice", "sd": "صلاح", "syn": "good words that tell somebody what to do"}, {"w": "rule", "sd": "قاعدو", "syn": "something we have to follow"}]}, {"cls": "vi", "unit": 2, "title": "Present Continuous Tense", "display": "Present Continuous Tense", "reading": "My English Book 6, Unit 1, Language Practice", "lesson": [{"t": "h", "x": "Present Continuous Tense"}, {"t": "p", "x": "The present continuous tense tells us about an action that is happening right now."}, {"t": "def", "x": "The present continuous tense is used for an action happening now. We make it with is, am or are and the verb with 'ing'."}, {"t": "h", "x": "Rule 1. Make it with is/am/are + verb + ing"}, {"t": "rule", "x": "Use is, am or are with the verb + ing."}, {"t": "ex", "x": "I am reading. He is playing. She is cooking. We are going. They are eating. Saba is climbing a tree. Asad is eating an ice cream."}, {"t": "h", "x": "Rule 2. Use it for an action happening now"}, {"t": "rule", "x": "Use the present continuous tense when the action is happening at this very moment."}, {"t": "ex", "x": "Look! The children are playing in the park. The teacher is writing on the board. It is raining now."}, {"t": "h", "x": "Rule 3. Use it for a plan that is fixed"}, {"t": "rule", "x": "We also use it for a plan that is already fixed for today or tomorrow."}, {"t": "ex", "x": "We are going to Karachi tomorrow. I am visiting my uncle on Sunday. Our class is having an Eid Milan party."}, {"t": "rl", "x": "At school, the teacher is teaching us English now. The boys are writing in their notebooks."}, {"t": "rl", "x": "At home, my mother is cooking biryani. My father is watching the news. I am doing my homework."}, {"t": "rl", "x": "In the park, Saba is climbing a tree and Rafiq is flying a kite. Beena and John are playing cricket."}, {"t": "note", "x": "Do not forget the be verb: say 'He is playing', not 'He playing'."}], "sections": [{"num": "1", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Look at the picture given below and write a paragraph in your notebook about what the children are doing in the park. You can write like this (choose only one phrase from the highlighted ones; choose different phrases for the topic sentence and the concluding sentence): All the children are enjoying themselves/are having a good time/are having fun in the park. Saba is ______. Asad ______. Beena, John, Kumar and Sita ______. Rafiq ______. Rani ______. Zahid ______. In short, all of them are having a good time/are having fun/are enjoying themselves in the park.", "a": "Model paragraph: All the children are enjoying themselves in the park. Saba is climbing a tree. Rani is sitting on a bench. Asad is eating an ice cream. Rafiq is flying a kite. Beena, John, Kumar and Sita are playing cricket. Zahid is sleeping under a tree. In short, all of them are having a good time in the park."}]}]}], "words": [{"w": "present continuous tense", "sd": "زمان حال جاري", "syn": "the tense for an action happening now"}]}, {"cls": "vi", "unit": 3, "title": "Pronouns as Reference Words", "display": "Pronouns as Reference Words", "reading": "My English Book 6, Unit 2, Language Practice", "lesson": [{"t": "h", "x": "Pronouns as Reference Words"}, {"t": "p", "x": "A pronoun is a word used in place of a noun. As a reference word, a pronoun points back to a noun we have already named, so we do not repeat the name."}, {"t": "def", "x": "A pronoun used as a reference word stands for a noun named earlier in the text. It helps the text hold together."}, {"t": "h", "x": "Rule 1. A pronoun points back to a noun"}, {"t": "rule", "x": "When a noun has been named, we use a pronoun for it later. The pronoun must match the noun in number and gender."}, {"t": "ex", "x": "Ahmed is my friend. He is kind. Sana is my sister. She is tall. The book is on the table. It is new."}, {"t": "h", "x": "Rule 2. Reflexive pronouns point back to the subject"}, {"t": "rule", "x": "A reflexive pronoun ends in 'self' (singular) or 'selves' (plural): myself, yourself, himself, herself, itself, ourselves, yourselves, themselves. It points back to the subject."}, {"t": "ex", "x": "I am teaching myself to play hockey. He hurt himself. She made the dress herself. They enjoyed themselves."}, {"t": "h", "x": "Rule 3. Match the reflexive pronoun with the subject"}, {"t": "rule", "x": "Use 'myself' with I, 'yourself' with you (one person), 'himself' with he, 'herself' with she, 'itself' with it, 'ourselves' with we, 'yourselves' with you (many people), 'themselves' with they."}, {"t": "ex", "x": "I did it myself. You did it yourself. He did it himself. She did it herself. We did it ourselves. They did it themselves."}, {"t": "rl", "x": "At school, I finished my homework myself. My friend taught himself to draw. The teacher said, 'Do it yourselves.'"}, {"t": "rl", "x": "At home, my sister made a card herself. My brother hurt himself while playing. We cleaned the house ourselves."}, {"t": "rl", "x": "On the cricket ground, the captain hurt himself while catching the ball. The boys enjoyed themselves."}, {"t": "note", "x": "Do not use 'hisself' or 'theirselves'. The correct forms are 'himself' and 'themselves'."}], "sections": [{"num": "1", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Look at the sentences in the following table. Find out the pronoun that is used and put it in the 'Pronoun' column. Who does the pronoun refer to? Find out and write it in the 'Refers to' column. The first two have been done as examples. 1. Aslam is a nice boy. He helps everyone.", "a": "Pronoun: He — Refers to: Aslam. (Example given in the book.)"}, {"q": "2. The soldiers are very brave. They always protect our country.", "a": "Pronoun: They — Refers to: The soldiers. (Example given in the book.)"}, {"q": "3. The train came at 6 o'clock. It was on time.", "a": "Pronoun: It — Refers to: The train."}, {"q": "4. The people clapped loudly. They were very happy because their team had won.", "a": "Pronoun: They — Refers to: The people."}, {"q": "5. My mother was not at home. She had gone to buy some milk.", "a": "Pronoun: She — Refers to: My mother."}, {"q": "6. Zeenat was not feeling well. She had fever.", "a": "Pronoun: She — Refers to: Zeenat."}, {"q": "7. The little boy was hungry. He wanted some food.", "a": "Pronoun: He — Refers to: The little boy."}, {"q": "8. The dog was barking loudly. It had seen a stranger near the door.", "a": "Pronoun: It — Refers to: The dog."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Match the Subjects in Column A with the correct Reflexive Pronouns in Column B to complete the sentences. Column A: 1. Ahmad likes talking to, 2. I did it, 3. Mustafa and Abbas hurt, 4. You must polish your shoes, 5. Ayesha washed her sock, 6. Fatima, Alia and I cleaned it, 7. You must complete the work, 8. The car moved by. Column B: a. themselves, b. herself, c. ourselves, d. himself, e. yourself, f. myself, g. itself, h. Yourselves. 1. Ahmad likes talking to ______.", "a": "1-d — Ahmad likes talking to himself. (Example given in the book.)"}, {"q": "2. I did it ______.", "a": "2-f — I did it myself."}, {"q": "3. Mustafa and Abbas hurt ______.", "a": "3-a — Mustafa and Abbas hurt themselves."}, {"q": "4. You must polish your shoes ______.", "a": "4-e — You must polish your shoes yourself."}, {"q": "5. Ayesha washed her sock ______.", "a": "5-b — Ayesha washed her sock herself."}, {"q": "6. Fatima, Alia and I cleaned it ______.", "a": "6-c — Fatima, Alia and I cleaned it ourselves."}, {"q": "7. You must complete the work ______.", "a": "7-h — You must complete the work yourselves."}, {"q": "8. The car moved by ______.", "a": "8-g — The car moved by itself."}]}]}, {"num": "3", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Fill in the blanks with the correct Reflexive Pronouns. Follow the example. 1) I am teaching myself to play hockey.", "a": "I am teaching myself to play hockey. (Example given in the book.)"}, {"q": "2) Be careful with that knife. You might cut ______. (singular)", "a": "Be careful with that knife. You might cut yourself."}, {"q": "3) Would you two like to get ______ some milk? (plural)", "a": "Would you two like to get yourselves some milk?"}, {"q": "4) We've brought ______ something to eat.", "a": "We've brought ourselves something to eat."}, {"q": "5) I wish the children would behave ______.", "a": "I wish the children would behave themselves."}, {"q": "6) When he opened his eyes he found ______ lying by the side of a road.", "a": "When he opened his eyes he found himself lying by the side of a road."}, {"q": "7) Asifa had to cook for ______.", "a": "Asifa had to cook for herself."}, {"q": "8) The bird was making a nest by ______.", "a": "The bird was making a nest by itself."}]}]}], "words": [{"w": "pronoun", "sd": "ضمير", "syn": "a word used in place of a noun"}, {"w": "reference word", "sd": "حوالو ڏيندڙ لفظ", "syn": "a word that points back to a noun named earlier"}, {"w": "reflexive pronoun", "sd": "انعڪاسي ضمير", "syn": "a pronoun ending in self or selves that points back to the subject"}]}, {"cls": "vi", "unit": 4, "title": "Past Continuous Tense", "display": "Past Continuous Tense", "reading": "My English Book 6, Unit 2, Language Practice", "lesson": [{"t": "h", "x": "Past Continuous Tense"}, {"t": "p", "x": "The past continuous tense tells us about an action that was going on at a time in the past."}, {"t": "def", "x": "The past continuous tense is used for an action that was in progress at a time in the past. We make it with was or were and the verb with 'ing'."}, {"t": "h", "x": "Rule 1. Make it with was/were + verb + ing"}, {"t": "rule", "x": "Use was or were with the verb + ing."}, {"t": "ex", "x": "I was reading. He was playing. She was cooking. We were eating. They were going. What were you doing at 8 o'clock yesterday?"}, {"t": "h", "x": "Rule 2. Use 'was' with I, he, she and it"}, {"t": "rule", "x": "Use 'was' with I, he, she and it, and 'were' with you, we and they."}, {"t": "ex", "x": "I was sleeping. She was singing. We were playing. They were watching TV."}, {"t": "h", "x": "Rule 3. Use it with a time in the past"}, {"t": "rule", "x": "The past continuous goes with a time in the past: at 6 o'clock, yesterday morning, last Sunday."}, {"t": "ex", "x": "What were they doing at 10 o'clock? They were playing cricket. Yesterday at six, I was preparing my lesson."}, {"t": "h", "x": "Rule 4. Past continuous with simple past"}, {"t": "rule", "x": "We often use the past continuous for the longer action and the simple past for the short action that stopped it: 'I was reading when he came.'"}, {"t": "ex", "x": "I was walking to school when it started to rain. She was cooking when the guests arrived."}, {"t": "rl", "x": "Yesterday morning at 8 o'clock, I was going to school. My brother was playing cricket."}, {"t": "rl", "x": "At home last night, my mother was cooking food and my father was reading a newspaper."}, {"t": "rl", "x": "In the market yesterday, the shopkeepers were selling fruit. The children were buying sweets."}, {"t": "note", "x": "The past continuous tells us what was happening; the simple past tells us what happened."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "What were the following people doing at the given times. Write the answers in your notebook. Remember to use 'I' or my mother/father/brother/sister when writing the sentence. Your father at 7 o'clock in the morning — what was he doing?", "a": "Model answer: My father was getting ready for work at 7 o'clock in the morning. (Answers will vary.)"}, {"q": "Your mother when you were in school — what was she doing?", "a": "Model answer: My mother was cooking food when I was in school. (Answers will vary.)"}, {"q": "Your brother/sister at 8 o'clock at night — what was he/she doing?", "a": "Model answer: My brother was watching television at 8 o'clock at night. (Answers will vary.)"}, {"q": "You at 1 o'clock in the afternoon — what were you doing?", "a": "Model answer: I was eating lunch at 1 o'clock in the afternoon. (Answers will vary.)"}, {"q": "Your father when you were having lunch — what was he doing?", "a": "Model answer: My father was having lunch when I was having lunch. (Answers will vary.)"}, {"q": "Your mother at 9 o'clock at night — what was she doing?", "a": "Model answer: My mother was ironing clothes at 9 o'clock at night. (Answers will vary.)"}, {"q": "Your brother/sister at 3 o'clock in the afternoon — what was he/she doing?", "a": "Model answer: My sister was playing with her friends at 3 o'clock in the afternoon. (Answers will vary.)"}, {"q": "You when your mother was cooking lunch — what were you doing?", "a": "Model answer: I was doing my homework when my mother was cooking lunch. (Answers will vary.)"}, {"q": "Your father at 7 o'clock in the evening — what was he doing?", "a": "Model answer: My father was watching the news at 7 o'clock in the evening. (Answers will vary.)"}, {"q": "Your mother at 5 o'clock in the evening — what was she doing?", "a": "Model answer: My mother was making tea at 5 o'clock in the evening. (Answers will vary.)"}, {"q": "Your brother/sister when you were doing your homework — what was he/she doing?", "a": "Model answer: My brother was playing cricket when I was doing my homework. (Answers will vary.)"}, {"q": "You at 11 o'clock at night — what were you doing?", "a": "Model answer: I was sleeping at 11 o'clock at night. (Answers will vary.)"}]}]}, {"num": "2", "name": "Exercise 6 (Past Continuous Tense)", "exercises": [{"label": "Exercise 6 (Past Continuous Tense)", "items": [{"q": "Complete the following story by filling the blanks with the past continuous form of the verb. You can choose the verbs from the list below. Paragraph 1: flow, look, try, sit, sink, thank. Paragraph 2: fly, enjoy, eat, go, run. One day a bird was sitting on a tree near a stream. It ______ down at the water below.", "a": "It was looking down at the water below. (verb: look)"}, {"q": "Suddenly it saw that an ant ______ in the water.", "a": "Suddenly it saw that an ant was sinking in the water. (verb: sink)"}, {"q": "It ______ to get out but the water ______ very fast.", "a": "It was trying to get out but the water was flowing very fast. (verbs: try, flow)"}, {"q": "The ant climbed on the leaf and looked up as if it ______ the bird for saving its life.", "a": "The ant climbed on the leaf and looked up as if it was thanking the bird for saving its life. (verb: thank)"}, {"q": "A few days later, the bird was on another tree and ______ its food.", "a": "A few days later, the bird was on another tree and was eating its food. (verb: eat)"}, {"q": "It looked happy as if it ______ itself.", "a": "It looked happy as if it was enjoying itself. (verb: enjoy)"}, {"q": "It did not see that a hunter ______ to shoot it.", "a": "It did not see that a hunter was going to shoot it. (verb: go)"}, {"q": "The bird flew away. As it ______ away it saw that the little ant ______ back into its hole in the ground.", "a": "As it was flying away it saw that the little ant was running back into its hole in the ground. (verbs: fly, run)"}]}]}], "words": [{"w": "past continuous tense", "sd": "زمان ماضي جاري", "syn": "the tense for an action going on in the past"}]}, {"cls": "vi", "unit": 5, "title": "Nouns: Number and Gender", "display": "Nouns: Number and Gender", "reading": "My English Book 6, Units 3 and 4, Language Practice", "lesson": [{"t": "h", "x": "Nouns: Number and Gender"}, {"t": "p", "x": "A noun has number: singular for one and plural for more than one. A noun also has gender: masculine for males and feminine for females."}, {"t": "def", "x": "Number tells us if a noun is one (singular) or more than one (plural). Gender tells us if a noun is masculine or feminine."}, {"t": "h", "x": "Rule 1. Add 's' to make most plurals"}, {"t": "rule", "x": "Add 's' to most nouns to make them plural."}, {"t": "ex", "x": "sister — sisters, boy — boys, girl — girls, book — books, bus — buses."}, {"t": "h", "x": "Rule 2. Add 'es' after s, x, ch or sh"}, {"t": "rule", "x": "For nouns that end with s, x, ch or sh, add 'es'."}, {"t": "ex", "x": "watch — watches, box — boxes, bush — bushes, glass — glasses, bunch — bunches."}, {"t": "h", "x": "Rule 3. Change 'y' to 'ies' and 'f' to 'ves'"}, {"t": "rule", "x": "For nouns that end with a consonant + y, change y to ies. For nouns that end with f or fe, change f to ves."}, {"t": "ex", "x": "baby — babies, city — cities, shelf — shelves, knife — knives, wife — wives, leaf — leaves."}, {"t": "h", "x": "Rule 4. Some plurals change the word"}, {"t": "rule", "x": "Some nouns change in the plural: man — men, woman — women, child — children, foot — feet, tooth — teeth, ox — oxen, person — people."}, {"t": "ex", "x": "How many people are there in the buses? Five women opened a school. I saw an ox in the field. I saw oxen in the field."}, {"t": "h", "x": "Rule 5. Masculine and feminine nouns"}, {"t": "rule", "x": "Masculine nouns name males and feminine nouns name females."}, {"t": "ex", "x": "man — woman, boy — girl, father — mother, brother — sister, son — daughter, uncle — aunt, king — queen, cock — hen, bull — cow, horse — mare, lion — lioness, tiger — tigress, prince — princess, hero — heroine, actor — actress, doe — buck."}, {"t": "rl", "x": "At school, there are twenty boys and fifteen girls. Five women opened a school in our village."}, {"t": "rl", "x": "At home, my father is a man and my mother is a woman. I have one brother and two sisters."}, {"t": "rl", "x": "In the market, the farmer sells milk from his cow. The lion and the lioness are in the zoo."}, {"t": "note", "x": "The verb must agree with the noun number: 'Every child enjoys learning' (singular) but 'Children enjoy learning' (plural)."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Write down the plurals of the nouns given below in your notebook. 1) sister", "a": "sisters"}, {"q": "2) watch", "a": "watches"}, {"q": "3) shelf", "a": "shelves"}, {"q": "4) fox", "a": "foxes"}, {"q": "5) tomato", "a": "tomatoes"}, {"q": "6) person", "a": "people"}, {"q": "7) hair", "a": "hair (the spelling stays the same in singular and plural)"}, {"q": "8) tooth", "a": "teeth"}, {"q": "9) wife", "a": "wives"}, {"q": "10) dash", "a": "dashes"}, {"q": "11) fairy", "a": "fairies"}, {"q": "12) match", "a": "matches"}, {"q": "13) buffalo", "a": "buffaloes"}, {"q": "14) holiday", "a": "holidays"}, {"q": "15) mosquito", "a": "mosquitoes"}, {"q": "16) berry", "a": "berries"}, {"q": "17) cage", "a": "cages"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "In pairs, choose the correct noun number in the following sentences. Write the correct answers in your notebook. Follow the example. 1) How many person/people are there in the buses/bus?", "a": "How many people are there in the buses?"}, {"q": "2) Five woman/women opened a school/schools.", "a": "Five women opened schools."}, {"q": "3) Every child/children enjoys learning through picture/pictures.", "a": "Every child enjoys learning through pictures."}, {"q": "4) Most cricket player/players are more than five foot/feet tall.", "a": "Most cricket players are more than five feet tall."}, {"q": "5) Which kind of sheeps/sheep does your family/families have?", "a": "Which kind of sheep does your family have?"}, {"q": "6) I have to buy a watch/watches and a pair of shoe/shoes.", "a": "I have to buy a watch and a pair of shoes."}, {"q": "7) The boys caught ten fish/fishes and five crab/crabs.", "a": "The boys caught ten fish and five crabs."}, {"q": "8) Many man/men in the field have axe an axes in their hand.", "a": "Many men in the field have axes in their hand."}, {"q": "9) The girls/girl were wearing very beautiful dress/dresses.", "a": "The girls were wearing very beautiful dresses."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Rewrite the following sentences changing the noun number to plural. Remember to change the verb and pronouns as needed. Follow the example. 1) I saw an ox in the field.", "a": "I saw oxen in the field."}, {"q": "2) The young woman put the things on the shelf.", "a": "The young women put the things on the shelves."}, {"q": "3) Cut the orange and the mango in half.", "a": "Cut the oranges and the mangoes in half."}, {"q": "4) My younger brother can walk like a goose.", "a": "My younger brothers can walk like geese."}, {"q": "5) She needs a potato and a tomato.", "a": "She needs potatoes and tomatoes."}, {"q": "6) There is a sheep in the barn.", "a": "There are sheep in the barn."}, {"q": "7) Please lock the hen here so that the fox cannot eat it.", "a": "Please lock the hens here so that the foxes cannot eat them."}, {"q": "8) Mr Samad has a son and a daughter.", "a": "Mr Samad has sons and daughters."}, {"q": "9) My knife is on the table.", "a": "My knives are on the table."}]}]}, {"num": "4", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Memorize the following Noun Genders. Add two more in each of the group given below. Masculine Gender — Feminine Gender (people): uncle — aunt, king — queen, host — hostess, landlord — landlady, sir — madam, husband — wife, nephew — niece, prince — princess, widower — widow, son — daughter.", "a": "Masculine — Feminine (people): uncle — aunt, king — queen, host — hostess, landlord — landlady, sir — madam, husband — wife, nephew — niece, prince — princess, widower — widow, son — daughter. Two more added: man — woman, brother — sister."}, {"q": "Masculine Gender — Feminine Gender (animals): billy goat — nanny goat, stag (deer) — doe, bull — cow, drake — duck, peacock — peahen, fox — vixen, tiger — tigress, jack (donkey) — jenny, ram (sheep) — ewe, stallion (horse) — mare.", "a": "Masculine — Feminine (animals): billy goat — nanny goat, stag (deer) — doe, bull — cow, drake — duck, peacock — peahen, fox — vixen, tiger — tigress, jack (donkey) — jenny, ram (sheep) — ewe, stallion (horse) — mare. Two more added: lion — lioness, cock — hen."}, {"q": "Common Gender: baby, child, doctor, friend, neighbour, principal, police officer, parent, singer, teacher.", "a": "Common Gender: baby, child, doctor, friend, neighbour, principal, police officer, parent, singer, teacher. Two more added: student, cousin."}, {"q": "Neuter Gender: apple, book, cup, drum, egg, fan, grass, hammer, pot, train.", "a": "Neuter Gender: apple, book, cup, drum, egg, fan, grass, hammer, pot, train. Two more added: table, door."}]}]}, {"num": "5", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "In pairs, change the gender of the nouns and rewrite the sentences. Follow the example. 1) A beautiful doe ran about in my garden.", "a": "A beautiful stag ran about in my garden."}, {"q": "2) The wild mare broke the ropes and jumped over the fence.", "a": "The wild stallion broke the ropes and jumped over the fence."}, {"q": "3) The vixen killed a cock.", "a": "The fox killed a hen."}, {"q": "4) The rich prince sent a peacock as a gift to the king.", "a": "The rich princess sent a peahen as a gift to the queen."}, {"q": "5) Sir, I cannot come to school tomorrow.", "a": "Madam, I cannot come to school tomorrow."}, {"q": "6) The widower had a mare that died last week.", "a": "The widow had a stallion that died last week."}, {"q": "7) The landlady died in a car accident.", "a": "The landlord died in a car accident."}, {"q": "8) My hostess is a fine teacher.", "a": "My host is a fine teacher."}, {"q": "9) Their niece treats their aunt very nicely.", "a": "Their nephew treats their uncle very nicely."}, {"q": "10) They have a cow, two rams, four nanny goats and six cocks.", "a": "They have a bull, two ewes, four billy goats and six hens."}]}]}, {"num": "6", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "In pairs, discuss the change in the gender of the nouns in the following statements. Remember to change the pronouns, where needed. For birds and animals, the pronoun his, her, or it can be used. After discussing, write the answers in your notebook. Follow the examples given below. Example 1: The boy bought fruit for himself.", "a": "The girl bought fruit for herself. (Example given in the book.)"}, {"q": "Example 2: The teacher asked Salma to bring book of his.", "a": "The teacher asked Aslam to bring his book. (The book's example is misprinted — 'book of his' is not correct English and the pronoun change does not follow from the name change. The corrected pair is: 'The teacher asked Salma to bring her book.' → 'The teacher asked Aslam to bring his book.')"}, {"q": "1) All the girls left the classroom except Seema.", "a": "All the boys left the classroom except Aslam."}, {"q": "2) Her neighbour likes the hen she bought last week.", "a": "His neighbour likes the cock he bought last week."}, {"q": "3) My uncle helped me with homework of mine when he came to house.", "a": "My aunt helped me with homework of mine when she came to the house."}, {"q": "4) The tiger killed a doe and ate it.", "a": "The tigress killed a stag and ate it."}, {"q": "5) The prince became the king when he was just fifteen years old.", "a": "The princess became the queen when she was just fifteen years old."}, {"q": "6) The doctor's clinic is always full of people because she is very kind.", "a": "The doctor's clinic is always full of people because he is very kind."}, {"q": "7) Father of mine wants to sell his mare and buy a cow.", "a": "Mother of mine wants to sell her stallion and buy a bull."}, {"q": "8) Everyone likes this singer because she sings well and voice of hers beautiful.", "a": "Everyone likes this singer because he sings well and his voice is beautiful."}, {"q": "9) Nazia is the cricket captain of her school's team.", "a": "Aslam is the cricket captain of his school's team."}, {"q": "10) Our landlady sold two ewes of hers and one billy goat because she needed some money.", "a": "Our landlord sold two rams of his and one nanny goat because he needed some money."}]}]}], "words": [{"w": "singular", "sd": "واحد", "syn": "naming one thing"}, {"w": "plural", "sd": "جمع", "syn": "naming more than one thing"}, {"w": "masculine", "sd": "مذڪر", "syn": "male"}, {"w": "feminine", "sd": "مؤنث", "syn": "female"}, {"w": "gender", "sd": "جنس", "syn": "whether a noun is masculine or feminine"}]}, {"cls": "vi", "unit": 6, "title": "Simple Future with Going To", "display": "Simple Future with Going To", "reading": "My English Book 6, Unit 4, Language Practice", "lesson": [{"t": "h", "x": "Simple Future with Going To"}, {"t": "p", "x": "We use 'going to' to talk about the future, for a plan we have already made or for something that is about to happen."}, {"t": "def", "x": "The 'going to' future is made with is, am or are + going to + verb. It talks about a future plan or something about to happen."}, {"t": "h", "x": "Rule 1. Make it with is/am/are + going to + verb"}, {"t": "rule", "x": "Use is, am or are, then 'going to', then the verb."}, {"t": "ex", "x": "I am going to play cricket. He is going to visit Karachi. We are going to watch a film. They are going to buy a new house."}, {"t": "h", "x": "Rule 2. Use it for a plan already made"}, {"t": "rule", "x": "Use 'going to' for a plan we have already decided."}, {"t": "ex", "x": "Aftab's friend is coming from Quetta to spend a week with him. He is going to show him the city. We are going to visit the museum tomorrow."}, {"t": "h", "x": "Rule 3. Use it for something about to happen"}, {"t": "rule", "x": "Use 'going to' when we can see that something is about to happen."}, {"t": "ex", "x": "Look at the clouds! It is going to rain. The baby is going to cry. He is going to fall!"}, {"t": "rl", "x": "At school, our class is going to have a picnic next week. I am going to take my lunch box."}, {"t": "rl", "x": "At home, my father is going to buy a new bicycle for me. My mother is going to cook biryani on Eid."}, {"t": "rl", "x": "In the market, the shopkeeper is going to open a new shop. I am going to buy a kite."}, {"t": "note", "x": "Do not use 'going to' with 'will' together. Say 'I am going to play', not 'I will going to play'."}], "sections": [{"num": "1", "name": "Exercise 1 (Going to)", "exercises": [{"label": "Exercise 1 (Going to)", "items": [{"q": "Look at the following table and make ten sentences as done in the following example. Write two sentences each for he, she, I, they, we, and it. Table: He/She — is/is not — going to — leave for Lahore at 5 o'clock, drink tea after this, read the novel after you finish it, visit the flood victims, have dinner after the game. I — am/am not — going to — (same five). They/We — are/are not — going to — (same five). It — is/is not — going to — eat the bone, rain heavily. Make a sentence with 'he'.", "a": "He is going to leave for Lahore at 5 o'clock. (Example given in the book.)"}, {"q": "Make a second sentence with 'he'.", "a": "He is not going to read the novel after you finish it. (Example given in the book.)"}, {"q": "Make a sentence with 'she'.", "a": "She is going to visit the flood victims."}, {"q": "Make a second sentence with 'she'.", "a": "She is not going to have dinner after the game."}, {"q": "Make a sentence with 'I'.", "a": "I am going to read the novel after you finish it."}, {"q": "Make a second sentence with 'I'.", "a": "I am not going to drink tea after this."}, {"q": "Make a sentence with 'they'.", "a": "They are going to have dinner after the game."}, {"q": "Make a second sentence with 'they'.", "a": "They are not going to leave for Lahore at 5 o'clock."}, {"q": "Make a sentence with 'we'.", "a": "We are going to visit the flood victims."}, {"q": "Make a second sentence with 'we'.", "a": "We are not going to read the novel after you finish it."}, {"q": "Make a sentence with 'it'.", "a": "It is going to rain heavily."}, {"q": "Make a second sentence with 'it'.", "a": "It is not going to eat the bone."}]}]}, {"num": "2", "name": "Exercise 2 (Going to)", "exercises": [{"label": "Exercise 2 (Going to)", "items": [{"q": "Aftab's friend is coming from Quetta to spend a week with him. Complete the following paragraph about his plans using going to. The verbs that you can use are given in the brackets. The first sentence has been done as an example. My friend is going to come (come) by bus. I am ______ (pick) my friend from the bus station. He ______ (stay) with me. We ______ (swim) in the lake. I ______ (take) him to the fields. We ______ (play) many games. He ______ (teach) me English. We ______ (enjoy) ourselves.", "a": "My friend is going to come by bus. I am going to pick my friend from the bus station. He is going to stay with me. We are going to swim in the lake. I am going to take him to the fields. We are going to play many games. He is going to teach me English. We are going to enjoy ourselves."}, {"q": "Now, complete the following paragraph using not going to. However, There are some tings that we are not going to do (do). We ______ (sleep) late. I ______ (climb) trees. He ______ (ride) the camel. We ______ (watch) the TV. We ______ (go) to the fair. In short, we ______ (do) anything that we do not want to do.", "a": "However, there are some things that we are not going to do. We are not going to sleep late. I am not going to climb trees. He is not going to ride the camel. We are not going to watch the TV. We are not going to go to the fair. In short, we are not going to do anything that we do not want to do."}]}]}], "words": [{"w": "future", "sd": "مستقبل", "syn": "the time that is yet to come"}, {"w": "plan", "sd": "منصوبو", "syn": "something we have decided to do"}]}, {"cls": "vi", "unit": 7, "title": "Passive Voice", "display": "Passive Voice", "reading": "My English Book 6, Unit 5, Language Practice", "lesson": [{"t": "h", "x": "Passive Voice"}, {"t": "p", "x": "In the active voice, the subject does the action. In the passive voice, the subject receives the action. We use the passive voice when the doer is not important or not known."}, {"t": "def", "x": "In the active voice, the subject does the action. In the passive voice, the subject receives the action. The passive is made with a be verb and the past participle."}, {"t": "h", "x": "Rule 1. Make the passive with be + past participle"}, {"t": "rule", "x": "Make the passive voice with is, am, are, was or were and the past participle of the verb."}, {"t": "ex", "x": "The letter is written. The room is cleaned. The food is cooked. The match was won."}, {"t": "h", "x": "Rule 2. Change active into passive"}, {"t": "rule", "x": "To change an active sentence into a passive one, make the object the subject, use the be verb and the past participle, and put the old subject after 'by' if needed."}, {"t": "ex", "x": "Active: Ali writes a letter. Passive: A letter is written by Ali. Active: The cat drank the milk. Passive: The milk was drunk by the cat."}, {"t": "h", "x": "Rule 3. Use the passive when the doer is not known"}, {"t": "rule", "x": "Use the passive voice when we do not know who did the action, or when it does not matter."}, {"t": "ex", "x": "The window was broken. (We do not know who broke it.) Rice is grown in Sindh. English is spoken in many countries."}, {"t": "rl", "x": "At school, the classroom is cleaned every day. The homework is checked by the teacher."}, {"t": "rl", "x": "At home, the food is cooked by my mother. The house is cleaned by all of us."}, {"t": "rl", "x": "In the market, fruit is sold in the shops. Mangoes are bought by many people."}, {"t": "note", "x": "The past participle of regular verbs ends in 'ed': cleaned, cooked, played. Irregular verbs change: written, drunk, won, made."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Change each of the following Active Voice sentence into a Passive voice in Present Simple. Underline the verb in the first sentence. Remember to use the past participle form of the verb in the Passive Voice. Use is, am or are, as needed. 1) I wash the dishes. --> The dishes ______ by me.", "a": "The dishes are washed by me. (Verb in the first sentence: wash.)"}, {"q": "2) My sister feeds the cows. --> The cows ______ by my sister.", "a": "The cows are fed by my sister. (Verb: feeds.)"}, {"q": "3) My uncle cooks the food. --> The food ______ by my uncle.", "a": "The food is cooked by my uncle. (Verb: cooks.)"}, {"q": "4) Grandmother cleans the kitchen. --> The kitchen ______ by grandmother.", "a": "The kitchen is cleaned by grandmother. (Verb: cleans.)"}, {"q": "5) My father pays the bills. --> The bills ______ by my father.", "a": "The bills are paid by my father. (Verb: pays.)"}, {"q": "6) The gardener cuts the bushes. --> The bushes ______ by the gardener.", "a": "The bushes are cut by the gardener. (Verb: cuts.)"}, {"q": "7) My brother drinks green tea. --> Green tea ______ by my brother.", "a": "Green tea is drunk by my brother. (Verb: drinks.)"}, {"q": "8) My aunt waters the plants. --> The plants ______ by my aunt.", "a": "The plants are watered by my aunt. (Verb: waters.)"}, {"q": "9) My mother does the laundry. --> The laundry ______ by my mother.", "a": "The laundry is done by my mother. (Verb: does.)"}, {"q": "10) My grandfather takes us to school. --> We ______ to school by my grandfather.", "a": "We are taken to school by my grandfather. (Verb: takes.)"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "In each of the following pairs of sentences, state which one is in the Active Voice and which in the Passive Voice by writing A and P in the blanks. 1) Our servant reads the newspaper.", "a": "A — Active Voice. (Example given in the book.)"}, {"q": "2) Bread and butter are eaten by Salma.", "a": "P — Passive Voice."}, {"q": "3) Thatta is liked by many people.", "a": "P — Passive Voice."}, {"q": "4) My brother polishes my shoes.", "a": "A — Active Voice."}, {"q": "5) The clouds are blown away by strong winds.", "a": "P — Passive Voice."}, {"q": "6) Good teams win matches.", "a": "A — Active Voice."}, {"q": "7) Teachers help students.", "a": "A — Active Voice."}, {"q": "8) Honey bees make honey.", "a": "A — Active Voice."}, {"q": "9) The tractor is driven by their father.", "a": "P — Passive Voice."}, {"q": "10) I am taught English by my sister.", "a": "P — Passive Voice."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Change the Voice of all the sentences in Exercise 2 above; change all the Active Voices into Passive and all the Passive ones into Active. 1) Our servant reads the newspaper.", "a": "The newspaper is read by our servant."}, {"q": "2) Bread and butter are eaten by Salma.", "a": "Salma eats bread and butter."}, {"q": "3) Thatta is liked by many people.", "a": "Many people like Thatta."}, {"q": "4) My brother polishes my shoes.", "a": "My shoes are polished by my brother."}, {"q": "5) The clouds are blown away by strong winds.", "a": "Strong winds blow the clouds away."}, {"q": "6) Good teams win matches.", "a": "Matches are won by good teams."}, {"q": "7) Teachers help students.", "a": "Students are helped by teachers."}, {"q": "8) Honey bees make honey.", "a": "Honey is made by honey bees."}, {"q": "9) The tractor is driven by their father.", "a": "Their father drives the tractor."}, {"q": "10) I am taught English by my sister.", "a": "My sister teaches me English."}]}]}], "words": [{"w": "active voice", "sd": "معروف", "syn": "the voice in which the subject does the action"}, {"w": "passive voice", "sd": "مجهول", "syn": "the voice in which the subject receives the action"}, {"w": "past participle", "sd": "اسم مفعول", "syn": "the third form of the verb, as in written or played"}]}, {"cls": "vi", "unit": 8, "title": "Prepositions of Time", "display": "Prepositions of Time", "reading": "My English Book 6, Unit 5, Language Practice", "lesson": [{"t": "h", "x": "Prepositions of Time"}, {"t": "p", "x": "Prepositions of time tell us when something happens. The three main ones are in, on and at."}, {"t": "def", "x": "A preposition of time shows when something happens. 'In' is for months, years and parts of the day. 'On' is for days and dates. 'At' is for exact times."}, {"t": "h", "x": "Rule 1. Use 'in' for months, years and parts of the day"}, {"t": "rule", "x": "Use 'in' with months, years, seasons and parts of the day (in the morning, in the evening, in 1998, in July)."}, {"t": "ex", "x": "I met my friend in 1998. It rains in July. The children like to go to the park in the evening."}, {"t": "h", "x": "Rule 2. Use 'on' for days and dates"}, {"t": "rule", "x": "Use 'on' with days of the week and dates (on Sunday, on Saturday, on Eid, on 14th August)."}, {"t": "ex", "x": "I have no school on Sundays. The school is opening on Saturday. Lots of people buy new clothes on Eid."}, {"t": "h", "x": "Rule 3. Use 'at' for exact times"}, {"t": "rule", "x": "Use 'at' with exact times and with night, midnight, noon and bedtime (at 6 o'clock, at midnight, at bedtime, at lunch time)."}, {"t": "ex", "x": "My father comes home at lunch time. Mother tells us a story at bedtime. There was a loud noise at midnight. We finished our homework at the same time."}, {"t": "rl", "x": "At school, we have a test on Monday. The school opens at 8 o'clock in the morning."}, {"t": "rl", "x": "At home, my father comes home at lunch time. We eat dinner in the evening. I was born in 2015."}, {"t": "rl", "x": "In the market, the shops open at 9 o'clock. We buy new clothes on Eid. It is cold in winter."}, {"t": "note", "x": "Remember: in + month/year, on + day/date, at + exact time."}], "sections": [{"num": "1", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "In pairs, choose the correct Preposition of Time. Write the correct sentences in your notebook. 1) I have no school on/in/at Sundays.", "a": "I have no school on Sundays. (on — given in the book.)"}, {"q": "2) My father comes home at/in/on lunch time.", "a": "My father comes home at lunch time."}, {"q": "3) The children like to go to the park in/on/at the evening.", "a": "The children like to go to the park in the evening."}, {"q": "4) Lots of people buy new clothes at/in/on Eid.", "a": "Lots of people buy new clothes on Eid."}, {"q": "5) What are you doing in/on/at the evening?", "a": "What are you doing in the evening?"}, {"q": "6) Mother always tells us a story at/in/on bedtime.", "a": "Mother always tells us a story at bedtime."}, {"q": "7) We finished our homework on/in/at the same time.", "a": "We finished our homework at the same time."}, {"q": "8) There was a loud noise which woke us up on/at/in midnight.", "a": "There was a loud noise which woke us up at midnight."}, {"q": "9) I met my husband on/at/in 1998.", "a": "I met my husband in 1998."}, {"q": "10) The school is opening in/on/at Saturday.", "a": "The school is opening on Saturday."}]}]}, {"num": "2", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Complete the following paragraph by filling the blanks with correct prepositions. Salma and her brother, Rumi, decided to go to Moenjodaro in the winter holidays. They wanted to go ______ December 18.", "a": "on — They wanted to go on December 18."}, {"q": "______ breakfast time they asked their father if they could go to Moenjodaro.", "a": "At — At breakfast time they asked their father if they could go to Moenjodaro."}, {"q": "He told them that they would discuss the matter ______ the evening.", "a": "in — He told them that they would discuss the matter in the evening."}, {"q": "He called both of them ______ 5 o'clock and asked them their plan.", "a": "at — He called both of them at 5 o'clock and asked them their plan."}, {"q": "Rumi told him that a train leaves for Moenjodaro ______ 8:00 am.", "a": "at — Rumi told him that a train leaves for Moenjodaro at 8:00 am."}, {"q": "They could take the train ______ December when they have their winter holidays.", "a": "in — They could take the train in December when they have their winter holidays."}, {"q": "They would reach Moenjodaro ______ noon.", "a": "at — They would reach Moenjodaro at noon."}, {"q": "Their father said that they could go ______ the 23rd of December.", "a": "on — Their father said that they could go on the 23rd of December."}, {"q": "They could stay with his friend for two nights and come back ______ Christmas Day.", "a": "on — They could stay with his friend for two nights and come back on Christmas Day."}, {"q": "Salma said to Rumi that they would give the good news to their mother ______ night.", "a": "at — Salma said to Rumi that they would give the good news to their mother at night."}]}]}], "words": [{"w": "preposition of time", "sd": "زمان جو حرف جر", "syn": "a word like in, on or at that shows when something happens"}]}, {"cls": "vi", "unit": 9, "title": "WH Question Words and First Conditional", "display": "WH Question Words and First Conditional", "reading": "My English Book 6, Unit 6, Language Practice", "lesson": [{"t": "h", "x": "WH Question Words and First Conditional"}, {"t": "p", "x": "WH question words ask for information. The first conditional talks about a real future result: if something happens, something else will happen."}, {"t": "def", "x": "WH words (what, where, when, who, why, how) ask for information. The first conditional is: If + present simple, will + verb."}, {"t": "h", "x": "Rule 1. WH words ask for information"}, {"t": "rule", "x": "Use what for a thing, where for a place, when for a time, who for a person, why for a reason, how for a way."}, {"t": "ex", "x": "What is your name? Where do you live? When do you go to school? Who is your teacher? Why are you late? How do you go to school?"}, {"t": "h", "x": "Rule 2. First conditional: If + present simple, will + verb"}, {"t": "rule", "x": "In the first conditional, the 'if' part uses the present simple and the result part uses 'will' with the verb."}, {"t": "ex", "x": "If you work hard, you will pass. If it rains, we will stay at home. If you see a snake, what will you do?"}, {"t": "h", "x": "Rule 3. The 'if' part can come first or second"}, {"t": "rule", "x": "The 'if' clause can come first or second. Use a comma when it comes first."}, {"t": "ex", "x": "If you study well, you will get good marks. You will get good marks if you study well."}, {"t": "h", "x": "Rule 4. Use 'as' and 'because' for cause and effect"}, {"t": "rule", "x": "Use 'as' and 'because' to show why something happens."}, {"t": "ex", "x": "Saeed will travel to school by bus because his bicycle is broken. As his bicycle is broken, Saeed will travel by bus. I want to learn English because it is useful."}, {"t": "rl", "x": "At school, the teacher asks, 'What will you do if you see a snake?' I say, 'I will run away.'"}, {"t": "rl", "x": "At home, my mother says, 'If you finish your homework, you will watch TV.' I finish my homework because I want to watch TV."}, {"t": "rl", "x": "On the cricket ground, if it rains, we will stop the match. If Ali bats well, we will win."}, {"t": "note", "x": "Do not use 'will' in the 'if' part: say 'If you work hard, you will pass' — not 'If you will work hard'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Fill in the blanks with the correct WH-Question from the ones given in brackets. Write the complete answers in your notebook. 1) Why are you so happy? (Why/Who/Whose)", "a": "Why are you so happy? (Example given in the book.)"}, {"q": "2) ______ is sitting behind you? (Where/Who/What)", "a": "Who is sitting behind you?"}, {"q": "3) ______ do you go to school? (How/Whose/Which)", "a": "How do you go to school?"}, {"q": "4) ______ did the first lesson begin? (When/How long/Who)", "a": "When did the first lesson begin?"}, {"q": "5) ______ is the police-station? (What time/Why/Where)", "a": "Where is the police-station?"}, {"q": "6) ______ is the weather like in Nawabshah? (How much/What/Why)", "a": "What is the weather like in Nawabshah?"}, {"q": "7) ______ did the tickets cost? (How much/How many/How soon)", "a": "How much did the tickets cost?"}, {"q": "8) ______ does she drink milk in a week? (When/How often/Who)", "a": "How often does she drink milk in a week?"}, {"q": "9) ______ book is that? (Whose/How far/When)", "a": "Whose book is that?"}, {"q": "10) ______ books were there? (How many/How much/How far)", "a": "How many books were there?"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Look at the answers given in the Answer column in the table below. In pairs, discuss the possible WH- Question that was asked. Write the answers in your notebook. 1. My little brother likes lemon juice.", "a": "Who likes lemon juice? (Example given in the book.)"}, {"q": "2. I had seven pencils.", "a": "How many pencils did you have? (Example given in the book.)"}, {"q": "3. I returned from Quetta last night.", "a": "When did you return from Quetta?"}, {"q": "4. The airport was about five miles away.", "a": "How far was the airport?"}, {"q": "5. The drama serial began at 8 o'clock.", "a": "What time did the drama serial begin?"}, {"q": "6. This is Amina's bag.", "a": "Whose bag is this?"}, {"q": "7. My aunt lives near our house.", "a": "Where does your aunt live?"}, {"q": "8. The servant is knocking on the door.", "a": "Who is knocking on the door?"}, {"q": "9. This book is more interesting than that one.", "a": "Which book is more interesting?"}, {"q": "10. I went to the seaside yesterday.", "a": "When did you go to the seaside?"}, {"q": "11. My favourite fruit is pineapple.", "a": "What is your favourite fruit?"}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Write ten 'Wh' questions that you can ask your friend. Then write the answers that you think your friend will give you. Write complete questions and complete answers in your notebook. 1) Your question: ______ Your answer: ______", "a": "1) Your question: What is your name? Your answer: My name is Ali."}, {"q": "2) Your question: ______ Your answer: ______", "a": "2) Your question: Where do you live? Your answer: I live in Hyderabad."}, {"q": "3) Your question: ______ Your answer: ______", "a": "3) Your question: When do you go to school? Your answer: I go to school at 8 o'clock."}, {"q": "4) Your question: ______ Your answer: ______", "a": "4) Your question: Who is your best friend? Your answer: Ahmed is my best friend."}, {"q": "5) Your question: ______ Your answer: ______", "a": "5) Your question: Why do you like English? Your answer: I like English because it is a beautiful language."}, {"q": "6) Your question: ______ Your answer: ______", "a": "6) Your question: Which subject do you like most? Your answer: I like English most."}, {"q": "7) Your question: ______ Your answer: ______", "a": "7) Your question: Whose bag is this? Your answer: This is Amina's bag."}, {"q": "8) Your question: ______ Your answer: ______", "a": "8) Your question: How do you go to school? Your answer: I go to school on foot."}, {"q": "9) Your question: ______ Your answer: ______", "a": "9) Your question: How many brothers do you have? Your answer: I have two brothers."}, {"q": "10) Your question: ______ Your answer: ______", "a": "10) Your question: What time does the school start? Your answer: The school starts at 8 o'clock."}]}]}, {"num": "4", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Complete the following First Conditional sentences using the correct form of the verbs given in the brackets. Write the complete sentences in your notebook. 1) If I go (go) out tonight, I will go (go) to the cinema.", "a": "If I go out tonight, I will go to the cinema. (Example given in the book.)"}, {"q": "2) If you ______ (get) back late, I ______ (be) angry.", "a": "If you get back late, I will be angry."}, {"q": "3) We ______ (see) each other next week if we ______ (not/see) each other tomorrow.", "a": "We will see each other next week if we do not see each other tomorrow."}, {"q": "4) If he ______ (come), I ______ (be) surprised.", "a": "If he comes, I will be surprised."}, {"q": "5) Anwar ______ (be) late if he ______ (wait) here longer.", "a": "Anwar will be late if he waits here longer."}, {"q": "6) If we ______ (go) on holiday this summer, we ______ (go) to China.", "a": "If we go on holiday this summer, we will go to China."}, {"q": "7) If the weather ______ (not/improve), we ______ (not/have) a picnic.", "a": "If the weather does not improve, we will not have a picnic."}, {"q": "8) They ______ (go) to the party if they ______ (be) invited.", "a": "They will go to the party if they are invited."}, {"q": "9) She ______ (be) tired tomorrow if she ______ (not/go) to bed early.", "a": "She will be tired tomorrow if she does not go to bed early."}, {"q": "10) The children ______ (feel) sick if they ______ (eat) all this cake.", "a": "The children will feel sick if they eat all this cake."}]}]}, {"num": "5", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Match the sentences in Column A with those in Column B to form meaningful First Conditional sentences. Write the complete sentences in your notebook. (a) The earth will be a better place — ______", "a": "The earth will be a better place if people don't cut trees. (Example given in the book.)"}, {"q": "(b) If you eat too much chocolate, ______", "a": "If you eat too much chocolate, you will get fat."}, {"q": "(c) The roads can be clean — ______", "a": "The roads can be clean if people don't throw rubbish on them."}, {"q": "(d) If we go to bed late, ______", "a": "If we go to bed late, we cannot wake up early."}, {"q": "(e) If she cooks dinner for him, ______", "a": "If she cooks dinner for him, he may feel happy."}, {"q": "(f) If mother tells me a story — ______", "a": "If mother tells me a story, I will sleep better."}, {"q": "(g) I will visit your village — ______", "a": "I will visit your village if you visit my city."}, {"q": "(h) If you scratch your feet again, ______", "a": "If you scratch your feet again, I will take you to the doctor."}, {"q": "(i) Fish will not die, ______", "a": "Fish will not die, if we don't throw trash in seas and rivers."}, {"q": "(j) If father stops eating tobacco, ______", "a": "If father stops eating tobacco, he will get better soon."}]}]}, {"num": "6", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Use your imagination to answer the following in the First Conditional. 1) What will you do if you see a snake near you?", "a": "If I see a snake near me, I will kill it. (Example given in the book.)"}, {"q": "2) Where will Tasneem go if she has a free train ticket?", "a": "Model answer: If Tasneem has a free train ticket, she will go to Karachi. (Any sensible answer is acceptable.)"}, {"q": "3) Whom will they give it to if they have an extra mobile phone?", "a": "Model answer: If they have an extra mobile phone, they will give it to their friend. (Any sensible answer is acceptable.)"}, {"q": "4) When will he come if I send him the card?", "a": "Model answer: If I send him the card, he will come tomorrow. (Any sensible answer is acceptable.)"}, {"q": "5) Which will she choose if she has a pink dress and a blue one?", "a": "Model answer: If she has a pink dress and a blue one, she will choose the pink one. (Any sensible answer is acceptable.)"}, {"q": "6) Where will we go if it is hot this evening?", "a": "Model answer: If it is hot this evening, we will go to the seaside. (Any sensible answer is acceptable.)"}, {"q": "7) What will he do if they give him a gift?", "a": "Model answer: If they give him a gift, he will thank them. (Any sensible answer is acceptable.)"}, {"q": "8) Who will we meet if we go to the party?", "a": "Model answer: If we go to the party, we will meet our friends. (Any sensible answer is acceptable.)"}, {"q": "9) What time will they come if we send the car?", "a": "Model answer: If we send the car, they will come at 5 o'clock. (Any sensible answer is acceptable.)"}, {"q": "10) When will the bus leave if we arrive early?", "a": "Model answer: If we arrive early, the bus will leave on time. (Any sensible answer is acceptable.)"}]}]}, {"num": "7", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Match the sentences in column A with those in column B to show the Cause and Effect / Result relationship. Write your answer in column C. 1. Saeed will travel to school by bus. — ______", "a": "1-d: Saeed will travel to school by bus — His bicycle is at the mechanic's. (Example given in the book.)"}, {"q": "2. Jaleel was soaked from head to toe. — ______", "a": "2-g: Jaleel was soaked from head to toe — He walked in the rain from school."}, {"q": "3. Daud would like to buy a new watch. — ______", "a": "3-j: Daud would like to buy a new watch — His old one fell in the river."}, {"q": "4. She was crying. — ______", "a": "4-h: She was crying — Maria lost her new doll."}, {"q": "5. I have a beautiful garden. — ______", "a": "5-c: I have a beautiful garden — Many people come to admire my garden."}, {"q": "6. It was a hot summer day. — ______", "a": "6-i: It was a hot summer day — We all decided to have cold lassi."}, {"q": "7. She was looking after the baby. — ______", "a": "7-a: She was looking after the baby — Mother did not cook last night."}, {"q": "8. There was a banana peel on the floor. — ______", "a": "8-b: There was a banana peel on the floor — Hajrah slipped and fell down."}, {"q": "9. The fruit was not washed properly. — ______", "a": "9-e: The fruit was not washed properly — I got sick when I ate it."}, {"q": "10. It was my sister's wedding. — ______", "a": "10-f: It was my sister's wedding — We served biryani for dinner."}]}]}, {"num": "8", "name": "Exercise 8", "exercises": [{"label": "Exercise 8", "items": [{"q": "Rewrite the matched sentences in column C by using as and because. 1) Saeed will travel to school by bus. His bicycle is at the mechanic's.", "a": "Saeed will travel to school by bus as his bicycle is at the mechanic's. OR As his bicycle is at the mechanic's, Saeed will travel to school by bus. (Example given in the book.)"}, {"q": "2) Jaleel was soaked from head to toe. He walked in the rain from school.", "a": "Jaleel was soaked from head to toe as he walked in the rain from school. OR Jaleel was soaked from head to toe because he walked in the rain from school."}, {"q": "3) Daud would like to buy a new watch. His old one fell in the river.", "a": "Daud would like to buy a new watch as his old one fell in the river. OR Daud would like to buy a new watch because his old one fell in the river."}, {"q": "4) She was crying. Maria lost her new doll.", "a": "She was crying as Maria lost her new doll. OR She was crying because Maria lost her new doll."}, {"q": "5) I have a beautiful garden. Many people come to admire my garden.", "a": "I have a beautiful garden as many people come to admire my garden. OR I have a beautiful garden because many people come to admire my garden."}, {"q": "6) It was a hot summer day. We all decided to have cold lassi.", "a": "We all decided to have cold lassi as it was a hot summer day. OR We all decided to have cold lassi because it was a hot summer day."}, {"q": "7) She was looking after the baby. Mother did not cook last night.", "a": "Mother did not cook last night as she was looking after the baby. OR Mother did not cook last night because she was looking after the baby."}, {"q": "8) There was a banana peel on the floor. Hajrah slipped and fell down.", "a": "Hajrah slipped and fell down as there was a banana peel on the floor. OR Hajrah slipped and fell down because there was a banana peel on the floor."}, {"q": "9) The fruit was not washed properly. I got sick when I ate it.", "a": "I got sick as the fruit was not washed properly. OR I got sick because the fruit was not washed properly."}, {"q": "10) It was my sister's wedding. We served biryani for dinner.", "a": "We served biryani for dinner as it was my sister's wedding. OR We served biryani for dinner because it was my sister's wedding."}]}]}], "words": [{"w": "WH question word", "sd": "سوالي لفظ", "syn": "a word like what, where or when that asks for information"}, {"w": "first conditional", "sd": "پھرين شرطي جملو", "syn": "If + present simple, will + verb"}, {"w": "cause", "sd": "سبب", "syn": "the reason something happens"}, {"w": "effect", "sd": "نتيجو", "syn": "the result of something"}]}, {"cls": "vi", "unit": 10, "title": "Cohesive Devices and Punctuation", "display": "Cohesive Devices and Punctuation", "reading": "My English Book 6, Units 1, 2, 3, 4, 5 and 6, Language Practice", "lesson": [{"t": "h", "x": "Cohesive Devices and Punctuation"}, {"t": "p", "x": "Cohesive devices join our ideas together so that a paragraph reads smoothly. Punctuation marks show us where a sentence begins and ends, and where to pause."}, {"t": "def", "x": "A cohesive device is a word or phrase that links sentences and ideas. Punctuation marks are the full stop, comma, question mark, exclamation mark, quotation marks and colon."}, {"t": "h", "x": "Rule 1. Use 'in brief', 'in short' and 'to sum up' to end a paragraph"}, {"t": "rule", "x": "To end a paragraph, begin the last sentence with 'in brief', 'in short' or 'to sum up', followed by a comma."}, {"t": "ex", "x": "In short, we are all responsible for taking care of our parks. In brief, we should complete our homework on time. To sum up, we must respect our parents."}, {"t": "h", "x": "Rule 2. Use 'but' and 'unlike' to show a difference"}, {"t": "rule", "x": "Use 'but' and 'unlike' to show that two things are different."}, {"t": "ex", "x": "Ali is tall, but Ahmed is short. Unlike Ali, Ahmed is short. The cat is small, but the dog is big."}, {"t": "h", "x": "Rule 3. Use 'once', 'as' and 'because' to link ideas"}, {"t": "rule", "x": "Use 'once' to show time, and 'as' and 'because' to show a reason."}, {"t": "ex", "x": "Once, there was a king. I stayed at home because I was ill. As it was raining, we stayed inside."}, {"t": "h", "x": "Rule 4. Begin a sentence with a capital letter and end it with a full stop"}, {"t": "rule", "x": "Every sentence begins with a capital letter and ends with a full stop, a question mark or an exclamation mark."}, {"t": "ex", "x": "Ali is a good boy. Where are you going? What a beautiful day!"}, {"t": "h", "x": "Rule 5. Use quotation marks for direct speech"}, {"t": "rule", "x": "Put quotation marks (\" \") around the exact words that somebody says, and put a comma before them."}, {"t": "ex", "x": "Father said to me, \"Finish your work!\" Kamran said, \"Mehnaz wants to play outside.\" \"Which shop do you want to go to?\" asked mother."}, {"t": "h", "x": "Rule 6. Use a comma to separate things in a list"}, {"t": "rule", "x": "Use commas to separate words in a list, and use a colon (:) before a list or an explanation."}, {"t": "ex", "x": "I bought a pen, a book and a bag. He said: \"Come here.\" The things we need are: a bat, a ball and stumps."}, {"t": "rl", "x": "At school, I write: 'My school is a good school. In short, I love my school.' My teacher says, \"Open your books.\""}, {"t": "rl", "x": "At home, my mother says, \"Wash your hands!\" I write a list: mangoes, apples and bananas."}, {"t": "rl", "x": "On the cricket ground, the captain says, \"Catch the ball!\" Unlike Ali, Ahmed is a fast bowler."}, {"t": "note", "x": "A question mark (?) is used for a question, and an exclamation mark (!) for a strong feeling or order."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Rewrite the following paragraphs by adding in brief, in short or to sum up at the beginning of the last sentence. Use each phrase only once and remember to use a comma after it. (a) We should take care of our parks. We should keep them clean and not throw trash anywhere. We must also not damage any property in our parks. We are all responsible for taking care of our parks.", "a": "We should take care of our parks. We should keep them clean and not throw trash anywhere. We must also not damage any property in our parks. In short, we are all responsible for taking care of our parks."}, {"q": "(b) Teachers usually tell us when to finish our homework. If we do not do our work on time we may lose marks. Our teachers may also get angry and punish us. They may also call our parents and tell them that we are careless. We should complete our homework on time in order to be good students.", "a": "Teachers usually tell us when to finish our homework. If we do not do our work on time we may lose marks. Our teachers may also get angry and punish us. They may also call our parents and tell them that we are careless. In brief, we should complete our homework on time in order to be good students."}, {"q": "(c) Misbehaving with our parents is bad manners. We should never shout at them or become angry at what they say. We should listen to what they say and follow their advice. We should always try to please them and look after their needs. We must respect our parents and be kind to them.", "a": "Misbehaving with our parents is bad manners. We should never shout at them or become angry at what they say. We should listen to what they say and follow their advice. We should always try to please them and look after their needs. To sum up, we must respect our parents and be kind to them."}]}]}, {"num": "2", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Work in pairs, and discuss where you need to put the quotation marks, the commas and the capital letters. After you have discussed, write the correct sentences in your notebooks. The first one has been done as an example. i. Father said to me finish your work!", "a": "Father said to me, \"Finish your work!\" (Example given in the book.)"}, {"q": "ii. Kamran said Mehnaz wants to play outside.", "a": "Kamran said, \"Mehnaz wants to play outside.\""}, {"q": "iii. Which shop do you want to go to? asked mother.", "a": "\"Which shop do you want to go to?\" asked mother."}, {"q": "iv. Mir said I don't believe you.", "a": "Mir said, \"I don't believe you.\""}, {"q": "v. I asked have you seen the movie Spiderman?", "a": "I asked, \"Have you seen the movie Spiderman?\""}, {"q": "vi. He said do you want to stay?", "a": "He said, \"Do you want to stay?\""}, {"q": "vii. I'm next she said softly.", "a": "\"I'm next,\" she said softly."}, {"q": "viii. Nyla told me you are the best!", "a": "Nyla told me, \"You are the best!\""}, {"q": "ix. We should go home said Bilal.", "a": "\"We should go home,\" said Bilal."}]}]}, {"num": "3", "name": "Exercise 7 (Full Stop)", "exercises": [{"label": "Exercise 7 (Full Stop)", "items": [{"q": "Work in pairs and rewrite each of the following as two separate sentences in your notebooks. Use capital letters and full stops where needed. Follow the example. Example: i often go for long walks on summer evenings it is peaceful and i can exercise too.", "a": "I often go for long walks on summer evenings. It is peaceful and I can exercise too. (Example given in the book.)"}, {"q": "1) they have a dog, a cat, and two hens next year they will buy a goat and a cow", "a": "They have a dog, a cat, and two hens. Next year they will buy a goat and a cow."}, {"q": "2) at the eid fair last saturday ali saw a clown he was wearing a red coat", "a": "At the Eid fair last Saturday Ali saw a clown. He was wearing a red coat."}, {"q": "3) the cock crows loudly all night we cannot sleep properly", "a": "The cock crows loudly all night. We cannot sleep properly."}, {"q": "4) my sister's parrot can say a few words i like the way it talks", "a": "My sister's parrot can say a few words. I like the way it talks."}, {"q": "5) one day a zebra escaped from its cage the zookeeper found it inside the elephant's cage", "a": "One day a zebra escaped from its cage. The zookeeper found it inside the elephant's cage."}]}]}, {"num": "4", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Fill in the following sentences, by adding but or unlike in the blanks. The first two have been done as examples. 1) Unlike Samina, Najma loves driving.", "a": "Unlike Samina, Najma loves driving. (Example given in the book.)"}, {"q": "2) The colour of my house is nice but, I want to change it.", "a": "The colour of my house is nice but I want to change it. (Example given in the book.)"}, {"q": "3) We are late ______ we will catch the train.", "a": "We are late but we will catch the train."}, {"q": "4) ______ Badin, the weather in Murree is quite cold.", "a": "Unlike Badin, the weather in Murree is quite cold."}, {"q": "5) We are having a good time ______ we miss some of our friends.", "a": "We are having a good time but we miss some of our friends."}, {"q": "6) The food here is good, ______ the food we had at the hotel last night.", "a": "The food here is good, unlike the food we had at the hotel last night."}, {"q": "7) Salima has many clothes ______ she wants to buy a new dress for Eid.", "a": "Salima has many clothes but she wants to buy a new dress for Eid."}, {"q": "8) ______ me, he is studying and also working.", "a": "Unlike me, he is studying and also working."}]}]}, {"num": "5", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Match column A and B to make sentences. Each sentence will either have 'but' or 'unlike'. Write the complete sentences in your notebooks. Follow the example. 1) Unlike Hyderabad — Bhambhore has no shopping plazas.", "a": "Unlike Hyderabad, Bhambhore has no shopping plazas. (Example given in the book.)"}, {"q": "2) Qurban has three goats — but he wants a cow.", "a": "Qurban has three goats but he wants a cow."}, {"q": "3) Lahore has a river — but Karachi has the sea.", "a": "Lahore has a river but Karachi has the sea."}, {"q": "4) Unlike you — I have six fingers on my right hand.", "a": "Unlike you, I have six fingers on my right hand."}, {"q": "5) I worked hard for the test — but I didn't pass.", "a": "I worked hard for the test but I didn't pass."}, {"q": "6) The peacocks are dying — but people are not paying attention.", "a": "The peacocks are dying but people are not paying attention."}, {"q": "7) Unlike coins — we can fold the paper money.", "a": "Unlike coins, we can fold the paper money."}, {"q": "8) A table has a flat top — but you cannot sleep on it.", "a": "A table has a flat top but you cannot sleep on it."}, {"q": "9) Unlike Aliya — Tasleem is tall.", "a": "Unlike Aliya, Tasleem is tall."}, {"q": "10) I like you — but you don't like me.", "a": "I like you but you don't like me."}]}]}, {"num": "6", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "In pairs, rewrite the following sentences putting in the missing capital letters and question marks. Follow the example. 1) are you ill", "a": "Are you ill?"}, {"q": "2) why are you wearing a sweater in july", "a": "Why are you wearing a sweater in July?"}, {"q": "3) may I come in, please", "a": "May I come in, please?"}, {"q": "4) who is taking farzana aunty to the station", "a": "Who is taking Farzana Aunty to the station?"}, {"q": "5) do you know arif's address in quetta", "a": "Do you know Arif's address in Quetta?"}, {"q": "6) where is the nearest supermarket in the gulshan area", "a": "Where is the nearest supermarket in the Gulshan area?"}, {"q": "7) sadiq, will you help me, please", "a": "Sadiq, will you help me, please?"}, {"q": "8) what did you say to Mrs. Chandio on friday", "a": "What did you say to Mrs. Chandio on Friday?"}, {"q": "9) were they waiting for us or for yusuf", "a": "Were they waiting for us or for Yusuf?"}, {"q": "10) is this the book that you bought from mr. shah", "a": "Is this the book that you bought from Mr. Shah?"}]}]}, {"num": "7", "name": "Exercise 9", "exercises": [{"label": "Exercise 9", "items": [{"q": "In pairs, discuss where to put commas in the following sentences. Write the correct sentences in your notebooks. Follow the examples above. 1) I like to eat eggs chapati and tomato chutney for breakfast.", "a": "I like to eat eggs, chapati and tomato chutney for breakfast."}, {"q": "2) There were plates spoons forks and knives on the table.", "a": "There were plates, spoons, forks and knives on the table."}, {"q": "3) She has dinner reads a book and prays before she goes to sleep.", "a": "She has dinner, reads a book and prays before she goes to sleep."}, {"q": "4) My favourite colours are blue red pink and purple.", "a": "My favourite colours are blue, red, pink and purple."}, {"q": "5) There were winter clothes old shoes and different types of hats in the cupboard.", "a": "There were winter clothes, old shoes and different types of hats in the cupboard."}, {"q": "6) He has to clean his room do his homework and polish his shoes.", "a": "He has to clean his room, do his homework and polish his shoes."}, {"q": "7) I need to visit my mother wash the dishes buy some fruit and cook the meal.", "a": "I need to visit my mother, wash the dishes, buy some fruit and cook the meal."}, {"q": "8) Amna Bashir Sultan and I are playing football.", "a": "Amna, Bashir, Sultan and I are playing football."}, {"q": "9) Karamdad wants to visit France Italy Germany and China.", "a": "Karamdad wants to visit France, Italy, Germany and China."}, {"q": "10) The tree is very beautiful tall old and green.", "a": "The tree is very beautiful, tall, old and green."}]}]}, {"num": "8", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Select sentences from column B to complete the sentences in column A. Write the complete sentences in your notebook. 1. Once you finish your science project,", "a": "Once you finish your science project, I will let you play with your friends. (Example given in the book.)"}, {"q": "2. Once they wash their hands,", "a": "Once they wash their hands, they will be allowed to eat."}, {"q": "3. Once the team finishes the practice,", "a": "Once the team finishes the practice, they can go home."}, {"q": "4. Once you finish your food,", "a": "Once you finish your food, all of you will get ice cream."}, {"q": "5. Once he says sorry,", "a": "Once he says sorry, he will be forgiven."}, {"q": "6. Once they reach Hyderabad,", "a": "Once they reach Hyderabad, they can reach Ranikot within an hour."}, {"q": "7. Once she finishes cooking,", "a": "Once she finishes cooking, she should take some rest."}, {"q": "8. Once the field is ploughed,", "a": "Once the field is ploughed, we can start sowing the seeds."}, {"q": "Complete the following sentence and write it in your notebook. Once you have finished, discuss your work with your partner. You may change your sentence, if you want to, after the discussion. 1) Once I pass my exams, ______.", "a": "Once I pass my exams, I will join English classes to improve my English. (Example given in the book.)"}, {"q": "2) Once my sister has completed her homework, ______.", "a": "Model answer: Once my sister has completed her homework, she will go out to play with her friends. (Any sensible completion is acceptable.)"}, {"q": "3) Once the people have caught the thief, ______.", "a": "Model answer: Once the people have caught the thief, they will hand him over to the police. (Any sensible completion is acceptable.)"}, {"q": "4) Once the monkey is left out of the cage, ______.", "a": "Model answer: Once the monkey is left out of the cage, it will run away into the jungle. (Any sensible completion is acceptable.)"}, {"q": "5) Once my money is finished, ______.", "a": "Model answer: Once my money is finished, I will not be able to buy anything. (Any sensible completion is acceptable.)"}, {"q": "6) Once you have bought an elephant, ______.", "a": "Model answer: Once you have bought an elephant, you will need a big place to keep it. (Any sensible completion is acceptable.)"}, {"q": "7) Once the bell rings, ______.", "a": "Model answer: Once the bell rings, we will go home. (Any sensible completion is acceptable.)"}]}]}, {"num": "9", "name": "Exercise 9", "exercises": [{"label": "Exercise 9", "items": [{"q": "Work in pairs, select the sentences from the following ones in which the colon has been used correctly and write them in your notebook. 1) (a) The children's books were left in three places: Mrs Saleem's room, the kitchen and the gardener's cupboard. (b) The children's books: were left in three places, Mrs Saleem's room, the kitchen and the gardener's cupboard. (c) The children's books were left in three places: Mrs Saleem's room, the kitchen and the gardener's cupboard.", "a": "(a) The children's books were left in three places: Mrs Saleem's room, the kitchen and the gardener's cupboard. CORRECT (given in the book)."}, {"q": "2) (a) My brother has many hobbies: collecting coins from different countries, reading story books, growing fruits and vegetables, and painting natural scenes. (b) My brother has: many hobbies collecting coins from different countries, reading story books, growing fruits and vegetables, and painting natural scenes. (c) My brother has many: hobbies collecting coins from different countries, reading story books, growing fruits and vegetables, and painting natural scenes.", "a": "(a) My brother has many hobbies: collecting coins from different countries, reading story books, growing fruits and vegetables, and painting natural scenes."}, {"q": "3) (a) The basket contained: fruit, biscuits, chocolates and sweets. (b) The basket contained these items: fruit, biscuits, chocolates and sweets. (c) The basket: contained fruit, biscuits, chocolates and sweets.", "a": "(b) The basket contained these items: fruit, biscuits, chocolates and sweets."}, {"q": "4) (a) You can choose: any type of book you want story book, book of jokes, recipe book or gardening book. (b) You can choose any type of book: you want story book, book of jokes, recipe book or gardening book. (c) You can choose any type of book you want: story book, book of jokes or a recipe book gardening book.", "a": "(c) You can choose any type of book you want: story book, book of jokes or a recipe book or gardening book. (The book prints 'a recipe book gardening book' — the word 'or' is missing; it has been added here.)"}, {"q": "5) (a) I can see: many things from here the old lighthouse, seagulls catching fish, children playing on the beach, and boats in the sea. (b) I can see many things from here: the old lighthouse, seagulls catching fish, children playing on the beach, and boats in the sea. (c) I can see many things from here the old lighthouse, seagulls catching fish: children playing on the beach, and boats in the sea.", "a": "(b) I can see many things from here: the old lighthouse, seagulls catching fish, children playing on the beach, and boats in the sea."}, {"q": "6) (a) There are many types of trees here: the old neem tree, the mango tree full of fruits, two trees with tiny lemons, and the tree with red apples. (b) There are many: types of trees here, the old neem tree, the mango tree full of fruits, two trees with tiny lemons, and the tree with red apples. (c) There are many types of trees here, the old neem tree: the mango tree full of fruits, two trees with tiny lemons, and the tree with red apples.", "a": "(a) There are many types of trees here: the old neem tree, the mango tree full of fruits, two trees with tiny lemons, and the tree with red apples."}, {"q": "7) (a) In the bag: there were the following items, scissors, a hairbrush, some money and her address book. (b) In the bag there were: the following items, scissors, a hairbrush, some money and her address book. (c) In the bag there were the following items: scissors, a hairbrush, some money and her address book.", "a": "(c) In the bag there were the following items: scissors, a hairbrush, some money and her address book."}]}]}, {"num": "10", "name": "Exercise 10", "exercises": [{"label": "Exercise 10", "items": [{"q": "Write the following sentence in your notebook by adding a colon and the commas in the right place. The first one has been done as an example. 1) There are many advantages of growing trees pollution free air shade in the summer and branches for tying a swing.", "a": "There are many advantages of growing trees: pollution free air, shade in the summer, and branches for tying a swing. (Example given in the book.)"}, {"q": "2) Please buy these things from the shop a litre of milk a loaf of bread a packet of salt and a tin of oil.", "a": "Please buy these things from the shop: a litre of milk, a loaf of bread, a packet of salt, and a tin of oil."}, {"q": "3) There are too many things in this drawer pencils papers boxes combs and clips.", "a": "There are too many things in this drawer: pencils, papers, boxes, combs and clips."}, {"q": "4) Travelling by train has many advantages one can easily walk about there is place to sleep properly one can enjoy the scenery and one can make new friends.", "a": "Travelling by train has many advantages: one can easily walk about, there is place to sleep properly, one can enjoy the scenery, and one can make new friends."}, {"q": "5) Cut all these fruits and put them in the bowl a mango three bananas an orange two apples and a guava.", "a": "Cut all these fruits and put them in the bowl: a mango, three bananas, an orange, two apples, and a guava."}, {"q": "6) Pack all the things that we need to take with us all our warm clothes at least three pairs of shoes the new camera some of the medicines and one or two blankets.", "a": "Pack all the things that we need to take with us: all our warm clothes, at least three pairs of shoes, the new camera, some of the medicines, and one or two blankets."}, {"q": "7) The girls decided to buy all the things they would need for Eid dresses sandals purses bangles earrings and mehndi.", "a": "The girls decided to buy all the things they would need for Eid: dresses, sandals, purses, bangles, earrings and mehndi."}]}]}, {"num": "11", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Match the sentences in column A with those in column B to show the Cause and Effect / Result relationship. Write your answer in column C. 1. Saeed will travel to school by bus. — ______", "a": "1-d: Saeed will travel to school by bus — His bicycle is at the mechanic's. (Example given in the book.)"}, {"q": "2. Jaleel was soaked from head to toe. — ______", "a": "2-g: Jaleel was soaked from head to toe — He walked in the rain from school."}, {"q": "3. Daud would like to buy a new watch. — ______", "a": "3-j: Daud would like to buy a new watch — His old one fell in the river."}, {"q": "4. She was crying. — ______", "a": "4-h: She was crying — Maria lost her new doll."}, {"q": "5. I have a beautiful garden. — ______", "a": "5-c: I have a beautiful garden — Many people come to admire my garden."}, {"q": "6. It was a hot summer day. — ______", "a": "6-i: It was a hot summer day — We all decided to have cold lassi."}, {"q": "7. She was looking after the baby. — ______", "a": "7-a: She was looking after the baby — Mother did not cook last night."}, {"q": "8. There was a banana peel on the floor. — ______", "a": "8-b: There was a banana peel on the floor — Hajrah slipped and fell down."}, {"q": "9. The fruit was not washed properly. — ______", "a": "9-e: The fruit was not washed properly — I got sick when I ate it."}, {"q": "10. It was my sister's wedding. — ______", "a": "10-f: It was my sister's wedding — We served biryani for dinner."}]}]}, {"num": "12", "name": "Exercise 8", "exercises": [{"label": "Exercise 8", "items": [{"q": "Rewrite the matched sentences in column C by using as and because. 1) Saeed will travel to school by bus. His bicycle is at the mechanic's.", "a": "Saeed will travel to school by bus as his bicycle is at the mechanic's. OR As his bicycle is at the mechanic's, Saeed will travel to school by bus. (Example given in the book.)"}, {"q": "2) Jaleel was soaked from head to toe. He walked in the rain from school.", "a": "Jaleel was soaked from head to toe as he walked in the rain from school. OR Jaleel was soaked from head to toe because he walked in the rain from school."}, {"q": "3) Daud would like to buy a new watch. His old one fell in the river.", "a": "Daud would like to buy a new watch as his old one fell in the river. OR Daud would like to buy a new watch because his old one fell in the river."}, {"q": "4) She was crying. Maria lost her new doll.", "a": "She was crying as Maria lost her new doll. OR She was crying because Maria lost her new doll."}, {"q": "5) I have a beautiful garden. Many people come to admire my garden.", "a": "I have a beautiful garden as many people come to admire my garden. OR I have a beautiful garden because many people come to admire my garden."}, {"q": "6) It was a hot summer day. We all decided to have cold lassi.", "a": "We all decided to have cold lassi as it was a hot summer day. OR We all decided to have cold lassi because it was a hot summer day."}, {"q": "7) She was looking after the baby. Mother did not cook last night.", "a": "Mother did not cook last night as she was looking after the baby. OR Mother did not cook last night because she was looking after the baby."}, {"q": "8) There was a banana peel on the floor. Hajrah slipped and fell down.", "a": "Hajrah slipped and fell down as there was a banana peel on the floor. OR Hajrah slipped and fell down because there was a banana peel on the floor."}, {"q": "9) The fruit was not washed properly. I got sick when I ate it.", "a": "I got sick as the fruit was not washed properly. OR I got sick because the fruit was not washed properly."}, {"q": "10) It was my sister's wedding. We served biryani for dinner.", "a": "We served biryani for dinner as it was my sister's wedding. OR We served biryani for dinner because it was my sister's wedding."}]}]}], "words": [{"w": "cohesive device", "sd": "ڳنڍڻ وارو اوزار", "syn": "a word or phrase that links sentences and ideas"}, {"w": "punctuation", "sd": "اوقاف", "syn": "marks like the full stop and comma that organise writing"}, {"w": "quotation marks", "sd": "واوين", "syn": "the marks \" \" used around spoken words"}, {"w": "colon", "sd": "نقطا", "syn": "the mark : used before a list or explanation"}]}, {"cls": "vii", "unit": 1, "title": "Possessive Pronouns", "display": "Possessive Pronouns", "reading": "My English Book 7, Unit 1, Language Practice", "lesson": [{"t": "h", "x": "Possessive Pronouns"}, {"t": "p", "x": "A possessive pronoun shows that something belongs to somebody, and it stands alone without a noun after it."}, {"t": "def", "x": "A possessive pronoun is a word like mine, yours, his, hers, ours or theirs. It shows ownership and stands alone."}, {"t": "h", "x": "Rule 1. Possessive pronouns stand alone"}, {"t": "rule", "x": "A possessive pronoun does not need a noun after it. 'This book is mine' — 'mine' stands alone."}, {"t": "ex", "x": "This pen is mine. That bag is yours. The house is ours. The toys are theirs. The bat is his. The doll is hers."}, {"t": "h", "x": "Rule 2. Match the possessive pronoun with the owner"}, {"t": "rule", "x": "Use 'mine' for I, 'yours' for you, 'his' for he, 'hers' for she, 'ours' for we, 'theirs' for they."}, {"t": "ex", "x": "I have a book. The book is mine. Ali has a bat. The bat is his. We have a house. The house is ours."}, {"t": "h", "x": "Rule 3. Do not mix up possessive adjectives and possessive pronouns"}, {"t": "rule", "x": "A possessive adjective needs a noun after it (my book). A possessive pronoun stands alone (The book is mine)."}, {"t": "ex", "x": "This is my pen. The pen is mine. This is her bag. The bag is hers. This is our house. The house is ours."}, {"t": "rl", "x": "At school, this pen is mine and that pen is yours. The teacher says, 'Whose book is this?' I say, 'It is mine.'"}, {"t": "rl", "x": "At home, my mother says, 'This room is ours.' My sister says, 'That doll is mine, not hers.'"}, {"t": "rl", "x": "In the market, my father bought a bag. The bag is his. My brother bought a ball. The ball is his too."}, {"t": "note", "x": "Do not write an apostrophe in possessive pronouns: 'hers', 'theirs', 'ours' — not 'her's' or 'their's'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Fill in the blanks in the following exercise with the possessive pronouns given in the box below. You can use one pronoun only once. Write the complete sentences in your notebook. Box: mine, your's, his, her's, our's, their's, its. 1. This is the cat's food. The food is ______.", "a": "This is the cat's food. The food is its."}, {"q": "2. That house belongs to us. The house is ______.", "a": "That house belongs to us. The house is ours."}, {"q": "3. Adnan is the owner of the blue car. The car is ______.", "a": "Adnan is the owner of the blue car. The car is his."}, {"q": "4. I have many pictures. The pictures are all ______.", "a": "I have many pictures. The pictures are all mine."}, {"q": "5. You received this prize. It is ______.", "a": "You received this prize. It is yours."}, {"q": "6. These goats were given to them. The goats are ______.", "a": "These goats were given to them. The goats are theirs."}, {"q": "7. The teacher gave her the pencil. The pencil was ______.", "a": "The teacher gave her the pencil. The pencil was hers."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Fill in the blanks with suitable possessive pronouns with the help of the hints. Write the answers in your notebook. i. Look at the bowls of ice-cream. ______ is the blue one. (belongs to Meena)", "a": "Look at the bowls of ice-cream. Hers is the blue one."}, {"q": "ii. I like your dress. Do you like ______? (my dress)", "a": "I like your dress. Do you like mine?"}, {"q": "iii. I looked everywhere for your socks. I found Ali's socks but couldn't find ______. (socks belong to you)", "a": "I looked everywhere for your socks. I found Ali's socks but couldn't find yours."}, {"q": "iv. All the books were good but ______ was the best. (Ali's story book was the best)", "a": "All the books were good but his was the best."}, {"q": "v. Sara has cleaned her cupboards but Sana has not cleaned ______ as yet. (Sana's Cupboard)", "a": "Sara has cleaned her cupboards but Sana has not cleaned hers as yet."}, {"q": "vi. Here is your car, ______ is over there, where we left it. (belonging to my family)", "a": "Here is your car, ours is over there, where we left it."}, {"q": "vii. The soldier has won this medal through hard work. It is ______. (soldier's medal)", "a": "The soldier has won this medal through hard work. It is his."}, {"q": "viii. The piano you were playing with is new. They are ______. (belong to them)", "a": "The piano you were playing with is new. They are theirs."}, {"q": "ix. The dog is wearing a nice collar, but it is not ______. (dog's collar)", "a": "The dog is wearing a nice collar, but it is not its."}, {"q": "x. Your photos are good but ______ are terrible. (the photos belonging to us)", "a": "Your photos are good but ours are terrible."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Work in pairs and orally complete the following dialogue; one student should play the role of Mansoor and the other of Yaqoob. Fill in the blanks with the correct possessive pronouns. The first one has been done as an example. After the oral practice, write the complete dialogue in your notebooks. Mansoor: I bought this book yesterday. It is mine.", "a": "Mansoor: I bought this book yesterday. It is mine. (Example given in the book.)"}, {"q": "Yaqoob: You also bought this pen. It is ______.", "a": "Yaqoob: You also bought this pen. It is yours."}, {"q": "Mansoor: Which book is Rubina's? Yaqoob: The book with the blue cover is ______.", "a": "Yaqoob: The book with the blue cover is hers."}, {"q": "Mansoor: And what about Babar? Yaqoob: The grey cap is ______.", "a": "Yaqoob: The grey cap is his."}, {"q": "Mansoor: I also bought something for uncle Qurban's family. Yaqoob: Yes, this table cloth is ______.", "a": "Yaqoob: Yes, this table cloth is theirs."}, {"q": "Mansoor: Where is the bird's food? Yaqoob: The food is ______. It can eat.", "a": "Yaqoob: The food is its. It can eat."}, {"q": "Mansoor: The bird is for us. It is ______. And I also bought this computer for you. Yaqoob: Wow! This computer is ______ now!", "a": "Mansoor: The bird is for us. It is ours. And I also bought this computer for you. Yaqoob: Wow! This computer is yours now!"}]}]}], "words": [{"w": "possessive pronoun", "sd": "ملڪيتي ضمير", "syn": "a pronoun like mine or theirs that shows ownership and stands alone"}, {"w": "possessive adjective", "sd": "ملڪيتي صفت", "syn": "a word like my or his that comes before a noun"}]}, {"cls": "vii", "unit": 2, "title": "Countable and Uncountable Nouns", "display": "Countable and Uncountable Nouns", "reading": "My English Book 7, Unit 1, Language Practice", "lesson": [{"t": "h", "x": "Countable and Uncountable Nouns"}, {"t": "p", "x": "Some nouns can be counted and some cannot. Countable nouns have a plural. Uncountable nouns do not."}, {"t": "def", "x": "A countable noun is a noun we can count: one book, two books. An uncountable noun is a noun we cannot count: water, milk, rice."}, {"t": "h", "x": "Rule 1. Countable nouns have a plural"}, {"t": "rule", "x": "Countable nouns can be singular or plural. We can count them with numbers."}, {"t": "ex", "x": "book — books, pen — pens, boy — boys, mango — mangoes, chair — chairs, apple — apples."}, {"t": "h", "x": "Rule 2. Uncountable nouns have no plural"}, {"t": "rule", "x": "Uncountable nouns like water, milk, sugar, rice, oil, salt, tea and flour have no plural. We do not add 's' to them."}, {"t": "ex", "x": "water, milk, rice, sugar, oil, salt, tea, flour, sand, air, money, advice, furniture."}, {"t": "h", "x": "Rule 3. Use 'some', 'much' and 'a little' with uncountable nouns"}, {"t": "rule", "x": "We say 'some water', 'much water' and 'a little water'. We do not say 'two waters'."}, {"t": "ex", "x": "I want some milk. There is much water in the jug. Give me a little sugar."}, {"t": "h", "x": "Rule 4. Use 'many' and 'a few' with countable nouns"}, {"t": "rule", "x": "We say 'many books' and 'a few pens'. We do not say 'much books'."}, {"t": "ex", "x": "There are many students in the class. I have a few pens. How many mangoes do you want?"}, {"t": "rl", "x": "At school, I have three books and two pens. They are countable. My bottle has water in it. Water is uncountable."}, {"t": "rl", "x": "At home, my mother cooks rice for us. Rice is uncountable. She gives me an apple. Apples are countable."}, {"t": "rl", "x": "In the market, the shopkeeper sells sugar and oil. Sugar and oil are uncountable. He also sells mangoes and apples. They are countable."}, {"t": "note", "x": "Some nouns can be both: 'a glass' (countable) and 'glass' as a material (uncountable)."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Fill in the blanks in the following exercise with suitable phrases given in the box below. Do the exercise in your notebook. After you have done it, discuss your answers with your partner. Box: a tankful of, 10 pages of, a spoonful of, three cups of, some, a slice of, a lot of, a pinch of, a glass of, a sack of. i. Can I have ______ water, please?", "a": "Can I have a glass of water, please?"}, {"q": "ii. Pass me ______ bread, please.", "a": "Pass me a slice of bread, please."}, {"q": "iii. Add ______ salt in the flour.", "a": "Add a pinch of salt in the flour."}, {"q": "iv. Ahmed carried ______ flour on his back.", "a": "Ahmed carried a sack of flour on his back."}, {"q": "v. Put ______ sugar in my tea.", "a": "Put a spoonful of sugar in my tea."}, {"q": "vi. There is ______ traffic on the road.", "a": "There is a lot of traffic on the road."}, {"q": "vii. The fire brigade had ______ water.", "a": "The fire brigade had a tankful of water."}, {"q": "viii. I need ______ tea for the guests.", "a": "I need three cups of tea for the guests."}, {"q": "ix. The beggar is asking for ______ money.", "a": "The beggar is asking for some money."}, {"q": "x. The teacher told the students to search for ______ information on Bhambore.", "a": "The teacher told the students to search for 10 pages of information on Bhambore."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Your mother wants to buy twelve things when she goes shopping. Add three things that you want her to buy for you. Make a shopping list of all the things by adding 'how much' or 'how many', she has to buy. Two have been done as examples. 1. bananas — ______", "a": "1. bananas — a dozen bananas"}, {"q": "2. meat — ______", "a": "2. meat — two kilograms of meat. (Example given in the book.)"}, {"q": "3. oil — ______", "a": "3. oil — two litres of oil"}, {"q": "4. milk — ______", "a": "4. milk — two litres of milk"}, {"q": "5. tea — ______", "a": "5. tea — a packet of tea. (Example given in the book.)"}, {"q": "6. mangoes — ______", "a": "6. mangoes — two kilograms of mangoes"}, {"q": "7. rice — ______", "a": "7. rice — five kilograms of rice"}, {"q": "8. eggs — ______", "a": "8. eggs — a dozen eggs"}, {"q": "9. flour — ______", "a": "9. flour — five kilograms of flour"}, {"q": "10. juice — ______", "a": "10. juice — two bottles of juice"}, {"q": "11. candles — ______", "a": "11. candles — ten candles"}, {"q": "12. salt — ______", "a": "12. salt — one kilogram of salt"}, {"q": "13. (Add one thing that you want your mother to buy for you.) — ______", "a": "13. biscuits — a packet of biscuits"}, {"q": "14. (Add one thing that you want your mother to buy for you.) — ______", "a": "14. apples — a dozen apples"}, {"q": "15. (Add one thing that you want your mother to buy for you.) — ______", "a": "15. soap — two bars of soap"}]}]}], "words": [{"w": "countable noun", "sd": "ڳڻپ جوڳو اسم", "syn": "a noun we can count"}, {"w": "uncountable noun", "sd": "اڻڳڻپ جوڳو اسم", "syn": "a noun we cannot count"}]}, {"cls": "vii", "unit": 3, "title": "Articles", "display": "Articles", "reading": "My English Book 7, Units 2 and 5, Language Practice", "lesson": [{"t": "h", "x": "Articles"}, {"t": "p", "x": "A, an and the are articles. We use 'a' and 'an' for one thing in general, and 'the' for a special or known thing."}, {"t": "def", "x": "An article is a word used before a noun. 'A' and 'an' are indefinite articles. 'The' is the definite article."}, {"t": "h", "x": "Rule 1. Use 'a' before a consonant sound"}, {"t": "rule", "x": "Use 'a' before a word that begins with a consonant sound."}, {"t": "ex", "x": "a book, a pen, a dress, a boy, a country, a university, a one-rupee coin."}, {"t": "h", "x": "Rule 2. Use 'an' before a vowel sound"}, {"t": "rule", "x": "Use 'an' before a word that begins with a vowel sound (a, e, i, o, u)."}, {"t": "ex", "x": "an apple, an egg, an eye, an elephant, an umbrella, an hour, an honest man."}, {"t": "h", "x": "Rule 3. Use 'the' for a special or known thing"}, {"t": "rule", "x": "Use 'the' when we talk about a special or known thing, or when there is only one of it."}, {"t": "ex", "x": "The sun rises in the east. The River Indus is the longest river in Pakistan. The book on the table is mine. I read the newspaper in the morning."}, {"t": "h", "x": "Rule 4. Use 'the' with superlatives and with some names"}, {"t": "rule", "x": "Use 'the' before the superlative degree and before the names of rivers, seas, oceans and mountain ranges."}, {"t": "ex", "x": "the tallest boy, the best student, the River Indus, the Arabian Sea, the Himalayas."}, {"t": "h", "x": "Rule 5. Use no article in some cases"}, {"t": "rule", "x": "Do not use an article before a person's name, before a general plural noun, or before the name of a language or a subject."}, {"t": "ex", "x": "Ali is my friend. Boys play cricket. I learn English. We study science."}, {"t": "rl", "x": "At school, I have a pen and an eraser. The pen is blue. The teacher is the best in our school."}, {"t": "rl", "x": "At home, my mother bought a dress. The dress is red. She gave me an apple."}, {"t": "rl", "x": "In the market, I saw the moon in the sky. The sun is hot. A shopkeeper sells fruit."}, {"t": "note", "x": "Use 'the' the second time we talk about a thing: 'I saw a dog. The dog was black.'"}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Here is a list of 12 nouns; some of these are single and countable, some are countable but are not single, and some are uncountable. Write these in your notebook and add 'a' or 'an' before single countable nouns. 1. food, 2. room, 3. apple, 4. water, 5. kite, 6. tables, 7. orange, 8. hour, 9. milk, 10. vans, 11. eyes, 12. finger.", "a": "1. food — uncountable, so no article is used. 2. a room. 3. an apple. 4. water — uncountable, so no article is used. 5. a kite. 6. tables — plural countable, so no article is used. 7. an orange. 8. an hour. 9. milk — uncountable, so no article is used. 10. vans — plural countable, so no article is used. 11. eyes — plural countable, so no article is used. 12. a finger."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Now, here is a list of 12 adjectives that you can use with the nouns given in exercise 1. Work with a partner and decide which adjective you can use with each noun. The adjectives are in a jumbled order. You can use each adjective only once. Write down the most suitable adjective along with each noun in your notebook. Don't forget to add 'a' and 'an' where necessary. Adjectives: 1. oval, 2. black, 3. early, 4. tasty, 5. injured, 6. sweet, 7. fast, 8. twenty, 9. dirty, 10. untidy, 11. creamy, 12. unripe.", "a": "1. food — tasty food. 2. room — an untidy room. 3. apple — a sweet apple. 4. water — dirty water. 5. kite — an oval kite. 6. tables — twenty tables. 7. orange — unripe oranges. 8. hour — an early hour. 9. milk — creamy milk. 10. vans — fast vans. 11. eyes — black eyes. 12. finger — an injured finger."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Complete the following sentences using the suitable adjective-noun pair, along with the article, if any, from exercise 2. Do the exercise in your note book. After you have done it, compare your answers with your partner. 1. Mansoor bought ______ for the kite flying competition.", "a": "Mansoor bought an oval kite for the kite flying competition."}, {"q": "2. My mother made pudding with ______.", "a": "My mother made pudding with creamy milk."}, {"q": "3. The cook made ______ for my sister's wedding.", "a": "The cook made tasty food for my sister's wedding."}, {"q": "4. Please don't buy ______.", "a": "Please don't buy unripe oranges."}, {"q": "5. The cleaner managed to do all his work with ______.", "a": "The cleaner managed to do all his work with an injured finger."}, {"q": "6. Drinking ______ can make us fall sick.", "a": "Drinking dirty water can make us fall sick."}, {"q": "7. Get up at ______ and you will be able to complete all your work.", "a": "Get up at an early hour and you will be able to complete all your work."}, {"q": "8. The baby has brown hair and ______.", "a": "The baby has brown hair and black eyes."}, {"q": "9. Put ______ here, one behind the other.", "a": "Put twenty tables here, one behind the other."}, {"q": "10. The people were afraid because the ______ were racing against each other.", "a": "The people were afraid because the fast vans were racing against each other."}, {"q": "11. I like eating ______ every day.", "a": "I like eating a sweet apple every day."}, {"q": "12. His father told him to clean up his ______.", "a": "His father told him to clean up his untidy room."}]}]}, {"num": "4", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "In all the following sentences the article 'the' has to be used twice. Read these sentences and decide where the article will come. Now write the complete sentences, along with the article 'the' in your notebooks. 1. Sami is most intelligent boy in class.", "a": "Sami is the most intelligent boy in the class."}, {"q": "In all the following sentences the article 'the' has to be used twice. Read these sentences and decide where the article will come. Now write the complete sentences, along with the article 'the' in your notebooks. 2. We must all do something to make sure that air we breathe and water we drink are clean.", "a": "We must all do something to make sure that the air we breathe and the water we drink are clean."}, {"q": "In all the following sentences the article 'the' has to be used twice. Read these sentences and decide where the article will come. Now write the complete sentences, along with the article 'the' in your notebooks. 3. We swam in lake not in river because it was safer.", "a": "We swam in the lake not in the river because it was safer."}, {"q": "In all the following sentences the article 'the' has to be used twice. Read these sentences and decide where the article will come. Now write the complete sentences, along with the article 'the' in your notebooks. 4. I hope my city will be cleanest city in world one day.", "a": "I hope my city will be the cleanest city in the world one day."}, {"q": "In all the following sentences the article 'the' has to be used twice. Read these sentences and decide where the article will come. Now write the complete sentences, along with the article 'the' in your notebooks. 5. Harry saw clouds coming from behind mountain.", "a": "Harry saw the clouds coming from behind the mountain."}, {"q": "In all the following sentences the article 'the' has to be used twice. Read these sentences and decide where the article will come. Now write the complete sentences, along with the article 'the' in your notebooks. 6. Our house is in north of city.", "a": "Our house is in the north of the city."}, {"q": "In all the following sentences the article 'the' has to be used twice. Read these sentences and decide where the article will come. Now write the complete sentences, along with the article 'the' in your notebooks. 7. I can see sun rising in east from my window.", "a": "I can see the sun rising in the east from my window."}, {"q": "In all the following sentences the article 'the' has to be used twice. Read these sentences and decide where the article will come. Now write the complete sentences, along with the article 'the' in your notebooks. 8. All citizens must follow traffic rules while walking and driving on road.", "a": "All citizens must follow the traffic rules while walking and driving on the road."}]}]}], "words": [{"w": "article", "sd": "حرف تنڪير", "syn": "a word like a, an or the used before a noun"}, {"w": "definite article", "sd": "حرف تنڪير خاص", "syn": "the article 'the'"}, {"w": "indefinite article", "sd": "حرف تنڪير عام", "syn": "the articles 'a' and 'an'"}]}, {"cls": "vii", "unit": 4, "title": "Reflexive Pronouns", "display": "Reflexive Pronouns", "reading": "My English Book 7, Unit 2, Language Practice", "lesson": [{"t": "h", "x": "Reflexive Pronouns"}, {"t": "p", "x": "A reflexive pronoun ends in 'self' or 'selves'. It points back to the subject of the sentence."}, {"t": "def", "x": "A reflexive pronoun is a pronoun like myself, yourself, himself, herself, itself, ourselves, yourselves or themselves. It points back to the subject."}, {"t": "h", "x": "Rule 1. Use a reflexive pronoun when the subject and the object are the same person"}, {"t": "rule", "x": "When the subject does something to himself or herself, use a reflexive pronoun."}, {"t": "ex", "x": "I hurt myself. He taught himself. She made the dress herself. They enjoyed themselves."}, {"t": "h", "x": "Rule 2. Match the reflexive pronoun with the subject"}, {"t": "rule", "x": "Use 'myself' with I, 'yourself' with you (one person), 'himself' with he, 'herself' with she, 'itself' with it, 'ourselves' with we, 'yourselves' with you (many people), 'themselves' with they."}, {"t": "ex", "x": "I did it myself. You did it yourself. He did it himself. She did it herself. We did it ourselves. They did it themselves."}, {"t": "h", "x": "Rule 3. Use a reflexive pronoun for emphasis"}, {"t": "rule", "x": "We also use a reflexive pronoun to emphasise the subject: 'I myself did it.' 'The king himself came.'"}, {"t": "ex", "x": "The teacher herself checked the papers. I myself saw the accident. Raza fixed the radio himself."}, {"t": "rl", "x": "At school, I finished my homework myself. My friend taught himself to draw. The teacher said, 'Do it yourselves.'"}, {"t": "rl", "x": "At home, my sister made a card herself. My brother hurt himself while playing. We cleaned the house ourselves."}, {"t": "rl", "x": "On the cricket ground, the captain hurt himself while catching the ball. The boys enjoyed themselves."}, {"t": "note", "x": "Do not use 'hisself' or 'theirselves'. The correct forms are 'himself' and 'themselves'."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Here is a list of reflexive pronouns. Fill the following blanks with the correct reflexive pronoun. You can use each reflexive pronoun only once. Pronouns: myself, ourselves, yourself, yourselves, herself, himself, itself, themselves. a) I hurt ______ while cleaning the kitchen.", "a": "a) I hurt myself while cleaning the kitchen."}, {"q": "b) She hurt ______ while trying to learn a new game.", "a": "b) She hurt herself while trying to learn a new game."}, {"q": "c) She should swim ______ in hot weather.", "a": "c) She should swim herself in hot weather. (As printed, this sentence is ungrammatical — see the flags file. The book probably means 'She should swim by herself in hot weather.')"}, {"q": "d) She photographed ______.", "a": "d) She photographed herself."}, {"q": "e) They trained ______ for the match.", "a": "e) They trained themselves for the match."}, {"q": "f) He danced ______ on the stage.", "a": "f) He danced himself on the stage. (As printed, this is ungrammatical — see the flags file. The book probably means 'He danced by himself on the stage.')"}, {"q": "g) Irellised ______ that I am right.", "a": "g) I realised myself that I am right. (The book prints the verb as 'Irellised' — a misprint for 'realised' — and the sentence takes no reflexive pronoun; see the flags file. The book probably means 'I reminded myself that I am right.')"}, {"q": "h) We changed ______.", "a": "h) We changed ourselves."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Match the questions with suitable answers. Write your answers in the match column. One has been done as an example. 1. Who did your homework? Answers: a) No, he will come himself. b) Yes, she stitched herself. c) No one, I made myself. d) No, he did himself. e) No, they repaired themselves. f) I did myself. g) No, we figured out ourselves.", "a": "1 f — Who did your homework? I did myself. (Example given in the book.)"}, {"q": "2. Did the carpenter help them in making the stage?", "a": "2 d — Did the carpenter help them in making the stage? No, he did himself. (By elimination — see the flags file; no answer in the list matches this question properly.)"}, {"q": "3. Did the leaflet explain how it was to be done?", "a": "3 g — Did the leaflet explain how it was to be done? No, we figured out ourselves."}, {"q": "4. Who helped you to make it?", "a": "4 c — Who helped you to make it? No one, I made myself."}, {"q": "5. Will Ali pick him up on his way?", "a": "5 a — Will Ali pick him up on his way? No, he will come himself."}, {"q": "6. She is wearing a well stitched dress, isn't she?", "a": "6 b — She is wearing a well stitched dress, isn't she? Yes, she stitched herself."}, {"q": "7. Did the mechanic repair their car?", "a": "7 e — Did the mechanic repair their car? No, they repaired themselves."}]}]}, {"num": "3", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Fill in the blanks with suitable reflexive pronouns. i. Raza was going to take it to the shop but ended up fixing by ______ one afternoon.", "a": "i. Raza was going to take it to the shop but ended up fixing it by himself one afternoon."}, {"q": "ii. We must avoid reporting things that we haven't seen ______.", "a": "ii. We must avoid reporting things that we haven't seen ourselves."}, {"q": "iii. You told ______ that you bought it for Rs. 500.", "a": "iii. You told yourself that you bought it for Rs. 500."}, {"q": "iv. He prefers to be by ______ while preparing for tests.", "a": "iv. He prefers to be by himself while preparing for tests."}, {"q": "v. My brother and I served snacks to the guests ______ as our mother was not home.", "a": "v. My brother and I served snacks to the guests ourselves as our mother was not home."}, {"q": "vi. The horse hurt ______ while trying to escape.", "a": "vi. The horse hurt itself while trying to escape."}, {"q": "vii. All of you will have to go ______ to get your gift.", "a": "vii. All of you will have to go yourselves to get your gift."}, {"q": "viii. The boys want to learn cooking so, they are cooking ______.", "a": "viii. The boys want to learn cooking so, they are cooking themselves."}, {"q": "ix. We should not fight ______.", "a": "ix. We should not fight ourselves."}, {"q": "x. The car started moving by ______ as it was on a slope.", "a": "x. The car started moving by itself as it was on a slope."}]}]}], "words": [{"w": "reflexive pronoun", "sd": "انعڪاسي ضمير", "syn": "a pronoun ending in self or selves that points back to the subject"}, {"w": "emphasis", "sd": "زور", "syn": "giving special importance to a word"}]}, {"cls": "vii", "unit": 5, "title": "Conditional Sentences", "display": "Conditional Sentences", "reading": "My English Book 7, Unit 3, Language Practice", "lesson": [{"t": "h", "x": "Conditional Sentences"}, {"t": "p", "x": "A conditional sentence has two parts: the 'if' part (the condition) and the result part. If one thing happens, another thing will happen."}, {"t": "def", "x": "A conditional sentence talks about a condition and its result. The first conditional is: If + present simple, will + verb."}, {"t": "h", "x": "Rule 1. First conditional: If + present simple, will + verb"}, {"t": "rule", "x": "In the first conditional, the 'if' part uses the present simple and the result part uses 'will' with the verb."}, {"t": "ex", "x": "If you work hard, you will pass. If Alina works fast, she will finish her work. If it rains, we will stay at home."}, {"t": "h", "x": "Rule 2. The 'if' part can come first or second"}, {"t": "rule", "x": "The 'if' clause can come first or second. Use a comma when it comes first."}, {"t": "ex", "x": "If you work hard, you will pass. You will pass if you work hard. She will finish her work if Alina works fast."}, {"t": "h", "x": "Rule 3. Do not use 'will' in the 'if' part"}, {"t": "rule", "x": "Do not use 'will' in the 'if' part of a first conditional sentence."}, {"t": "ex", "x": "If you work hard, you will pass. (Not: If you will work hard, you will pass.)"}, {"t": "h", "x": "Rule 4. Join sentences with 'and' and 'but'"}, {"t": "rule", "x": "Use 'and' to join two same ideas and 'but' to join two different ideas."}, {"t": "ex", "x": "Salma loves mangoes, but she does not like oranges. My mother loves me, and she loves my sister too. The boy is sad because he lost his ball."}, {"t": "rl", "x": "At school, if I work hard, I will pass my exams. If I am late, the teacher will punish me."}, {"t": "rl", "x": "At home, if my mother cooks biryani, I will eat two plates. If it rains, we will stay at home."}, {"t": "rl", "x": "On the cricket ground, if Ali bats well, we will win the match. If it rains, the match will stop."}, {"t": "note", "x": "The first conditional talks about a real future result. It is not about an impossible dream."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Match the 'if' clause with its result clause: If you work hard,", "a": "c. you will get good grades. — If you work hard, you will get good grades. (Example given in the book.)"}, {"q": "Match the 'if' clause with its result clause: If it rains,", "a": "h. I will stay at home. — If it rains, I will stay at home."}, {"q": "Match the 'if' clause with its result clause: If father allows me,", "a": "f. I will go with you. — If father allows me, I will go with you."}, {"q": "Match the 'if' clause with its result clause: If he helps Abdul,", "a": "a. he will not have any problem. — If he helps Abdul, he will not have any problem."}, {"q": "Match the 'if' clause with its result clause: If Amma makes the halwa,", "a": "g. we will enjoy eating it. — If Amma makes the halwa, we will enjoy eating it."}, {"q": "Match the 'if' clause with its result clause: If Salma sings well", "a": "b. she will win the singing competition. — If Salma sings well, she will win the singing competition."}, {"q": "Match the 'if' clause with its result clause: If I feed the dog,", "a": "e. it will take care of my house. — If I feed the dog, it will take care of my house."}, {"q": "Match the 'if' clause with its result clause: If she treats the children nicely,", "a": "d. they will always listen to her. — If she treats the children nicely, they will always listen to her."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Complete the conditional sentence: If Alina works fast,", "a": "Model sentence: If Alina works fast, she will finish her work on time."}, {"q": "Complete the conditional sentence: If Saleem writes neatly,", "a": "Model sentence: If Saleem writes neatly, his teacher will praise him."}, {"q": "Complete the conditional sentence: If the weather becomes sunny,", "a": "Model sentence: If the weather becomes sunny, we will go out to play."}, {"q": "Complete the conditional sentence: If father comes home early,", "a": "Model sentence: If father comes home early, we will go to the park with him."}, {"q": "Complete the conditional sentence: If my work finishes before 5 o'clock,", "a": "Model sentence: If my work finishes before 5 o'clock, I will go home early."}, {"q": "Complete the conditional sentence: If the train leaves on time,", "a": "Model sentence: If the train leaves on time, we will reach our destination in time."}, {"q": "Complete the conditional sentence: If we help others,", "a": "Model sentence: If we help others, they will help us when we need help."}, {"q": "Complete the conditional sentence: If the ministers do their work,", "a": "Model sentence: If the ministers do their work, our country will make progress."}, {"q": "Complete the conditional sentence in the thought bubble: If my sister comes early", "a": "Model sentence: If my sister comes early, we will play together. (The thought bubble in the book gives this ninth 'if' clause with no result clause.)"}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Rewrite the sentence from Exercise 2 with the 'if' clause at the end: If Alina works fast, she will finish her work on time.", "a": "Alina will finish her work on time if she works fast. (Example given in the book.)"}, {"q": "Rewrite the sentence from Exercise 2 with the 'if' clause at the end: If Saleem writes neatly, his teacher will praise him.", "a": "His teacher will praise Saleem if he writes neatly."}, {"q": "Rewrite the sentence from Exercise 2 with the 'if' clause at the end: If the weather becomes sunny, we will go out to play.", "a": "We will go out to play if the weather becomes sunny."}, {"q": "Rewrite the sentence from Exercise 2 with the 'if' clause at the end: If father comes home early, we will go to the park with him.", "a": "We will go to the park with father if he comes home early."}, {"q": "Rewrite the sentence from Exercise 2 with the 'if' clause at the end: If my work finishes before 5 o'clock, I will go home early.", "a": "I will go home early if my work finishes before 5 o'clock."}, {"q": "Rewrite the sentence from Exercise 2 with the 'if' clause at the end: If the train leaves on time, we will reach our destination in time.", "a": "We will reach our destination in time if the train leaves on time."}, {"q": "Rewrite the sentence from Exercise 2 with the 'if' clause at the end: If we help others, they will help us when we need help.", "a": "People will help us if we help others."}, {"q": "Rewrite the sentence from Exercise 2 with the 'if' clause at the end: If the ministers do their work, our country will make progress.", "a": "Our country will make progress if the ministers do their work."}, {"q": "Rewrite the sentence from Exercise 2 with the 'if' clause at the end: If my sister comes early, we will play together.", "a": "We will play together if my sister comes early."}]}]}, {"num": "4", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Join the following sentences using 'but' and 'and': Salma loves mangoes. She does not like oranges.", "a": "Salma loves mangoes but she does not like oranges."}, {"q": "Join the following sentences using 'but' and 'and': This flower is very beautiful. It smells nice too.", "a": "This flower is very beautiful and it smells nice too."}, {"q": "Join the following sentences using 'but' and 'and': The white cup is full. The blue one is empty.", "a": "The white cup is full but the blue one is empty."}, {"q": "Join the following sentences using 'but' and 'and': We are on time. The train is late.", "a": "We are on time but the train is late."}, {"q": "Join the following sentences using 'but' and 'and': My brother plays cricket. My brother plays hockey.", "a": "My brother plays cricket and hockey."}, {"q": "Join the following sentences using 'but' and 'and': This book has many pages. This book has very few pages.", "a": "This book has many pages but this book has very few pages. (The two sentences contradict each other — see the flags file.)"}, {"q": "Join the following sentences using 'but' and 'and': I like climbing trees. I like jumping from trees.", "a": "I like climbing trees and jumping from trees."}]}]}, {"num": "5", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Match the sentence in Column A with the sentence in Column B: 1. My mother loves me.", "a": "e) and she loves my sister too. — My mother loves me and she loves my sister too. (Example given in the book.)"}, {"q": "Match the sentence in Column A with the sentence in Column B: 2. Their house is far from the school.", "a": "h) Our house is near the school. — Their house is far from the school but our house is near the school."}, {"q": "Match the sentence in Column A with the sentence in Column B: 3. I am short.", "a": "a) My brother is very tall. — I am short but my brother is very tall."}, {"q": "Match the sentence in Column A with the sentence in Column B: 4. Jumman wants to buy a horse.", "a": "g) He wants to buy a goat. — Jumman wants to buy a horse but he wants to buy a goat. (See the flags file.)"}, {"q": "Match the sentence in Column A with the sentence in Column B: 5. Karim and James worked hard.", "a": "c) They both got good grades. — Karim and James worked hard and they both got good grades."}, {"q": "Match the sentence in Column A with the sentence in Column B: 6. My mobile phone fell down.", "a": "b) It did not break. — My mobile phone fell down but it did not break."}, {"q": "Match the sentence in Column A with the sentence in Column B: 7. Ram Chand bowled well.", "a": "d) He did not get a wicket. — Ram Chand bowled well but he did not get a wicket."}, {"q": "Match the sentence in Column A with the sentence in Column B: 8. Razia washed her clothes.", "a": "f) She cleaned her room. — Razia washed her clothes and she cleaned her room."}]}]}, {"num": "6", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Join the pair of sentences with 'but' or 'and': My mother loves me. / She loves my sister too.", "a": "'and' — My mother loves me and she loves my sister too."}, {"q": "Join the pair of sentences with 'but' or 'and': Their house is far from the school. / Our house is near the school.", "a": "'but' — Their house is far from the school but our house is near the school."}, {"q": "Join the pair of sentences with 'but' or 'and': I am short. / My brother is very tall.", "a": "'but' — I am short but my brother is very tall."}, {"q": "Join the pair of sentences with 'but' or 'and': Jumman wants to buy a horse. / He wants to buy a goat.", "a": "'but' — Jumman wants to buy a horse but he wants to buy a goat."}, {"q": "Join the pair of sentences with 'but' or 'and': Karim and James worked hard. / They both got good grades.", "a": "'and' — Karim and James worked hard and they both got good grades."}, {"q": "Join the pair of sentences with 'but' or 'and': My mobile phone fell down. / It did not break.", "a": "'but' — My mobile phone fell down but it did not break."}, {"q": "Join the pair of sentences with 'but' or 'and': Ram Chand bowled well. / He did not get a wicket.", "a": "'but' — Ram Chand bowled well but he did not get a wicket."}, {"q": "Join the pair of sentences with 'but' or 'and': Razia washed her clothes. / She cleaned her room.", "a": "'and' — Razia washed her clothes and she cleaned her room."}]}]}], "words": [{"w": "conditional sentence", "sd": "شرطي جملو", "syn": "a sentence with an 'if' part and a result part"}, {"w": "condition", "sd": "شرط", "syn": "something that must happen first"}, {"w": "result", "sd": "نتيجو", "syn": "what happens because of the condition"}]}, {"cls": "vii", "unit": 6, "title": "Forming Adjectives and Question Words", "display": "Forming Adjectives and Question Words", "reading": "My English Book 7, Unit 4, Language Practice", "lesson": [{"t": "h", "x": "Forming Adjectives and Question Words"}, {"t": "p", "x": "We can make adjectives from nouns by adding endings like 'less', 'ful', 'ous' and 'y'. We use question words to ask questions."}, {"t": "def", "x": "An adjective can be formed from a noun by adding a suffix. A question word begins a question that asks for information."}, {"t": "h", "x": "Rule 1. Add 'less' to mean 'without'"}, {"t": "rule", "x": "Add 'less' to a noun to make an adjective that means 'without': end — endless, job — jobless, aim — aimless, tree — treeless, hope — hopeless, care — careless."}, {"t": "ex", "x": "endless, jobless, aimless, treeless, hopeless, careless, fearless, homeless."}, {"t": "h", "x": "Rule 2. Add 'ful' to mean 'full of'"}, {"t": "rule", "x": "Add 'ful' to a noun to make an adjective that means 'full of': care — careful, beauty — beautiful, help — helpful, power — powerful."}, {"t": "ex", "x": "careful, beautiful, helpful, powerful, wonderful, useful, joyful."}, {"t": "h", "x": "Rule 3. Add 'ous' and 'y' to make adjectives"}, {"t": "rule", "x": "Add 'ous' or 'y' to a noun to make an adjective: danger — dangerous, fame — famous, rain — rainy, sun — sunny, wind — windy."}, {"t": "ex", "x": "dangerous, famous, rainy, sunny, windy, cloudy, dusty."}, {"t": "h", "x": "Rule 4. Use the main verb and the helping verb to make a question"}, {"t": "rule", "x": "To make a question, put the helping verb before the subject: 'The horse is eating grass.' — 'Is the horse eating grass?' 'The teacher is happy.' — 'Is the teacher happy?'"}, {"t": "ex", "x": "Is the horse eating grass? Are the boys playing? Is the teacher very happy with the class today?"}, {"t": "h", "x": "Rule 5. Use WH words to ask for information"}, {"t": "rule", "x": "Use what, where, when, who, why and how to ask for information."}, {"t": "ex", "x": "What is the horse eating? Where is the horse? When will the teacher come? Who is eating grass? Why is the horse eating grass?"}, {"t": "rl", "x": "At school, the weather is sunny today. The boys are careful in the class. The teacher asks, 'Is the horse eating grass?'"}, {"t": "rl", "x": "At home, my mother is careful with money. The room is beautiful. My father asks, 'What are you doing?'"}, {"t": "rl", "x": "In the market, the road is dusty. The mangoes are famous in our area. The shopkeeper asks, 'How many mangoes do you want?'"}, {"t": "note", "x": "Do not mix up 'less' and 'ful': 'careless' means without care, 'careful' means full of care."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Change the noun into an adjective: end", "a": "endless — end + less (Example given in the book.)"}, {"q": "Change the noun into an adjective: job", "a": "jobless — job + less"}, {"q": "Change the noun into an adjective: aim", "a": "aimless — aim + less"}, {"q": "Change the noun into an adjective: tree", "a": "treeless — tree + less"}, {"q": "Change the noun into an adjective: harm", "a": "harmful — harm + ful (Example given in the book.)"}, {"q": "Change the noun into an adjective: peace", "a": "peaceful — peace + ful"}, {"q": "Change the noun into an adjective: hope", "a": "hopeful — hope + ful"}, {"q": "Change the noun into an adjective: care", "a": "careful — care + ful"}, {"q": "Change the noun into an adjective: wind", "a": "windy — wind + y (Example given in the book.)"}, {"q": "Change the noun into an adjective: air", "a": "airy — air + y"}, {"q": "Change the noun into an adjective: dirt", "a": "dirty — dirt + y"}, {"q": "Change the noun into an adjective: powder", "a": "powdery — powder + y"}, {"q": "Change the noun into an adjective: ghost", "a": "ghostly — ghost + ly (Example given in the book.)"}, {"q": "Change the noun into an adjective: mother", "a": "motherly — mother + ly"}, {"q": "Change the noun into an adjective: hour", "a": "hourly — hour + ly"}, {"q": "Change the noun into an adjective: friend", "a": "friendly — friend + ly"}, {"q": "Change the noun into an adjective: child", "a": "childish — child + ish (Example given in the book.)"}, {"q": "Change the noun into an adjective: salt", "a": "saltish — salt + ish"}, {"q": "Change the noun into an adjective: fool", "a": "foolish — fool + ish"}, {"q": "Change the noun into an adjective: book", "a": "bookish — book + ish"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Fill in the blank with the most suitable adjective from the table in Exercise 1: The travellers were tired but in the ___ desert they could not find any shady place to rest.", "a": "treeless — The travellers were tired but in the treeless desert they could not find any shady place to rest."}, {"q": "Fill in the blank with the most suitable adjective from the table in Exercise 1: Every citizen wants to lead a ___ life, a life without fear and worries.", "a": "peaceful — Every citizen wants to lead a peaceful life, a life without fear and worries."}, {"q": "Fill in the blank with the most suitable adjective from the table in Exercise 1: The ___ clothes of the children show that they have been playing in the garden.", "a": "dirty — The dirty clothes of the children show that they have been playing in the garden."}, {"q": "Fill in the blank with the most suitable adjective from the table in Exercise 1: I like my new neighbours because they are very ___ people.", "a": "friendly — I like my new neighbours because they are very friendly people."}, {"q": "Fill in the blank with the most suitable adjective from the table in Exercise 1: In order to succeed in life we need both practical and ___ knowledge.", "a": "bookish — In order to succeed in life we need both practical and bookish knowledge."}, {"q": "Fill in the blank with the most suitable adjective from the table in Exercise 1: Decide what you want to do in life. Do not lead an ___ life.", "a": "aimless — Decide what you want to do in life. Do not lead an aimless life."}, {"q": "Fill in the blank with the most suitable adjective from the table in Exercise 1: ___ drivers always drive the car within the speed limit.", "a": "careful — Careful drivers always drive the car within the speed limit."}, {"q": "Fill in the blank with the most suitable adjective from the table in Exercise 1: We have very ___ weather today. If you work outside, your papers will fly away.", "a": "windy — We have very windy weather today. If you work outside, your papers will fly away."}, {"q": "Fill in the blank with the most suitable adjective from the table in Exercise 1: Some schools have an ___ time table but some have classes of forty minutes.", "a": "hourly — Some schools have an hourly time table but some have classes of forty minutes."}, {"q": "Fill in the blank with the most suitable adjective from the table in Exercise 1: We drink sweet tea but people in Gilgit Baltistan drink ___ tea.", "a": "saltish — We drink sweet tea but people in Gilgit Baltistan drink saltish tea. (The table's word is 'saltish'; the natural word is 'salty' — see the flags file.)"}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Use the adjective 'endless' in your own sentence.", "a": "The endless desert stretched as far as the eye could see."}, {"q": "Use the adjective 'harmful' in your own sentence.", "a": "Smoking is harmful to our health."}, {"q": "Use the adjective 'hopeful' in your own sentence.", "a": "We should always be hopeful about the future."}, {"q": "Use the adjective 'foolish' in your own sentence.", "a": "The little boy told a foolish story that made everyone laugh."}, {"q": "Use the adjective 'ghostly' in your own sentence.", "a": "My grandmother tells us ghostly stories on winter nights."}]}]}, {"num": "4", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Underline the main verb two times and the helping verb once: The horse is eating grass.", "a": "Helping verb: is; main verb: eating."}, {"q": "Underline the main verb two times and the helping verb once: I am a teacher.", "a": "Main verb: am (no helping verb — 'am' is the main verb)."}, {"q": "Underline the main verb two times and the helping verb once: We love Pakistan.", "a": "Main verb: love (no helping verb)."}, {"q": "Underline the main verb two times and the helping verb once: Saba can sing beautifully.", "a": "Helping verb: can; main verb: sing."}, {"q": "Underline the main verb two times and the helping verb once: The train is late.", "a": "Main verb: is (no helping verb — 'is' is the main verb)."}, {"q": "Underline the main verb two times and the helping verb once: Tahir and Javed will go to Lahore.", "a": "Helping verb: will; main verb: go."}, {"q": "Underline the main verb two times and the helping verb once: We have eaten our food.", "a": "Helping verb: have; main verb: eaten."}, {"q": "Underline the main verb two times and the helping verb once: The old man was lost.", "a": "Main verb: was (no helping verb — 'was' is the main verb; see the flags file)."}, {"q": "Underline the main verb two times and the helping verb once: All of them are playing cricket.", "a": "Helping verb: are; main verb: playing."}, {"q": "Underline the main verb two times and the helping verb once: My sister buys new books every year.", "a": "Main verb: buys (no helping verb)."}]}]}, {"num": "5", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Change the statement in Exercise 4 into a simple Yes/No question: The horse is eating grass.", "a": "Is the horse eating grass?"}, {"q": "Change the statement in Exercise 4 into a simple Yes/No question: I am a teacher.", "a": "Am I a teacher?"}, {"q": "Change the statement in Exercise 4 into a simple Yes/No question: We love Pakistan.", "a": "Do we love Pakistan?"}, {"q": "Change the statement in Exercise 4 into a simple Yes/No question: Saba can sing beautifully.", "a": "Can Saba sing beautifully?"}, {"q": "Change the statement in Exercise 4 into a simple Yes/No question: The train is late.", "a": "Is the train late?"}, {"q": "Change the statement in Exercise 4 into a simple Yes/No question: Tahir and Javed will go to Lahore.", "a": "Will Tahir and Javed go to Lahore?"}, {"q": "Change the statement in Exercise 4 into a simple Yes/No question: We have eaten our food.", "a": "Have we eaten our food?"}, {"q": "Change the statement in Exercise 4 into a simple Yes/No question: The old man was lost.", "a": "Was the old man lost?"}, {"q": "Change the statement in Exercise 4 into a simple Yes/No question: All of them are playing cricket.", "a": "Are all of them playing cricket?"}, {"q": "Change the statement in Exercise 4 into a simple Yes/No question: My sister buys new books every year.", "a": "Does my sister buy new books every year?"}]}]}, {"num": "6", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Form a 'Wh' question with the statement in Exercise 4: The horse is eating grass.", "a": "What is the horse eating?"}, {"q": "Form a 'Wh' question with the statement in Exercise 4: I am a teacher.", "a": "What are you?"}, {"q": "Form a 'Wh' question with the statement in Exercise 4: We love Pakistan.", "a": "What do we love?"}, {"q": "Form a 'Wh' question with the statement in Exercise 4: Saba can sing beautifully.", "a": "How can Saba sing?"}, {"q": "Form a 'Wh' question with the statement in Exercise 4: The train is late.", "a": "Why is the train late?"}, {"q": "Form a 'Wh' question with the statement in Exercise 4: Tahir and Javed will go to Lahore.", "a": "Where will Tahir and Javed go?"}, {"q": "Form a 'Wh' question with the statement in Exercise 4: We have eaten our food.", "a": "What have we eaten?"}, {"q": "Form a 'Wh' question with the statement in Exercise 4: The old man was lost.", "a": "Who was lost?"}, {"q": "Form a 'Wh' question with the statement in Exercise 4: All of them are playing cricket.", "a": "What are all of them playing?"}, {"q": "Form a 'Wh' question with the statement in Exercise 4: My sister buys new books every year.", "a": "What does my sister buy every year?"}]}]}, {"num": "7", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Change the statement into a question as directed (Y/N): The teacher is very happy with the class today.", "a": "Is the teacher very happy with the class today?"}, {"q": "Change the statement into a question as directed (Wh): You are wearing a black dress.", "a": "What are you wearing?"}, {"q": "Change the statement into a question as directed (Y/N): The train will leave for Peshawar at 4 o'clock.", "a": "Will the train leave for Peshawar at 4 o'clock?"}, {"q": "Change the statement into a question as directed (Y/N): My house is in Hafizabad.", "a": "Is your house in Hafizabad? (The person changes from 'my' to 'your' when the statement is turned into a question — see the flags file.)"}, {"q": "Change the statement into a question as directed (Wh): Our new neighbors are nice people.", "a": "What are our new neighbours like?"}, {"q": "Change the statement into a question as directed (Y/N): The blind old man needs help.", "a": "Does the blind old man need help?"}, {"q": "Change the statement into a question as directed (Wh): The little bird has fallen from its nest.", "a": "Where has the little bird fallen from?"}, {"q": "Change the statement into a question as directed (Wh): I am feeling very hungry and thirsty.", "a": "How are you feeling?"}, {"q": "Change the statement into a question as directed (Y/N): The naughty boy was punished by the teacher.", "a": "Was the naughty boy punished by the teacher?"}, {"q": "Change the statement into a question as directed (Wh): The teacher is helping Babar.", "a": "Whom is the teacher helping?"}]}]}], "words": [{"w": "adjective", "sd": "صفت", "syn": "a word that describes a noun"}, {"w": "suffix", "sd": "پڇاڙي", "syn": "letters added at the end of a word"}, {"w": "question word", "sd": "سوالي لفظ", "syn": "a word like what or where that begins a question"}]}, {"cls": "vii", "unit": 7, "title": "Present Perfect Tense", "display": "Present Perfect Tense", "reading": "My English Book 7, Unit 5, Language Practice", "lesson": [{"t": "h", "x": "Present Perfect Tense"}, {"t": "p", "x": "The present perfect tense tells us about an action that has just finished, or an action that started in the past and is still true now."}, {"t": "def", "x": "The present perfect tense is made with has or have and the past participle. It links the past with the present."}, {"t": "h", "x": "Rule 1. Make it with has/have + past participle"}, {"t": "rule", "x": "Use has or have with the past participle of the verb."}, {"t": "ex", "x": "I have lost my pen. She has finished her work. They have gone to school. He has eaten his lunch."}, {"t": "h", "x": "Rule 2. Use 'has' with he, she and it"}, {"t": "rule", "x": "Use 'has' with he, she and it, and 'have' with I, you, we and they."}, {"t": "ex", "x": "He has read the book. She has written a letter. I have seen the film. We have played the match."}, {"t": "h", "x": "Rule 3. Use it for an action that has just finished"}, {"t": "rule", "x": "Use the present perfect for an action that has just finished, often with 'just', 'already' or 'yet'."}, {"t": "ex", "x": "I have just finished my work. She has already gone home. Have you eaten yet? I have lost my pen. (I lost it a short time ago.)"}, {"t": "h", "x": "Rule 4. Use it for an action that started in the past and is still true"}, {"t": "rule", "x": "Use the present perfect for an action that started in the past and is still true now."}, {"t": "ex", "x": "I have lived in Karachi for five years. She has known him since 2020. We have studied English for three years."}, {"t": "rl", "x": "At school, I have finished my homework. The teacher has checked our notebooks. We have won the match."}, {"t": "rl", "x": "At home, my mother has cooked the food. I have lost my pen. My father has gone to the market."}, {"t": "rl", "x": "On the cricket ground, Ali has scored fifty runs. The boys have played well today."}, {"t": "note", "x": "Do not use the present perfect with a finished past time like 'yesterday': say 'I lost my pen yesterday', not 'I have lost my pen yesterday'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. One has been done as an example. 1. Present: break, Past: ___, Past Participle: ___", "a": "break — broke — broken"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 2. Present: ___, Past: ___, Past Participle: brought", "a": "bring — brought — brought"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 3. Present: buy, Past: ___, Past Participle: ___", "a": "buy — bought — bought"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 4. Present: ___, Past: decided, Past Participle: ___", "a": "decide — decided — decided"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 5. Present: ___, Past: ___, Past Participle: done", "a": "do — did — done"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 6. Present: drink, Past: ___, Past Participle: ___", "a": "drink — drank — drunk"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 7. Present: ___, Past: ate, Past Participle: ___", "a": "eat — ate — eaten"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 8. Present: ___, Past: ___, Past Participle: found", "a": "find — found — found"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 9. Present: finish, Past: ___, Past Participle: ___", "a": "finish — finished — finished"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 10. Present: ___, Past: went, Past Participle: ___", "a": "go — went — gone"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 11. Present: keep, Past: ___, Past Participle: ___", "a": "keep — kept — kept"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 12. Present: ___, Past: left, Past Participle: ___", "a": "leave — left — left"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 13. Present: ___, Past: ___, Past Participle: lost", "a": "lose — lost — lost"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 14. Present: make, Past: ___, Past Participle: ___", "a": "make — made — made"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 15. Present: ___, Past: opened, Past Participle: ___", "a": "open — opened — opened"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 16. Present: put, Past: ___, Past Participle: ___", "a": "put — put — put"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 17. Present: ___, Past: ___, Past Participle: read", "a": "read — read — read"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 18. Present: see, Past: ___, Past Participle: ___", "a": "see — saw — seen"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 19. Present: ___, Past: sold, Past Participle: ___", "a": "sell — sold — sold"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 20. Present: think, Past: ___, Past Participle: ___", "a": "think — thought — thought"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 21. Present: walk, Past: ___, Past Participle: ___", "a": "walk — walked — walked"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 22. Present: ___, Past: ___, Past Participle: washed", "a": "wash — washed — washed"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 23. Present: win, Past: ___, Past Participle: ___", "a": "win — won — won"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 24. Present: ___, Past: worked, Past Participle: ___", "a": "work — worked — worked"}, {"q": "The following table contains the present, past, and the past participle forms of some verbs. Fill in the missing forms. 25. Present: write, Past: ___, Past Participle: ___", "a": "write — wrote — written"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Work in pairs and fill in the following blanks by using the past participle of the verb. Remember to use have / has with verb. Select one word from the list in exercise 1 to complete the sentence. You can use one word only once. 1. The train ___ the station.", "a": "The train has left the station. (left)"}, {"q": "Work in pairs and fill in the following blanks by using the past participle of the verb. Remember to use have / has with verb. Select one word from the list in exercise 1 to complete the sentence. You can use one word only once. 2. We ___ to go to Sakardu for our holidays.", "a": "We have decided to go to Sakardu for our holidays. (decided)"}, {"q": "Work in pairs and fill in the following blanks by using the past participle of the verb. Remember to use have / has with verb. Select one word from the list in exercise 1 to complete the sentence. You can use one word only once. 3. John and David ___ this movie before.", "a": "John and David have seen this movie before. (seen)"}, {"q": "Work in pairs and fill in the following blanks by using the past participle of the verb. Remember to use have / has with verb. Select one word from the list in exercise 1 to complete the sentence. You can use one word only once. 4. Mr. Chandimal ___ his car to us.", "a": "Mr. Chandimal has sold his car to us. (sold)"}, {"q": "Work in pairs and fill in the following blanks by using the past participle of the verb. Remember to use have / has with verb. Select one word from the list in exercise 1 to complete the sentence. You can use one word only once. 5. The baby ___ the new vase.", "a": "The baby has broken the new vase. (broken)"}, {"q": "Work in pairs and fill in the following blanks by using the past participle of the verb. Remember to use have / has with verb. Select one word from the list in exercise 1 to complete the sentence. You can use one word only once. 6. The class ___ the water park for a picnic.", "a": "The class has gone to the water park for a picnic. (gone)"}, {"q": "Work in pairs and fill in the following blanks by using the past participle of the verb. Remember to use have / has with verb. Select one word from the list in exercise 1 to complete the sentence. You can use one word only once. 7. I ___ this book many times.", "a": "I have read this book many times. (read)"}, {"q": "Work in pairs and fill in the following blanks by using the past participle of the verb. Remember to use have / has with verb. Select one word from the list in exercise 1 to complete the sentence. You can use one word only once. 8. Rani ___ a letter to the editor of a local newspaper.", "a": "Rani has written a letter to the editor of a local newspaper. (written)"}, {"q": "Work in pairs and fill in the following blanks by using the past participle of the verb. Remember to use have / has with verb. Select one word from the list in exercise 1 to complete the sentence. You can use one word only once. 9. This shop keeper ___ a new shop near the railway station.", "a": "This shop keeper has opened a new shop near the railway station. (opened)"}, {"q": "Work in pairs and fill in the following blanks by using the past participle of the verb. Remember to use have / has with verb. Select one word from the list in exercise 1 to complete the sentence. You can use one word only once. 10. The Pakistan team ___ the match by six wickets.", "a": "The Pakistan team has won the match by six wickets. (won)"}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Complete the following dialogue using the present perfect tense of the verbs in Exercise 1. Anna: I have lost my book. Have you seen it? Zeenat: Yes, I ___ it. It was on the basin.", "a": "Yes, I have seen it. It was on the basin."}, {"q": "Complete the following dialogue using the present perfect tense of the verbs in Exercise 1. Anna: Oh no. I hope no one ___ it.", "a": "Oh no. I hope no one has washed it."}, {"q": "Complete the following dialogue using the present perfect tense of the verbs in Exercise 1. Zeenat: Silly girl! no one washes books. I ___ it on the table.", "a": "Silly girl! no one washes books. I have put it on the table."}, {"q": "Complete the following dialogue using the present perfect tense of the verbs in Exercise 1. Zeenat: I ___ that already. Here is your tea.", "a": "I have made that already. Here is your tea."}, {"q": "Complete the following dialogue using the present perfect tense of the verbs in Exercise 1. Zeenat: Yes. I ___ my share. You can have this.", "a": "Yes. I have eaten my share. You can have this."}, {"q": "Complete the following dialogue using the present perfect tense of the verbs in Exercise 1. Zeenat: Yes. I ___ all my work.", "a": "Yes. I have finished all my work."}, {"q": "Complete the following dialogue using the present perfect tense of the verbs in Exercise 1. Anna: And I ___ the essay that the teacher gave us as homework.", "a": "And I have done the essay that the teacher gave us as homework."}, {"q": "Complete the following dialogue using the present perfect tense of the verbs in Exercise 1. Zeenat: We ___ hard the whole day. We can now take a break.", "a": "We have worked hard the whole day. We can now take a break."}]}]}], "words": [{"w": "present perfect tense", "sd": "زمان حال مڪمل", "syn": "the tense made with has/have and the past participle"}, {"w": "past participle", "sd": "اسم مفعول", "syn": "the third form of the verb, as in written or played"}]}, {"cls": "vii", "unit": 8, "title": "Since and For", "display": "Since and For", "reading": "My English Book 7, Unit 6, Language Practice", "lesson": [{"t": "h", "x": "Since and For"}, {"t": "p", "x": "We use 'since' and 'for' to talk about time. 'Since' is used with a point of time. 'For' is used with a period of time."}, {"t": "def", "x": "'Since' is used with a point of time (when something started). 'For' is used with a period of time (how long something has lasted)."}, {"t": "h", "x": "Rule 1. Use 'since' with a point of time"}, {"t": "rule", "x": "Use 'since' with a point of time: since 2020, since Monday, since morning, since I was a child, since last year."}, {"t": "ex", "x": "I have lived here since 2020. She has known him since Monday. We have waited since morning."}, {"t": "h", "x": "Rule 2. Use 'for' with a period of time"}, {"t": "rule", "x": "Use 'for' with a period of time: for five years, for two hours, for a week, for a long time, for three days."}, {"t": "ex", "x": "I have lived here for five years. She has waited for two hours. We have studied English for three years."}, {"t": "h", "x": "Rule 3. Use them with the present perfect tense"}, {"t": "rule", "x": "'Since' and 'for' are often used with the present perfect tense."}, {"t": "ex", "x": "He has worked here since 2019. He has worked here for six years. It has rained since morning. It has rained for two hours."}, {"t": "rl", "x": "At school, I have studied here since 2021. I have studied here for five years."}, {"t": "rl", "x": "At home, my mother has cooked since morning. She has cooked for two hours. My father has waited for me since noon."}, {"t": "rl", "x": "On the cricket ground, the boys have played since 4 o'clock. They have played for two hours."}, {"t": "note", "x": "Remember: since + when it started, for + how long it lasted."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Work with your partner and fill in the following blanks with 'since' or 'for' as appropriate. 1. Mother, can I please go to my friend's house __________ twenty minutes.", "a": "for — Mother, can I please go to my friend's house for twenty minutes."}, {"q": "Work with your partner and fill in the following blanks with 'since' or 'for' as appropriate. 2. Zaman has been in this shop __________ nine o' clock.", "a": "since — Zaman has been in this shop since nine o' clock."}, {"q": "Work with your partner and fill in the following blanks with 'since' or 'for' as appropriate. 3. The baby has been crawling __________ he was 8 months old.", "a": "since — The baby has been crawling since he was 8 months old."}, {"q": "Work with your partner and fill in the following blanks with 'since' or 'for' as appropriate. 4. My neighbour's dog has been barking __________ two hours.", "a": "for — My neighbour's dog has been barking for two hours."}, {"q": "Work with your partner and fill in the following blanks with 'since' or 'for' as appropriate. 5. We have been cleaning our house __________ yesterday.", "a": "since — We have been cleaning our house since yesterday."}, {"q": "Work with your partner and fill in the following blanks with 'since' or 'for' as appropriate. 6. The teacher gave the class some homework __________ the next day.", "a": "for — The teacher gave the class some homework for the next day."}, {"q": "Work with your partner and fill in the following blanks with 'since' or 'for' as appropriate. 7. I have been reading about pollution __________ I have been in class 3.", "a": "since — I have been reading about pollution since I have been in class 3."}, {"q": "Work with your partner and fill in the following blanks with 'since' or 'for' as appropriate. 8. They had to travel __________ six hours to reach Larkana.", "a": "for — They had to travel for six hours to reach Larkana."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Fill the blanks in the following sentences with 'for' and 'since'. The first one has been done as an example. 1. The gardener has worked here __________ 20 years. The gardener has worked here __________ we moved to this house.", "a": "The gardener has worked here for 20 years. The gardener has worked here since we moved to this house. (Example given in the book.)"}, {"q": "Fill the blanks in the following sentences with 'for' and 'since'. 2. My brother works __________ ten hours every day. My brother has been working here __________ the last five years.", "a": "My brother works for ten hours every day. My brother has been working here for the last five years."}, {"q": "Fill the blanks in the following sentences with 'for' and 'since'. 3. Sameena has been driving the car __________ two o' clock. Sameena drives the car __________ two to four hours on weekdays.", "a": "Sameena has been driving the car since two o' clock. Sameena drives the car for two to four hours on weekdays."}, {"q": "Fill the blanks in the following sentences with 'for' and 'since'. 4. I've been living in Karachi __________ my birth. I've lived in Sukkar __________ two years.", "a": "I've been living in Karachi since my birth. I've lived in Sukkar for two years. (The book prints 'Sukkar'; it should be 'Sukkur'.)"}, {"q": "Fill the blanks in the following sentences with 'for' and 'since'. 5. They walked __________ several hours before they reached a petrol pump. They have been walking __________ morning.", "a": "They walked for several hours before they reached a petrol pump. They have been walking since morning."}, {"q": "Fill the blanks in the following sentences with 'for' and 'since'. 6. The players have been playing __________ afternoon. The players have been playing __________ five hours.", "a": "The players have been playing since afternoon. The players have been playing for five hours."}, {"q": "Fill the blanks in the following sentences with 'for' and 'since'. 7. The teacher talked __________ ten minutes and then asked the students to read. The teacher has been talking __________ the class began.", "a": "The teacher talked for ten minutes and then asked the students to read. The teacher has been talking since the class began."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Nasreen: I have been studying in this school __________ two years. What about you?", "a": "for — Nasreen: I have been studying in this school for two years. What about you?"}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Asma: I have been studying here __________ I was 3 years old.", "a": "since — Asma: I have been studying here since I was 3 years old."}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Nasreen: That is interesting. Has Ms. Bibi taught here __________ many years?", "a": "for — Nasreen: That is interesting. Has Ms. Bibi taught here for many years?"}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Asma: No, she has been teaching here __________ last year.", "a": "since — Asma: No, she has been teaching here since last year."}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Nasreen: Has the Principal been working here __________ 2008?", "a": "since — Nasreen: Has the Principal been working here since 2008?"}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Asma: Yes. But before that she worked __________ 10 years in a private school.", "a": "for — Asma: Yes. But before that she worked for 10 years in a private school."}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Nasreen: Do you know __________ how long we have had this English book?", "a": "since — Nasreen: Do you know since how long we have had this English book? (The book's wording is awkward; correct English would be 'Do you know how long we have had this English book?')"}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Asma: I think we have had it __________ last year.", "a": "since — Asma: I think we have had it since last year."}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Nasreen: And what about the Urdu Book? __________ when have we had that?", "a": "Since — Nasreen: And what about the Urdu Book? Since when have we had that?"}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Asma: We've had that book __________ at least 10 years.", "a": "for — Asma: We've had that book for at least 10 years."}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Nasreen: Thank you Asma. I've known you __________ two years but this is the first time we've really talked.", "a": "for — Nasreen: Thank you Asma. I've known you for two years but this is the first time we've really talked."}, {"q": "Complete the following dialogue between Nasreen and Asma using 'since' and 'for', as appropriate. Asma: You're welcome. I feel we have been friends __________ childhood.", "a": "since — Asma: You're welcome. I feel we have been friends since childhood. (The book prints the last speaker's name as 'Asthma'; it should be 'Asma'.)"}]}]}], "words": [{"w": "since", "sd": "کان وٺي", "syn": "from a point of time in the past"}, {"w": "for", "sd": "لاءِ", "syn": "for a period of time"}]}, {"cls": "vii", "unit": 9, "title": "Position of Adverbs and Voice", "display": "Position of Adverbs and Voice", "reading": "My English Book 7, Unit 7, Language Practice", "lesson": [{"t": "h", "x": "Position of Adverbs and Voice"}, {"t": "p", "x": "An adverb tells us how, when, where or how often an action happens. The position of the adverb matters. In this lesson we also learn the active and passive voice."}, {"t": "def", "x": "An adverb is a word that tells us more about a verb. The active voice says who does the action. The passive voice says what is done."}, {"t": "h", "x": "Rule 1. Adverbs of manner go after the verb"}, {"t": "rule", "x": "An adverb of manner (how) usually goes after the verb or after the object."}, {"t": "ex", "x": "He speaks slowly. She sings sweetly. The cat is sitting quietly. They walked quickly."}, {"t": "h", "x": "Rule 2. Adverbs of place go after the verb"}, {"t": "rule", "x": "An adverb of place (where) usually goes after the verb or after the object."}, {"t": "ex", "x": "The cat is sitting on the ground. The boys are playing outside. She looked everywhere."}, {"t": "h", "x": "Rule 3. Adverbs of time go at the beginning or the end"}, {"t": "rule", "x": "An adverb of time (when) can go at the beginning or at the end of a sentence."}, {"t": "ex", "x": "Yesterday, we went to the market. We went to the market yesterday. Now, I am doing my work."}, {"t": "h", "x": "Rule 4. Adverbs of frequency go before the main verb"}, {"t": "rule", "x": "An adverb of frequency (how often) usually goes before the main verb, but after the be verb."}, {"t": "ex", "x": "I always get up early. She often reads books. He is always happy. They never tell a lie."}, {"t": "h", "x": "Rule 5. Active voice: subject does the action"}, {"t": "rule", "x": "In the active voice, the subject does the action: 'He saw a beautiful bird.'"}, {"t": "ex", "x": "He saw a beautiful bird. Ali wrote a letter. The boys played cricket."}, {"t": "h", "x": "Rule 6. Passive voice: subject receives the action"}, {"t": "rule", "x": "In the passive voice, the subject receives the action. Make it with be + past participle: 'A beautiful bird was seen by him.'"}, {"t": "ex", "x": "A beautiful bird was seen by him. A letter was written by Ali. Cricket was played by the boys."}, {"t": "rl", "x": "At school, the teacher speaks slowly. The boys always listen carefully. The homework is checked by the teacher."}, {"t": "rl", "x": "At home, my mother cooks food daily. I always help her. The house is cleaned every day."}, {"t": "rl", "x": "On the cricket ground, Ali bats well. The match was won by our team. The boys played happily."}, {"t": "note", "x": "Do not put the adverb between the verb and the object: say 'He speaks English well', not 'He speaks well English'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Put the adverb 'on the ground' in the right column of the table (How / When / Where / How Often).", "a": "Where — 'on the ground' tells us where the action took place."}, {"q": "Put the adverb 'last time' in the right column of the table (How / When / Where / How Often).", "a": "When — 'last time' tells us when the action took place."}, {"q": "Put the adverb 'often' in the right column of the table (How / When / Where / How Often).", "a": "How Often — 'often' tells us how often the action took place."}, {"q": "Put the adverb 'slowly' in the right column of the table (How / When / Where / How Often).", "a": "How — 'slowly' tells us how the action was done."}, {"q": "Put the adverb 'during the break' in the right column of the table (How / When / Where / How Often).", "a": "When — 'during the break' tells us when the action took place."}, {"q": "Put the adverb 'sometimes' in the right column of the table (How / When / Where / How Often).", "a": "How Often — 'sometimes' tells us how often the action took place."}, {"q": "Put the adverb 'under the tree' in the right column of the table (How / When / Where / How Often).", "a": "Where — 'under the tree' tells us where the action took place."}, {"q": "Put the adverb 'at 8 o'clock' in the right column of the table (How / When / Where / How Often).", "a": "When — 'at 8 o'clock' tells us when the action took place."}, {"q": "Put the adverb 'rarely' in the right column of the table (How / When / Where / How Often).", "a": "How Often — 'rarely' tells us how often the action took place."}, {"q": "Put the adverb 'normally' in the right column of the table (How / When / Where / How Often).", "a": "How Often — 'normally' tells us how often the action took place."}, {"q": "Put the adverb 'next to the bank' in the right column of the table (How / When / Where / How Often).", "a": "Where — 'next to the bank' tells us where the action took place."}, {"q": "Put the adverb 'quickly' in the right column of the table (How / When / Where / How Often).", "a": "How — 'quickly' tells us how the action was done."}, {"q": "Put the adverb 'yesterday' in the right column of the table (How / When / Where / How Often).", "a": "When — 'yesterday' tells us when the action took place."}, {"q": "Put the adverb 'always' in the right column of the table (How / When / Where / How Often).", "a": "How Often — 'always' tells us how often the action took place."}, {"q": "Put the adverb 'behind the door' in the right column of the table (How / When / Where / How Often).", "a": "Where — 'behind the door' tells us where the action took place."}, {"q": "Put the adverb 'nicely' in the right column of the table (How / When / Where / How Often).", "a": "How — 'nicely' tells us how the action was done."}, {"q": "Put the adverb 'near the railway station' in the right column of the table (How / When / Where / How Often).", "a": "Where — 'near the railway station' tells us where the action took place."}, {"q": "Put the adverb 'five days ago' in the right column of the table (How / When / Where / How Often).", "a": "When — 'five days ago' tells us when the action took place."}, {"q": "Put the adverb 'usually' in the right column of the table (How / When / Where / How Often).", "a": "How Often — 'usually' tells us how often the action took place."}, {"q": "Put the adverb 'loudly' in the right column of the table (How / When / Where / How Often).", "a": "How — 'loudly' tells us how the action was done."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Choose an adverb from the table above to complete the following sentence. The cat is sitting ______. (where)", "a": "The cat is sitting on the ground."}, {"q": "Choose an adverb from the table above to complete the following sentence. She is behaving ______. (how)", "a": "She is behaving nicely."}, {"q": "Choose an adverb from the table above to complete the following sentence. Razia drinks tea in the morning ______. (how often)", "a": "Razia drinks tea in the morning usually."}, {"q": "Choose an adverb from the table above to complete the following sentence. We went to Mohenjo-Daro ______. (when)", "a": "We went to Mohenjo-Daro five days ago."}, {"q": "Choose an adverb from the table above to complete the following sentence. The soldiers fought the enemy ______. (how)", "a": "The soldiers fought the enemy loudly. (None of the How adverbs in the table fits this sentence naturally; see the flags file.)"}, {"q": "Choose an adverb from the table above to complete the following sentence. The students ______ eat something during break time. (how often)", "a": "The students usually eat something during break time."}, {"q": "Choose an adverb from the table above to complete the following sentence. The class will begin ______. (when)", "a": "The class will begin at 8 o'clock."}, {"q": "Choose an adverb from the table above to complete the following sentence. Their house is ______. (where)", "a": "Their house is near the railway station."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Complete the following story by writing the correct adverb in the blank. A man was going to the market to sell caps. He was walking ______ because he was tired.", "a": "A man was going to the market to sell caps. He was walking slowly because he was tired."}, {"q": "Complete the following story by writing the correct adverb in the blank. He decided to rest ______.", "a": "He decided to rest under the tree."}, {"q": "Complete the following story by writing the correct adverb in the blank. He ______ rested under the tree while going to the market.", "a": "He usually rested under the tree while going to the market."}, {"q": "Complete the following story by writing the correct adverb in the blank. He got up ______ and looked around.", "a": "He got up quickly and looked around."}, {"q": "Complete the following story by writing the correct adverb in the blank. He remembered what he had done when this happened ______.", "a": "He remembered what he had done when this happened last time."}, {"q": "Complete the following story by writing the correct adverb in the blank. He took off his cap and threw it ______.", "a": "He took off his cap and threw it on the ground."}, {"q": "Complete the following story by writing the correct adverb in the blank. The man knew that monkeys ______ like to copy people.", "a": "The man knew that monkeys usually like to copy people."}, {"q": "Complete the following story by writing the correct adverb in the blank. He ______ picked up all his caps and put them in his bag.", "a": "He quickly picked up all his caps and put them in his bag."}]}]}, {"num": "4", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "The past participle form 'affected' is given; fill in the present and past form.", "a": "Present: affect, Past: affected."}, {"q": "The past participle form 'asked' is given; fill in the present and past form.", "a": "Present: ask, Past: asked."}, {"q": "The past participle form 'bought' is given; fill in the present and past form.", "a": "Present: buy, Past: bought."}, {"q": "The past participle form 'brought' is given; fill in the present and past form.", "a": "Present: bring, Past: brought."}, {"q": "The past participle form 'broken' is given; fill in the present and past form.", "a": "Present: break, Past: broke."}, {"q": "The past participle form 'calculated' is given; fill in the present and past form.", "a": "Present: calculate, Past: calculated."}, {"q": "The past participle form 'cleaned' is given; fill in the present and past form.", "a": "Present: clean, Past: cleaned."}, {"q": "The past participle form 'drawn' is given; fill in the present and past form.", "a": "Present: draw, Past: drew."}, {"q": "The past participle form 'driven' is given; fill in the present and past form.", "a": "Present: drive, Past: drove."}, {"q": "The past participle form 'given' is given; fill in the present and past form.", "a": "Present: give, Past: gave."}, {"q": "The past participle form 'hit' is given; fill in the present and past form.", "a": "Present: hit, Past: hit."}, {"q": "The past participle form 'liked' is given; fill in the present and past form.", "a": "Present: like, Past: liked."}, {"q": "The past participle form 'made' is given; fill in the present and past form.", "a": "Present: make, Past: made."}, {"q": "The past participle form 'pumped' is given; fill in the present and past form.", "a": "Present: pump, Past: pumped."}, {"q": "The past participle form 'seen' is given; fill in the present and past form.", "a": "Present: see, Past: saw."}, {"q": "The past participle form 'sell' is given; fill in the present and past form.", "a": "Present: sell, Past: sold. (The book prints 'sell' in the Past Participle column, but the past participle of 'sell' is 'sold'.)"}, {"q": "The past participle form 'shown' is given; fill in the present and past form.", "a": "Present: show, Past: showed."}, {"q": "The past participle form 'stopped' is given; fill in the present and past form.", "a": "Present: stop, Past: stopped."}, {"q": "The past participle form 'sung' is given; fill in the present and past form.", "a": "Present: sing, Past: sang."}, {"q": "The past participle form 'taken' is given; fill in the present and past form.", "a": "Present: take, Past: took."}, {"q": "The past participle form 'thrown' is given; fill in the present and past form.", "a": "Present: throw, Past: threw."}, {"q": "The past participle form 'uprooted' is given; fill in the present and past form.", "a": "Present: uproot, Past: uprooted."}, {"q": "The past participle form 'woken' is given; fill in the present and past form.", "a": "Present: wake, Past: woke."}]}]}, {"num": "5", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Change the following active sentence into passive. He saw a beautiful bird.", "a": "A beautiful bird was seen by him."}, {"q": "Change the following active sentence into passive. The singer was singing a new song.", "a": "A new song was being sung by the singer."}, {"q": "Change the following active sentence into passive. William had bought a new car.", "a": "A new car had been bought by William."}, {"q": "Change the following active sentence into passive. Fehmida is drawing a new picture.", "a": "A new picture is being drawn by Fehmida."}, {"q": "Change the following active sentence into passive. Fayyaz makes very tasty cakes.", "a": "Very tasty cakes are made by Fayyaz."}, {"q": "Change the following active sentence into passive. Some boys were selling bananas.", "a": "Bananas were being sold by some boys."}, {"q": "Change the following active sentence into passive. Raja cleans the car every day.", "a": "The car is cleaned by Raja every day."}, {"q": "Change the following active sentence into passive. Dilip is bringing the children to school.", "a": "The children are being brought to school by Dilip."}, {"q": "Change the following active sentence into passive. She drove the car very nicely.", "a": "The car was driven very nicely by her."}, {"q": "Change the following active sentence into passive. The judge has given him a chance.", "a": "He has been given a chance by the judge."}]}]}, {"num": "6", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "HEAVY STORM HITS CITY — Read the following news item. Select the best verb from the list in Exercise 4 that will fit in the blank. The city ______ such a powerful storm after decades.", "a": "The city had not seen such a powerful storm after decades. (This blank needs the active form 'had not seen'; a passive form does not fit here. See the flags file.)"}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. Trees ______ and billboards ______ on the ground.", "a": "Trees were uprooted and billboards were thrown on the ground."}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. The windows of some cars ______ by the falling trees and billboards.", "a": "The windows of some cars were broken by the falling trees and billboards."}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. People ______ from a deep sleep by the sound of thunder.", "a": "People were woken from a deep sleep by the sound of thunder."}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. All the planes coming to the city ______ to go to other cities.", "a": "All the planes coming to the city were asked to go to other cities."}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. Trains ______ at various stations away from the city.", "a": "Trains were stopped at various stations away from the city."}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. Some photographs of the storm ______ by our staff photographer.", "a": "Some photographs of the storm were taken by our staff photographer."}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. The cost of the damage ______ by the government agencies.", "a": "The cost of the damage was calculated by the government agencies."}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. Meanwhile, the water ______ out from the roads so that people can go to work.", "a": "Meanwhile, the water was pumped out from the roads so that people can go to work."}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. The electric supply ______ in most areas of the city.", "a": "The electric supply was affected in most areas of the city."}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. Although the storm warning ______, but nobody expected the storm to be so powerful.", "a": "Although the storm warning was given, but nobody expected the storm to be so powerful."}, {"q": "HEAVY STORM HITS CITY — Select the best verb from the list in Exercise 4 that will fit in the blank. The storm ______ people that they should take such government warnings seriously.", "a": "The storm had shown people that they should take such government warnings seriously. (This blank needs the active form 'had shown'; a passive form does not fit here. See the flags file.)"}]}]}], "words": [{"w": "adverb", "sd": "ظرف", "syn": "a word that tells us more about a verb"}, {"w": "adverb of manner", "sd": "ڪيفيت جو ظرف", "syn": "an adverb that tells us how an action happens"}, {"w": "adverb of time", "sd": "وقت جو ظرف", "syn": "an adverb that tells us when an action happens"}, {"w": "adverb of place", "sd": "جاءِ جو ظرف", "syn": "an adverb that tells us where an action happens"}, {"w": "active voice", "sd": "معروف", "syn": "the voice in which the subject does the action"}, {"w": "passive voice", "sd": "مجهول", "syn": "the voice in which the subject receives the action"}]}, {"cls": "viii", "unit": 1, "title": "Used To and Prepositions", "display": "Used To and Prepositions", "reading": "My English Book 8, Unit 1, Language Practice", "lesson": [{"t": "h", "x": "Used To and Prepositions"}, {"t": "p", "x": "We use 'used to' for a past habit. A preposition shows the place of a thing: in, on, under, at, by, beside, near, inside, outside."}, {"t": "def", "x": "'Used to' + verb talks about a past habit. A preposition is a word that shows where a thing is."}, {"t": "h", "x": "Rule 1. Use 'used to' for a past habit"}, {"t": "rule", "x": "Use 'used to' with the verb to talk about something we did often in the past but do not do now."}, {"t": "ex", "x": "When I was a child, I used to ride a bicycle. My grandfather used to walk to the market. We used to play in the street."}, {"t": "h", "x": "Rule 2. After 'used to', use the first form of the verb"}, {"t": "rule", "x": "After 'used to', use the verb without 's' or 'ed'."}, {"t": "ex", "x": "I used to play. She used to read. They used to go to school. He used to drink milk."}, {"t": "h", "x": "Rule 3. Prepositions show place"}, {"t": "rule", "x": "Use in, inside, outside, on, under, at, by, beside and near to show where a thing is."}, {"t": "ex", "x": "The book is on the table. The ball is under the chair. The school is near the mosque. Please put this book on the table. The cat is inside the room."}, {"t": "h", "x": "Rule 4. Use 'in' for a big place and 'at' for a small place"}, {"t": "rule", "x": "Use 'in' for a city or a country, and 'at' for a small place like a school or a house."}, {"t": "ex", "x": "I live in Karachi. He is at school. She is at home. We live in Pakistan."}, {"t": "rl", "x": "When I was in my primary classes, I used to play with toys. Now I play cricket. My bag is on my desk."}, {"t": "rl", "x": "At home, my grandmother used to cook on a stove. The cat is under the table. My mother is in the kitchen."}, {"t": "rl", "x": "In the market, the shop is beside the mosque. The fruit is in the basket. My father used to buy sweets for us."}, {"t": "note", "x": "Do not write 'use to' for the past habit. The past form is always 'used to'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Select the correct word from Column B to complete the sentence: When I was a child I used to ___ a bicycle. (Column B: bite, play, take, visit, love, get up, tease, ride)", "a": "When I was a child I used to ride a bicycle."}, {"q": "Select the correct word from Column B to complete the sentence: Essa used to ___ mangoes.", "a": "Essa used to love mangoes."}, {"q": "Select the correct word from Column B to complete the sentence: Seema used to ___ early in the morning.", "a": "Seema used to get up early in the morning."}, {"q": "Select the correct word from Column B to complete the sentence: When I was a child my father used to ___ care of me.", "a": "When I was a child my father used to take care of me."}, {"q": "Select the correct word from Column B to complete the sentence: They used to ___ historical places.", "a": "They used to visit historical places."}, {"q": "Select the correct word from Column B to complete the sentence: Our pet dog used to ___ our guests.", "a": "Our pet dog used to bite our guests. (This is the only word left in Column B for this sentence; see the flags file.)"}, {"q": "Select the correct word from Column B to complete the sentence: My grandfather used to ___ with the children.", "a": "My grandfather used to play with the children."}, {"q": "Select the correct word from Column B to complete the sentence: His brother used to ___ everyone in the family.", "a": "His brother used to tease everyone in the family."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Use the verb 'open' to make a complete sentence showing a past habitual action.", "a": "Her brother used to open his shop early in the morning. (Example given in the book.)"}, {"q": "Use the verb 'drive' to make a complete sentence showing a past habitual action.", "a": "My father used to drive us to school every morning."}, {"q": "Use the verb 'make' to make a complete sentence showing a past habitual action.", "a": "My mother used to make delicious food for us on Sundays."}, {"q": "Use the verb 'give' to make a complete sentence showing a past habitual action.", "a": "Our teacher used to give us a new story to read every week."}, {"q": "Use the verb 'sell' to make a complete sentence showing a past habitual action.", "a": "The old man used to sell vegetables in our street."}, {"q": "Use the verb 'call' to make a complete sentence showing a past habitual action.", "a": "My grandfather used to call us every evening."}, {"q": "Use the verb 'send' to make a complete sentence showing a past habitual action.", "a": "My uncle used to send us gifts on Eid."}, {"q": "Use the verb 'receive' to make a complete sentence showing a past habitual action.", "a": "We used to receive many guests on Eid day."}]}]}, {"num": "3", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Complete the sentence by choosing one word from those given in the brackets: Please put this book ___ the table. (inside, at, on, in)", "a": "Please put this book on the table."}, {"q": "Complete the sentence by choosing one word from those given in the brackets: Her shoes are ___ the bed. (in, on, under, before)", "a": "Her shoes are under the bed."}, {"q": "Complete the sentence by choosing one word from those given in the brackets: My teacher is ___ the class. (in, at, above, below)", "a": "My teacher is in the class."}, {"q": "Complete the sentence by choosing one word from those given in the brackets: A huge crowd is waiting ___ the stadium. (on, above, outside, under)", "a": "A huge crowd is waiting outside the stadium."}, {"q": "Complete the sentence by choosing one word from those given in the brackets: Their house is ___ their school. (at, near, in, below)", "a": "Their house is near their school."}, {"q": "Complete the sentence by choosing one word from those given in the brackets: I have put the baby ___ the cot. (in, at, before, behind)", "a": "I have put the baby in the cot."}, {"q": "Complete the sentence by choosing one word from those given in the brackets: The train is ___ the station. (in, at, under, above)", "a": "The train is at the station."}, {"q": "Complete the sentence by choosing one word from those given in the brackets: Murree is about 7000 ft. ___ the sea level. (below, behind, on, above)", "a": "Murree is about 7000 ft. above the sea level."}]}]}, {"num": "4", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Fill in the blank with a correct preposition from the list given earlier (in, inside, outside, on, under, at, by, beside, near, above, below, behind, among, between): The boys fell ___ the pond yesterday.", "a": "The boys fell in the pond yesterday. (The book's list has no 'into'; see the flags file.)"}, {"q": "Fill in the blank with a correct preposition from the list given earlier: Let's go ___ as it is going to rain.", "a": "Let's go inside as it is going to rain."}, {"q": "Fill in the blank with a correct preposition from the list given earlier: Many minerals were found ___ the surface of the earth.", "a": "Many minerals were found below the surface of the earth."}, {"q": "Fill in the blank with a correct preposition from the list given earlier: We can get most of the things that we need ___ our house.", "a": "We can get most of the things that we need near our house."}, {"q": "Fill in the blank with a correct preposition from the list given earlier: The old man is resting ___ the tree as it is very hot.", "a": "The old man is resting under the tree as it is very hot."}, {"q": "Fill in the blank with a correct preposition from the list given earlier: I always keep my mobile phone ___ the top shelf.", "a": "I always keep my mobile phone on the top shelf."}, {"q": "Fill in the blank with a correct preposition from the list given earlier: Please go and see who is ___ the door.", "a": "Please go and see who is at the door."}, {"q": "Fill in the blank with a correct preposition from the list given earlier: The mouse is ___ the log in the corner.", "a": "The mouse is behind the log in the corner."}]}]}, {"num": "5", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Use at least 7 prepositions from the list given earlier (in, inside, outside, on, under, at, by, beside, near, above, below, behind, among, between) in your own sentences.", "a": "Model sentences (7 prepositions used — in, on, under, beside, near, among, between): 1. The cat is sitting in the basket. 2. The book is on the table. 3. The ball is under the chair. 4. Ali is standing beside his brother. 5. Our school is near the canal. 6. Sana is sitting among her friends. 7. The shop is between the bank and the post office."}]}]}], "words": [{"w": "used to", "sd": "عادت هئي", "syn": "a phrase for a past habit that is finished now"}, {"w": "preposition", "sd": "حرف جر", "syn": "a word that shows the place or position of a thing"}, {"w": "habit", "sd": "عادت", "syn": "something we do often"}]}, {"cls": "viii", "unit": 2, "title": "Past Perfect Tense", "display": "Past Perfect Tense", "reading": "My English Book 8, Unit 2, Language Practice", "lesson": [{"t": "h", "x": "Past Perfect Tense"}, {"t": "p", "x": "The past perfect tense tells us about an action that happened before another action in the past. The first action is in the past perfect, and the second action is in the simple past."}, {"t": "def", "x": "The past perfect tense is made with had and the past participle. It shows that one past action happened before another past action."}, {"t": "h", "x": "Rule 1. Make it with had + past participle"}, {"t": "rule", "x": "Use had with the past participle of the verb."}, {"t": "ex", "x": "I had studied Japanese before I went to school. She had finished her work before the teacher came. They had eaten before we arrived."}, {"t": "h", "x": "Rule 2. The past perfect comes first"}, {"t": "rule", "x": "The action that happened first is in the past perfect, and the action that happened second is in the simple past."}, {"t": "ex", "x": "I had studied before I went to school. (First I studied, then I went.) The train had left before we reached the station."}, {"t": "h", "x": "Rule 3. Use it with 'before', 'after' and 'by the time'"}, {"t": "rule", "x": "Use the past perfect with before, after and by the time."}, {"t": "ex", "x": "After I had finished my work, I went to play. By the time we reached, the train had left. He had read the book before he saw the film."}, {"t": "rl", "x": "At school, I had finished my homework before the teacher came. The bell had rung before we reached the class."}, {"t": "rl", "x": "At home, my mother had cooked the food before my father came home. I had eaten before I went to play."}, {"t": "rl", "x": "On the cricket ground, the match had started before we arrived. Ali had scored fifty runs before he got out."}, {"t": "note", "x": "Do not use the past perfect for two actions that happened at the same time. Use it only when one action happened before the other."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Read the sentence and underline the action that you think happened first: I (study) Japanese before I (go) to study in Japan.", "a": "I had studied Japanese before I went to study in Japan. (The action that happened first is: I studied Japanese.)"}, {"q": "Read the sentence and underline the action that you think happened first: We (have) a lot of trouble at the airport because we (lose) our passports.", "a": "We had a lot of trouble at the airport because we had lost our passports. (The action that happened first is: we lost our passports.)"}, {"q": "Read the sentence and underline the action that you think happened first: After we (watch) TV for a while we (go) to sleep.", "a": "After we had watched TV for a while, we went to sleep. (The action that happened first is: we watched TV.)"}, {"q": "Read the sentence and underline the action that you think happened first: Sachal (know) many people at the office because he (work) there some years ago.", "a": "Sachal knew many people at the office because he had worked there some years ago. (The action that happened first is: he worked there.)"}, {"q": "Read the sentence and underline the action that you think happened first: Farah (enjoy) the movie because she (read) the book.", "a": "Farah enjoyed the movie because she had read the book. (The action that happened first is: she read the book.)"}, {"q": "Read the sentence and underline the action that you think happened first: My father (be) to Syria before the problems (start) in that country.", "a": "My father had been to Syria before the problems started in that country. (The action that happened first is: my father had been to Syria.)"}, {"q": "Read the sentence and underline the action that you think happened first: I (play) cricket after I (finish) my homework.", "a": "I played cricket after I had finished my homework. (The action that happened first is: I finished my homework.)"}, {"q": "Read the sentence and underline the action that you think happened first: When I (come) to your house last night you (go) to bed.", "a": "When I came to your house last night, you had gone to bed. (The action that happened first is: you went to bed.)"}, {"q": "Read the sentence and underline the action that you think happened first: The train (leave) the station when we (reach) because we were late.", "a": "The train had left the station when we reached because we were late. (The action that happened first is: the train left the station.)"}, {"q": "Read the sentence and underline the action that you think happened first: We (go) out for a walk after it (stop) raining.", "a": "We went out for a walk after it had stopped raining. (The action that happened first is: it stopped raining.)"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Write the sentence in your notebook. Use the simple past tense of the verb given in brackets for the action that happened later and the past perfect tense for the action that happened first: I (study) Japanese before I (go) to study in Japan.", "a": "I had studied Japanese before I went to study in Japan."}, {"q": "Write the sentence in your notebook. Use the simple past tense for the action that happened later and the past perfect tense for the action that happened first: We (have) a lot of trouble at the airport because we (lose) our passports.", "a": "We had a lot of trouble at the airport because we had lost our passports."}, {"q": "Write the sentence in your notebook. Use the simple past tense for the action that happened later and the past perfect tense for the action that happened first: After we (watch) TV for a while we (go) to sleep.", "a": "After we had watched TV for a while, we went to sleep."}, {"q": "Write the sentence in your notebook. Use the simple past tense for the action that happened later and the past perfect tense for the action that happened first: Sachal (know) many people at the office because he (work) there some years ago.", "a": "Sachal knew many people at the office because he had worked there some years ago."}, {"q": "Write the sentence in your notebook. Use the simple past tense for the action that happened later and the past perfect tense for the action that happened first: Farah (enjoy) the movie because she (read) the book.", "a": "Farah enjoyed the movie because she had read the book."}, {"q": "Write the sentence in your notebook. Use the simple past tense for the action that happened later and the past perfect tense for the action that happened first: My father (be) to Syria before the problems (start) in that country.", "a": "My father had been to Syria before the problems started in that country."}, {"q": "Write the sentence in your notebook. Use the simple past tense for the action that happened later and the past perfect tense for the action that happened first: I (play) cricket after I (finish) my homework.", "a": "I played cricket after I had finished my homework."}, {"q": "Write the sentence in your notebook. Use the simple past tense for the action that happened later and the past perfect tense for the action that happened first: When I (come) to your house last night you (go) to bed.", "a": "When I came to your house last night, you had gone to bed."}, {"q": "Write the sentence in your notebook. Use the simple past tense for the action that happened later and the past perfect tense for the action that happened first: The train (leave) the station when we (reach) because we were late.", "a": "The train had left the station when we reached because we were late."}, {"q": "Write the sentence in your notebook. Use the simple past tense for the action that happened later and the past perfect tense for the action that happened first: We (go) out for a walk after it (stop) raining.", "a": "We went out for a walk after it had stopped raining."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Read the following story and fill in the blanks with the correct tense of the verbs given. Paragraph 3 verbs: teach, is, show, clap. Story: Everyone ___ for them. These were mentally challenged girls but they ___ everyone a very powerful lesson. They ___ to all the people present there that helping others and caring for their feelings ___ as important as winning a competition.", "a": "Paragraph 3 (completed): Everyone clapped for them. These were mentally challenged girls but they taught everyone a very powerful lesson. They showed to all the people present there that helping others and caring for their feelings is as important as winning a competition."}]}]}], "words": [{"w": "past perfect tense", "sd": "زمان ماضي مڪمل", "syn": "the tense made with had and the past participle"}, {"w": "past participle", "sd": "اسم مفعول", "syn": "the third form of the verb, as in written or played"}]}, {"cls": "viii", "unit": 3, "title": "Must, Must Not and Imperative Sentences", "display": "Must, Must Not and Imperative Sentences", "reading": "My English Book 8, Unit 3, Language Practice", "lesson": [{"t": "h", "x": "Must, Must Not and Imperative Sentences"}, {"t": "p", "x": "We use 'must' for a rule and 'must not' to forbid something. An imperative sentence gives an order or an instruction."}, {"t": "def", "x": "'Must' shows a rule or a strong duty. 'Must not' forbids something. An imperative sentence gives an order or an instruction, and it begins with a verb."}, {"t": "h", "x": "Rule 1. Use 'must' for a rule"}, {"t": "rule", "x": "Use 'must' when something is a rule or a duty that we have to follow."}, {"t": "ex", "x": "A good friend must help others. We must follow the traffic rules. You must wear a helmet."}, {"t": "h", "x": "Rule 2. Use 'must not' to forbid something"}, {"t": "rule", "x": "Use 'must not' (mustn't) when something is not allowed."}, {"t": "ex", "x": "You must not drive fast. You must not cross the road on a red light. You must not throw rubbish on the road."}, {"t": "h", "x": "Rule 3. An imperative sentence begins with a verb"}, {"t": "rule", "x": "An imperative sentence begins with the verb. The subject 'you' is understood."}, {"t": "ex", "x": "Stop at the red light. Look both ways before you cross the road. Wash your hands. Scrub your teeth."}, {"t": "h", "x": "Rule 4. Use 'do not' for a negative order"}, {"t": "rule", "x": "To tell somebody not to do something, begin with 'Do not' or 'Don't' and then the verb."}, {"t": "ex", "x": "Do not run on the road. Don't waste water. Do not throw rubbish on the ground."}, {"t": "rl", "x": "At school, we must come on time. The teacher says, 'Sit down and open your books.'"}, {"t": "rl", "x": "At home, my mother says, 'Wash your hands before lunch.' I must help my parents."}, {"t": "rl", "x": "On the road, we must stop at the red light. The policeman says, 'Look both ways before you cross.'"}, {"t": "note", "x": "After must and must not, use the verb without 's' or 'ed'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Here is a list of ten things; students must do five of these and mustn't do five. Put these under the respective headings in the table given below: exercise regularly, behave rudely, shout in class, study hard, obey their teachers, follow the school rules, break the school furniture, miss their classes, do their homework, write on the school wall or furniture", "a": "MUST DO: 1. exercise regularly 2. study hard 3. obey their teachers 4. follow the school rules 5. do their homework. MUSTN'T DO: 1. behave rudely 2. shout in class 3. break the school furniture 4. miss their classes 5. write on the school wall or furniture."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Complete the statement: A good friend must __________", "a": "Model answer: A good friend must help his friends in need."}, {"q": "Complete the statement: A good friend mustn't __________", "a": "Model answer: A good friend mustn't tell lies to his friends."}, {"q": "Complete the statement: A good teacher must __________", "a": "Model answer: A good teacher must teach his students with love and care."}, {"q": "Complete the statement: A good teacher mustn't __________", "a": "Model answer: A good teacher mustn't punish his students without reason."}, {"q": "Complete the statement: A good classmate must __________", "a": "Model answer: A good classmate must help his classmates in their studies."}, {"q": "Complete the statement: A good classmate mustn't __________", "a": "Model answer: A good classmate mustn't disturb his classmates in the class."}, {"q": "Complete the statement: A good brother or sister must __________", "a": "Model answer: A good brother or sister must love and help his younger brothers and sisters."}, {"q": "Complete the statement: A good brother or sister mustn't __________", "a": "Model answer: A good brother or sister mustn't fight with his brothers and sisters."}, {"q": "Complete the statement: A good parent must __________", "a": "Model answer: A good parent must take good care of his children."}, {"q": "Complete the statement: A good parent mustn't __________", "a": "Model answer: A good parent mustn't beat his children."}, {"q": "Complete the statement: A good son or daughter must __________", "a": "Model answer: A good son or daughter must respect and obey his parents."}, {"q": "Complete the statement: A good son or daughter mustn't __________", "a": "Model answer: A good son or daughter mustn't disobey his parents."}, {"q": "Complete the statement: A good neighbour must __________", "a": "Model answer: A good neighbour must help his neighbours in need."}, {"q": "Complete the statement: A good neighbour mustn't __________", "a": "Model answer: A good neighbour mustn't disturb his neighbours."}, {"q": "Complete the statement: A good citizen must __________", "a": "Model answer: A good citizen must follow the laws of the country."}, {"q": "Complete the statement: A good citizen mustn't __________", "a": "Model answer: A good citizen mustn't break the laws of the country."}]}]}, {"num": "3", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Complete the set of instructions using the verbs in the list (scrub, wash, dry, separate, keep, apply, take, rinse — each verb only once): 1. __________ all the utensils, glasses, dishes etc. to the washing area.", "a": "1. Take all the utensils, glasses, dishes etc. to the washing area. (given in the book as the example)"}, {"q": "Complete the set of instructions using the verbs in the list (scrub, wash, dry, separate, keep, apply, take, rinse — each verb only once): 2. __________ them into different piles.", "a": "2. Separate them into different piles."}, {"q": "Complete the set of instructions using the verbs in the list (scrub, wash, dry, separate, keep, apply, take, rinse — each verb only once): 3. __________ the small things, like spoons, bowls and things made of glass first.", "a": "3. Wash the small things, like spoons, bowls and things made of glass first."}, {"q": "Complete the set of instructions using the verbs in the list (scrub, wash, dry, separate, keep, apply, take, rinse — each verb only once): 4. __________ soap to all the things mentioned above and then rinse them with water.", "a": "4. Apply soap to all the things mentioned above and then rinse them with water."}, {"q": "Complete the set of instructions using the verbs in the list (scrub, wash, dry, separate, keep, apply, take, rinse — each verb only once): 5. __________ all the other utensils properly using the washing powder and soap.", "a": "5. Scrub all the other utensils properly using the washing powder and soap."}, {"q": "Complete the set of instructions using the verbs in the list (scrub, wash, dry, separate, keep, apply, take, rinse — each verb only once): 6. __________ all the scrubbed utensils one by one.", "a": "6. Rinse all the scrubbed utensils one by one."}, {"q": "Complete the set of instructions using the verbs in the list (scrub, wash, dry, separate, keep, apply, take, rinse — each verb only once): 7. __________ them with a clean towel.", "a": "7. Dry them with a clean towel."}, {"q": "Complete the set of instructions using the verbs in the list (scrub, wash, dry, separate, keep, apply, take, rinse — each verb only once): 8. __________ them in their proper place.", "a": "8. Keep them in their proper place."}]}]}], "words": [{"w": "must", "sd": "ضرور", "syn": "shows a rule or strong duty"}, {"w": "imperative sentence", "sd": "حڪم وارو جملو", "syn": "a sentence that gives an order or advice"}]}, {"cls": "viii", "unit": 4, "title": "Direct and Indirect Speech", "display": "Direct and Indirect Speech", "reading": "My English Book 8, Unit 4, Language Practice", "lesson": [{"t": "h", "x": "Direct and Indirect Speech"}, {"t": "p", "x": "Direct speech gives the exact words of the speaker inside quotation marks. Indirect speech reports what the speaker said, without quotation marks."}, {"t": "def", "x": "Direct speech is the exact words of the speaker. Indirect speech reports the words of the speaker in our own words."}, {"t": "h", "x": "Rule 1. Direct speech uses quotation marks"}, {"t": "rule", "x": "In direct speech, put the speaker's exact words inside quotation marks."}, {"t": "ex", "x": "Shah said, \"I don't like seafood.\" Mujeeb said to him, \"I cannot meet you after school today.\""}, {"t": "h", "x": "Rule 2. Indirect speech uses 'that' and no quotation marks"}, {"t": "rule", "x": "In indirect speech, use 'that' after the reporting verb (said, told) and do not use quotation marks."}, {"t": "ex", "x": "Shah said that he did not like seafood. Mujeeb said to him that he could not meet him after school that day."}, {"t": "h", "x": "Rule 3. Change the tense back one step"}, {"t": "rule", "x": "When the reporting verb is in the past, change the tense back one step: present simple becomes past simple, present continuous becomes past continuous, will becomes would, can becomes could."}, {"t": "ex", "x": "Direct: \"I am happy.\" Indirect: He said that he was happy. Direct: \"I will come.\" Indirect: He said that he would come. Direct: \"I can swim.\" Indirect: He said that he could swim."}, {"t": "h", "x": "Rule 4. Change the words for time and place"}, {"t": "rule", "x": "Change today to that day, tomorrow to the next day, yesterday to the day before, here to there, this to that."}, {"t": "ex", "x": "Direct: \"I cannot meet you today.\" Indirect: He said that he could not meet him that day. Direct: \"I will come tomorrow.\" Indirect: He said that he would come the next day."}, {"t": "rl", "x": "At school, the teacher said, \"Open your books.\" I told my friend that the teacher had said to open our books."}, {"t": "rl", "x": "At home, my mother said, \"Wash your hands.\" I told my sister that mother had said to wash our hands."}, {"t": "rl", "x": "On the cricket ground, Ali said, \"I will bat first.\" Ahmed told us that Ali would bat first."}, {"t": "note", "x": "In indirect speech, change I to he or she, my to his or her, and we to they, to match the speaker."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Complete the sentence in the indirect speech: 1. Mujeeb said to him, \"I cannot meet you after school today.\" Mujeeb said to him that he __________ him after school __________.", "a": "Mujeeb said to him that he could not meet him after school that day."}, {"q": "Complete the sentence in the indirect speech: 2. Seema said, \"The food is very tasty here.\" Seema said that the food __________ very tasty __________.", "a": "Seema said that the food was very tasty there."}, {"q": "Complete the sentence in the indirect speech: 3. I said to Murad, \"I am going to ride my bike to work from tomorrow.\" I said to Murad that I __________ my bike to work from the __________.", "a": "I said to Murad that I was going to ride my bike to work from the next day."}, {"q": "Complete the sentence in the indirect speech: 4. My parents said, \"We have been to Lahore several times.\" My parents said that they __________ to Lahore several times.", "a": "My parents said that they had been to Lahore several times."}, {"q": "Complete the sentence in the indirect speech: 5. Hania said to her, \"I forgot to call my mother this evening.\" Hania said to her that she __________ to call her mother __________.", "a": "Hania said to her that she had forgotten to call her mother that evening."}, {"q": "Complete the sentence in the indirect speech: 6. We said to the teacher, \"We will complete our work by next week.\" We said to our teacher that we __________ our work by __________.", "a": "We said to our teacher that we would complete our work by the following week."}, {"q": "Complete the sentence in the indirect speech: 7. Manmohan said, \"I will visit Quetta next year.\" Manmohan said that he __________ Quetta the following year.", "a": "Manmohan said that he would visit Quetta the following year."}, {"q": "Complete the sentence in the indirect speech: 8. Fahim's boss said to his employees, \"The meeting will start at 2:00 pm today.\" Fahim's boss said to his employees that the meeting __________ at 2:00 pm __________.", "a": "Fahim's boss said to his employees that the meeting would start at 2:00 pm that day."}, {"q": "Complete the sentence in the indirect speech: 9. All the mechanics said to us, \"We cannot fix your car.\" All the mechanics said to us that they __________ our car.", "a": "All the mechanics said to us that they could not fix our car."}, {"q": "Complete the sentence in the indirect speech: 10. My brother said to him, \"I've already seen this movie.\" My brother said to him that he __________ already __________ __________ movie.", "a": "My brother said to him that he had already seen that movie."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Change the sentence from Direct speech into Indirect speech: 1. Shah said, \"I don't like seafood.\"", "a": "Shah said that he did not like seafood."}, {"q": "Change the sentence from Direct speech into Indirect speech: 2. I said, \"I was sleeping when you came last night.\"", "a": "I said that I had been sleeping when he came the previous night."}, {"q": "Change the sentence from Direct speech into Indirect speech: 3. Mariam said, \"I am planning to go to Turkey next summer.\"", "a": "Mariam said that she was planning to go to Turkey the next summer."}, {"q": "Change the sentence from Direct speech into Indirect speech: 4. Deeba said, \"We visited our grandmother last summer.\"", "a": "Deeba said that they had visited their grandmother the previous summer."}, {"q": "Change the sentence from Direct speech into Indirect speech: 5. Rashid said, \"We're going to visit my aunt this evening.\"", "a": "Rashid said that they were going to visit his aunt that evening."}, {"q": "Change the sentence from Direct speech into Indirect speech: 6. My sister said, \"I have to finish my report by tonight.\"", "a": "My sister said that she had to finish her report by that night."}, {"q": "Change the sentence from Direct speech into Indirect speech: 7. The little girl said, \"I can't read Farsi.\"", "a": "The little girl said that she could not read Farsi."}, {"q": "Change the sentence from Direct speech into Indirect speech: 8. My classmates said, \"We will come to the presentation tomorrow.\"", "a": "My classmates said that they would come to the presentation the next day."}, {"q": "Change the sentence from Direct speech into Indirect speech: 9. Safdar said to me, \"I can meet you today at noon.\"", "a": "Safdar said to me that he could meet me that day at noon."}, {"q": "Change the sentence from Direct speech into Indirect speech: 10. All of us said, \"We will be in college next year.\"", "a": "All of us said that we would be in college the following year."}]}]}], "words": [{"w": "direct speech", "sd": "سڌو ڪلام", "syn": "the exact words of the speaker inside quotation marks"}, {"w": "indirect speech", "sd": "اڻ سڌو ڪلام", "syn": "reporting what the speaker said, without quotation marks"}, {"w": "reporting verb", "sd": "بيان ڪرڻ وارو فعل", "syn": "a verb like said or told that reports speech"}]}, {"cls": "viii", "unit": 5, "title": "Adverbs of Manner", "display": "Adverbs of Manner", "reading": "My English Book 8, Unit 4, Language Practice", "lesson": [{"t": "h", "x": "Adverbs of Manner"}, {"t": "p", "x": "An adverb of manner tells us how an action happens. Most adverbs of manner are made by adding 'ly' to an adjective."}, {"t": "def", "x": "An adverb of manner is a word that tells us how an action happens. It usually ends in 'ly'."}, {"t": "h", "x": "Rule 1. Add 'ly' to an adjective to make an adverb"}, {"t": "rule", "x": "Add 'ly' to most adjectives to make adverbs of manner."}, {"t": "ex", "x": "glad — gladly, slow — slowly, quick — quickly, happy — happily, careful — carefully, loud — loudly, soft — softly."}, {"t": "h", "x": "Rule 2. Change 'y' to 'i' before adding 'ly'"}, {"t": "rule", "x": "For adjectives that end with a consonant + y, change y to i and add ly."}, {"t": "ex", "x": "happy — happily, easy — easily, heavy — heavily, angry — angrily, busy — busily."}, {"t": "h", "x": "Rule 3. Adjectives that end in 'le' drop the 'e'"}, {"t": "rule", "x": "For adjectives that end in 'le', drop the 'e' and add 'y': gentle — gently, simple — simply, terrible — terribly."}, {"t": "ex", "x": "gentle — gently, simple — simply, terrible — terribly, horrible — horribly."}, {"t": "h", "x": "Rule 4. An adverb of manner goes after the verb"}, {"t": "rule", "x": "An adverb of manner usually goes after the verb or after the object."}, {"t": "ex", "x": "They walked quickly. She sings sweetly. He speaks slowly. The cat sat quietly."}, {"t": "rl", "x": "At school, the teacher speaks slowly. The boys listen carefully. Ali writes neatly."}, {"t": "rl", "x": "At home, my mother cooks food well. My sister sings sweetly. My brother walks quickly."}, {"t": "rl", "x": "On the cricket ground, Ali bats well. The boys play happily. The captain shouts loudly."}, {"t": "note", "x": "Some adverbs do not end in 'ly': well, fast, hard, late, early. 'He runs fast' — not 'fastly'."}], "sections": [{"num": "1", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: glad", "a": "gladly"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: clever", "a": "cleverly"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: poor", "a": "poorly"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: sudden", "a": "suddenly"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: quick", "a": "quickly"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: cheap", "a": "cheaply"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: patient", "a": "patiently"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: real", "a": "really"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: proper", "a": "properly"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: hungry", "a": "hungrily"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: lazy", "a": "lazily"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: noisy", "a": "noisily"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: easy", "a": "easily"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: angry", "a": "angrily"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: heavy", "a": "heavily"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: true", "a": "truly"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: simple", "a": "simply"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: gentle", "a": "gently"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: comfortable", "a": "comfortably"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: possible", "a": "possibly"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: idle", "a": "idly"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: hopeful", "a": "hopefully"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: thankful", "a": "thankfully"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: grateful", "a": "gratefully"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: careful", "a": "carefully"}, {"q": "Follow the rules for forming adverbs of manner and write the adverb formed from the adjective: peaceful", "a": "peacefully"}]}]}, {"num": "2", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Complete the sentence by adding one adverb from the table in Exercise 4 (use one adverb only once): 1. They were sitting __________ and talking when they heard a loud noise.", "a": "They were sitting comfortably and talking when they heard a loud noise."}, {"q": "Complete the sentence by adding one adverb from the table in Exercise 4 (use one adverb only once): 2. The lights went off __________ so the program had to end.", "a": "The lights went off suddenly so the program had to end."}, {"q": "Complete the sentence by adding one adverb from the table in Exercise 4 (use one adverb only once): 3. All the students were able to do the math paper __________.", "a": "All the students were able to do the math paper easily."}, {"q": "Complete the sentence by adding one adverb from the table in Exercise 4 (use one adverb only once): 4. We should all live __________ with our neighbours.", "a": "We should all live peacefully with our neighbours."}, {"q": "Complete the sentence by adding one adverb from the table in Exercise 4 (use one adverb only once): 5. The chairman left the meeting __________ because his wife was sick.", "a": "The chairman left the meeting quickly because his wife was sick."}, {"q": "Complete the sentence by adding one adverb from the table in Exercise 4 (use one adverb only once): 6. The people had not had food for two days so they ate __________.", "a": "The people had not had food for two days so they ate hungrily."}, {"q": "Complete the sentence by adding one adverb from the table in Exercise 4 (use one adverb only once): 7. The nurse lifted the baby __________ and changed her clothes.", "a": "The nurse lifted the baby gently and changed her clothes."}, {"q": "Complete the sentence by adding one adverb from the table in Exercise 4 (use one adverb only once): 8. The office clerk __________ took the money that his boss gave him", "a": "The office clerk gratefully took the money that his boss gave him."}]}]}], "words": [{"w": "adverb of manner", "sd": "ڪيفيت جو ظرف", "syn": "an adverb that tells us how an action happens"}, {"w": "adjective", "sd": "صفت", "syn": "a word that describes a noun"}]}, {"cls": "viii", "unit": 6, "title": "Tag Questions and Linking Words", "display": "Tag Questions and Linking Words", "reading": "My English Book 8, Unit 5, Language Practice", "lesson": [{"t": "h", "x": "Tag Questions and Linking Words"}, {"t": "p", "x": "A tag question is a short question added at the end of a statement. Linking words join two sentences or ideas."}, {"t": "def", "x": "A tag question is a short question like 'isn't it?' or 'aren't you?' added at the end of a statement. Linking words like and, but and because join sentences."}, {"t": "h", "x": "Rule 1. A positive statement takes a negative tag"}, {"t": "rule", "x": "If the statement is positive, the tag is negative."}, {"t": "ex", "x": "My bag isn't under the table, is it? The train is late today, isn't it? You are coming, aren't you?"}, {"t": "h", "x": "Rule 2. A negative statement takes a positive tag"}, {"t": "rule", "x": "If the statement is negative, the tag is positive."}, {"t": "ex", "x": "My bag isn't under the table, is it? (The statement is negative, so the tag is positive.) He doesn't like milk, does he? She isn't happy, is she?"}, {"t": "h", "x": "Rule 3. The tag uses the same helping verb"}, {"t": "rule", "x": "The tag uses the same helping verb as the statement: is — isn't, are — aren't, was — wasn't, do — don't, does — doesn't, can — can't, will — won't."}, {"t": "ex", "x": "You can swim, can't you? He will come, won't he? They are playing, aren't they? She was happy, wasn't she?"}, {"t": "h", "x": "Rule 4. Join sentences with 'and', 'but' and 'because'"}, {"t": "rule", "x": "Use 'and' to join two same ideas, 'but' to join two different ideas, and 'because' to give a reason."}, {"t": "ex", "x": "The colour of this dress is nice, and I like it. The colour is nice, but I do not like the size. I like it because it is cheap."}, {"t": "rl", "x": "At school, the teacher says, 'We are going on a field trip this Saturday, aren't we?' I say, 'Yes, we are.'"}, {"t": "rl", "x": "At home, my mother says, 'The food is ready, isn't it?' I say, 'Yes, it is.' I like rice because it is tasty."}, {"t": "rl", "x": "On the cricket ground, Ali says, 'The match is today, isn't it?' I say, 'Yes, it is.' We will win because we play well."}, {"t": "note", "x": "Put a comma before the tag question, and end the tag with a question mark."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Change the statement into a question by adding the appropriate question tag: My bag isn't under the table, ______?", "a": "My bag isn't under the table, is it?"}, {"q": "Change the statement into a question by adding the appropriate question tag: The children are really enjoying themselves, ______?", "a": "The children are really enjoying themselves, aren't they?"}, {"q": "Change the statement into a question by adding the appropriate question tag: The old man looks very tired, ______?", "a": "The old man looks very tired, doesn't he?"}, {"q": "Change the statement into a question by adding the appropriate question tag: You can't open this lock with your key, ______?", "a": "You can't open this lock with your key, can you?"}, {"q": "Change the statement into a question by adding the appropriate question tag: The goats are busy grazing grass, ______?", "a": "The goats are busy grazing grass, aren't they?"}, {"q": "Change the statement into a question by adding the appropriate question tag: The team has practised a lot today, ______?", "a": "The team has practised a lot today, hasn't it?"}, {"q": "Change the statement into a question by adding the appropriate question tag: The teacher won't take the test today, ______?", "a": "The teacher won't take the test today, will he/she?"}, {"q": "Change the statement into a question by adding the appropriate question tag: This man isn't your uncle, ______?", "a": "This man isn't your uncle, is he?"}, {"q": "Change the statement into a question by adding the appropriate question tag: Your tea is getting cold, ______?", "a": "Your tea is getting cold, isn't it?"}, {"q": "Change the statement into a question by adding the appropriate question tag: We haven't paid our electric bill, ______?", "a": "We haven't paid our electric bill, have we?"}, {"q": "Change the statement into a question by adding the appropriate question tag: My mother cleans the house every day, ______?", "a": "My mother cleans the house every day, doesn't she?"}, {"q": "Change the statement into a question by adding the appropriate question tag: I don't know how to drive a car, ______?", "a": "I don't know how to drive a car, do I?"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Rewrite the statement as a question by using an appropriate question tag: The train is late today.", "a": "The train is late today, isn't it?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: You aren't going to see the match tomorrow.", "a": "You aren't going to see the match tomorrow, are you?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: They finished their work on time.", "a": "They finished their work on time, didn't they?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: The school is far from their house.", "a": "The school is far from their house, isn't it?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: The students should obey the school rules.", "a": "The students should obey the school rules, shouldn't they?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: The mountain climbers have reached the top.", "a": "The mountain climbers have reached the top, haven't they?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: Our football team can win this match.", "a": "Our football team can win this match, can't it?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: The child is not crossing the road properly.", "a": "The child is not crossing the road properly, is he/she?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: My sister exercises every day.", "a": "My sister exercises every day, doesn't she?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: I will get good grades in my exams.", "a": "I will get good grades in my exams, won't I?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: Last night, their dog barked the whole night.", "a": "Last night, their dog barked the whole night, didn't it?"}, {"q": "Rewrite the statement as a question by using an appropriate question tag: They shouldn't talk so loudly when everyone is sleeping.", "a": "They shouldn't talk so loudly when everyone is sleeping, should they?"}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Complete the dialogue by using the appropriate question tags. Zaman: We are going on a field trip this Saturday, ______?", "a": "We are going on a field trip this Saturday, aren't we?"}, {"q": "Complete the dialogue by using the appropriate question tags. Hamza: Yes. And we'll leave at six o'clock, ______?", "a": "Yes. And we'll leave at six o'clock, won't we?"}, {"q": "Complete the dialogue by using the appropriate question tags. Shoaib: Mr. Qureshi is also coming with us, ______?", "a": "Mr. Qureshi is also coming with us, isn't he?"}, {"q": "Complete the dialogue by using the appropriate question tags. Zaman: But Mr. Mirza won't come, ______?", "a": "But Mr. Mirza won't come, will he?"}, {"q": "Complete the dialogue by using the appropriate question tags. Hamza: I'm sure it will be great fun, ______?", "a": "I'm sure it will be great fun, won't it?"}, {"q": "Complete the dialogue by using the appropriate question tags. Shoaib: If we are allowed to swim it will be fun, otherwise we will get bored, ______?", "a": "If we are allowed to swim it will be fun, otherwise we will get bored, won't we?"}, {"q": "Complete the dialogue by using the appropriate question tags. Zaman: Depends. Hamza and I will enjoy playing cricket ______, Hamza?", "a": "Depends. Hamza and I will enjoy playing cricket, won't we, Hamza?"}, {"q": "Complete the dialogue by using the appropriate question tags. Hamza: Sure. Abid and Haseeb will also play with us, ______?", "a": "Sure. Abid and Haseeb will also play with us, won't they?"}, {"q": "Complete the dialogue by using the appropriate question tags. Shoaib: The school management will provide us the bats and balls, ______?", "a": "The school management will provide us the bats and balls, won't it?"}, {"q": "Complete the dialogue by using the appropriate question tags. Zaman: I think they will, ______?", "a": "I think they will, won't they?"}, {"q": "Complete the dialogue by using the appropriate question tags. Hamza: Well, last time they did and we had a great time, ______?", "a": "Well, last time they did and we had a great time, didn't we?"}, {"q": "Complete the dialogue by using the appropriate question tags. Shoaib: We can always catch up on our sleep if there is nothing else to do, ______?", "a": "We can always catch up on our sleep if there is nothing else to do, can't we?"}]}]}, {"num": "4", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Join the sentences using 'and', 'but', or 'because', as appropriate: The colour of this dress is nice. I like the colour of the dress that you bought.", "a": "The colour of this dress is nice and I like the colour of the dress that you bought."}, {"q": "Join the sentences using 'and', 'but', or 'because', as appropriate: Our house is big. It has a nice view of the river.", "a": "Our house is big and it has a nice view of the river."}, {"q": "Join the sentences using 'and', 'but', or 'because', as appropriate: My sister wants to go to university. She wants to become an engineer.", "a": "My sister wants to go to university because she wants to become an engineer."}, {"q": "Join the sentences using 'and', 'but', or 'because', as appropriate: His older brother is a pilot. His younger brother also wants to become a pilot.", "a": "His older brother is a pilot and his younger brother also wants to become a pilot."}, {"q": "Join the sentences using 'and', 'but', or 'because', as appropriate: We can reach Gilgit faster by air. Travelling by road is much fun.", "a": "We can reach Gilgit faster by air, but travelling by road is much fun."}, {"q": "Join the sentences using 'and', 'but', or 'because', as appropriate: Growing vegetables at home is good. We can have fresh vegetables to eat.", "a": "Growing vegetables at home is good because we can have fresh vegetables to eat."}, {"q": "Join the sentences using 'and', 'but', or 'because', as appropriate: Playing games is good. Playing all the time and not studying is not good.", "a": "Playing games is good, but playing all the time and not studying is not good."}, {"q": "Join the sentences using 'and', 'but', or 'because', as appropriate: People give money to those who need it. They also give voluntary time.", "a": "People give money to those who need it and they also give voluntary time."}, {"q": "Join the sentences using 'and', 'but', or 'because', as appropriate: We should protect ourselves from mosquitoes. Mosquito bites can cause malaria.", "a": "We should protect ourselves from mosquitoes because mosquito bites can cause malaria."}, {"q": "Join the sentences using 'and', 'but', or 'because', as appropriate: Our school gets over at twelve. I reach home at two O'clock.", "a": "Our school gets over at twelve and I reach home at two O'clock."}]}]}, {"num": "5", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Choose a sentence from Column B that matches with the one in Column A and join the pair to form one sentence by adding 'and', 'but', or 'because': I decided to have an early dinner.", "a": "e) I wanted to sleep early. — I decided to have an early dinner because I wanted to sleep early. (given in the book)"}, {"q": "Choose a sentence from Column B that matches with the one in Column A and join the pair to form one sentence by adding 'and', 'but', or 'because': They wanted to return the bag to the shopkeeper.", "a": "h) they forgot the bag at home. — They wanted to return the bag to the shopkeeper, but they forgot the bag at home."}, {"q": "Choose a sentence from Column B that matches with the one in Column A and join the pair to form one sentence by adding 'and', 'but', or 'because': They left home early to catch the train.", "a": "j) they missed their train due to a traffic jam. — They left home early to catch the train, but they missed their train due to a traffic jam."}, {"q": "Choose a sentence from Column B that matches with the one in Column A and join the pair to form one sentence by adding 'and', 'but', or 'because': She bought a new dress for Eid.", "a": "b) she also bought a new pair of sandals. — She bought a new dress for Eid and she also bought a new pair of sandals."}, {"q": "Choose a sentence from Column B that matches with the one in Column A and join the pair to form one sentence by adding 'and', 'but', or 'because': Our neighbours sold their old house.", "a": "i) they wanted to buy a new one. — Our neighbours sold their old house because they wanted to buy a new one."}, {"q": "Choose a sentence from Column B that matches with the one in Column A and join the pair to form one sentence by adding 'and', 'but', or 'because': Many people go to the park on holidays.", "a": "c) many people go to the seaside to have fun. — Many people go to the park on holidays, but many people go to the seaside to have fun."}, {"q": "Choose a sentence from Column B that matches with the one in Column A and join the pair to form one sentence by adding 'and', 'but', or 'because': His parents took his baby sister to the doctor.", "a": "a) she had high fever. — His parents took his baby sister to the doctor because she had high fever."}, {"q": "Choose a sentence from Column B that matches with the one in Column A and join the pair to form one sentence by adding 'and', 'but', or 'because': The player tried his best to catch the ball.", "a": "d) the ball went to the boundary for four runs. — The player tried his best to catch the ball, but the ball went to the boundary for four runs."}, {"q": "Choose a sentence from Column B that matches with the one in Column A and join the pair to form one sentence by adding 'and', 'but', or 'because': My uncle is a lawyer.", "a": "f) his son is also studying to become a lawyer. — My uncle is a lawyer and his son is also studying to become a lawyer."}, {"q": "Choose a sentence from Column B that matches with the one in Column A and join the pair to form one sentence by adding 'and', 'but', or 'because': The food in this restaurant is good.", "a": "g) the food in the restaurant across the street is better. — The food in this restaurant is good, but the food in the restaurant across the street is better."}]}]}, {"num": "6", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Complete the sentence: My friend wants to travel to ______ and ______.", "a": "My friend wants to travel to Karachi and Lahore. (Model completion — students may use any two places.)"}, {"q": "Complete the sentence: He decided to wash the dishes because ______.", "a": "He decided to wash the dishes because they were dirty. (Model completion.)"}, {"q": "Complete the sentence: Our exams were scheduled for Monday but ______.", "a": "Our exams were scheduled for Monday but they were postponed to Wednesday. (Model completion.)"}, {"q": "Complete the sentence: Their father gave them some money because ______.", "a": "Their father gave them some money because they needed to buy books. (Model completion.)"}, {"q": "Complete the sentence: The farmers grew some ______ and ______.", "a": "The farmers grew some wheat and rice. (Model completion — students may use any two crops.)"}, {"q": "Complete the sentence: My mother told me that the purse was in the cupboard but ______.", "a": "My mother told me that the purse was in the cupboard but it was not there. (Model completion.)"}, {"q": "Complete the sentence: The soup is getting cold but ______.", "a": "The soup is getting cold but we have not eaten it yet. (Model completion.)"}, {"q": "Complete the sentence: The little girl is crying because ______.", "a": "The little girl is crying because she has lost her doll. (Model completion.)"}, {"q": "Complete the sentence: His father is going to ______ and ______.", "a": "His father is going to Karachi and Hyderabad. (Model completion — students may use any two places.)"}, {"q": "Complete the sentence: The bus is heavily loaded because ______.", "a": "The bus is heavily loaded because many passengers are travelling in it. (Model completion.)"}]}]}], "words": [{"w": "tag question", "sd": "سوالي لاحقو", "syn": "a short question added at the end of a statement"}, {"w": "linking word", "sd": "ڳنڍڻ وارو لفظ", "syn": "a word that joins sentences or ideas"}]}, {"cls": "viii", "unit": 7, "title": "Degrees of Adjectives", "display": "Degrees of Adjectives", "reading": "My English Book 8, Units 6 and 7, Language Practice", "lesson": [{"t": "h", "x": "Degrees of Adjectives"}, {"t": "p", "x": "Adjectives have three degrees: positive, comparative and superlative. We use 'than' with the comparative degree, and 'the' with the superlative degree."}, {"t": "def", "x": "The positive degree is the simple form. The comparative degree compares two things. The superlative degree compares one thing with all the others."}, {"t": "h", "x": "Rule 1. The comparative compares two things"}, {"t": "rule", "x": "Use the comparative degree (adjective + er + than) to compare two things."}, {"t": "ex", "x": "Our new neighbours are better than the older ones. This bag is more expensive than that purse. Ali is taller than Ahmed."}, {"t": "h", "x": "Rule 2. The superlative compares one thing with all the others"}, {"t": "rule", "x": "Use the superlative degree (the + adjective + est) to compare one thing with all the others."}, {"t": "ex", "x": "Bilal is the tallest boy. This is the most expensive bag. She is the best student."}, {"t": "h", "x": "Rule 3. 'The ... the ...' shows that two things change together"}, {"t": "rule", "x": "Use 'the + comparative, the + comparative' to show that two things change together."}, {"t": "ex", "x": "The faster the train, the sooner we will reach. The younger the children, the quicker they learn a new language. The thinner you are, the easier it is to run. The healthier your eating habits, the better your health."}, {"t": "h", "x": "Rule 4. Long adjectives use 'more' and 'most'"}, {"t": "rule", "x": "For long adjectives, use 'more' for the comparative and 'most' for the superlative."}, {"t": "ex", "x": "expensive — more expensive — most expensive, beautiful — more beautiful — most beautiful, difficult — more difficult — most difficult."}, {"t": "h", "x": "Rule 5. Some adjectives change in a special way"}, {"t": "rule", "x": "Some adjectives do not take 'er' and 'est': good — better — best, bad — worse — worst, little — less — least, much — more — most."}, {"t": "ex", "x": "good — better — best, bad — worse — worst, much — more — most."}, {"t": "rl", "x": "At school, Ali is tall. Ahmed is taller than Ali. Bilal is the tallest boy in our class."}, {"t": "rl", "x": "At home, my bag is heavy. My brother's bag is heavier than mine. My father's bag is the heaviest."}, {"t": "rl", "x": "In the market, this mango is sweet. That mango is sweeter. The mango in that shop is the sweetest of all."}, {"t": "note", "x": "Use 'than' after the comparative and 'the' before the superlative."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "__________ the train, __________ we will reach. (fast, soon)", "a": "The faster the train, the sooner we will reach."}, {"q": "__________ the children, __________ they learn a new language. (young, quick)", "a": "The younger the children, the quicker they learn a new language."}, {"q": "__________ you are, __________ it is to run. (thin, easy)", "a": "The thinner you are, the easier it is to run."}, {"q": "__________ your eating habits, __________ your health. (healthy, good)", "a": "The healthier your eating habits, the better your health."}, {"q": "__________ a driver, __________ the journey. (careful, safe)", "a": "The more careful a driver, the safer the journey."}, {"q": "__________ one lives, __________ ones' life. (simple, easy)", "a": "The simpler one lives, the easier one's life."}, {"q": "__________ a country, __________ its people. (clean, healthy)", "a": "The cleaner a country, the healthier its people."}, {"q": "__________ the days, __________ the nights. (long, short)", "a": "The longer the days, the shorter the nights."}, {"q": "__________ the nut, __________ it is to break it. (hard, difficult)", "a": "The harder the nut, the more difficult it is to break it."}, {"q": "__________ one gets, __________ the time one has for oneself. (busy, less)", "a": "The busier one gets, the less the time one has for oneself."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "__________ the quality of the material, __________ the cost.", "a": "The better the quality of the material, the higher the cost."}, {"q": "__________ the wood, __________ expensive the furniture will be.", "a": "The older the wood, the more expensive the furniture will be."}, {"q": "__________ the place, __________ it will be for resting.", "a": "The shadier the place, the cooler it will be for resting."}, {"q": "__________ the water, __________ the tea.", "a": "The hotter the water, the nicer the tea."}, {"q": "__________ one's style of living, __________ one's life becomes.", "a": "The plainer one's style of living, the easier one's life becomes."}, {"q": "__________ the room, __________ I feel.", "a": "The darker the room, the more comfortable I feel."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Mountain Climbers' Trip: __________ the day of our climbing came, __________ we got.", "a": "The nearer the day of our climbing came, the more excited we got."}, {"q": "Mountain Climbers' Trip: Soon the day came. We all got up very early; however, __________ we tried to leave, __________ we seemed to get.", "a": "The later we tried to leave, the less organized we seemed to get."}, {"q": "Mountain Climbers' Trip: The van was waiting outside. __________ we thought we were, __________ it seemed we were.", "a": "The nearer we thought we were, the farther it seemed we were."}, {"q": "Mountain Climbers' Trip: Finally, we all piled into the van. __________ the van drew to the mountain, __________ the look in everyone's eyes.", "a": "The closer the van drew to the mountain, the brighter the look in everyone's eyes."}, {"q": "Mountain Climbers' Trip: Our guide started to give us last minute instructions. __________ he guided us, __________ we seemed to understand.", "a": "The more he guided us, the less we seemed to understand."}, {"q": "Mountain Climbers' Trip: At first it was great fun. __________ the mountain air got, __________ we felt.", "a": "The cooler the mountain air got, the fresher we felt."}, {"q": "Mountain Climbers' Trip: But, as we started climbing, __________ we got, __________ it was for us to breathe.", "a": "The higher we got, the more difficult it was for us to breathe."}, {"q": "Mountain Climbers' Trip: Although the scenery was beautiful, we were feeling too tired to look around. We were just climbing. __________ we tried to climb, __________ we became.", "a": "The quicker we tried to climb, the slower we became."}, {"q": "Mountain Climbers' Trip: And __________ we climbed, __________ our speed became.", "a": "The steeper we climbed, the slower our speed became."}, {"q": "Mountain Climbers' Trip: In fact, __________ the end of the journey, __________ it seemed.", "a": "The nearer the end of the journey, the farther it seemed."}]}]}, {"num": "4", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Our new neighbours are __________ the older ones. (good)", "a": "Our new neighbours are better than the older ones."}, {"q": "His boss is __________ our boss. (kind)", "a": "His boss is kinder than our boss."}, {"q": "Travelling by train is __________ travelling by air. (cheap)", "a": "Travelling by train is cheaper than travelling by air."}, {"q": "Your dress is __________ your friend's dress. (pretty)", "a": "Your dress is prettier than your friend's dress."}, {"q": "Some of the students in this class are __________ the others. (intelligent)", "a": "Some of the students in this class are more intelligent than the others."}, {"q": "This hospital is __________ the hospital near our house. (clean)", "a": "This hospital is cleaner than the hospital near our house."}, {"q": "The stars in the village seem __________ the stars in the city. (bright)", "a": "The stars in the village seem brighter than the stars in the city."}, {"q": "Today the patient's condition is __________ yesterday. (bad)", "a": "Today the patient's condition is worse than yesterday."}, {"q": "The bag lying downstairs is __________ the one lying upstairs. (useful)", "a": "The bag lying downstairs is more useful than the one lying upstairs."}, {"q": "This week has been __________ last week. (busy)", "a": "This week has been busier than last week."}]}]}, {"num": "5", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Picture pair 1 and 2 (bag — expensive; purse — cheap): For each pair, write two sentences using 'than' along with the adjectives provided at the top of each picture.", "a": "The bag is more expensive than the purse. The purse is cheaper than the bag. (This is the example given in the book.)"}, {"q": "Picture pair 3 and 4 (elephant — big; rabbit — small): For each pair, write two sentences using 'than' along with the adjectives provided at the top of each picture.", "a": "The elephant is bigger than the rabbit. The rabbit is smaller than the elephant."}, {"q": "Picture pair 5 and 6 (ice cream — cold; tea — warm): For each pair, write two sentences using 'than' along with the adjectives provided at the top of each picture.", "a": "The ice cream is colder than the tea. The tea is warmer than the ice cream."}, {"q": "Picture pair 7 and 8 (old shoes — old; new slippers — new): For each pair, write two sentences using 'than' along with the adjectives provided at the top of each picture.", "a": "The shoes are older than the slippers. The slippers are newer than the shoes."}, {"q": "Picture pair 9 and 10 (mango — sweet; orange — sour): For each pair, write two sentences using 'than' along with the adjectives provided at the top of each picture.", "a": "The mango is sweeter than the orange. The orange is more sour than the mango."}, {"q": "Picture pair 11 and 12 (crow — ugly; peacock — beautiful): For each pair, write two sentences using 'than' along with the adjectives provided at the top of each picture.", "a": "The crow is uglier than the peacock. The peacock is more beautiful than the crow."}, {"q": "Picture pair 13 and 14 (baby — young; old man — old): For each pair, write two sentences using 'than' along with the adjectives provided at the top of each picture.", "a": "The baby is younger than the old man. The old man is older than the baby."}, {"q": "Picture pair 15 and 16 (train — slow; aeroplane — fast): For each pair, write two sentences using 'than' along with the adjectives provided at the top of each picture.", "a": "The train is slower than the aeroplane. The aeroplane is faster than the train."}]}]}], "words": [{"w": "positive degree", "sd": "سادو درجو", "syn": "the simple form of an adjective"}, {"w": "comparative degree", "sd": "تقابلي درجو", "syn": "the form used to compare two things"}, {"w": "superlative degree", "sd": "اعليٰ درجو", "syn": "the form used to compare one thing with all the others"}]}, {"cls": "viii", "unit": 8, "title": "Relative Pronouns", "display": "Relative Pronouns", "reading": "My English Book 8, Unit 6, Language Practice", "lesson": [{"t": "h", "x": "Relative Pronouns"}, {"t": "p", "x": "A relative pronoun joins two sentences. It stands for a noun and begins a clause that tells us more about that noun."}, {"t": "def", "x": "A relative pronoun (who, which, that, whose, whom) joins two sentences. It tells us more about a noun."}, {"t": "h", "x": "Rule 1. Use 'who' for people"}, {"t": "rule", "x": "Use 'who' for people."}, {"t": "ex", "x": "One of our neighbours who used to live with us now lives with my uncle. The boy who won the prize is my friend."}, {"t": "h", "x": "Rule 2. Use 'which' for things and animals"}, {"t": "rule", "x": "Use 'which' for things and animals."}, {"t": "ex", "x": "The farmer found the goat which had been stolen from his farm. The book which is on the table is mine."}, {"t": "h", "x": "Rule 3. Use 'that' for people, things and animals"}, {"t": "rule", "x": "Use 'that' for people, things and animals."}, {"t": "ex", "x": "I want to eat an egg that has two yolks. They sold the house that they had bought last year. I know the maid that broke the new tray."}, {"t": "h", "x": "Rule 4. Use 'whose' to show ownership"}, {"t": "rule", "x": "Use 'whose' to show that something belongs to somebody."}, {"t": "ex", "x": "The boy whose book was lost is crying. The man whose car was stolen is sad."}, {"t": "rl", "x": "At school, the teacher who teaches us English is kind. The book that I bought yesterday is very good."}, {"t": "rl", "x": "At home, my uncle who lives in Karachi visited us. The dog which barks at night is ours."}, {"t": "rl", "x": "In the market, the shopkeeper who sells fruit is my friend. The mangoes that I bought are sweet."}, {"t": "note", "x": "Do not use 'who' for a thing or 'which' for a person."}], "sections": [{"num": "1", "name": "Exercise 1 (Relative Pronouns)", "exercises": [{"label": "Exercise 1 (Relative Pronouns)", "items": [{"q": "The farmer found the goat — join it with the correct part from part B.", "a": "The farmer found the goat which had been stolen from his farm."}, {"q": "One of our neighbours — join it with the correct part from part B.", "a": "One of our neighbours who used to live with us now lives with my uncle."}, {"q": "I want to eat an egg — join it with the correct part from part B.", "a": "I want to eat an egg that has two yolks."}, {"q": "They sold the house — join it with the correct part from part B.", "a": "They sold the house that they had bought last year."}, {"q": "Their new teacher, — join it with the correct part from part B.", "a": "Their new teacher, who sings beautifully, is absent today."}, {"q": "Zameer owns the shop — join it with the correct part from part B.", "a": "Zameer owns the shop which has five doors."}, {"q": "My grandfather — join it with the correct part from part B.", "a": "My grandfather who travels a lot has gone to Canada."}, {"q": "It was our class team — join it with the correct part from part B.", "a": "It was our class team that won the volley ball match."}]}]}, {"num": "2", "name": "Exercise 2 (Relative Pronouns)", "exercises": [{"label": "Exercise 2 (Relative Pronouns)", "items": [{"q": "I know the maid __________ broke the new tray.", "a": "I know the maid who broke the new tray."}, {"q": "The book __________ has a yellow sticker belongs to Asad.", "a": "The book which has a yellow sticker belongs to Asad."}, {"q": "My friend painted the house __________ we sold yesterday.", "a": "My friend painted the house that we sold yesterday."}, {"q": "A gold medal was given to the player __________ scored the most runs.", "a": "A gold medal was given to the player who scored the most runs."}, {"q": "The woman __________ is wearing a blue shawl is my sister.", "a": "The woman who is wearing a blue shawl is my sister."}, {"q": "The computer I like the best is the one __________ is very old.", "a": "The computer I like the best is the one that is very old."}, {"q": "You will find the captain at the table __________ is near the window.", "a": "You will find the captain at the table that is near the window."}, {"q": "Many birds used to nest in the tree __________ they cut.", "a": "Many birds used to nest in the tree which they cut."}, {"q": "The ice-cream __________ is in this tub is better.", "a": "The ice-cream which is in this tub is better."}, {"q": "The child __________ was running slipped and fell.", "a": "The child who was running slipped and fell."}]}]}, {"num": "3", "name": "Exercise 3 (Relative Pronouns)", "exercises": [{"label": "Exercise 3 (Relative Pronouns)", "items": [{"q": "Father: Tomorrow is a public holiday. Let's go and visit uncle Jamal __________ is ill.", "a": "Father: Tomorrow is a public holiday. Let's go and visit uncle Jamal who is ill."}, {"q": "Areeb: Yes! Let's go there and then go to the park __________ is near his house.", "a": "Areeb: Yes! Let's go there and then go to the park which is near his house."}, {"q": "Maira: Can we take my friend __________ lives next door with us?", "a": "Maira: Can we take my friend who lives next door with us?"}, {"q": "Father: Sure. We can then have dinner at any small hotel __________ serves good food.", "a": "Father: Sure. We can then have dinner at any small hotel which serves good food."}, {"q": "Areeb: Or we can buy bun kebab and fries from the hawker __________ stands outside the park.", "a": "Areeb: Or we can buy bun kebab and fries from the hawker who stands outside the park."}, {"q": "Areeb: ...and then have ice cream from a shop __________ sells cone ice cream.", "a": "Areeb: ...and then have ice cream from a shop which sells cone ice cream."}, {"q": "Maira: I want to have the ice cream __________ has chocolate pieces in it.", "a": "Maira: I want to have the ice cream which has chocolate pieces in it."}, {"q": "Areeb: Great! The plan that we visit uncle, Jamil __________ is ill and have ice cream later, is superb!", "a": "Areeb: Great! The plan that we visit uncle, Jamil who is ill and have ice cream later, is superb! (The book spells the uncle's name 'Jamil' here, but 'Jamal' everywhere else.)"}, {"q": "Maira: Let's ask mother, __________ is busy in the kitchen, what she thinks of our plan.", "a": "Maira: Let's ask mother, who is busy in the kitchen, what she thinks of our plan."}, {"q": "Father: I've already asked her. She loved the idea __________ we visit uncle Jamal.", "a": "Father: I've already asked her. She loved the idea that we visit uncle Jamal."}, {"q": "Maira: I must go and tell my friend. She loves the bun kebab __________ is sold near the park.", "a": "Maira: I must go and tell my friend. She loves the bun kebab which is sold near the park."}]}]}], "words": [{"w": "relative pronoun", "sd": "اضافي ضمير", "syn": "a pronoun like who, which or that that joins two sentences"}, {"w": "clause", "sd": "شق", "syn": "a part of a sentence with a subject and a verb"}]}, {"cls": "viii", "unit": 9, "title": "Emphatic Pronouns", "display": "Emphatic Pronouns", "reading": "My English Book 8, Unit 7, Language Practice", "lesson": [{"t": "h", "x": "Emphatic Pronouns"}, {"t": "p", "x": "An emphatic pronoun is the same word as a reflexive pronoun, but it is used to emphasise a noun or a pronoun."}, {"t": "def", "x": "An emphatic pronoun (myself, yourself, himself, herself, itself, ourselves, yourselves, themselves) is used to emphasise a noun or a pronoun."}, {"t": "h", "x": "Rule 1. An emphatic pronoun emphasises the subject"}, {"t": "rule", "x": "Put the emphatic pronoun just after the subject to emphasise it."}, {"t": "ex", "x": "I myself did the work. The king himself came. The teacher herself checked the papers. We ourselves cleaned the house."}, {"t": "h", "x": "Rule 2. An emphatic pronoun can come at the end"}, {"t": "rule", "x": "An emphatic pronoun can also come at the end of the sentence to emphasise the subject."}, {"t": "ex", "x": "I did the work myself. She made the dress herself. They cleaned the house themselves."}, {"t": "h", "x": "Rule 3. Emphatic and reflexive pronouns look the same"}, {"t": "rule", "x": "Emphatic and reflexive pronouns have the same forms, but their use is different. A reflexive pronoun is the object of the verb. An emphatic pronoun only emphasises."}, {"t": "ex", "x": "I hurt myself. (reflexive — myself is the object) I myself did it. (emphatic — myself emphasises I)"}, {"t": "rl", "x": "At school, our neighbours love gardening. They look after their plants themselves."}, {"t": "rl", "x": "At home, my sister made a card herself. My father himself repaired the bicycle."}, {"t": "rl", "x": "On the cricket ground, the captain himself caught the ball. The boys themselves cleaned the ground."}, {"t": "note", "x": "Do not use 'hisself' or 'theirselves'. The correct forms are 'himself' and 'themselves'."}], "sections": [{"num": "1", "name": "Exercise 4 (Emphatic Pronouns)", "exercises": [{"label": "Exercise 4 (Emphatic Pronouns)", "items": [{"q": "Our neighbours love gardening. __________ look after their plants __________.", "a": "Our neighbours love gardening. They look after their plants themselves."}, {"q": "The principal of our school, Mr. Samad, is a nice man. __________ guides all the teachers.", "a": "The principal of our school, Mr. Samad, is a nice man. He himself guides all the teachers."}, {"q": "My friend gets good marks in all the tests. __________ does not take tuitions but studies hard __________.", "a": "My friend gets good marks in all the tests. He does not take tuitions but studies hard himself."}, {"q": "Our house is always neat and clean. __________ clean it __________.", "a": "Our house is always neat and clean. We clean it ourselves."}, {"q": "All of you are loved by your teachers. This is because __________ are good students.", "a": "All of you are loved by your teachers. This is because you yourselves are good students."}, {"q": "Train your dog well then __________ will then take care of your house.", "a": "Train your dog well then it itself will then take care of your house."}, {"q": "No one is responsible for your actions. Only __________ are responsible for them.", "a": "No one is responsible for your actions. Only you yourself are responsible for them."}]}]}, {"num": "2", "name": "Exercise 5 (Emphatic Pronouns)", "exercises": [{"label": "Exercise 5 (Emphatic Pronouns)", "items": [{"q": "Fatima: I spoke to her last night and __________ told me that she was coming.", "a": "Fatima: I spoke to her last night and she herself told me that she was coming."}, {"q": "Amna: Can __________ try and contact her __________ to see why she is late?", "a": "Amna: Can you try and contact her yourself to see why she is late?"}, {"q": "Shirin: Remember, the teacher told us that __________ will be responsible for all our things?", "a": "Shirin: Remember, the teacher told us that we ourselves will be responsible for all our things?"}, {"q": "Sabah: Yes, I know. __________ typed up all the instructions of our teacher.", "a": "Sabah: Yes, I know. I myself typed up all the instructions of our teacher."}, {"q": "Fatima: Mr. Zameer has arranged for the food. __________ will pick it up from the cook and bring it here.", "a": "Fatima: Mr. Zameer has arranged for the food. He himself will pick it up from the cook and bring it here."}, {"q": "Amna: Can all of __________ please check if your bags have been put in the van?", "a": "Amna: Can all of you yourselves please check if your bags have been put in the van?"}, {"q": "Shirin: Those of you who will not check __________ will be responsible if their bags are left behind.", "a": "Shirin: Those of you who will not check themselves will be responsible if their bags are left behind."}, {"q": "Fatima: Hurrah! My bag is a genius. __________ went inside the van.", "a": "Fatima: Hurrah! My bag is a genius. It itself went inside the van. (The book's words 'My bag is a genius' are odd; the sense is that the bag somehow got into the van by itself.)"}]}]}], "words": [{"w": "emphatic pronoun", "sd": "تأڪيدي ضمير", "syn": "a pronoun like himself that emphasises a noun or pronoun"}, {"w": "reflexive pronoun", "sd": "انعڪاسي ضمير", "syn": "a pronoun ending in self or selves that points back to the subject"}]}, {"cls": "ix", "unit": 1, "title": "Second Conditional", "display": "Second Conditional", "reading": "Secondary Stage English Book One, Unit 1, Language Practice", "lesson": [{"t": "h", "x": "Second Conditional"}, {"t": "p", "x": "The second conditional talks about an unreal or imaginary situation in the present or future. If the situation were true, something else would happen."}, {"t": "def", "x": "The second conditional is: If + past simple, would + verb. It talks about an unreal or imaginary situation."}, {"t": "h", "x": "Rule 1. If + past simple, would + verb"}, {"t": "rule", "x": "In the second conditional, the 'if' part uses the past simple and the result part uses 'would' with the verb."}, {"t": "ex", "x": "If all people in Pakistan became honest, our country would progress. If we had a computer, we would finish our work quickly. If I were rich, I would help the poor."}, {"t": "h", "x": "Rule 2. Use 'were' for all persons with 'if'"}, {"t": "rule", "x": "In the 'if' part, use 'were' for all persons, even with I, he, she and it."}, {"t": "ex", "x": "If I were a bird, I would fly. If he were here, he would help us. If she were rich, she would give money to the poor."}, {"t": "h", "x": "Rule 3. The 'if' part can come first or second"}, {"t": "rule", "x": "The 'if' clause can come first or second. Use a comma when it comes first."}, {"t": "ex", "x": "If we had a computer, we would finish our work. We would finish our work if we had a computer."}, {"t": "h", "x": "Rule 4. Second conditional is unreal"}, {"t": "rule", "x": "The second conditional is about an imaginary situation, not a real one. Compare: First conditional — 'If you work hard, you will pass' (real). Second conditional — 'If you worked hard, you would pass' (imaginary)."}, {"t": "ex", "x": "If I had wings, I would fly. (I do not have wings.) If I were the king, I would help everyone."}, {"t": "rl", "x": "At school, if I had a computer, I would learn many new things. If our teacher were here, she would help us."}, {"t": "rl", "x": "At home, if my father were rich, he would buy a big house. If I had a bicycle, I would go to school on it."}, {"t": "rl", "x": "On the cricket ground, if Ali were the captain, he would win the match. If it rained, we would stop playing."}, {"t": "note", "x": "Do not use 'would' in the 'if' part: say 'If I had a computer, I would finish my work' — not 'If I would have a computer'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Match the second conditional sentences: If all people in Pakistan became honest ______.", "a": "g) the country would progress very fast. (given in the book)"}, {"q": "Match the second conditional sentences: I could easily get an A grade in my exams ______.", "a": "f) if I worked really hard."}, {"q": "Match the second conditional sentences: If our driver did not drive so fast ______.", "a": "d) we would not be in hospital right now."}, {"q": "Match the second conditional sentences: The tourists would not be lost ______.", "a": "b) if they had an updated map of the area."}, {"q": "Match the second conditional sentences: If they had the time ______.", "a": "c) they could visit all their friends."}, {"q": "Match the second conditional sentences: If money grew on trees ______.", "a": "h) everyone would be rich."}, {"q": "Match the second conditional sentences: Our schools would produce capable leaders ______.", "a": "a) if the students and teachers paid due attention."}, {"q": "Match the second conditional sentences: Her idea would be accepted ______.", "a": "e) if she presented it well."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Complete the second conditional sentence: If we had a computer, ______ (finish)", "a": "If we had a computer, we could finish this work quickly. (example given in the book) If we had a computer, we could find some more information. (example given in the book)"}, {"q": "Complete the second conditional sentence: We might see a bear, ______ (go)", "a": "We might see a bear, if we went further in the woods. (example given in the book) We might see a bear, if we climbed on a tree. (example given in the book)"}, {"q": "Complete the second conditional sentence: If she studied harder, ______ (get)", "a": "If she studied harder, she would get good marks."}, {"q": "Complete the second conditional sentence: If you grew multiple crops on your land, ______ (earn)", "a": "If you grew multiple crops on your land, you would earn more money."}, {"q": "Complete the second conditional sentence: People would fly, ______ (have)", "a": "People would fly, if they had wings."}, {"q": "Complete the second conditional sentence: If I owned a camera, ______ (take)", "a": "If I owned a camera, I would take many photographs."}, {"q": "Complete the second conditional sentence: They might win the match, ______ (work)", "a": "They might win the match, if they worked hard."}, {"q": "Complete the second conditional sentence: If Abdullah lived with his family, ______ (save)", "a": "If Abdullah lived with his family, he would save money."}, {"q": "Complete the second conditional sentence: My family would move to the city, ______ (allow)", "a": "My family would move to the city, if my father allowed us to move there."}, {"q": "Complete the second conditional sentence: She could become a good doctor, ______ (get)", "a": "She could become a good doctor, if she got admission to a medical college."}]}]}], "words": [{"w": "second conditional", "sd": "ٻيو شرطي جملو", "syn": "If + past simple, would + verb, for an unreal situation"}, {"w": "first conditional", "sd": "پھرين شرطي جملو", "syn": "If + present simple, will + verb, for a real situation"}, {"w": "unreal", "sd": "غير حقيقي", "syn": "imaginary, not real"}]}, {"cls": "ix", "unit": 2, "title": "Punctuation", "display": "Punctuation", "reading": "Secondary Stage English Book One, Units 1 and 8, Language Practice", "lesson": [{"t": "h", "x": "Punctuation"}, {"t": "p", "x": "Punctuation marks show us where a sentence begins and ends, and where to pause. The main marks are the full stop, comma, question mark, exclamation mark, capital letter and quotation marks."}, {"t": "def", "x": "Punctuation is the use of marks like the full stop, comma, question mark, exclamation mark and quotation marks to organise writing."}, {"t": "h", "x": "Rule 1. Begin a sentence with a capital letter and end it with a full stop"}, {"t": "rule", "x": "Every sentence begins with a capital letter and ends with a full stop, a question mark or an exclamation mark."}, {"t": "ex", "x": "Ali is a good boy. Where are you going? What a beautiful day! We are going to be late for school, Amjad, said his sister."}, {"t": "h", "x": "Rule 2. Use a capital letter for proper nouns"}, {"t": "rule", "x": "Begin the names of people, places, days, months and holidays with a capital letter."}, {"t": "ex", "x": "Ali, Sana, Karachi, Lahore, Pakistan, Friday, November, Eid, the River Indus."}, {"t": "h", "x": "Rule 3. Use a comma to separate things in a list"}, {"t": "rule", "x": "Use commas to separate words in a list, and to separate the name of the person spoken to."}, {"t": "ex", "x": "I bought a pen, a book and a bag. We are going to be late for school, Amjad, said his sister."}, {"t": "h", "x": "Rule 4. Use quotation marks for direct speech"}, {"t": "rule", "x": "Put quotation marks (\" \") around the exact words that somebody says."}, {"t": "ex", "x": "\"We are going to be late for school, Amjad,\" said his sister. \"Where are you going?\" asked mother."}, {"t": "h", "x": "Rule 5. Use a question mark for a question and an exclamation mark for a strong feeling"}, {"t": "rule", "x": "Use a question mark (?) at the end of a question and an exclamation mark (!) for a strong feeling or order."}, {"t": "ex", "x": "Where are you going? What a beautiful day! Hurry up!"}, {"t": "rl", "x": "At school, I write: 'My school is a good school.' My teacher says, \"Open your books.\""}, {"t": "rl", "x": "At home, my mother says, \"Wash your hands!\" I write a list: mangoes, apples and bananas."}, {"t": "rl", "x": "In the market, the shopkeeper says, \"Come here!\" I ask, \"How much is this?\""}, {"t": "note", "x": "A comma is also used before the reporting verb in direct speech: '\"Come here,\" said Ali.'"}], "sections": [{"num": "1", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "1. We are going to be late for school, Amjad, said his sister.", "a": "\"We are going to be late for school, Amjad,\" said his sister."}, {"q": "2. The students stood up and said, Good morning, teacher.", "a": "The students stood up and said, \"Good morning, teacher.\""}, {"q": "3. The cleaner said, I have cleaned your yard, and then he went away.", "a": "The cleaner said, \"I have cleaned your yard,\" and then he went away."}, {"q": "4. The small child was crying, and kept saying, Where is my mother?", "a": "The small child was crying, and kept saying, \"Where is my mother?\""}, {"q": "5. Come on in, children, said the gatekeeper, I am going to close the gate.", "a": "\"Come on in, children,\" said the gatekeeper, \"I am going to close the gate.\""}, {"q": "6. All the people were shouting, Pakistan Zindabad! We have won the match!", "a": "All the people were shouting, \"Pakistan Zindabad! We have won the match!\""}, {"q": "7. I have lost my car keys, said the old man. How can I start my car now?", "a": "\"I have lost my car keys,\" said the old man. \"How can I start my car now?\""}, {"q": "8. Be careful! There are many bees flying here. They may bite you, said Zahra.", "a": "\"Be careful! There are many bees flying here. They may bite you,\" said Zahra."}]}]}], "words": [{"w": "punctuation", "sd": "اوقاف", "syn": "marks like the full stop and comma that organise writing"}, {"w": "capital letter", "sd": "وڏو اکر", "syn": "a big letter like A, B, C"}, {"w": "quotation marks", "sd": "واوين", "syn": "the marks \" \" used around spoken words"}, {"w": "full stop", "sd": "سھڻو", "syn": "the mark . at the end of a sentence"}]}, {"cls": "ix", "unit": 3, "title": "Modals for Ability", "display": "Modals for Ability", "reading": "Secondary Stage English Book One, Unit 2, Language Practice", "lesson": [{"t": "h", "x": "Modals for Ability"}, {"t": "p", "x": "Modals are helping verbs like can, could, may, might, must, shall, should, will and would. We use 'can' and 'could' to talk about ability."}, {"t": "def", "x": "A modal is a helping verb that shows ability, permission, possibility or duty. 'Can' shows present ability. 'Could' shows past ability."}, {"t": "h", "x": "Rule 1. Use 'can' for present ability"}, {"t": "rule", "x": "Use 'can' to say what somebody is able to do now."}, {"t": "ex", "x": "I can swim. She can speak English. He can play cricket. We can read this book."}, {"t": "h", "x": "Rule 2. Use 'could' for past ability"}, {"t": "rule", "x": "Use 'could' to say what somebody was able to do in the past."}, {"t": "ex", "x": "I could swim when I was five years old. She could read when she was four. He could play cricket when he was young."}, {"t": "h", "x": "Rule 3. Use 'cannot' and 'could not' for no ability"}, {"t": "rule", "x": "Use 'cannot' (can't) and 'could not' (couldn't) to say what somebody is not able or was not able to do."}, {"t": "ex", "x": "I cannot swim. I can't ride a horse. He could not read when he was five. She couldn't speak English last year."}, {"t": "h", "x": "Rule 4. After can and could, use the verb without 's' or 'ed'"}, {"t": "rule", "x": "After can, could and other modals, use the first form of the verb."}, {"t": "ex", "x": "I can play. She could swim. He can read. (Not: I can plays, She could swam.)"}, {"t": "rl", "x": "At school, I can read English books. My friend could not read last year, but now he can."}, {"t": "rl", "x": "At home, my sister can cook food. My brother could swim when he was ten years old."}, {"t": "rl", "x": "On the cricket ground, Ali can bat well. Ahmed could bowl fast when he was young."}, {"t": "note", "x": "Use 'can' for the present and 'could' for the past. Do not use 'can' for the past."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Fill in the blank with the positive or negative form of a suitable modal verb (can/could): I ______ swim when I was a child but I ______ swim now.", "a": "I could swim when I was a child but I can't swim now."}, {"q": "Fill in the blank with the positive or negative form of a suitable modal verb (can/could): My brother ______ run fast when he was five years old but he ______ run fast now.", "a": "My brother could run fast when he was five years old but he can't run fast now."}, {"q": "Fill in the blank with the positive or negative form of a suitable modal verb (can/could): They ______ come early but they ______ find a bus earlier.", "a": "They could come early but they couldn't find a bus earlier."}, {"q": "Fill in the blank with the positive or negative form of a suitable modal verb (can/could): Nowadays, Sana ______ speak English fluently but she ______ speak so well a year ago.", "a": "Nowadays, Sana can speak English fluently but she couldn't speak so well a year ago."}, {"q": "Fill in the blank with the positive or negative form of a suitable modal verb (can/could): Sameer ______ speak several languages when he was young but now he ______ speak only English fluently.", "a": "Sameer could speak several languages when he was young but now he can speak only English fluently."}, {"q": "Fill in the blank with the positive or negative form of a suitable modal verb (can/could): Little Shahzain ______ crawl but he still ______ walk.", "a": "Little Shahzain can crawl but he still can't walk."}, {"q": "Fill in the blank with the positive or negative form of a suitable modal verb (can/could): Sara ______ embroider and stitch clothes but her sister ______.", "a": "Sara can embroider and stitch clothes but her sister can't. (Note: the book leaves the second blank without a verb; 'can't' is the intended answer. See the writer's flags.)"}, {"q": "Fill in the blank with the positive or negative form of a suitable modal verb (can/could): We ______ play after completing our homework but we ______ play before that.", "a": "We can play after completing our homework but we can't play before that."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Write about your abilities/inabilities in the following blanks. You should share what you were/were not able to do when you were younger, what you can do now and what you will be able to do when you grow up. When I was younger/When I was nine years old: I could ______ But, I couldn't ______ Now, I can ______ However, I can't ______ When I grow up, I can ______", "a": "When I was nine years old, I could ride a bicycle. But, I couldn't swim. Now, I can speak English well. However, I can't drive a car. When I grow up, I can become a famous doctor. (Model answer; students write about their own abilities.)"}]}]}], "words": [{"w": "modal", "sd": "مددگار فعل", "syn": "a helping verb like can, could, may or must"}, {"w": "ability", "sd": "قابليت", "syn": "what somebody is able to do"}]}, {"cls": "ix", "unit": 4, "title": "Prefixes and Suffixes", "display": "Prefixes and Suffixes", "reading": "Secondary Stage English Book One, Units 2, 4 and 7, Language Practice", "lesson": [{"t": "h", "x": "Prefixes and Suffixes"}, {"t": "p", "x": "A prefix is a group of letters added at the beginning of a word. A suffix is a group of letters added at the end of a word. They change the meaning of the word."}, {"t": "def", "x": "A prefix is added at the beginning of a word. A suffix is added at the end of a word. Both change the meaning of the word."}, {"t": "h", "x": "Rule 1. The prefix 're' means 'again'"}, {"t": "rule", "x": "Add 're' to a word to mean 'again': rewrite, reread, rebuild, return, replay, renew."}, {"t": "ex", "x": "rewrite — write again, reread — read again, rebuild — build again, return — turn again."}, {"t": "h", "x": "Rule 2. The suffix 'ment' makes a noun"}, {"t": "rule", "x": "Add 'ment' to a verb to make a noun: employ — employment, treat — treatment, manage — management, pay — payment, retire — retirement, judge — judgement."}, {"t": "ex", "x": "employment, treatment, management, payment, retirement, judgement."}, {"t": "h", "x": "Rule 3. The suffix 'ness' makes a noun"}, {"t": "rule", "x": "Add 'ness' to an adjective to make a noun: ill — illness, bold — boldness, neat — neatness, kind — kindness, soft — softness."}, {"t": "ex", "x": "illness, boldness, neatness, kindness, softness, happiness, sadness."}, {"t": "h", "x": "Rule 4. The suffix 'al' makes a noun or an adjective"}, {"t": "rule", "x": "Add 'al' to a word to make a noun or an adjective: sign — signal, survive — survival, approve — approval, propose — proposal, nation — national."}, {"t": "ex", "x": "signal, survival, approval, proposal, national, natural."}, {"t": "h", "x": "Rule 5. The prefix 'un' means 'not'"}, {"t": "rule", "x": "Add 'un' to a word to mean 'not': happy — unhappy, lucky — unlucky, kind — unkind, known — unknown."}, {"t": "ex", "x": "An unhappy person often falls sick. It was an unlucky day. He is unkind to animals."}, {"t": "rl", "x": "At school, I rewrite my homework when it is wrong. My teacher's kindness makes us happy."}, {"t": "rl", "x": "At home, my mother pays the bill. The payment is made every month. My father's employment is in Karachi."}, {"t": "rl", "x": "In the market, the shopkeeper's approval is needed. The signal is red, so we stop."}, {"t": "note", "x": "A prefix changes the meaning at the beginning; a suffix changes the word at the end. 'Un' + 'happy' = 'unhappy'. 'Kind' + 'ness' = 'kindness'."}], "sections": [{"num": "1", "name": "Exercise 4A", "exercises": [{"label": "Exercise 4A", "items": [{"q": "Fill in the blank with a noun formed by using the suffix 'ment' with the appropriate given word (employ, treat, manage, pay, retire, judge): As soon as the judgement was given, the reporters left the court room.", "a": "As soon as the judgement was given, the reporters left the court room. (given in the book)"}, {"q": "Fill in the blank with a noun formed by using the suffix 'ment': Zaman is back to work after his ______.", "a": "Zaman is back to work after his treatment."}, {"q": "Fill in the blank with a noun formed by using the suffix 'ment': The workers receive their weekly ______ every Friday.", "a": "The workers receive their weekly payment every Friday."}, {"q": "Fill in the blank with a noun formed by using the suffix 'ment': My son is looking for ______ as he lost his job last week.", "a": "My son is looking for employment as he lost his job last week."}, {"q": "Fill in the blank with a noun formed by using the suffix 'ment': After his ______ at the age of sixty he has decided to write a book.", "a": "After his retirement at the age of sixty he has decided to write a book."}, {"q": "Fill in the blank with a noun formed by using the suffix 'ment': The ______ of the school announced their new admission policy yesterday.", "a": "The management of the school announced their new admission policy yesterday."}]}]}, {"num": "2", "name": "Exercise 4B", "exercises": [{"label": "Exercise 4B", "items": [{"q": "Fill in the blank by using the suffix 'ness' with the appropriate given word (ill, bold, neat, kind, soft): Her ______ has made her weak.", "a": "Her illness has made her weak."}, {"q": "Fill in the blank by using the suffix 'ness': I love the ______ of our new sofa set.", "a": "I love the softness of our new sofa set."}, {"q": "Fill in the blank by using the suffix 'ness': Our neighbour's son, who is a soldier, fought the enemy with ______.", "a": "Our neighbour's son, who is a soldier, fought the enemy with boldness."}, {"q": "Fill in the blank by using the suffix 'ness': The principal of our school treats everyone with ______.", "a": "The principal of our school treats everyone with kindness."}, {"q": "Fill in the blank by using the suffix 'ness': My mother taught us ______ in all our work.", "a": "My mother taught us neatness in all our work."}]}]}, {"num": "3", "name": "Exercise 4C", "exercises": [{"label": "Exercise 4C", "items": [{"q": "Fill in the blank by using the suffix 'al' with the appropriate given word (sign, survive, approve, propose, remove): The ______ of the green turtle is in danger on the Karachi beaches.", "a": "The survival of the green turtle is in danger on the Karachi beaches."}, {"q": "Fill in the blank by using the suffix 'al': Our ______ for setting up a dispensary was accepted by the minister.", "a": "Our proposal for setting up a dispensary was accepted by the minister."}, {"q": "Fill in the blank by using the suffix 'al': The ______ of garbage is the responsibility of the government.", "a": "The removal of garbage is the responsibility of the government."}, {"q": "Fill in the blank by using the suffix 'al': The train moved out of the station as soon as the guard gave the ______.", "a": "The train moved out of the station as soon as the guard gave the signal."}, {"q": "Fill in the blank by using the suffix 'al': I needed my parents' ______ for going to friend's wedding.", "a": "I needed my parents' approval for going to friend's wedding."}]}]}, {"num": "4", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Fill the blanks in the following exercise by using the prefix 're' with the appropriate given words. One has been done as an example. Words: tell, do, claim, apply, print, arrange. 1. The government is trying to reclaim (given in the book) land from the sea in Karachi.", "a": "The government is trying to reclaim land from the sea in Karachi. (Example given in the book: re + claim = reclaim.)"}, {"q": "Fill the blank by using the prefix 're' with the appropriate given word. Words: tell, do, claim, apply, print, arrange. 2. The company had to ______ this book three times.", "a": "The company had to reprint this book three times."}, {"q": "Fill the blank by using the prefix 're' with the appropriate given word. Words: tell, do, claim, apply, print, arrange. 3. I advised my friend to ______ for a teaching position in our school.", "a": "I advised my friend to reapply for a teaching position in our school."}, {"q": "Fill the blank by using the prefix 're' with the appropriate given word. Words: tell, do, claim, apply, print, arrange. 4. My father likes to ______ his childhood stories to his grandchildren.", "a": "My father likes to retell his childhood stories to his grandchildren."}, {"q": "Fill the blank by using the prefix 're' with the appropriate given word. Words: tell, do, claim, apply, print, arrange. 5. Saira and Khalida decided to ______ the furniture in their room.", "a": "Saira and Khalida decided to rearrange the furniture in their room."}, {"q": "Fill the blank by using the prefix 're' with the appropriate given word. Words: tell, do, claim, apply, print, arrange. 6. The teacher told the class to ______ the exercise.", "a": "The teacher told the class to redo the exercise."}, {"q": "Fill the blanks in the following exercise by using the prefix 'mis' with the appropriate given words. Words: treat, match, behave, understand, place. 1. When children ______ they are often punished by their parents.", "a": "When children misbehave they are often punished by their parents."}, {"q": "Fill the blank by using the prefix 'mis' with the appropriate given word. Words: treat, match, behave, understand, place. 2. My brothers always ______ their mobile phones.", "a": "My brothers always misplace their mobile phones."}, {"q": "Fill the blank by using the prefix 'mis' with the appropriate given word. Words: treat, match, behave, understand, place. 3. There is a ______ between their income and expenditure.", "a": "There is a mismatch between their income and expenditure."}, {"q": "Fill the blank by using the prefix 'mis' with the appropriate given word. Words: treat, match, behave, understand, place. 4. Many people ______ their leader's message.", "a": "Many people misunderstand their leader's message."}, {"q": "Fill the blank by using the prefix 'mis' with the appropriate given word. Words: treat, match, behave, understand, place. 5. It is not right to ______ servants.", "a": "It is not right to mistreat servants."}, {"q": "Fill the blanks in the following exercise by using the prefix 'inter' with the appropriate given words. Words: national, faith, personal, city, dependent. 1. The ______ bus service is very good in some countries.", "a": "The intercity bus service is very good in some countries."}, {"q": "Fill the blank by using the prefix 'inter' with the appropriate given word. Words: national, faith, personal, city, dependent. 2. There is more ______ travel today than about fifty years ago.", "a": "There is more international travel today than about fifty years ago."}, {"q": "Fill the blank by using the prefix 'inter' with the appropriate given word. Words: national, faith, personal, city, dependent. 3. For success in any work good ______ skills are needed.", "a": "For success in any work good interpersonal skills are needed."}, {"q": "Fill the blank by using the prefix 'inter' with the appropriate given word. Words: national, faith, personal, city, dependent. 4. The quality of goods and their price are ______.", "a": "The quality of goods and their price are interdependent."}, {"q": "Fill the blank by using the prefix 'inter' with the appropriate given word. Words: national, faith, personal, city, dependent. 5. ______ understanding is very important for peace in the world.", "a": "Interfaith understanding is very important for peace in the world."}]}]}, {"num": "5", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "A.1. An ____________ person often falls sick.", "a": "An unhealthy person often falls sick."}, {"q": "A.2. Saba is very ____________ and does not like meeting people.", "a": "Saba is very unfriendly and does not like meeting people."}, {"q": "A.3. People who are ____________ never thank others for helping them.", "a": "People who are ungrateful never thank others for helping them."}, {"q": "A.4. Badar was very ____________ because he lost his favourite watch.", "a": "Badar was very unhappy because he lost his favourite watch."}, {"q": "A.5. My uncle took an ____________ decision due to which he suffered a big loss.", "a": "My uncle took an unwise decision due to which he suffered a big loss."}, {"q": "B.1. This small boy is very ____________ and does not take part in any work.", "a": "This small boy is very inactive and does not take part in any work."}, {"q": "B.2. The judge was upset with the prisoner for giving an ____________ statement to the court.", "a": "The judge was upset with the prisoner for giving an incorrect statement to the court."}, {"q": "B.3. Don't leave your work ____________ or the boss will be angry.", "a": "Don't leave your work incomplete or the boss will be angry."}, {"q": "B.4. Sajid is very ____________ in class; hence, he often fails in the tests.", "a": "Sajid is very inattentive in class; hence, he often fails in the tests."}, {"q": "B.5. This amount of money is ____________ if you want to buy a new computer.", "a": "This amount of money is insufficient if you want to buy a new computer."}, {"q": "C.1. We sometimes ____________ even with our very close friends.", "a": "We sometimes disagree even with our very close friends."}, {"q": "C.2. We cannot trust ____________ people as they can cheat us.", "a": "We cannot trust dishonest people as they can cheat us."}, {"q": "C.3. A ____________ child can cause many problems for the whole family.", "a": "A disobedient child can cause many problems for the whole family."}, {"q": "C.4. Our teacher was ____________ with our performance in the competition.", "a": "Our teacher was dissatisfied with our performance in the competition."}, {"q": "C.5. We should never be ____________ to our country.", "a": "We should never be disloyal to our country."}]}]}], "words": [{"w": "prefix", "sd": "اڳياڙي", "syn": "letters added at the beginning of a word"}, {"w": "suffix", "sd": "پڇاڙي", "syn": "letters added at the end of a word"}, {"w": "noun", "sd": "اسم", "syn": "a word that names a person, place, animal or thing"}]}, {"cls": "ix", "unit": 5, "title": "Types of Sentences: Simple and Compound", "display": "Types of Sentences: Simple and Compound", "reading": "Secondary Stage English Book One, Units 3 and 5, Language Practice", "lesson": [{"t": "h", "x": "Types of Sentences: Simple and Compound"}, {"t": "p", "x": "There are four kinds of sentences: simple, compound, complex and compound-complex. In this lesson we learn simple and compound sentences, and the four kinds by purpose: declarative, interrogative, imperative and exclamatory."}, {"t": "def", "x": "A simple sentence has one subject and one verb. A compound sentence has two simple sentences joined by a conjunction like and, but, or, so or for."}, {"t": "h", "x": "Rule 1. A simple sentence has one subject and one verb"}, {"t": "rule", "x": "A simple sentence has one subject and one verb. It gives one complete idea."}, {"t": "ex", "x": "Sabiha is shivering. Apples are good for health. Ali plays cricket. The sun rises in the east."}, {"t": "h", "x": "Rule 2. A compound sentence joins two simple sentences"}, {"t": "rule", "x": "A compound sentence joins two simple sentences with and, but, or, so, for or yet."}, {"t": "ex", "x": "Sabiha is shivering, and she is wearing a sweater. Ali plays cricket, and Ahmed plays hockey. I was tired, so I went to bed."}, {"t": "h", "x": "Rule 3. Four kinds of sentences by purpose"}, {"t": "rule", "x": "A declarative sentence makes a statement. An interrogative sentence asks a question. An imperative sentence gives an order. An exclamatory sentence shows a strong feeling."}, {"t": "ex", "x": "Declarative: Apples are good for health. Interrogative: Are apples good for health? Imperative: Eat an apple every day. Exclamatory: What a sweet apple!"}, {"t": "h", "x": "Rule 4. Change a sentence from one kind to another"}, {"t": "rule", "x": "We can change an affirmative sentence into a negative one, and a statement into a question."}, {"t": "ex", "x": "Affirmative: Sabiha is shivering. Negative: Sabiha is not shivering. Question: Is Sabiha shivering?"}, {"t": "rl", "x": "At school, the teacher says, 'Ali is a good boy.' (simple) 'Ali is a good boy, and Ahmed is a good boy too.' (compound)"}, {"t": "rl", "x": "At home, my mother says, 'Eat your food.' (imperative) I ask, 'Is the food ready?' (interrogative)"}, {"t": "rl", "x": "On the cricket ground, Ali plays well. (simple) Ali plays well, and Ahmed bowls well. (compound) What a good shot! (exclamatory)"}, {"t": "note", "x": "A compound sentence has two parts, each of which could be a sentence on its own. Use a comma before the conjunction."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Write what type of sentence it is: Sabiha is shivering.", "a": "declarative affirmative (given in the book)"}, {"q": "Write what type of sentence it is: Are we going to the football field?", "a": "interrogative affirmative"}, {"q": "Write what type of sentence it is: The stranger was not calling from the hospital.", "a": "declarative negative"}, {"q": "Write what type of sentence it is: Will you come to my house tomorrow to study?", "a": "interrogative affirmative"}, {"q": "Write what type of sentence it is: I like to play cricket.", "a": "declarative affirmative"}, {"q": "Write what type of sentence it is: Isn't this your book?", "a": "interrogative negative"}, {"q": "Write what type of sentence it is: Aren't you the girl who won the gold medal?", "a": "interrogative negative"}, {"q": "Write what type of sentence it is: Juman doesn't like to play hockey.", "a": "declarative negative"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Change the affirmative sentence into negative: Sabiha is shivering.", "a": "Sabiha is not shivering."}, {"q": "Change the interrogative affirmative sentence into interrogative negative: Are we going to the football field?", "a": "Aren't we going to the football field?"}, {"q": "Change the negative sentence into affirmative: The stranger was not calling from the hospital.", "a": "The stranger was calling from the hospital."}, {"q": "Change the interrogative affirmative sentence into interrogative negative: Will you come to my house tomorrow to study?", "a": "Won't you come to my house tomorrow to study?"}, {"q": "Change the affirmative sentence into negative: I like to play cricket.", "a": "I don't like to play cricket."}, {"q": "Change the interrogative negative sentence into interrogative affirmative: Isn't this your book?", "a": "Is this your book?"}, {"q": "Change the interrogative negative sentence into interrogative affirmative: Aren't you the girl who won the gold medal?", "a": "Are you the girl who won the gold medal?"}, {"q": "Change the negative sentence into affirmative: Juman doesn't like to play hockey.", "a": "Juman likes to play hockey."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Apples are good for health. What type of sentence is it?", "a": "declarative affirmative (given in the book)"}, {"q": "These apples are not good for health. What type of sentence is it?", "a": "declarative negative (given in the book)"}, {"q": "Are these apples tasty? What type of sentence is it?", "a": "interrogative affirmative (given in the book)"}, {"q": "Aren't these apples raw? What type of sentence is it?", "a": "interrogative negative (given in the book)"}, {"q": "Work in groups of four (Steps 1-5). Using a new key word, write the four types of sentences.", "a": "Model set with the key word 'book': Declarative affirmative: This book is very interesting. Declarative negative: This book is not very interesting. Interrogative affirmative: Is this book interesting? Interrogative negative: Isn't this book interesting? (Repeat the activity with two more key words so that you have twelve sentences in your notebook, as the book asks.)"}]}]}, {"num": "4", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Look at the sentence in the table below. Against the sentence put a tick mark in the column that identifies whether it is a simple or a compound sentence. 1. This year has started on a positive note for the students.", "a": "simple (example given in the book)"}, {"q": "Look at the sentence in the table below. Against the sentence put a tick mark in the column that identifies whether it is a simple or a compound sentence. 2. The classrooms smell of fresh paint, as they were painted during the holidays.", "a": "compound (according to the book's rule, two complete sentences joined by a comma and a conjunction - 'as'. Note: in strict grammar 'as' makes this a complex sentence, because the second part cannot stand alone as a complete sentence.)"}, {"q": "Look at the sentence in the table below. Against the sentence put a tick mark in the column that identifies whether it is a simple or a compound sentence. 3. The students love the newly painted classrooms, and they like the newly polished desks.", "a": "compound (two complete sentences joined by a comma and 'and')"}, {"q": "Look at the sentence in the table below. Against the sentence put a tick mark in the column that identifies whether it is a simple or a compound sentence. 4. Their motivation has increased and their enthusiasm is clearly visible.", "a": "compound (two complete sentences joined by 'and'; the book's rule says comma + conjunction, but the comma is left out here)"}, {"q": "Look at the sentence in the table below. Against the sentence put a tick mark in the column that identifies whether it is a simple or a compound sentence. 5. Most of the students come to school regularly now.", "a": "simple (one subject and one predicate)"}, {"q": "Look at the sentence in the table below. Against the sentence put a tick mark in the column that identifies whether it is a simple or a compound sentence. 6. They actively participate in various class activities.", "a": "simple (one subject and one predicate)"}, {"q": "Look at the sentence in the table below. Against the sentence put a tick mark in the column that identifies whether it is a simple or a compound sentence. 7. The students enjoy being outdoors, because they all like sports activities.", "a": "compound (according to the book's rule, 'because' is listed among the conjunctions that join two complete sentences. Note: in strict grammar 'because' makes this a complex sentence.)"}, {"q": "Look at the sentence in the table below. Against the sentence put a tick mark in the column that identifies whether it is a simple or a compound sentence. 8. They are happy with the new look of the school, but they are not happy with the sports facilities that they have.", "a": "compound (two complete sentences joined by a comma and 'but')"}, {"q": "Look at the sentence in the table below. Against the sentence put a tick mark in the column that identifies whether it is a simple or a compound sentence. 9. They have requested their principal for better sports and game facilities.", "a": "simple (one subject and one predicate)"}, {"q": "Look at the sentence in the table below. Against the sentence put a tick mark in the column that identifies whether it is a simple or a compound sentence. 10. The students are hopeful that they will have good facilities soon, because their principal has promised that new play grounds will be developed.", "a": "compound (according to the book's rule, the two parts are joined by a comma and 'because'. Note: in strict grammar this is a complex sentence, because 'that they will have good facilities soon' is not a separate complete sentence.)"}]}]}, {"num": "5", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Join the two sentences to form a compound sentence, using any conjunction: and, but, for, because, as, so, or, nor, etc. a. Najma and Rehana studied very hard. They both got A grades in their exams.", "a": "Najma and Rehana studied very hard, so they both got A grades in their exams."}, {"q": "Join the two sentences to form a compound sentence, using any conjunction: and, but, for, because, as, so, or, nor, etc. b. Her father is a pilot. He has flown many different types of planes.", "a": "Her father is a pilot, and he has flown many different types of planes."}, {"q": "Join the two sentences to form a compound sentence, using any conjunction: and, but, for, because, as, so, or, nor, etc. c. Our car is very old. Its engine is in good condition.", "a": "Our car is very old, but its engine is in good condition."}, {"q": "Join the two sentences to form a compound sentence, using any conjunction: and, but, for, because, as, so, or, nor, etc. d. The boys were playing cricket. It was the first day of their summer vacations.", "a": "The boys were playing cricket, for it was the first day of their summer vacations."}, {"q": "Join the two sentences to form a compound sentence, using any conjunction: and, but, for, because, as, so, or, nor, etc. e. My brother is a good artist. He cannot sing at all.", "a": "My brother is a good artist, but he cannot sing at all."}, {"q": "Join the two sentences to form a compound sentence, using any conjunction: and, but, for, because, as, so, or, nor, etc. f. You may buy only a new dress now. You may buy a new dress and new shoes next month.", "a": "You may buy only a new dress now, or you may buy a new dress and new shoes next month."}, {"q": "Join the two sentences to form a compound sentence, using any conjunction: and, but, for, because, as, so, or, nor, etc. g. The baby cannot walk. The baby can crawl very fast.", "a": "The baby cannot walk, but the baby can crawl very fast."}, {"q": "Join the two sentences to form a compound sentence, using any conjunction: and, but, for, because, as, so, or, nor, etc. h. I love gardening. I can grow my own fresh vegetables.", "a": "I love gardening, for I can grow my own fresh vegetables."}, {"q": "Join the two sentences to form a compound sentence, using any conjunction: and, but, for, because, as, so, or, nor, etc. i. The flowers in this pot are very colourful. The flowers in your garden have a lovely fragrance.", "a": "The flowers in this pot are very colourful, and the flowers in your garden have a lovely fragrance."}, {"q": "Join the two sentences to form a compound sentence, using any conjunction: and, but, for, because, as, so, or, nor, etc. j. This book is very informative. It is also very interesting.", "a": "This book is very informative, and it is also very interesting."}]}]}], "words": [{"w": "simple sentence", "sd": "سادو جملو", "syn": "a sentence with one subject and one verb"}, {"w": "compound sentence", "sd": "مرڪب جملو", "syn": "two simple sentences joined by a conjunction"}, {"w": "declarative sentence", "sd": "بياني جملو", "syn": "a sentence that makes a statement"}, {"w": "interrogative sentence", "sd": "سوالي جملو", "syn": "a sentence that asks a question"}, {"w": "imperative sentence", "sd": "حڪم وارو جملو", "syn": "a sentence that gives an order"}, {"w": "exclamatory sentence", "sd": "حيرت وارو جملو", "syn": "a sentence that shows a strong feeling"}]}, {"cls": "ix", "unit": 6, "title": "Articles", "display": "Articles", "reading": "Secondary Stage English Book One, Unit 3, Language Practice", "lesson": [{"t": "h", "x": "Articles"}, {"t": "p", "x": "A, an and the are articles. We use 'a' and 'an' for one thing in general, and 'the' for a special or known thing."}, {"t": "def", "x": "An article is a word used before a noun. 'A' and 'an' are indefinite articles. 'The' is the definite article."}, {"t": "h", "x": "Rule 1. Use 'a' before a consonant sound"}, {"t": "rule", "x": "Use 'a' before a word that begins with a consonant sound."}, {"t": "ex", "x": "a book, a pen, a dress, a boy, a country, a university, a one-rupee coin."}, {"t": "h", "x": "Rule 2. Use 'an' before a vowel sound"}, {"t": "rule", "x": "Use 'an' before a word that begins with a vowel sound (a, e, i, o, u)."}, {"t": "ex", "x": "an apple, an egg, an eye, an elephant, an umbrella, an hour, an honest man."}, {"t": "h", "x": "Rule 3. Use 'the' for a special or known thing"}, {"t": "rule", "x": "Use 'the' when we talk about a special or known thing, or when there is only one of it."}, {"t": "ex", "x": "The Indus is the longest river in Pakistan. The sun rises in the east. The book on the table is mine."}, {"t": "h", "x": "Rule 4. Use 'the' with superlatives and with some names"}, {"t": "rule", "x": "Use 'the' before the superlative degree and before the names of rivers, seas, oceans and mountain ranges."}, {"t": "ex", "x": "the tallest boy, the best student, the River Indus, the Arabian Sea, the Himalayas."}, {"t": "h", "x": "Rule 5. Use no article in some cases"}, {"t": "rule", "x": "Do not use an article before a person's name, before a general plural noun, or before the name of a language or a subject."}, {"t": "ex", "x": "Ali is my friend. Boys play cricket. I learn English. We study science."}, {"t": "rl", "x": "At school, I have a pen and an eraser. The pen is blue. The teacher is the best in our school."}, {"t": "rl", "x": "At home, my mother bought a dress. The dress is red. She gave me an apple."}, {"t": "rl", "x": "In the market, I saw the moon in the sky. The sun is hot. A shopkeeper sells fruit."}, {"t": "note", "x": "Use 'the' the second time we talk about a thing: 'I saw a dog. The dog was black.'"}], "sections": [{"num": "1", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Fill in the blanks with a, an, the, where necessary: I know that ______ Indus is ______ longest river in ______ Pakistan.", "a": "I know that the Indus is the longest river in Pakistan."}, {"q": "Fill in the blanks with a, an, the, where necessary: In order to learn ______ language, we need two things; ______ good teacher and ______ will to work.", "a": "In order to learn a language, we need two things; a good teacher and the will to work."}, {"q": "Fill in the blanks with a, an, the, where necessary: ______ capital of ______ Pakistan is ______ Islamabad.", "a": "The capital of Pakistan is Islamabad."}, {"q": "Fill in the blanks with a, an, the, where necessary: Some people have ______ bicycles, some have ______ car, I have ______ both.", "a": "Some people have bicycles, some have a car, I have both. (No article is needed before 'bicycles' or 'both'.)"}, {"q": "Fill in the blanks with a, an, the, where necessary: In many countries, children ______ go to ______ school at ______ age of five.", "a": "In many countries, children go to school at the age of five."}, {"q": "Fill in the blanks with a, an, the, where necessary: They are studying ______ geography, and in particular ______ geography of ______ United Arab Emirates.", "a": "They are studying geography, and in particular the geography of the United Arab Emirates."}, {"q": "Fill in the blanks with a, an, the, where necessary: Her friend loves eating ______ orange at breakfast time, ______ apple with her lunch, and ______ banana at dinner time.", "a": "Her friend loves eating an orange at breakfast time, an apple with her lunch, and a banana at dinner time."}, {"q": "Fill in the blanks with a, an, the, where necessary: My mother says ______ more you exercise, ______ better your health.", "a": "My mother says the more you exercise, the better your health."}, {"q": "Fill in the blanks with a, an, the, where necessary: ______ Chinese are helping ______ Pakistanis to build ______ road from ______ Gwadar to ______ Chinese border.", "a": "The Chinese are helping the Pakistanis to build a road from Gwadar to the Chinese border."}, {"q": "Fill in the blanks with a, an, the, where necessary: ______ intelligent person always thinks before speaking, but many ______ people just say whatever comes to thier mind.", "a": "An intelligent person always thinks before speaking, but many people just say whatever comes to their mind. (The book prints 'thier'; the correct spelling is 'their'.)"}]}]}], "words": [{"w": "article", "sd": "حرف تنڪير", "syn": "a word like a, an or the used before a noun"}, {"w": "definite article", "sd": "حرف تنڪير خاص", "syn": "the article 'the'"}, {"w": "indefinite article", "sd": "حرف تنڪير عام", "syn": "the articles 'a' and 'an'"}]}, {"cls": "ix", "unit": 7, "title": "Change the Voice", "display": "Change the Voice", "reading": "Secondary Stage English Book One, Unit 4, Language Practice", "lesson": [{"t": "h", "x": "Change the Voice"}, {"t": "p", "x": "In the active voice, the subject does the action. In the passive voice, the subject receives the action. We can change a sentence from one voice to the other."}, {"t": "def", "x": "Voice shows whether the subject does the action (active) or receives the action (passive). The passive is made with a be verb and the past participle."}, {"t": "h", "x": "Rule 1. Make the passive with be + past participle"}, {"t": "rule", "x": "Make the passive voice with is, am, are, was, were, has been or will be and the past participle of the verb."}, {"t": "ex", "x": "The letter is written. The room was cleaned. The food has been cooked. The match will be won."}, {"t": "h", "x": "Rule 2. Change active into passive"}, {"t": "rule", "x": "To change an active sentence into a passive one, make the object the subject, use the be verb and the past participle, and put the old subject after 'by' if needed."}, {"t": "ex", "x": "Active: Ali writes a letter. Passive: A letter is written by Ali. Active: The cat drank the milk. Passive: The milk was drunk by the cat. Active: They will build a school. Passive: A school will be built by them."}, {"t": "h", "x": "Rule 3. Change passive into active"}, {"t": "rule", "x": "To change a passive sentence into an active one, make the 'by' part the subject and use the verb in the active voice."}, {"t": "ex", "x": "Passive: A letter is written by Ali. Active: Ali writes a letter. Passive: The match was won by our team. Active: Our team won the match."}, {"t": "h", "x": "Rule 4. Use the passive when the doer is not known"}, {"t": "rule", "x": "Use the passive voice when we do not know who did the action, or when it does not matter."}, {"t": "ex", "x": "The window was broken. (We do not know who broke it.) Rice is grown in Sindh. English is spoken in many countries."}, {"t": "rl", "x": "At school, the classroom is cleaned every day. The homework is checked by the teacher. Our team won the match."}, {"t": "rl", "x": "At home, the food is cooked by my mother. The house was cleaned by all of us."}, {"t": "rl", "x": "In the market, fruit is sold in the shops. Mangoes are bought by many people."}, {"t": "note", "x": "Keep the tense the same when you change the voice: present stays present, past stays past."}], "sections": [{"num": "1", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Work in pairs and complete the following news report using the correct form of the passive, using the verbs given in brackets. Write the correct news report in your notebook. The northern part of the country was hit (hit) by a massive earthquake this morning. The entire infrastructure ______ (damage) very badly.", "a": "The entire infrastructure was damaged very badly."}, {"q": "Work in pairs and complete the following news report using the correct form of the passive, using the verbs given in brackets. The roads ______ (break).", "a": "The roads were broken."}, {"q": "Work in pairs and complete the following news report using the correct form of the passive, using the verbs given in brackets. The telephone lines ______ (destroy).", "a": "The telephone lines were destroyed."}, {"q": "Work in pairs and complete the following news report using the correct form of the passive, using the verbs given in brackets. The mobile services ______ (disrupt).", "a": "The mobile services were disrupted."}, {"q": "Work in pairs and complete the following news report using the correct form of the passive, using the verbs given in brackets. The people ______ (scare) as many aftershocks are expected.", "a": "The people were scared as many aftershocks are expected."}, {"q": "Work in pairs and complete the following news report using the correct form of the passive, using the verbs given in brackets. Many aftershocks ______ (expect).", "a": "Many aftershocks are expected."}, {"q": "Work in pairs and complete the following news report using the correct form of the passive, using the verbs given in brackets. Food, water and medical aid ______ (rush) to the area.", "a": "Food, water and medical aid are being rushed to the area."}, {"q": "Work in pairs and complete the following news report using the correct form of the passive, using the verbs given in brackets. An appeal ______ (make) by the government asking people not to panic.", "a": "An appeal was made by the government asking people not to panic."}, {"q": "Work in pairs and complete the following news report using the correct form of the passive, using the verbs given in brackets. Work ______ (do) by the army to enable reaching of aid to the remote areas.", "a": "Work is being done by the army to enable reaching of aid to the remote areas."}, {"q": "Work in pairs and complete the following news report using the correct form of the passive, using the verbs given in brackets. Funds ______ (release) by the government to help people in this hour of grief.", "a": "Funds have been released by the government to help people in this hour of grief."}]}]}, {"num": "2", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Read the following story. Then, work with a partner and orally complete Samina's report to the police, using the passive form. Use the verbs from the story. Write the complete report in your notebook. This is what Samina said to the police when they asked her for details: A new servant was hired (given in the book) by me. She ______ to submit a copy of her identity card.", "a": "She was asked to submit a copy of her identity card."}, {"q": "Complete Samina's report to the police, using the passive form. A copy ______ by her.", "a": "A copy was given by her."}, {"q": "Complete Samina's report to the police, using the passive form. I ______ someone else's card to me by her.", "a": "I was given someone else's card by her. (The book's wording, 'I was given someone else's card to me by her', is ungrammatical; see the flags file.)"}, {"q": "Complete Samina's report to the police, using the passive form. Unfortunately, the details ______ by me.", "a": "Unfortunately, the details were not checked by me."}, {"q": "Complete Samina's report to the police, using the passive form. After a few days, I ______ by the servant for a loan.", "a": "After a few days, I was asked by the servant for a loan."}, {"q": "Complete Samina's report to the police, using the passive form. The loan ______ by me.", "a": "The loan was refused by me."}, {"q": "Complete Samina's report to the police, using the passive form. The following week, I ______ told a sad story by the servant and again I ______ for some money.", "a": "The following week, I was told a sad story by the servant and again I was asked for some money."}, {"q": "Complete Samina's report to the police, using the passive form. The servant ______ not to come to work from the next day.", "a": "The servant was told not to come to work from the next day."}, {"q": "Complete Samina's report to the police, using the passive form. When I went to my room, after a couple of hours, it ______ in a mess, with all the things on the floor.", "a": "When I went to my room, after a couple of hours, it was found in a mess, with all the things on the floor."}, {"q": "Complete Samina's report to the police, using the passive form. The cupboard ______ by her.", "a": "The cupboard had been emptied by her."}, {"q": "Complete Samina's report to the police, using the passive form. All the money and the jewellery ______ by her.", "a": "All the money and the jewellery had been taken away by her."}]}]}], "words": [{"w": "active voice", "sd": "معروف", "syn": "the voice in which the subject does the action"}, {"w": "passive voice", "sd": "مجهول", "syn": "the voice in which the subject receives the action"}, {"w": "past participle", "sd": "اسم مفعول", "syn": "the third form of the verb, as in written or played"}]}, {"cls": "ix", "unit": 8, "title": "Narration", "display": "Narration", "reading": "Secondary Stage English Book One, Unit 5, Language Practice", "lesson": [{"t": "h", "x": "Narration"}, {"t": "p", "x": "Narration is the same as direct and indirect speech. Direct speech gives the exact words of the speaker. Indirect speech reports what the speaker said."}, {"t": "def", "x": "Narration is the art of reporting speech. Direct narration gives the exact words. Indirect narration reports the words in our own words."}, {"t": "h", "x": "Rule 1. Direct speech uses quotation marks"}, {"t": "rule", "x": "In direct speech, put the speaker's exact words inside quotation marks."}, {"t": "ex", "x": "\"I have many friends,\" said Sabiha. \"I have to invite all of them tomorrow,\" she said."}, {"t": "h", "x": "Rule 2. Indirect speech uses 'that' and no quotation marks"}, {"t": "rule", "x": "In indirect speech, use 'that' after the reporting verb and do not use quotation marks."}, {"t": "ex", "x": "Sabiha said that she had many friends and that she had to invite all of them the next day."}, {"t": "h", "x": "Rule 3. Change the tense back one step"}, {"t": "rule", "x": "When the reporting verb is in the past, change the tense back one step: present simple becomes past simple, present perfect becomes past perfect, will becomes would, can becomes could."}, {"t": "ex", "x": "Direct: \"I have many friends.\" Indirect: She said that she had many friends. Direct: \"I will come.\" Indirect: He said that he would come."}, {"t": "h", "x": "Rule 4. Change the words for time and place"}, {"t": "rule", "x": "Change today to that day, tomorrow to the next day, yesterday to the day before, here to there, this to that."}, {"t": "ex", "x": "Direct: \"I have to invite all of them tomorrow.\" Indirect: She said that she had to invite all of them the next day."}, {"t": "rl", "x": "At school, the teacher said, \"Open your books.\" I told my friend that the teacher had said to open our books."}, {"t": "rl", "x": "At home, my mother said, \"Wash your hands.\" I told my sister that mother had said to wash our hands."}, {"t": "rl", "x": "On the cricket ground, Ali said, \"I will bat first.\" Ahmed told us that Ali would bat first."}, {"t": "note", "x": "In indirect speech, change I to he or she, my to his or her, and we to they, to match the speaker."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Change from direct to indirect speech: 1. \"I have many friends and I have to invite all of them tomorrow,\" said Abid.", "a": "Abid said that he had many friends and he had to invite all of them the next day."}, {"q": "Change from direct to indirect speech: 2. Reshma said, \"I hope I will get admission in the medical college this year.\"", "a": "Reshma said that she hoped she would get admission in the medical college that year."}, {"q": "Change from direct to indirect speech: 3. \"I wish I had ten hands and a hundred fingers to do all this work,\" said Feroza.", "a": "Feroza wished she had ten hands and a hundred fingers to do all that work."}, {"q": "Change from direct to indirect speech: 4. The student said, \"I promise I will do my homework regularly from today.\"", "a": "The student promised that he would do his homework regularly from that day."}, {"q": "Change from direct to indirect speech: 5. \"They want to buy a new car,\" said the lawyer, \"but they don't have any money.\"", "a": "The lawyer said that they wanted to buy a new car but they did not have any money."}, {"q": "Change from direct to indirect speech: 6. \"We hope we will be able to get permission from our parents,\" said the children.", "a": "The children hoped that they would be able to get permission from their parents."}, {"q": "Change from direct to indirect speech: 7. \"I never thought that a son of mine would get such bad marks!\" said his father.", "a": "His father exclaimed with surprise that he had never thought that a son of his would get such bad marks."}, {"q": "Change from direct to indirect speech: 8. The blind boy said, \"I wish I could see this interesting match on the television.\"", "a": "The blind boy wished he could see that interesting match on the television."}, {"q": "Change from direct to indirect speech: 9. \"Next week, we promise, we will clean the whole house,\" the children said to their parents.", "a": "The children promised their parents that they would clean the whole house the next week."}, {"q": "Change from direct to indirect speech: 10. \"Our team has won the champion's trophy here for the first time!\" said the coach.", "a": "The coach exclaimed with joy that their team had won the champion's trophy there for the first time."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Work in pairs, read the story 'Avoiding Criticism' and put all the direct speech sentences into indirect speech. Direct speech 1: One of the bystanders said, \"This boy is so selfish. He is riding on a donkey while his poor old father is forced to walk alongside.\"", "a": "One of the bystanders said that that boy was so selfish, as he was riding on a donkey while his poor old father was forced to walk alongside."}, {"q": "Work in pairs, read the story 'Avoiding Criticism' and put all the direct speech sentences into indirect speech. Direct speech 2: \"This is so disrespectful,\" said another man. \"What a horrible and spoiled child!\"", "a": "Another man said that that was so disrespectful, and exclaimed what a horrible and spoiled child he was."}, {"q": "Work in pairs, read the story 'Avoiding Criticism' and put all the direct speech sentences into indirect speech. Direct speech 3: \"I hope I am doing the right thing now,\" he (Nasrudin) said to himself.", "a": "Nasrudin hoped he was doing the right thing then."}, {"q": "Work in pairs, read the story 'Avoiding Criticism' and put all the direct speech sentences into indirect speech. Direct speech 4: One of them exclaimed, \"The poor young boy has to walk while his selfish father is riding the donkey! He is a heartless parent!\"", "a": "One of them exclaimed with pity that the poor young boy had to walk while his selfish father was riding the donkey, and that he was a heartless parent."}, {"q": "Work in pairs, read the story 'Avoiding Criticism' and put all the direct speech sentences into indirect speech. Direct speech 5: \"I wish people would mind their own business,\" he (Nasrudin) said.", "a": "Nasrudin wished people would mind their own business."}, {"q": "Work in pairs, read the story 'Avoiding Criticism' and put all the direct speech sentences into indirect speech. Direct speech 6: \"That man and his son are so cruel,\" one bystander commented. \"They are forcing that poor donkey to bear the weight of two people. They should be put in jail for this act.\"", "a": "One bystander commented that that man and his son were so cruel, as they were forcing that poor donkey to bear the weight of two people, and that they should be put in jail for that act."}, {"q": "Work in pairs, read the story 'Avoiding Criticism' and put all the direct speech sentences into indirect speech. Direct speech 7: Nasrudin told his son, \"The only way we can avoid people's comments is that we both walk.\"", "a": "Nasrudin told his son that the only way they could avoid people's comments was that they both walked."}, {"q": "Work in pairs, read the story 'Avoiding Criticism' and put all the direct speech sentences into indirect speech. Direct speech 8: \"I suppose you are right,\" the son replied.", "a": "The son replied that he supposed he was right."}, {"q": "Work in pairs, read the story 'Avoiding Criticism' and put all the direct speech sentences into indirect speech. Direct speech 9: \"I promise, nobody will be able to say anything to us as we are doing the right thing this time,\" said Nasrudin happily.", "a": "Nasrudin promised happily that nobody would be able to say anything to them as they were doing the right thing that time."}, {"q": "Work in pairs, read the story 'Avoiding Criticism' and put all the direct speech sentences into indirect speech. Direct speech 10: \"These people are so stupid that both of them are walking in this heat and neither of them is riding the donkey,\" they said. \"What foolish people they are!\"", "a": "They said that those people were so stupid that both of them were walking in that heat and neither of them was riding the donkey, and exclaimed what foolish people they were."}]}]}], "words": [{"w": "narration", "sd": "بيان", "syn": "reporting speech, direct or indirect"}, {"w": "direct speech", "sd": "سڌو ڪلام", "syn": "the exact words of the speaker inside quotation marks"}, {"w": "indirect speech", "sd": "اڻ سڌو ڪلام", "syn": "reporting what the speaker said, without quotation marks"}]}, {"cls": "ix", "unit": 9, "title": "Synonyms", "display": "Synonyms", "reading": "Secondary Stage English Book One, Unit 6, Language Practice", "lesson": [{"t": "h", "x": "Synonyms"}, {"t": "p", "x": "A synonym is a word that has the same or nearly the same meaning as another word. We use synonyms to avoid repeating the same word."}, {"t": "def", "x": "A synonym is a word that means the same or nearly the same as another word."}, {"t": "h", "x": "Rule 1. Synonyms have the same meaning"}, {"t": "rule", "x": "Words with the same meaning are synonyms: happy — glad, big — large, small — little, fast — quick, rich — wealthy."}, {"t": "ex", "x": "happy — glad, big — large, small — little, fast — quick, rich — wealthy, brave — bold, beautiful — pretty."}, {"t": "h", "x": "Rule 2. Choose the synonym that fits the sentence"}, {"t": "rule", "x": "Choose the synonym that fits the sentence best. Not every synonym fits every sentence."}, {"t": "ex", "x": "This cup of tea tastes like tea flavoured water. (The best synonym for 'tastes like' is 'is like'.) He is a brave boy. (brave = bold)"}, {"t": "h", "x": "Rule 3. One word can have many synonyms"}, {"t": "rule", "x": "One word can have many synonyms. Use the one that fits the meaning best."}, {"t": "ex", "x": "happy — glad, joyful, cheerful, pleased. Big — large, huge, enormous. Small — little, tiny, minute."}, {"t": "rl", "x": "At school, my teacher is kind. She is also gentle and helpful. The lesson was easy and simple."}, {"t": "rl", "x": "At home, my mother is happy and glad. The food is tasty and delicious."}, {"t": "rl", "x": "On the cricket ground, Ali is fast and quick. The match was exciting and thrilling."}, {"t": "note", "x": "A synonym is not the same as an antonym. An antonym is a word with the opposite meaning: happy — sad, big — small."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Rewrite the sentence replacing the synonym given in bold with an appropriate synonym from the four given options: He is a brilliant carpenter. He has made a doll house with miniature furniture for every room. a) pretty b) tiny c) fresh d) tall", "a": "He is a brilliant carpenter. He has made a doll house with tiny furniture for every room. (b) tiny"}, {"q": "Rewrite the sentence replacing the synonym given in bold with an appropriate synonym from the four given options: Mrs Amjad gave the class a difficult assignment for chemistry. a) free b) easy c) caring d) hard", "a": "Mrs Amjad gave the class a hard assignment for chemistry. (d) hard"}, {"q": "Rewrite the sentence replacing the synonym given in bold with an appropriate synonym from the four given options: My grandmother is old. She is about 90 years old. a) elderly b) crazy c) charming d) friendly", "a": "My grandmother is elderly. She is about 90 years old. (a) elderly"}, {"q": "Rewrite the sentence replacing the synonym given in bold with an appropriate synonym from the four given options: Our principal is very smart and slim. a) tall b) thin c) charming d) strict", "a": "Our principal is very smart and thin. (b) thin"}, {"q": "Rewrite the sentence replacing the synonym given in bold with an appropriate synonym from the four given options: A stable government ensures that a nation will progress. a) friendly b) steady c) strong d) outgoing", "a": "A steady government ensures that a nation will progress. (b) steady"}, {"q": "Rewrite the sentence replacing the synonym given in bold with an appropriate synonym from the four given options: Farzana is always ready to help the people in her neighbourhood. a) teach b) guide c) assist d) train", "a": "Farzana is always ready to assist the people in her neighbourhood. (c) assist"}, {"q": "Rewrite the sentence replacing the synonym given in bold with an appropriate synonym from the four given options: I feel drowsy after having rice for lunch. a) lazy b) active c) happy d) sleepy", "a": "I feel sleepy after having rice for lunch. (d) sleepy"}, {"q": "Rewrite the sentence replacing the synonym given in bold with an appropriate synonym from the four given options: The house next door has been vacant for two years. a) dirty b) empty c) robbed d) painted", "a": "The house next door has been empty for two years. (b) empty"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Select the most appropriate synonym to complete the sentence: This cup of tea tastes like tea flavoured water. It is very ______ (weak, frail, fragile)", "a": "This cup of tea tastes like tea flavoured water. It is very weak."}, {"q": "Select the most appropriate synonym to complete the sentence: If one wants to succeed in the exams, it is ______ to study regularly. (primary, important, significant)", "a": "If one wants to succeed in the exams, it is important to study regularly."}, {"q": "Select the most appropriate synonym to complete the sentence: During the monsoon rains the water in the rivers becomes very ______ (disordered, violent, rough)", "a": "During the monsoon rains the water in the rivers becomes very violent."}, {"q": "Select the most appropriate synonym to complete the sentence: The ruins of Moen-jo-Daro are ______ (old, past, aged)", "a": "The ruins of Moen-jo-Daro are old."}, {"q": "Select the most appropriate synonym to complete the sentence: Pakistan is ______ in minerals. (rich, wealthy, affluent)", "a": "Pakistan is rich in minerals."}, {"q": "Select the most appropriate synonym to complete the sentence: My mother has to go to the NADRA office because her ID card is no longer ______ (valid, authorized, legitimate)", "a": "My mother has to go to the NADRA office because her ID card is no longer valid."}, {"q": "Select the most appropriate synonym to complete the sentence: The bangles her grandmother gave her are made of ______ gold (true, correct, real)", "a": "The bangles her grandmother gave her are made of real gold."}, {"q": "Select the most appropriate synonym to complete the sentence: The teacher asked the students to remain ______ as the class next door was doing a test. (still, quiet, noiseless)", "a": "The teacher asked the students to remain quiet as the class next door was doing a test."}, {"q": "Select the most appropriate synonym to complete the sentence: This perfume has a lovely ______ (odour, smell, fragrance)", "a": "This perfume has a lovely fragrance."}, {"q": "Select the most appropriate synonym to complete the sentence: The entire staff in the office was full of ______ for the new manager (appreciation, admiration, praise)", "a": "The entire staff in the office was full of admiration for the new manager."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Four words in the following set of five words are synonyms; one word is different. Circle the word that you think is different: friendly, agreeable, pleasant, decent, amicable", "a": "The odd word is 'decent'. The other four words (friendly, agreeable, pleasant, amicable) all mean kind and pleasant in manner, while 'decent' means good, proper or respectable."}, {"q": "Four words in the following set of five words are synonyms; one word is different. Circle the word that you think is different: option, nice, choice, possibility, alternative", "a": "The odd word is 'nice'. The other four words (option, choice, possibility, alternative) are all about choosing between things."}, {"q": "Four words in the following set of five words are synonyms; one word is different. Circle the word that you think is different: reasonable, rude, impolite, cheeky, disrespectful", "a": "The odd word is 'reasonable'. The other four words (rude, impolite, cheeky, disrespectful) all mean behaving badly towards others."}, {"q": "Four words in the following set of five words are synonyms; one word is different. Circle the word that you think is different: severe, serious, harsh, stable, stern", "a": "The odd word is 'stable'. The other four words (severe, serious, harsh, stern) all mean strict or hard."}, {"q": "Four words in the following set of five words are synonyms; one word is different. Circle the word that you think is different: huge, large, enormous, mammoth, many", "a": "The odd word is 'many'. The other four words (huge, large, enormous, mammoth) all mean very big in size, while 'many' is about a large number."}, {"q": "Four words in the following set of five words are synonyms; one word is different. Circle the word that you think is different: rubbish, garbage, garden, trash, refuse", "a": "The odd word is 'garden'. The other four words (rubbish, garbage, trash, refuse) all mean waste."}, {"q": "Four words in the following set of five words are synonyms; one word is different. Circle the word that you think is different: polite, intelligent, smart, clever, bright", "a": "The odd word is 'polite'. The other four words (intelligent, smart, clever, bright) all mean clever."}, {"q": "Four words in the following set of five words are synonyms; one word is different. Circle the word that you think is different: position, vacancy, opening, clean, post", "a": "The odd word is 'clean'. The other four words (position, vacancy, opening, post) all mean a job that is available."}, {"q": "Four words in the following set of five words are synonyms; one word is different. Circle the word that you think is different: mistake, correct, error, inaccuracy, slip", "a": "The odd word is 'correct'. The other four words (mistake, error, inaccuracy, slip) all mean a mistake."}, {"q": "Four words in the following set of five words are synonyms; one word is different. Circle the word that you think is different: disease, ailment, wound, illness, disorder", "a": "The odd word is 'wound'. The other four words (disease, ailment, illness, disorder) all mean a sickness, while a wound is a physical injury."}]}]}], "words": [{"w": "synonym", "sd": "هم معنيٰ لفظ", "syn": "a word that means the same or nearly the same as another word"}, {"w": "antonym", "sd": "ضد", "syn": "a word with the opposite meaning"}]}, {"cls": "ix", "unit": 10, "title": "Since and For", "display": "Since and For", "reading": "Secondary Stage English Book One, Unit 6, Language Practice", "lesson": [{"t": "h", "x": "Since and For"}, {"t": "p", "x": "We use 'since' and 'for' to talk about time. 'Since' is used with a point of time. 'For' is used with a period of time."}, {"t": "def", "x": "'Since' is used with a point of time (when something started). 'For' is used with a period of time (how long something has lasted)."}, {"t": "h", "x": "Rule 1. Use 'since' with a point of time"}, {"t": "rule", "x": "Use 'since' with a point of time: since 2020, since Monday, since morning, since I was a child, since last year."}, {"t": "ex", "x": "I have lived here since 2020. She has known him since Monday. We have waited since morning."}, {"t": "h", "x": "Rule 2. Use 'for' with a period of time"}, {"t": "rule", "x": "Use 'for' with a period of time: for five years, for two hours, for a week, for a long time, for three days."}, {"t": "ex", "x": "I have lived here for five years. She has waited for two hours. We have studied English for three years."}, {"t": "h", "x": "Rule 3. Use them with the present perfect tense"}, {"t": "rule", "x": "'Since' and 'for' are often used with the present perfect tense."}, {"t": "ex", "x": "He has worked here since 2019. He has worked here for six years. It has rained since morning. It has rained for two hours."}, {"t": "rl", "x": "At school, I have studied here since 2021. I have studied here for five years."}, {"t": "rl", "x": "At home, my mother has cooked since morning. She has cooked for two hours. My father has waited for me since noon."}, {"t": "rl", "x": "On the cricket ground, the boys have played since 4 o'clock. They have played for two hours."}, {"t": "note", "x": "Remember: since + when it started, for + how long it lasted."}], "sections": [{"num": "1", "name": "Practice", "exercises": [{"label": "Practice (made from the rules — no exercise in the book for this topic)", "items": [{"q": "Use the rules in this lesson to make three sentences of your own about your school day.", "a": "Answers will differ. Check your sentences against the rules above."}]}]}], "words": [{"w": "since", "sd": "کان وٺي", "syn": "from a point of time in the past"}, {"w": "for", "sd": "لاءِ", "syn": "for a period of time"}]}, {"cls": "ix", "unit": 11, "title": "Translation", "display": "Translation", "reading": "Secondary Stage English Book One, Unit 7, Language Practice", "lesson": [{"t": "h", "x": "Translation"}, {"t": "p", "x": "Translation means changing a sentence from one language into another language. In this lesson we translate English sentences into Urdu, and we learn the meaning of idioms and figurative language."}, {"t": "def", "x": "Translation is changing a sentence from one language into another language without changing its meaning."}, {"t": "h", "x": "Rule 1. Keep the meaning the same"}, {"t": "rule", "x": "In translation, keep the meaning of the sentence the same. Do not add or remove ideas."}, {"t": "ex", "x": "I will go to Murree in spring. (English) — I will go to Murree in the spring season. (meaning)"}, {"t": "h", "x": "Rule 2. Change the word order for Urdu"}, {"t": "rule", "x": "English word order is subject — verb — object. Urdu word order is subject — object — verb. Change the order when you translate into Urdu."}, {"t": "ex", "x": "English: I will go to Murree in spring. Urdu order: I, in spring, to Murree, will go. (Subject — object — verb.)"}, {"t": "h", "x": "Rule 3. Translate the tense correctly"}, {"t": "rule", "x": "Keep the tense the same in translation. A present sentence stays present. A past sentence stays past. A future sentence stays future."}, {"t": "ex", "x": "The train left the station at 7 o'clock. (past) I will go to Murree in spring. (future) She is reading a book. (present)"}, {"t": "h", "x": "Rule 4. Learn idioms and figurative language"}, {"t": "rule", "x": "Some sentences use idioms or figurative language. Translate the meaning, not the words one by one."}, {"t": "ex", "x": "She has a sweet tooth. (It means she likes sweet things.) The sun peaked happily from behind the clouds. (The sun came out happily.)"}, {"t": "rl", "x": "At school, the teacher says, 'Translate this sentence into Urdu.' I translate it word by word and then fix the word order."}, {"t": "rl", "x": "At home, my mother speaks Sindhi. I translate my English lesson for her so that she can understand it."}, {"t": "rl", "x": "In the market, the shopkeeper speaks Urdu. I translate what my father says into Urdu for him."}, {"t": "note", "x": "A good translation sounds natural in the other language. Do not translate word by word if it sounds wrong."}], "sections": [{"num": "1", "name": "Translation", "exercises": [{"label": "Translation", "items": [{"q": "I will go to Murree in spring.", "a": "آءٌ بهار جي موسم ۾ مري ويندس."}, {"q": "There is a spring of hot water at Manghopir, in Karachi.", "a": "ڪراچي ۾ منگهوپير وٽ گرم پاڻي جو چشمو آهي."}, {"q": "Since a spring is broken, this clock is not working.", "a": "جيئن ته اسپرنگ ٽٽي وئي آهي، هي گهڙي ڪم نه پئي ڪري."}, {"q": "With a spring, the runner crossed the winning line.", "a": "هڪ ڇلانگ هڻي، ڊوڙندڙ فتح واري ليڪ پار ڪري ويو."}]}]}, {"num": "2", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "1. The train left the station at 7 o'clock.", "a": "ٽرين ست وڳي اسٽيشن تان رواني ٿي وئي."}, {"q": "2. I can train you to become a good cricketer.", "a": "آءٌ توکي سٺو ڪرڪيٽر بڻجڻ جي تربيت ڏئي سگهان ٿو."}, {"q": "3. There is plenty of light in this room.", "a": "هن ڪمري ۾ گهڻي روشني آهي."}, {"q": "4. Please, light all the candles on the cake.", "a": "مهرباني ڪري ڪيڪ تي سڀئي ميڻ بتيون ٻاريو."}, {"q": "5. Jamal offered to book our seats on the bus.", "a": "جمال بس ۾ اسان جون سيٽون بُڪ ڪرڻ جي آڇ ڪئي."}, {"q": "6. Have you seen my new book?", "a": "ڇا تو منهنجو نئون ڪتاب ڏٺو آهي؟"}, {"q": "7. The principal asked the students to state their reasons for being late.", "a": "پرنسپال شاگردن کي دير سان اچڻ جا سبب ٻڌائڻ لاءِ چيو."}, {"q": "8. The state should ensure that all people follow the rules.", "a": "رياست کي يقيني بڻائڻ گهرجي ته سڀئي ماڻهو قاعدن تي عمل ڪن."}, {"q": "9. This is exactly my point that we should leave early.", "a": "منهنجو مطلب بلڪل اهو ئي آهي ته اسان کي جلدي نڪرڻ گهرجي."}, {"q": "10. Don't point at people when you are speaking about them.", "a": "جڏهن توهان ڪنهن بابت ڳالهائي رهيا آهيو ته انهن ڏانهن آڱر نه ڪريو."}, {"q": "11. My brother got the first rank in his final tests.", "a": "منهنجي ڀاءُ پنهنجي آخري امتحانن ۾ پهرين پوزيشن حاصل ڪئي."}, {"q": "12. The rank of a soldier depends on many factors.", "a": "هڪ سپاهي جو عهدو ڪيترن ئي ڳالهين تي منحصر آهي."}]}]}, {"num": "3", "name": "Translation (figurative language)", "exercises": [{"label": "Translation (figurative language)", "items": [{"q": "a) She has a sweet tooth.", "a": "Literal translation: هن جا ڏند مٺا آهن. Real meaning: هن کي مٺيون شيون کائڻ جو ڏاڍو شوق آهي. (She loves sweet things.)"}, {"q": "b) This news is music to my ears.", "a": "Literal translation: هي خبر منهنجي ڪنن لاءِ موسيقي آهي. Real meaning: هي خبر ٻڌي مون کي ڏاڍي خوشي ٿي آهي. (I am very pleased to hear this news.)"}]}]}, {"num": "4", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "1. The sun peaked happily from behind the clouds.", "a": "سج خوشيءَ سان ڪڪرن جي پٺيان نمودار ٿيو."}, {"q": "2. The trees danced back and forth in the wind.", "a": "وڻ هوا ۾ اڳتي پوئتي جهومي رهيا هئا."}, {"q": "3. It was time to go home but the bell refused to ring.", "a": "گهر وڃڻ جو وقت ٿي ويو هو، پر گهنٽي وڄڻ جو نالو ئي نه پئي ورتو."}, {"q": "4. The angry sky roared and threw lightening around.", "a": "ڪاوڙيل آسمان گڙگڙيو ۽ هر طرف بجلي ڪڙڪي."}, {"q": "5. The delicious smell of pudding pulled me to the kitchen.", "a": "پڊنگ جي لذيذ خوشبو مون کي باورچي خاني ڏانهن ڇڪي وئي."}, {"q": "6. I can see that news travels quickly.", "a": "مون کي خبر آهي ته خبرون تيزيءَ سان پکڙجن ٿيون."}, {"q": "7. I wish you weren't always such a chicken.", "a": "ڪاش تون هميشه ايترو بزدل نه هجين."}, {"q": "8. The kids at that school are all brains.", "a": "ان اسڪول جا ٻار سڀ ڏاڍا ذهين آهن."}, {"q": "9. You are my guardian angel.", "a": "تون منهنجو محافظ فرشتو آهين."}, {"q": "10. I've been on cloud nine all day.", "a": "آءٌ سڄو ڏينهن ڏاڍو خوش آهيان."}]}]}], "words": [{"w": "translation", "sd": "ترجمو", "syn": "changing a sentence from one language into another"}, {"w": "idiom", "sd": "اصطلاح", "syn": "a phrase with a meaning different from its words"}, {"w": "figurative language", "sd": "مجازي ٻولي", "syn": "language that uses words in a special, non-literal way"}]}, {"cls": "ix", "unit": 12, "title": "Degrees of Adverbs", "display": "Degrees of Adverbs", "reading": "Secondary Stage English Book One, Unit 8, Language Practice", "lesson": [{"t": "h", "x": "Degrees of Adverbs"}, {"t": "p", "x": "Adverbs also have three degrees: positive, comparative and superlative. We use them to compare how an action happens."}, {"t": "def", "x": "The positive degree is the simple form of the adverb. The comparative degree compares two actions. The superlative degree compares one action with all the others."}, {"t": "h", "x": "Rule 1. The positive degree is the simple form"}, {"t": "rule", "x": "The positive degree is the adverb itself: quickly, slowly, angrily, happily, carefully."}, {"t": "ex", "x": "He walks quickly. She speaks slowly. They work happily."}, {"t": "h", "x": "Rule 2. Add 'er' or use 'more' for the comparative"}, {"t": "rule", "x": "For short adverbs, add 'er'. For long adverbs, use 'more'."}, {"t": "ex", "x": "fast — faster, soon — sooner, hard — harder, quickly — more quickly, carefully — more carefully, angrily — more angrily."}, {"t": "h", "x": "Rule 3. Add 'est' or use 'most' for the superlative"}, {"t": "rule", "x": "For short adverbs, add 'est'. For long adverbs, use 'most'."}, {"t": "ex", "x": "fast — fastest, soon — soonest, hard — hardest, quickly — most quickly, carefully — most carefully, angrily — most angrily."}, {"t": "h", "x": "Rule 4. Some adverbs change in a special way"}, {"t": "rule", "x": "Some adverbs do not take 'er' and 'est': well — better — best, badly — worse — worst, much — more — most, little — less — least."}, {"t": "ex", "x": "well — better — best, badly — worse — worst, much — more — most, far — farther — farthest."}, {"t": "rl", "x": "At school, Ali runs fast. Ahmed runs faster than Ali. Bilal runs the fastest of all."}, {"t": "rl", "x": "At home, my mother cooks well. My aunt cooks better than my mother. My grandmother cooks the best."}, {"t": "rl", "x": "On the cricket ground, Ali bats well. Ahmed bats better than Ali. The captain bats the best."}, {"t": "note", "x": "Use 'than' after the comparative and 'the' before the superlative."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "1. Positive: angrily — Comparative: ? Superlative: ?", "a": "more angrily — most angrily"}, {"q": "2. Superlative: most bravely — Positive: ? Comparative: ?", "a": "bravely — more bravely"}, {"q": "3. Positive: carefully — Comparative: ? Superlative: ?", "a": "more carefully — most carefully"}, {"q": "4. Comparative: more comfortably — Positive: ? Superlative: ?", "a": "comfortably — most comfortably"}, {"q": "5. Comparative: earlier — Positive: ? Superlative: ?", "a": "early — earliest"}, {"q": "6. Superlative: most easily — Positive: ? Comparative: ?", "a": "easily — more easily"}, {"q": "7. Positive: loudly — Comparative: ? Superlative: ?", "a": "more loudly (louder) — most loudly (loudest)"}, {"q": "8. Superlative: fastest — Positive: ? Comparative: ?", "a": "fast — faster"}, {"q": "9. Comparative: more gently — Positive: ? Superlative: ?", "a": "gently — most gently"}, {"q": "10. Superlative: most happily — Positive: ? Comparative: ?", "a": "happily — more happily"}, {"q": "11. Positive: hard — Comparative: ? Superlative: ?", "a": "harder — hardest"}, {"q": "12. Superlative: most probably — Positive: ? Comparative: ?", "a": "probably — more probably"}, {"q": "13. Comparative: longer — Positive: ? Superlative: ?", "a": "long — longest"}, {"q": "14. Superlative: farthest — Positive: ? Comparative: ?", "a": "far — farther (further)"}, {"q": "15. Comparative: more noisily — Positive: ? Superlative: ?", "a": "noisily — most noisily"}, {"q": "16. Positive: high — Comparative: ? Superlative: ?", "a": "higher — highest"}, {"q": "17. Positive: quickly — Comparative: ? Superlative: ?", "a": "more quickly — most quickly (quickest)"}, {"q": "18. Comparative: more skilfully — Positive: ? Superlative: ?", "a": "skilfully — most skilfully"}, {"q": "19. Superlative: most truthfully — Positive: ? Comparative: ?", "a": "truthfully — more truthfully"}, {"q": "20. Comparative: better — Positive: ? Superlative: ?", "a": "well — best"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "1. My uncle went the ____________ from his home during the recent floods.", "a": "My uncle went the farthest from his home during the recent floods."}, {"q": "2. Let's see who runs the ____________ in the race.", "a": "Let's see who runs the fastest in the race."}, {"q": "3. The workers protested ____________ at getting low salaries, as compared to long working hours and shorter breaks.", "a": "The workers protested more angrily at getting low salaries, as compared to long working hours and shorter breaks."}, {"q": "4. The Bolan Express is the ____________ train you can take, the rest leave after 10 o'clock.", "a": "The Bolan Express is the earliest train you can take, the rest leave after 10 o'clock."}, {"q": "5. The drivers from Germany drove their cars ____________ than those from Japan.", "a": "The drivers from Germany drove their cars more carefully than those from Japan."}, {"q": "6. Salim climbed ____________ than Fazal but Hanif climbed the ____________.", "a": "Salim climbed higher than Fazal but Hanif climbed the highest."}, {"q": "7. As compared to the soldiers in the first and middle rows, the soldiers in the last row fought the enemy ____________.", "a": "As compared to the soldiers in the first and middle rows, the soldiers in the last row fought the enemy most bravely."}, {"q": "8. Saima answered ____________ than her friends.", "a": "Saima answered better than her friends."}, {"q": "9. Newborn babies should be handled ____________ than all other age groups.", "a": "Newborn babies should be handled more gently than all other age groups."}, {"q": "10. My father was sitting ____________ in his chair and enjoying the talk show on TV.", "a": "My father was sitting comfortably in his chair and enjoying the talk show on TV."}]}]}, {"num": "3", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "A.1. We needed space to do our project work so we moved all the ____________ furniture to one side.", "a": "We needed space to do our project work so we moved all the movable furniture to one side."}, {"q": "A.2. When travelling, we should try and take easily ____________ clothes with us.", "a": "When travelling, we should try and take easily washable clothes with us."}, {"q": "A.3. This is a very ____________ chair.", "a": "This is a very comfortable chair."}, {"q": "A.4. Non-payment of taxes is a ____________ crime.", "a": "Non-payment of taxes is a punishable crime."}, {"q": "A.5. We can recover from ____________ diseases quickly if we go to the doctor.", "a": "We can recover from curable diseases quickly if we go to the doctor."}, {"q": "B.1. This food is ____________ as compared to the food we had yesterday.", "a": "This food is tasteless as compared to the food we had yesterday."}, {"q": "B.2. I asked my mother to buy ____________ chicken for the new dish that I wanted to try.", "a": "I asked my mother to buy boneless chicken for the new dish that I wanted to try."}, {"q": "B.3. This fellow is ____________ as far as work is concerned.", "a": "This fellow is useless as far as work is concerned."}, {"q": "B.4. Finally, I have found work after being ____________ for six months.", "a": "Finally, I have found work after being jobless for six months."}, {"q": "B.5. Many ____________ people sleep on the footpaths.", "a": "Many homeless people sleep on the footpaths."}]}]}], "words": [{"w": "adverb", "sd": "ظرف", "syn": "a word that tells us more about a verb"}, {"w": "positive degree", "sd": "سادو درجو", "syn": "the simple form of an adverb"}, {"w": "comparative degree", "sd": "تقابلي درجو", "syn": "the form used to compare two actions"}, {"w": "superlative degree", "sd": "اعليٰ درجو", "syn": "the form used to compare one action with all the others"}]}, {"cls": "x", "unit": 1, "title": "Punctuation", "display": "Punctuation", "reading": "Secondary Stage English Book Two, Unit 1, Language Practice", "lesson": [{"t": "h", "x": "Punctuation"}, {"t": "p", "x": "Punctuation marks show us where a sentence begins and ends, and where to pause. The main marks are the full stop, comma, question mark, exclamation mark, apostrophe and quotation marks."}, {"t": "def", "x": "Punctuation is the use of marks like the full stop, comma, question mark, exclamation mark, apostrophe and quotation marks to organise writing."}, {"t": "h", "x": "Rule 1. Begin a sentence with a capital letter"}, {"t": "rule", "x": "Every sentence begins with a capital letter. Proper nouns also begin with a capital letter."}, {"t": "ex", "x": "The mausoleum of Shah Abdul Lateef Bhitai is in Bhitshah. Ali is a good boy. Karachi is a big city."}, {"t": "h", "x": "Rule 2. Use a full stop at the end of a statement"}, {"t": "rule", "x": "Use a full stop (.) at the end of a statement."}, {"t": "ex", "x": "The helping group needs clothes, food, water, blankets and medicines. Ali is a good boy."}, {"t": "h", "x": "Rule 3. Use a comma to separate things in a list"}, {"t": "rule", "x": "Use commas to separate words in a list, and to separate the name of the person spoken to."}, {"t": "ex", "x": "The helping group needs clothes, food, water, blankets and medicines. Come here, Ali."}, {"t": "h", "x": "Rule 4. Use a question mark for a question and an exclamation mark for a strong feeling"}, {"t": "rule", "x": "Use a question mark (?) at the end of a question and an exclamation mark (!) for a strong feeling or order."}, {"t": "ex", "x": "Where are you going? What a beautiful day! Hurry up!"}, {"t": "h", "x": "Rule 5. Use an apostrophe for possession and contractions"}, {"t": "rule", "x": "Use an apostrophe (') to show possession (Ali's book) and in contractions (isn't, don't, can't)."}, {"t": "ex", "x": "This book isn't mine, said Abdul Karim. I don't know who put it here. Ali's book is new."}, {"t": "h", "x": "Rule 6. Use quotation marks for direct speech"}, {"t": "rule", "x": "Put quotation marks (\" \") around the exact words that somebody says."}, {"t": "ex", "x": "\"This book isn't mine,\" said Abdul Karim. \"Where are you going?\" asked mother."}, {"t": "rl", "x": "At school, I write: 'My school is a good school.' My teacher says, \"Open your books.\""}, {"t": "rl", "x": "At home, my mother says, \"Wash your hands!\" I write a list: mangoes, apples and bananas."}, {"t": "rl", "x": "In the market, the shopkeeper says, \"Come here!\" I ask, \"How much is this?\""}, {"t": "note", "x": "A comma is also used before the reporting verb in direct speech: '\"Come here,\" said Ali.'"}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Rewrite the sentence correcting the errors of capitalization: the mausoleum of shah abdul lateef bhitai is in sindh.", "a": "The mausoleum of Shah Abdul Lateef Bhitai is in Sindh."}, {"q": "Rewrite the sentence correcting the errors of capitalization: sameer and ali went to quetta last july.", "a": "Sameer and Ali went to Quetta last July."}, {"q": "Rewrite the sentence correcting the errors of capitalization: the river indus flows from gilgit baltistan to the arabian sea.", "a": "The river Indus flows from Gilgit Baltistan to the Arabian Sea."}, {"q": "Rewrite the sentence correcting the errors of capitalization: the liaquat national hospital is on the stadium road in karachi.", "a": "The Liaquat National Hospital is on the Stadium Road in Karachi."}, {"q": "Rewrite the sentence correcting the errors of capitalization: \"are zahra and samina coming today?\" asked mrs afzal.", "a": "\"Are Zahra and Samina coming today?\" asked Mrs Afzal."}, {"q": "Rewrite the sentence correcting the errors of capitalization: the highest peak, mount Everest, is in the Himalayan ranges, in nepal.", "a": "The highest peak, Mount Everest, is in the Himalayan ranges, in Nepal."}, {"q": "Rewrite the sentence correcting the errors of capitalization: we are planning to go to islamabad in march to see the faisal mosque.", "a": "We are planning to go to Islamabad in March to see the Faisal Mosque."}, {"q": "Rewrite the sentence correcting the errors of capitalization: he said, \"my uncle's name is asif shaikh and he lives in london.\"", "a": "He said, \"My uncle's name is Asif Shaikh and he lives in London.\""}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Insert commas, full stops, question marks and exclamation marks: The helping group needs clothes food water blankets and shoes for the flood victims", "a": "The helping group needs clothes, food, water, blankets and shoes for the flood victims."}, {"q": "Insert commas, full stops, question marks and exclamation marks: Hurrah Pakistan has won the world cup We must meet celebrate enjoy and have fun", "a": "Hurrah! Pakistan has won the World Cup. We must meet, celebrate, enjoy and have fun."}, {"q": "Insert commas, full stops, question marks and exclamation marks: Nevertheless some people are talking some are resting some are reading and some are having fun", "a": "Nevertheless, some people are talking, some are resting, some are reading and some are having fun."}, {"q": "Insert commas, full stops, question marks and exclamation marks: \"Have you finished your homework\" his mother asked", "a": "\"Have you finished your homework?\" his mother asked."}, {"q": "Insert commas, full stops, question marks and exclamation marks: Alas the old man is dead He suffered a lot", "a": "Alas! The old man is dead. He suffered a lot."}, {"q": "Insert commas, full stops, question marks and exclamation marks: The teacher said \"Where is your bag\" \"I don't know\" said Sabah \"I just kept it here\"", "a": "The teacher said, \"Where is your bag?\" \"I don't know,\" said Sabah. \"I just kept it here.\""}, {"q": "Insert commas, full stops, question marks and exclamation marks: Moreover I have seen his picture in magazines on television and in movies", "a": "Moreover, I have seen his picture in magazines, on television and in movies."}, {"q": "Insert commas, full stops, question marks and exclamation marks: Chuck chuck chuck The train began moving out of the station therefore the people started running", "a": "Chuck, chuck, chuck! The train began moving out of the station. Therefore, the people started running."}, {"q": "Insert commas, full stops, question marks and exclamation marks: Wow This is a pleasant surprise Why didn't you tell me you were coming", "a": "Wow! This is a pleasant surprise. Why didn't you tell me you were coming?"}, {"q": "Insert commas, full stops, question marks and exclamation marks: \"Your book has been lying on this table for ten days\" said mr jawad \"when will you read it\"", "a": "\"Your book has been lying on this table for ten days,\" said Mr Jawad. \"When will you read it?\""}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Insert apostrophes and quotation marks: This book isn't mine, said Abdul Karim. I dont know who put it here.", "a": "\"This book isn't mine,\" said Abdul Karim. \"I don't know who put it here.\""}, {"q": "Insert apostrophes and quotation marks: Can we go to the seaside, father? the children asked. Its such a lovely day.", "a": "\"Can we go to the seaside, father?\" the children asked. \"It's such a lovely day.\""}, {"q": "Insert apostrophes and quotation marks: The girls father said, Ill take you to school today. Its still early and well reach in time.", "a": "The girl's father said, \"I'll take you to school today. It's still early and we'll reach in time.\""}, {"q": "Insert apostrophes and quotation marks: Mother said, Wholl help me clean the house? I cant said Laila Ive got to write an essay.", "a": "Mother said, \"Who'll help me clean the house?\" \"I can't,\" said Laila. \"I've got to write an essay.\""}, {"q": "Insert apostrophes and quotation marks: Ive seen this movie before. Whats its name? said Fakhir. I don't know, replied Asad.", "a": "\"I've seen this movie before. What's its name?\" said Fakhar. \"I don't know,\" replied Asad."}, {"q": "Insert apostrophes and quotation marks: Sabiha, said Rana, arent we going to Hyderabad today? No, said Sabiha, im not feeling well.", "a": "\"Sabiha,\" said Rana, \"aren't we going to Hyderabad today?\" \"No,\" said Sabiha, \"I'm not feeling well.\""}, {"q": "Insert apostrophes and quotation marks: This is Najmas house, said Nabila. Ive been here before. However, the gates colour has been changed.", "a": "\"This is Najma's house,\" said Nabila. \"I've been here before. However, the gate's colour has been changed.\""}, {"q": "Insert apostrophes and quotation marks: Hurry up, lets go, children, said grandfather. Put on your shoes. Were already late. I don't want to miss the bus.", "a": "\"Hurry up, let's go, children,\" said grandfather. \"Put on your shoes. We're already late. I don't want us to miss the bus.\""}]}]}], "words": [{"w": "punctuation", "sd": "اوقاف", "syn": "marks like the full stop and comma that organise writing"}, {"w": "capital letter", "sd": "وڏو اکر", "syn": "a big letter like A, B, C"}, {"w": "quotation marks", "sd": "واوين", "syn": "the marks \" \" used around spoken words"}, {"w": "full stop", "sd": "سھڻو", "syn": "the mark . at the end of a sentence"}, {"w": "apostrophe", "sd": "اعراب", "syn": "the sign ' used in writing"}]}, {"cls": "x", "unit": 2, "title": "Prefixes and Suffixes", "display": "Prefixes and Suffixes", "reading": "Secondary Stage English Book Two, Unit 1, Language Practice", "lesson": [{"t": "h", "x": "Prefixes and Suffixes"}, {"t": "p", "x": "A prefix is a group of letters added at the beginning of a word. A suffix is a group of letters added at the end of a word. They change the meaning of the word."}, {"t": "def", "x": "A prefix is added at the beginning of a word. A suffix is added at the end of a word. Both change the meaning of the word."}, {"t": "h", "x": "Rule 1. Common prefixes: un, in, im, dis, mis, re, pre"}, {"t": "rule", "x": "Add a prefix to change the meaning: un + happy = unhappy, in + correct = incorrect, dis + honest = dishonest, mis + understand = misunderstand, re + write = rewrite, pre + paid = prepaid."}, {"t": "ex", "x": "unhappy, incorrect, impossible, dishonest, impolite, unusual, illegal, irrelevant, misunderstand, rewrite, prepaid."}, {"t": "h", "x": "Rule 2. Common suffixes: ness, ment, tion, able, ful, less, ly"}, {"t": "rule", "x": "Add a suffix to change the word: kind + ness = kindness, employ + ment = employment, act + tion = action, comfort + able = comfortable, care + ful = careful, care + less = careless, quick + ly = quickly."}, {"t": "ex", "x": "kindness, employment, action, comfortable, careful, careless, quickly, happiness."}, {"t": "h", "x": "Rule 3. A prefix and a suffix can be added together"}, {"t": "rule", "x": "We can add a prefix and a suffix to the same root word: pay — repay — repayment, happy — unhappy — unhappiness."}, {"t": "ex", "x": "pay — repay — repayment, happy — unhappy — unhappiness, kind — unkind — unkindness."}, {"t": "h", "x": "Rule 4. The spelling may change"}, {"t": "rule", "x": "When we add a suffix, the spelling of the root word may change: easy — uneasy, happy — happiness, pay — payment."}, {"t": "ex", "x": "easy — uneasy, happy — happiness, pay — payment, employ — employment."}, {"t": "rl", "x": "At school, my father was feeling uneasy due to severe pain. The teacher's kindness makes us happy."}, {"t": "rl", "x": "At home, my mother pays the bill. The payment is made every month. My father's employment is in Karachi."}, {"t": "rl", "x": "In the market, the shopkeeper is dishonest. The prices are unusual today. The mangoes are comfortable to carry."}, {"t": "note", "x": "A prefix changes the meaning at the beginning; a suffix changes the word at the end."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "(Prefixes, row 1): Form words by adding prefixes to: pay, honest, polite, usual, legal, relevant.", "a": "pay - prepay; honest - dishonest (given in the book); polite - impolite; usual - unusual; legal - illegal (given in the book); relevant - irrelevant."}, {"q": "(Prefixes, row 2): Form words by adding prefixes to: order, certain, understand, selfish, appear, official.", "a": "order - disorder; certain - uncertain; understand - misunderstand; selfish - unselfish; appear - disappear; official - unofficial."}, {"q": "(Prefixes, row 3): Form words by adding prefixes to: obey, normal, successful, literate, pleasant, sense.", "a": "obey - disobey; normal - abnormal; successful - unsuccessful; literate - illiterate; pleasant - unpleasant; sense - nonsense."}, {"q": "(Prefixes, row 4): Form words by adding prefixes to: formal, logical, conscious, mortal, bearable, agree.", "a": "formal - informal; logical - illogical; conscious - unconscious; mortal - immortal; bearable - unbearable; agree - disagree."}, {"q": "(Prefixes, row 5): Form words by adding prefixes to: use, regular, possible, easy, fortunately, happy.", "a": "use - misuse; regular - irregular; possible - impossible; easy - uneasy; fortunately - unfortunately; happy - unhappy."}, {"q": "(Suffixes, row 1): Form words by adding suffixes to: child, help, reflect, strength, kind, employ.", "a": "child - childish (given in the book); help - helpful; reflect - reflection; strength - strengthen; kind - kindness; employ - employment."}, {"q": "(Suffixes, row 2): Form words by adding suffixes to: power, accident, salt, response, survive, reject.", "a": "power - powerful; accident - accidental; salt - saltish; response - responsive; survive - survival (given in the book); reject - rejection."}, {"q": "(Suffixes, row 3): Form words by adding suffixes to: pollute, achieve, product, excite, shame, inform.", "a": "pollute - pollution; achieve - achievement; product - production; excite - excitement; shame - shameful; inform - information."}, {"q": "(Suffixes, row 4): Form words by adding suffixes to: suggest, enjoy, equip, agree, comfort, improve.", "a": "suggest - suggestion; enjoy - enjoyment; equip - equipment; agree - agreement; comfort - comfortable; improve - improvement."}, {"q": "(Suffixes, row 5): Form words by adding suffixes to: mother, attract, amuse, relate, sad, cheer.", "a": "mother - motherhood; attract - attractive; amuse - amusement; relate - relation; sad - sadness; cheer - cheerful."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Fill in the blank with a prefix or suffix: My father was feeling ______ due to severe pain. (easy)", "a": "My father was feeling uneasy due to severe pain."}, {"q": "Fill in the blank with a prefix or suffix: His seat on the train was very ______. (comfort)", "a": "His seat on the train was very uncomfortable."}, {"q": "Fill in the blank with a prefix or suffix: Mr. Moeen is very ______ and is often absent from his office. (regular)", "a": "Mr. Moeen is very irregular and is often absent from his office."}, {"q": "Fill in the blank with a prefix or suffix: His ______ behaviour bothered everyone. (child)", "a": "His childish behaviour bothered everyone."}, {"q": "Fill in the blank with a prefix or suffix: There is a lot of ______ in our country. (pollute)", "a": "There is a lot of pollution in our country."}, {"q": "Fill in the blank with a prefix or suffix: We must show ______ to everyone, especially the old and the weak. (kind)", "a": "We must show kindness to everyone, especially the old and the weak."}, {"q": "Fill in the blank with a prefix or suffix: All survived in the horrible accident, but ______ the driver was killed. (fortunately)", "a": "All survived in the horrible accident, but unfortunately the driver was killed."}, {"q": "Fill in the blank with a prefix or suffix: ______ of the sunlight in the mirror disturbed me when I was driving. (reflect)", "a": "Reflection of the sunlight in the mirror disturbed me when I was driving."}, {"q": "Fill in the blank with a prefix or suffix: ______ from the national hockey team was ______ for me. (reject, bearable)", "a": "Rejection from the national hockey team was unbearable for me."}, {"q": "Fill in the blank with a prefix or suffix: The ______ given by the team member was ______. (inform, official)", "a": "The information given by the team member was unofficial."}]}]}, {"num": "3", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "Add a prefix and a suffix to the root word 'pay' and write a sentence using each word.", "a": "Prefix + root: prepay - I had to prepay to get my mobile credit. Root word: pay - They receive their pay on the last day of the month. Root + suffix: payment - My father has made the payment for his motorbike. (example given in the book)"}, {"q": "Add a prefix and a suffix to the root word 'happy' and write a sentence using each word.", "a": "Prefix + root: unhappy - I am unhappy about my result. Root word: happy - I am happy today. Root + suffix: happiness - Happiness is the best gift of life."}, {"q": "Add a prefix and a suffix to the root word 'agree' and write a sentence using each word.", "a": "Prefix + root: disagree - I disagree with you. Root word: agree - I agree with your plan. Root + suffix: agreement - We have reached an agreement."}, {"q": "Add a prefix and a suffix to the root word 'order' and write a sentence using each word.", "a": "Prefix + root: disorder - There was disorder in the class. Root word: order - Please put your books in order. Root + suffix: orderly - He is an orderly boy."}, {"q": "Add a prefix and a suffix to the root word 'use' and write a sentence using each word.", "a": "Prefix + root: misuse - Do not misuse your mobile phone. Root word: use - We use water for drinking. Root + suffix: useful - This book is very useful."}]}]}], "words": [{"w": "prefix", "sd": "اڳياڙي", "syn": "letters added at the beginning of a word"}, {"w": "suffix", "sd": "پڇاڙي", "syn": "letters added at the end of a word"}, {"w": "root word", "sd": "اصل لفظ", "syn": "the word to which a prefix or suffix is added"}]}, {"cls": "x", "unit": 3, "title": "Present Tenses", "display": "Present Tenses", "reading": "Secondary Stage English Book Two, Unit 2, Language Practice", "lesson": [{"t": "h", "x": "Present Tenses"}, {"t": "p", "x": "There are four present tenses: present simple, present continuous, present perfect and present perfect continuous. Each one is used for a different kind of present action."}, {"t": "def", "x": "The present simple is for habits and facts. The present continuous is for an action happening now. The present perfect is for an action that has just finished. The present perfect continuous is for an action that started in the past and is still going on."}, {"t": "h", "x": "Rule 1. Present simple: verb, or verb + s/es"}, {"t": "rule", "x": "Use the present simple for habits, routines and facts. With he, she and it, add 's' or 'es' to the verb."}, {"t": "ex", "x": "I play cricket. He plays cricket. She reads a book. The sun rises in the east. The train leaves in half an hour."}, {"t": "h", "x": "Rule 2. Present continuous: is/am/are + verb + ing"}, {"t": "rule", "x": "Use the present continuous for an action happening now, or for a plan that is fixed."}, {"t": "ex", "x": "I am writing a letter. She is singing a song. It is raining now. We are taking a trip to Tharparkar next Sunday."}, {"t": "h", "x": "Rule 3. Present perfect: has/have + past participle"}, {"t": "rule", "x": "Use the present perfect for an action that has just finished, or for an action that started in the past and is still true."}, {"t": "ex", "x": "I have eaten my lunch. She has read the book. They have gone to school. We have lived here for five years."}, {"t": "h", "x": "Rule 4. Present perfect continuous: has/have been + verb + ing"}, {"t": "rule", "x": "Use the present perfect continuous for an action that started in the past and is still going on."}, {"t": "ex", "x": "I have been watching TV for two hours. It has been raining since morning. She has been cooking since 10 o'clock."}, {"t": "rl", "x": "At school, I play cricket every day. (present simple) I am playing cricket now. (present continuous)"}, {"t": "rl", "x": "At home, my mother has cooked the food. (present perfect) She has been cooking since morning. (present perfect continuous)"}, {"t": "rl", "x": "In the market, the shopkeeper sells fruit every day. He is selling fruit now. He has sold many mangoes today."}, {"t": "note", "x": "Do not use the present perfect with a finished past time like 'yesterday': say 'I lost my pen yesterday', not 'I have lost my pen yesterday'."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Use the correct form of the Present Simple. Use one word only once (build, remember, play, dress, forget, listen, study, get). Birds usually ______ their nests in the summer.", "a": "Birds usually build their nests in the summer."}, {"q": "Use the correct form of the Present Simple. I always ______ carefully to parents' advice.", "a": "I always listen carefully to parents' advice."}, {"q": "Use the correct form of the Present Simple. He ______ up late and ______ quickly for school.", "a": "He gets up late and dresses quickly for school."}, {"q": "Use the correct form of the Present Simple. We ______ in the afternoon and ______ in the evening.", "a": "We play in the afternoon and study in the evening."}, {"q": "Use the correct form of the Present Simple. My friend ______ name but ______ numbers.", "a": "My friend remembers name but forgets numbers."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Use the correct form of the Present Continuous. Use one word only once (write, sing, rain, make, explain, swim, enjoy, learn). Look! It ______ so hard.", "a": "Look! It is raining so hard."}, {"q": "Use the correct form of the Present Continuous. We ______ English these days.", "a": "We are learning English these days."}, {"q": "Use the correct form of the Present Continuous. The birds ______ and the farmers ______ their songs.", "a": "The birds are singing and the farmers are enjoying their songs."}, {"q": "Use the correct form of the Present Continuous. The teacher ______ and the students ______.", "a": "The teacher is explaining and the students are writing."}, {"q": "Use the correct form of the Present Continuous. Some children ______ in the pond and some ______ clay toys.", "a": "Some children are swimming in the pond and some are making clay toys."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Use the correct form of the Present Simple and Present Continuous. Use one word only once (come, sleep, behave, speak, clean, drink, understand, wash, travel, watch). We ______ to Gilgit tomorrow.", "a": "We are travelling to Gilgit tomorrow."}, {"q": "Use the correct form of the Present Simple and Present Continuous. My sister ______ nicely with everyone.", "a": "My sister behaves nicely with everyone."}, {"q": "Use the correct form of the Present Simple and Present Continuous. His brother ______ tea three times a day.", "a": "His brother drinks tea three times a day."}, {"q": "Use the correct form of the Present Simple and Present Continuous. Our uncle ______ to our house this weekend.", "a": "Our uncle is coming to our house this weekend."}, {"q": "Use the correct form of the Present Simple and Present Continuous. She ______ and ______ Persian very well.", "a": "She speaks and understands Persian very well."}, {"q": "Use the correct form of the Present Simple and Present Continuous. I ______ my room every day and I also ______ my clothes sometimes.", "a": "I clean my room every day and I also wash my clothes sometimes."}, {"q": "Use the correct form of the Present Simple and Present Continuous. My mother usually ______ television at this time but today she ______.", "a": "My mother usually watches television at this time but today she is sleeping."}]}]}, {"num": "4", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Use the correct form of the Present Perfect. Use one word only once (eat, throw, help, go, read, make, apply, complain, climb, complete). I ______ this book twice already.", "a": "I have read this book twice already."}, {"q": "Use the correct form of the Present Perfect. We ______ all the mangoes.", "a": "We have eaten all the mangoes."}, {"q": "Use the correct form of the Present Perfect. My brother ______ for a job.", "a": "My brother has applied for a job."}, {"q": "Use the correct form of the Present Perfect. They will win this match as already they ______ ninety runs.", "a": "They will win this match as already they have made ninety runs."}, {"q": "Use the correct form of the Present Perfect. Seema ______ her work as Beena ______ her throughout.", "a": "Seema has completed her work as Beena has helped her throughout."}, {"q": "Use the correct form of the Present Perfect. We ______ so many times but they ______ the garbage here again.", "a": "We have complained so many times but they have thrown the garbage here again."}, {"q": "Use the correct form of the Present Perfect. Tariq's little sister ______ up the tree, now he ______ up to get her.", "a": "Tariq's little sister has climbed up the tree, now he has gone up to get her."}]}]}, {"num": "5", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Use the correct form of the Present Perfect Continuous. Use one word only once (jump, watch, rain, cook, drive, work, plant, talk, chase, sit). We ______ since twelve noon.", "a": "We have been working since twelve noon."}, {"q": "Use the correct form of the Present Perfect Continuous. It ______ for three hours continuously.", "a": "It has been raining for three hours continuously."}, {"q": "Use the correct form of the Present Perfect Continuous. They ______ for an hour.", "a": "They have been talking for an hour."}, {"q": "Use the correct form of the Present Perfect Continuous. I ______ all morning.", "a": "I have been driving all morning."}, {"q": "Use the correct form of the Present Perfect Continuous. She ______ food for us without a break while we ______ this match.", "a": "She has been cooking food for us without a break while we have been watching this match."}, {"q": "Use the correct form of the Present Perfect Continuous. My grandmother ______ outside and my father ______ vegetables.", "a": "My grandmother has been sitting outside and my father has been planting vegetables."}, {"q": "Use the correct form of the Present Perfect Continuous. The dog ______ the cat and the cat ______ all around.", "a": "The dog has been chasing the cat and the cat has been jumping all around."}]}]}], "words": [{"w": "present simple tense", "sd": "زمان حال سادو", "syn": "the tense for habits and facts"}, {"w": "present continuous tense", "sd": "زمان حال جاري", "syn": "the tense for an action happening now"}, {"w": "present perfect tense", "sd": "زمان حال مڪمل", "syn": "the tense made with has/have and the past participle"}, {"w": "present perfect continuous tense", "sd": "زمان حال مڪمل جاري", "syn": "the tense made with has/have been and the verb + ing"}]}, {"cls": "x", "unit": 4, "title": "Simple and Compound Sentences", "display": "Simple and Compound Sentences", "reading": "Secondary Stage English Book Two, Unit 2, Language Practice", "lesson": [{"t": "h", "x": "Simple and Compound Sentences"}, {"t": "p", "x": "A simple sentence has one subject and one verb. A compound sentence has two simple sentences joined by a conjunction. The FANBOYS are: for, and, nor, but, or, yet, so."}, {"t": "def", "x": "A simple sentence has one subject and one verb. A compound sentence has two simple sentences joined by a coordinating conjunction (FANBOYS)."}, {"t": "h", "x": "Rule 1. A simple sentence has one subject and one verb"}, {"t": "rule", "x": "A simple sentence has one subject and one verb. It gives one complete idea."}, {"t": "ex", "x": "You have been sleeping since morning. Ali plays cricket. The sun rises in the east."}, {"t": "h", "x": "Rule 2. A compound sentence joins two simple sentences"}, {"t": "rule", "x": "A compound sentence joins two simple sentences with a coordinating conjunction: for, and, nor, but, or, yet, so."}, {"t": "ex", "x": "I want to lose weight, yet I eat too much. Ali plays cricket, and Ahmed plays hockey. I was tired, so I went to bed. He is rich, but he is not happy."}, {"t": "h", "x": "Rule 3. Use a comma before the conjunction"}, {"t": "rule", "x": "In a compound sentence, put a comma before the conjunction."}, {"t": "ex", "x": "I want to lose weight, yet I eat too much. She is poor, but she is honest. Work hard, or you will fail."}, {"t": "h", "x": "Rule 4. Change a compound sentence into two simple sentences"}, {"t": "rule", "x": "To change a compound sentence into two simple sentences, remove the conjunction and make two sentences."}, {"t": "ex", "x": "Compound: I want to lose weight, yet I eat too much. Simple: I want to lose weight. I eat too much."}, {"t": "rl", "x": "At school, Ali is a good boy. (simple) Ali is a good boy, and Ahmed is a good boy too. (compound)"}, {"t": "rl", "x": "At home, my mother cooks food. (simple) My mother cooks food, and my sister helps her. (compound)"}, {"t": "rl", "x": "On the cricket ground, Ali plays well. (simple) Ali plays well, but Ahmed bowls well. (compound)"}, {"t": "note", "x": "FANBOYS stands for: for, and, nor, but, or, yet, so. These are the coordinating conjunctions."}], "sections": [{"num": "1", "name": "Exercise 10", "exercises": [{"label": "Exercise 10", "items": [{"q": "Write 'S' if it is a simple sentence and 'C' if it is a compound sentence. You have been sleeping since morning.", "a": "S (simple sentence)."}, {"q": "Write 'S' if it is a simple sentence and 'C' if it is a compound sentence. I don't know the answer.", "a": "S (simple sentence)."}, {"q": "Write 'S' if it is a simple sentence and 'C' if it is a compound sentence. I want to lose weight, yet I eat chocolates daily.", "a": "C (compound sentence) - given in the book."}, {"q": "Write 'S' if it is a simple sentence and 'C' if it is a compound sentence. Atif is famous, but he is very humble.", "a": "C (compound sentence)."}, {"q": "Write 'S' if it is a simple sentence and 'C' if it is a compound sentence. You may eat a mango or have mango pickle.", "a": "C (compound sentence)."}, {"q": "Write 'S' if it is a simple sentence and 'C' if it is a compound sentence. He is totally dependent on his parents.", "a": "S (simple sentence)."}, {"q": "Write 'S' if it is a simple sentence and 'C' if it is a compound sentence. He was feeling sick, so he went to the doctor.", "a": "C (compound sentence)."}, {"q": "Write 'S' if it is a simple sentence and 'C' if it is a compound sentence. No one is traveling these days.", "a": "S (simple sentence)."}, {"q": "Write 'S' if it is a simple sentence and 'C' if it is a compound sentence. I go to the library, for I love reading.", "a": "C (compound sentence)."}, {"q": "Write 'S' if it is a simple sentence and 'C' if it is a compound sentence. He is rich and he has a good heart.", "a": "C (compound sentence)."}]}]}, {"num": "2", "name": "Exercise 11", "exercises": [{"label": "Exercise 11", "items": [{"q": "Convert the compound sentence into two simple sentences by removing the linking word. I want to lose weight, yet I eat chocolates daily.", "a": "I want to lose weight. I eat chocolates daily. (example given in the book)"}, {"q": "Convert the compound sentence into two simple sentences by removing the linking word. Atif is famous, but he is very humble.", "a": "Atif is famous. He is very humble."}, {"q": "Convert the compound sentence into two simple sentences by removing the linking word. You may eat a mango or have mango pickle.", "a": "You may eat a mango. You may have mango pickle."}, {"q": "Convert the compound sentence into two simple sentences by removing the linking word. He was feeling sick, so he went to the doctor.", "a": "He was feeling sick. He went to the doctor."}, {"q": "Convert the compound sentence into two simple sentences by removing the linking word. I go to the library, for I love reading.", "a": "I go to the library. I love reading."}, {"q": "Convert the compound sentence into two simple sentences by removing the linking word. He is rich and he has a good heart.", "a": "He is rich. He has a good heart."}]}]}, {"num": "3", "name": "Exercise 12", "exercises": [{"label": "Exercise 12", "items": [{"q": "Make five simple sentences, using the linking words given earlier in FANBOYS where needed.", "a": "1. Ali plays cricket every Sunday. 2. She reads her book daily. 3. The sun rises in the east. 4. We went to school early today. 5. My father works in a bank."}, {"q": "Make five compound sentences, using the linking words given earlier in FANBOYS.", "a": "1. Ali plays cricket every Sunday, but he does not play hockey. 2. She reads her book daily, for she loves reading. 3. We can go to the park, or we can stay at home. 4. He worked hard, so he passed the examination. 5. I wanted to go to school, yet I was ill."}]}]}], "words": [{"w": "simple sentence", "sd": "سادو جملو", "syn": "a sentence with one subject and one verb"}, {"w": "compound sentence", "sd": "مرڪب جملو", "syn": "two simple sentences joined by a conjunction"}, {"w": "coordinating conjunction", "sd": "ڳنڍڻ وارو لفظ", "syn": "a word like and, but or so that joins two sentences"}]}, {"cls": "x", "unit": 5, "title": "Past Tenses", "display": "Past Tenses", "reading": "Secondary Stage English Book Two, Unit 3, Language Practice", "lesson": [{"t": "h", "x": "Past Tenses"}, {"t": "p", "x": "There are four past tenses: past simple, past continuous, past perfect and past perfect continuous. Each one is used for a different kind of past action."}, {"t": "def", "x": "The past simple is for a finished past action. The past continuous is for an action going on in the past. The past perfect is for an action that happened before another past action. The past perfect continuous is for an action that had been going on before another past action."}, {"t": "h", "x": "Rule 1. Past simple: verb + ed, or the second form"}, {"t": "rule", "x": "Use the past simple for a finished past action. Regular verbs add 'ed'. Irregular verbs change."}, {"t": "ex", "x": "I ate my lunch. She closed the door. They sold their house. He belonged to Karachi. Kakenya went to school."}, {"t": "h", "x": "Rule 2. Past continuous: was/were + verb + ing"}, {"t": "rule", "x": "Use the past continuous for an action that was going on at a time in the past."}, {"t": "ex", "x": "I was driving when it started to rain. She was shaking with fear. They were doing their homework."}, {"t": "h", "x": "Rule 3. Past perfect: had + past participle"}, {"t": "rule", "x": "Use the past perfect for an action that happened before another past action."}, {"t": "ex", "x": "She had swept the floor before her mother came. He had left before I arrived. They had spent all their money."}, {"t": "h", "x": "Rule 4. Past perfect continuous: had been + verb + ing"}, {"t": "rule", "x": "Use the past perfect continuous for an action that had been going on before another past action."}, {"t": "ex", "x": "I had been refusing to go to school. She had been waiting for two hours. They had been playing since morning."}, {"t": "rl", "x": "At school, I ate my lunch at 1 o'clock. (past simple) I was eating my lunch when the bell rang. (past continuous)"}, {"t": "rl", "x": "At home, my mother had cooked the food before my father came home. (past perfect) She had been cooking since morning. (past perfect continuous)"}, {"t": "rl", "x": "On the cricket ground, Ali had scored fifty runs before he got out. The boys had been playing since morning."}, {"t": "note", "x": "The past perfect tells us which past action happened first. The past continuous tells us what was happening."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "(Past Simple): Use the correct form of the Past Simple to fill the blanks. Words: eat, close, sell, belong, live, make, lock, run. 1. We ___ delicious food at their house.", "a": "We ate delicious food at their house."}, {"q": "(Past Simple): 2. The mouse ___ under the cupboard.", "a": "The mouse ran under the cupboard."}, {"q": "(Past Simple): 3. The guard ___ and ___ the gate before going to bed.", "a": "The guard closed and locked the gate before going to bed."}, {"q": "(Past Simple): 4. The house in which we ___ till last year ___ to my uncle.", "a": "The house in which we lived till last year belonged to my uncle."}, {"q": "(Past Simple): 5. The parrots ___ a lot of noise so we ___ them.", "a": "The parrots made a lot of noise so we sold them."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "(Past Continuous): Use the correct form of the Past Continuous to fill the blanks. Words: do, drive, shake, tell, fly, wash, fight, fall. a) The papers ___ in all directions due to strong winds.", "a": "The papers were flying in all directions due to strong winds."}, {"q": "(Past Continuous): b) The boys ___ over who would play first.", "a": "The boys were fighting over who would play first."}, {"q": "(Past Continuous): c) We ___ the tree and the ripe fruits ___ on the ground.", "a": "We were shaking the tree and the ripe fruits were falling on the ground."}, {"q": "(Past Continuous): d) My sister ___ her homework while I ___ dishes.", "a": "My sister was doing her homework while I was washing dishes."}, {"q": "(Past Continuous): e) The driver ___ the car and my brother ___ him the directions.", "a": "The driver was driving the car and my brother was telling him the directions."}]}]}, {"num": "3", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "(Past Perfect): Use the correct form of the Past Perfect to fill the blanks. Words: sweep, leave, spend, die, travel, reach, cover, finish. a) We ___ a lot of money on buying gifts, so we decided to stop.", "a": "We had spent a lot of money on buying gifts, so we decided to stop."}, {"q": "(Past Perfect): b) As soon as Samina ___ the yard there was a storm.", "a": "As soon as Samina had swept the yard there was a storm."}, {"q": "(Past Perfect): c) The group ___ several miles and ___ a big part of their journey.", "a": "The group had travelled several miles and had covered a big part of their journey."}, {"q": "(Past Perfect): d) The students ___ their work and ___ for home when the rain started.", "a": "The students had finished their work and had left for home when the rain started."}, {"q": "(Past Perfect): e) She ___ before they ___ the hospital.", "a": "She had died before they had reached the hospital."}]}]}, {"num": "4", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "(Past Perfect Continuous): Use the correct form of the Past Perfect Continuous to fill the blanks. Words: refuse, worry, cry, ring, fly, paint, warn, dig, bark, read. 1. He ___ for help for five hours when the rescue team finally arrived.", "a": "He had been crying for help for five hours when the rescue team finally arrived."}, {"q": "(Past Perfect Continuous): 2. I ___ for two hours before I fell asleep.", "a": "I had been reading for two hours before I fell asleep."}, {"q": "(Past Perfect Continuous): 3. We ___ for 16 hours and everyone was very tired.", "a": "We had been flying for 16 hours and everyone was very tired."}, {"q": "(Past Perfect Continuous): 4. I ___ about my results the whole week.", "a": "I had been worrying about my results the whole week."}, {"q": "(Past Perfect Continuous): 5. The labourers ___ and the painters ___ for several days before they were allowed to go home.", "a": "The labourers had been digging and the painters had been painting for several days before they were allowed to go home."}, {"q": "(Past Perfect Continuous): 6. The bell ___ and the dog ___ for nearly 20 minutes before someone opened the door.", "a": "The bell had been ringing and the dog had been barking for nearly 20 minutes before someone opened the door."}, {"q": "(Past Perfect Continuous): 7. The MET department ___ about a storm but the people ___ to listen.", "a": "The MET department had been warning about a storm but the people had refused to listen."}]}]}], "words": [{"w": "past simple tense", "sd": "زمان ماضي سادو", "syn": "the tense for a finished past action"}, {"w": "past continuous tense", "sd": "زمان ماضي جاري", "syn": "the tense for an action going on in the past"}, {"w": "past perfect tense", "sd": "زمان ماضي مڪمل", "syn": "the tense made with had and the past participle"}, {"w": "past perfect continuous tense", "sd": "زمان ماضي مڪمل جاري", "syn": "the tense made with had been and the verb + ing"}]}, {"cls": "x", "unit": 6, "title": "Articles", "display": "Articles", "reading": "Secondary Stage English Book Two, Unit 3, Language Practice", "lesson": [{"t": "h", "x": "Articles"}, {"t": "p", "x": "A, an and the are articles. We use 'a' and 'an' for one thing in general, and 'the' for a special or known thing. Sometimes no article is needed."}, {"t": "def", "x": "An article is a word used before a noun. 'A' and 'an' are indefinite articles. 'The' is the definite article. Sometimes we use no article (X)."}, {"t": "h", "x": "Rule 1. Use 'a' before a consonant sound"}, {"t": "rule", "x": "Use 'a' before a word that begins with a consonant sound."}, {"t": "ex", "x": "a book, a pen, a dress, a boy, a country, a university, a one-rupee coin."}, {"t": "h", "x": "Rule 2. Use 'an' before a vowel sound"}, {"t": "rule", "x": "Use 'an' before a word that begins with a vowel sound (a, e, i, o, u)."}, {"t": "ex", "x": "an apple, an egg, an eye, an elephant, an umbrella, an hour, an honest man."}, {"t": "h", "x": "Rule 3. Use 'the' for a special or known thing"}, {"t": "rule", "x": "Use 'the' when we talk about a special or known thing, or when there is only one of it."}, {"t": "ex", "x": "The Khyber Pass is a famous pass. The sun rises in the east. The book on the table is mine."}, {"t": "h", "x": "Rule 4. Use no article in some cases"}, {"t": "rule", "x": "Do not use an article before a person's name, before a general plural noun, or before the name of a language or a subject. Put a cross (X) where no article is needed."}, {"t": "ex", "x": "Ali is my friend. Boys play cricket. I learn English. We study science. He went to school. (X)"}, {"t": "rl", "x": "At school, I have a pen and an eraser. The pen is blue. The teacher is the best in our school."}, {"t": "rl", "x": "At home, my mother bought a dress. The dress is red. She gave me an apple."}, {"t": "rl", "x": "In the market, I saw the moon in the sky. The sun is hot. A shopkeeper sells fruit."}, {"t": "note", "x": "Use 'the' the second time we talk about a thing: 'I saw a dog. The dog was black.'"}], "sections": [{"num": "1", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "(Articles a/an): Fill the blanks with a/an where necessary. Put a cross (X) where no article is required. 1. ___ giraffe has ___ long neck.", "a": "A giraffe has a long neck."}, {"q": "(Articles a/an): 2. ___ Australian sheep gives us ___ good wool.", "a": "X Australian sheep gives us X good wool. (No article is needed before 'Australian sheep' or before 'good wool'.)"}, {"q": "(Articles a/an): 3. He is ___ honest man but his friend is ___ crook.", "a": "He is an honest man but his friend is a crook."}, {"q": "(Articles a/an): 4. To help the students, ___ example has been given in the exercise.", "a": "To help the students, an example has been given in the exercise."}, {"q": "(Articles a/an): 5. Would you like to have ___ cup of tea or ___ something to eat?", "a": "Would you like to have a cup of tea or X something to eat?"}, {"q": "(Articles a/an): 6. ___ factory is being built next to our house.", "a": "A factory is being built next to our house."}, {"q": "(Articles a/an): 7. Boil ___ eggs and make ___ sandwiches for breakfast.", "a": "Boil X eggs and make X sandwiches for breakfast."}, {"q": "(Articles a/an): 8. It was ___ honour to be nominated.", "a": "It was an honour to be nominated."}, {"q": "(Articles a/an): 9. I want to buy ___ uniform when ___ schools reopen in August.", "a": "I want to buy a uniform when X schools reopen in August."}, {"q": "(Articles a/an): 10. ___ old friend is staying at ___ hotel on the River Indus.", "a": "An old friend is staying at a hotel on the River Indus."}]}]}, {"num": "2", "name": "Exercise 8", "exercises": [{"label": "Exercise 8", "items": [{"q": "(Article 'the'): Fill the blanks with 'the' where necessary. Put a cross (X) where 'the' is not required. 1. ___ English language is ___ most spoken language in the world.", "a": "X English language is the most spoken language in the world."}, {"q": "(Article 'the'): 2. There are ___ beautiful flowers in ___ park.", "a": "There are X beautiful flowers in the park."}, {"q": "(Article 'the'): 3. My sister lives in ___ USA.", "a": "My sister lives in the USA."}, {"q": "(Article 'the'): 4. There is ___ dirt on this plate and there is a dirty mark on ___ tablecloth.", "a": "There is X dirt on this plate and there is a dirty mark on the tablecloth."}, {"q": "(Article 'the'): 5. ___ lions are dangerous animals, but ___ dogs are ___ good friends of people.", "a": "X lions are dangerous animals, but X dogs are X good friends of people."}, {"q": "(Article 'the'): 6. When you drive a car in ___ UAE, you must keep to ___ right.", "a": "When you drive a car in the UAE, you must keep to the right."}, {"q": "(Article 'the'): 7. ___ inventor of the telephone was ___ Graham Bell.", "a": "The inventor of the telephone was X Graham Bell."}, {"q": "(Article 'the'): 8. ___ directions to ___ central library are clear.", "a": "The directions to the central library are clear."}, {"q": "(Article 'the'): 9. ___ butcher opposite ___ library sells ___ good meat.", "a": "The butcher opposite the library sells X good meat."}, {"q": "(Article 'the'): 10. One of ___ persons I love ___ most is my mother.", "a": "One of the persons I love the most is my mother."}]}]}], "words": [{"w": "article", "sd": "حرف تنڪير", "syn": "a word like a, an or the used before a noun"}, {"w": "definite article", "sd": "حرف تنڪير خاص", "syn": "the article 'the'"}, {"w": "indefinite article", "sd": "حرف تنڪير عام", "syn": "the articles 'a' and 'an'"}]}, {"cls": "x", "unit": 7, "title": "Future Forms", "display": "Future Forms", "reading": "Secondary Stage English Book Two, Unit 4, Language Practice", "lesson": [{"t": "h", "x": "Future Forms"}, {"t": "p", "x": "There are many ways to talk about the future: will/shall, future continuous, future perfect, be going to, present continuous and present simple."}, {"t": "def", "x": "The future forms are: will/shall + verb, will/shall be + verb + ing, will/shall have + past participle, be going to + verb, present continuous and present simple."}, {"t": "h", "x": "Rule 1. Will/shall + verb for a future action"}, {"t": "rule", "x": "Use will or shall with the verb for a future action. 'Shall' is used with I and we. 'Will' is used with all persons."}, {"t": "ex", "x": "They will come here again next year. I shall complain to the principal next week. We shall be in trouble for being late."}, {"t": "h", "x": "Rule 2. Future continuous: will/shall be + verb + ing"}, {"t": "rule", "x": "Use the future continuous for an action that will be going on at a time in the future."}, {"t": "ex", "x": "I will be appearing for my board exams this year. They will be watching the cricket match tonight. This time tomorrow, I shall be driving the car."}, {"t": "h", "x": "Rule 3. Future perfect: will/shall have + past participle"}, {"t": "rule", "x": "Use the future perfect for an action that will be finished before a time in the future."}, {"t": "ex", "x": "We shall have climbed the mountain by tomorrow afternoon. He will have had his tooth pulled out by the time we reach. By the time we finish, they will have left."}, {"t": "h", "x": "Rule 4. Be going to + verb for a plan"}, {"t": "rule", "x": "Use 'be going to' with the verb for a plan already made, or for something about to happen."}, {"t": "ex", "x": "Tariq is going to deliver the speech. We are going to cut this tree. I am going to join the new hockey club soon."}, {"t": "h", "x": "Rule 5. Present continuous and present simple for the future"}, {"t": "rule", "x": "Use the present continuous for a fixed future plan, and the present simple for a timetable."}, {"t": "ex", "x": "We are taking a trip to Tharparkar next Sunday. The train leaves in half an hour. The ship sails for South Africa next week."}, {"t": "rl", "x": "At school, I will appear for my board exams this year. I am going to work hard. The exams will start next month."}, {"t": "rl", "x": "At home, my father will come home tomorrow. We shall have finished our work by then. My mother is going to cook biryani."}, {"t": "rl", "x": "On the cricket ground, they will be watching the match tonight. The match will start at 3 o'clock."}, {"t": "note", "x": "In the 'if' part of a future sentence, use the present simple, not 'will': 'It will cost more if we buy it next year.'"}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "— Will/shall: 1. They ___ (come) here again next year.", "a": "They will come here again next year."}, {"q": "— Will/shall: 2. I ___ (complain) to the principal sometimes next week.", "a": "I shall complain to the principal sometimes next week."}, {"q": "— Will/shall: 3. They ___ (do) business with us from next year.", "a": "They will do business with us from next year."}, {"q": "— Will/shall: 4. This time tomorrow, I ___ (be) very busy.", "a": "This time tomorrow, I shall be very busy."}, {"q": "— Will/shall: 5. We ___ (be) in trouble for being late.", "a": "We shall be in trouble for being late."}, {"q": "— Future continuous: 1. I ___ (appear) for my board exams this year.", "a": "I will be appearing for my board exams this year."}, {"q": "— Future continuous: 2. We ___ (go) out later in the evening.", "a": "We shall be going out later in the evening."}, {"q": "— Future continuous: 3. He ___ (stay) home the whole evening.", "a": "He will be staying home the whole evening."}, {"q": "— Future continuous: 4. They ___ (watch) the cricket match tonight.", "a": "They will be watching the cricket match tonight."}, {"q": "— Future continuous: 5. I ___ (drive) the car as our driver is ill.", "a": "I shall be driving the car as our driver is ill."}, {"q": "— Future Perfect: 1. We ___ (climb) the mountain by tomorrow afternoon.", "a": "We shall have climbed the mountain by tomorrow afternoon."}, {"q": "— Future Perfect: 2. He ___ (have) his tooth pulled out by the time we reach.", "a": "He will have had his tooth pulled out by the time we reach."}, {"q": "— Future Perfect: 3. I ___ (meet) the captain of the cricket team by six o'clock tomorrow.", "a": "I shall have met the captain of the cricket team by six o'clock tomorrow."}, {"q": "— Future Perfect: 4. His tailor ___ (stitch) his clothes by the time we get there.", "a": "His tailor will have stitched his clothes by the time we get there."}, {"q": "— Future Perfect: 5. By the time we finish they ___ (leave).", "a": "By the time we finish they will have left."}, {"q": "— Be going to: 1. Tariq ___ (deliver) the speech on behalf of the class.", "a": "Tariq is going to deliver the speech on behalf of the class."}, {"q": "— Be going to: 2. We ___ (cut) this tree as it is about to fall.", "a": "We are going to cut this tree as it is about to fall."}, {"q": "— Be going to: 3. I think they ___ (get) admission in the best college.", "a": "I think they are going to get admission in the best college."}, {"q": "— Be going to: 4. The tree ___ (shed) its leaves soon as it is autumn time.", "a": "The tree is going to shed its leaves soon as it is autumn time."}, {"q": "— Be going to: 5. I ___ (go) join the new hockey club soon.", "a": "I am going to join the new hockey club soon."}, {"q": "— Present continuous: 1. We ___ (take) a trip to Tharparkar next Sunday.", "a": "We are taking a trip to Tharparkar next Sunday."}, {"q": "— Present continuous: 2. I ___ (cook) biryani for lunch today.", "a": "I am cooking biryani for lunch today."}, {"q": "— Present continuous: 3. They ___ (buy) a new house soon.", "a": "They are buying a new house soon."}, {"q": "— Present continuous: 4. He ___ (invite) several people to his son's wedding next month.", "a": "He is inviting several people to his son's wedding next month."}, {"q": "— Present continuous: 5. She ___ (participate) in the debate competition to be held by the school.", "a": "She is participating in the debate competition to be held by the school."}, {"q": "— Present simple: 1. We ___ (start) this work tomorrow.", "a": "We start this work tomorrow."}, {"q": "— Present simple: 2. The train ___ (leave) in half an hour.", "a": "The train leaves in half an hour."}, {"q": "— Present simple: 3. The ship ___ (sail) for South Africa next week.", "a": "The ship sails for South Africa next week."}, {"q": "— Present simple: 4. She ___ (begin) her career in the Pakistani air force next year.", "a": "She begins her career in the Pakistani air force next year."}, {"q": "— Present simple: 5. He ___ (return) tomorrow after a week-long journey.", "a": "He returns tomorrow after a week-long journey."}, {"q": "— Two future actions: 1. It ___ (cost) a lot more if we ___ (buy) it next year.", "a": "It will cost a lot more if we buy it next year."}, {"q": "— Two future actions: 2. He ___ (visit) us when he ___ (come) to Karachi on his next visit.", "a": "He will visit us when he comes to Karachi on his next visit."}, {"q": "— Two future actions: 3. We ___ (wait) for you at the gate until you ___ (arrive).", "a": "We will wait for you at the gate until you arrive."}, {"q": "— Two future actions: 4. The cat ___ (drink) the milk by the time you ___ (move) the bowl.", "a": "The cat will have drunk the milk by the time you move the bowl."}, {"q": "— Two future actions: 5. The programme ___ (end) by the time they ___ (finish) their food.", "a": "The programme will have ended by the time they finish their food."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Complete the sentences using the correct future form of the given verbs. 1. Do you think people ___ (travel) to the moon again?", "a": "Do you think people will travel to the moon again?"}, {"q": "Tomorrow we ___ (rehearse) a school play in the gym.", "a": "Tomorrow we will be rehearsing a school play in the gym."}, {"q": "Dad ___ (wait) for you at the station when you arrive next week.", "a": "Dad will be waiting for you at the station when you arrive next week."}, {"q": "By the end of this year, I ___ (visit) Brazil.", "a": "By the end of this year, I shall have visited Brazil."}, {"q": "I ___ (make) a shelf for my technology project.", "a": "I am going to make a shelf for my technology project."}, {"q": "Look at that car! It ___ (crash) if the driver doesn't slow down.", "a": "Look at that car! It will crash if the driver doesn't slow down."}, {"q": "If I won't know the answer, I ___ (ask) my elder sister.", "a": "If I won't know the answer, I shall ask my elder sister."}, {"q": "We ___ (go) on a picnic next weekend. Would you like to come?", "a": "We are going on a picnic next weekend. Would you like to come?"}, {"q": "Sara and Meena ___ (finish) their IT project by tomorrow afternoon.", "a": "Sara and Meena will have finished their IT project by tomorrow afternoon."}, {"q": "Raza ___ (take) his goat for a walk when his mother ___ (come) back from work.", "a": "Raza will be taking his goat for a walk when his mother comes back from work."}]}]}], "words": [{"w": "future", "sd": "مستقبل", "syn": "the time that is yet to come"}, {"w": "future continuous tense", "sd": "زمان مستقبل جاري", "syn": "the tense made with will/shall be and the verb + ing"}, {"w": "future perfect tense", "sd": "زمان مستقبل مڪمل", "syn": "the tense made with will/shall have and the past participle"}]}, {"cls": "x", "unit": 8, "title": "Active and Passive Voice", "display": "Active and Passive Voice", "reading": "Secondary Stage English Book Two, Unit 4, Language Practice", "lesson": [{"t": "h", "x": "Active and Passive Voice"}, {"t": "p", "x": "In the active voice, the subject does the action. In the passive voice, the subject receives the action. We can change a sentence from one voice to the other."}, {"t": "def", "x": "Voice shows whether the subject does the action (active) or receives the action (passive). The passive is made with a be verb and the past participle."}, {"t": "h", "x": "Rule 1. Make the passive with be + past participle"}, {"t": "rule", "x": "Make the passive voice with is, am, are, was, were, has been or will be and the past participle of the verb."}, {"t": "ex", "x": "The walls are being painted by the workers. Students should study environmental issues. (active) Environmental issues should be studied by students. (passive)"}, {"t": "h", "x": "Rule 2. Change active into passive"}, {"t": "rule", "x": "To change an active sentence into a passive one, make the object the subject, use the be verb and the past participle, and put the old subject after 'by' if needed."}, {"t": "ex", "x": "Active: Students should study environmental issues. Passive: Environmental issues should be studied by students. Active: The workers are painting the walls. Passive: The walls are being painted by the workers."}, {"t": "h", "x": "Rule 3. Change passive into active"}, {"t": "rule", "x": "To change a passive sentence into an active one, make the 'by' part the subject and use the verb in the active voice."}, {"t": "ex", "x": "Passive: The walls are being painted by the workers. Active: The workers are painting the walls. Passive: A local jewellery shop was robbed by two men. Active: Two men robbed a local jewellery shop."}, {"t": "h", "x": "Rule 4. Use the passive when the doer is not known"}, {"t": "rule", "x": "Use the passive voice when we do not know who did the action, or when it does not matter."}, {"t": "ex", "x": "A local jewellery shop was robbed yesterday. (We do not know who robbed it.) Rice is grown in Sindh. English is spoken in many countries."}, {"t": "rl", "x": "At school, the classroom is cleaned every day. The homework is checked by the teacher. Our team won the match."}, {"t": "rl", "x": "At home, the food is cooked by my mother. The house was cleaned by all of us."}, {"t": "rl", "x": "In the market, fruit is sold in the shops. Mangoes are bought by many people."}, {"t": "note", "x": "Keep the tense the same when you change the voice: present stays present, past stays past."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "(Passive to Active): Change the following passive voice into active voice. 1. The walls are being painted by them.", "a": "They are painting the walls."}, {"q": "(Passive to Active): 2. The latest book of the writer is liked by the readers.", "a": "The readers like the latest book of the writer."}, {"q": "(Passive to Active): 3. We had been given the wrong tickets.", "a": "Someone had given us the wrong tickets."}, {"q": "(Passive to Active): 4. The thieves were caught.", "a": "The police caught the thieves."}, {"q": "(Passive to Active): 5. These three books had been written by him in 1873.", "a": "He had written these three books in 1873."}, {"q": "(Passive to Active): 6. Why is time wasted by everyone?", "a": "Why does everyone waste time?"}, {"q": "(Passive to Active): 7. The new houses will be built by the new construction company.", "a": "The new construction company will build the new houses."}, {"q": "(Passive to Active): 8. The official documents have been sent by the officer.", "a": "The officer has sent the official documents."}, {"q": "(Passive to Active): 9. They can be given some information about the job by Ramiz.", "a": "Ramiz can give them some information about the job."}, {"q": "(Passive to Active): 10. A new road was being planned near my house by the government.", "a": "The government was planning a new road near my house."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "(Active to Passive): Change the following active voice into passive voice. 1. Students should study environmental problems at school.", "a": "Environmental problems should be studied by students at school."}, {"q": "(Active to Passive): 2. Teachers could include this topic in their classes.", "a": "This topic could be included in their classes by teachers."}, {"q": "(Active to Passive): 3. Some people buy returnable bottles and use recycled paper.", "a": "Returnable bottles are bought and recycled paper is used by some people."}, {"q": "(Active to Passive): 4. Governments have constantly ignored important issues for economic reasons.", "a": "Important issues have constantly been ignored by governments for economic reasons."}, {"q": "(Active to Passive): 5. At school, teachers often tell students about pollution and its prevention.", "a": "At school, students are often told about pollution and its prevention by teachers."}, {"q": "(Active to Passive): 6. In developed countries, authorities expect everybody to cooperate.", "a": "In developed countries, everybody is expected to cooperate by authorities."}, {"q": "(Active to Passive): 7. Everyone should throw their bottles in the bottle recycling bins.", "a": "Their bottles should be thrown by everyone in the bottle recycling bins."}, {"q": "(Active to Passive): 8. Parents must teach their children how to dispose the rubbish.", "a": "Children must be taught by parents how to dispose the rubbish."}, {"q": "(Active to Passive): 9. Last year several nations held a meeting to discuss environmental problems.", "a": "Last year a meeting was held by several nations to discuss environmental problems."}, {"q": "(Active to Passive): 10. Organizations like Greenpeace are giving people leaflets about what to do.", "a": "People are being given leaflets by organizations like Greenpeace about what to do."}]}]}], "words": [{"w": "active voice", "sd": "معروف", "syn": "the voice in which the subject does the action"}, {"w": "passive voice", "sd": "مجهول", "syn": "the voice in which the subject receives the action"}, {"w": "past participle", "sd": "اسم مفعول", "syn": "the third form of the verb, as in written or played"}]}, {"cls": "x", "unit": 9, "title": "Plurals of Nouns", "display": "Plurals of Nouns", "reading": "Secondary Stage English Book Two, Unit 5, Language Practice", "lesson": [{"t": "h", "x": "Plurals of Nouns"}, {"t": "p", "x": "A noun is singular when it names one thing and plural when it names more than one. Most plurals add 's' or 'es', but many nouns change in a special way."}, {"t": "def", "x": "A singular noun names one thing. A plural noun names more than one thing. The plural is made by adding 's' or 'es', or by changing the word."}, {"t": "h", "x": "Rule 1. Add 's' to make most plurals"}, {"t": "rule", "x": "Add 's' to most nouns to make them plural."}, {"t": "ex", "x": "story — stories, book — books, pen — pens, girl — girls, boy — boys."}, {"t": "h", "x": "Rule 2. Change 'y' to 'ies'"}, {"t": "rule", "x": "For nouns that end with a consonant + y, change y to ies."}, {"t": "ex", "x": "story — stories, city — cities, baby — babies, lady — ladies, fly — flies."}, {"t": "h", "x": "Rule 3. Add 'es' after s, x, ch or sh"}, {"t": "rule", "x": "For nouns that end with s, x, ch or sh, add 'es'."}, {"t": "ex", "x": "glass — glasses, box — boxes, watch — watches, bush — bushes, cliff — cliffs, dish — dishes."}, {"t": "h", "x": "Rule 4. Change 'f' or 'fe' to 'ves'"}, {"t": "rule", "x": "For nouns that end with f or fe, change f to ves: leaf — leaves, knife — knives, wife — wives, life — lives, shelf — shelves."}, {"t": "ex", "x": "leaf — leaves, knife — knives, wife — wives, life — lives, shelf — shelves, thief — thieves."}, {"t": "h", "x": "Rule 5. Some plurals change the word"}, {"t": "rule", "x": "Some nouns change in the plural: man — men, woman — women, child — children, foot — feet, tooth — teeth, ox — oxen, person — people, mouse — mice, goose — geese."}, {"t": "ex", "x": "I saw three big oxen near the cliff. The children are playing. The men are working. The women are cooking."}, {"t": "rl", "x": "At school, there are twenty boys and fifteen girls. I have three books and two pens."}, {"t": "rl", "x": "At home, my mother bought three mangoes and two apples. The children are playing in the garden."}, {"t": "rl", "x": "In the market, the farmer sells oxen and sheep. I saw three big oxen near the cliff."}, {"t": "note", "x": "Some nouns have the same singular and plural: sheep — sheep, deer — deer, fish — fish, furniture — furniture."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Plural of 'story'", "a": "stories"}, {"q": "Plural of 'Hair'", "a": "hair (the same in singular and plural)"}, {"q": "Plural of 'child'", "a": "children"}, {"q": "Plural of 'Leaf'", "a": "leaves"}, {"q": "Plural of 'son in law'", "a": "sons-in-law"}, {"q": "Plural of 'tooth'", "a": "teeth"}, {"q": "Plural of 'woman'", "a": "women"}, {"q": "Plural of 'thief'", "a": "thieves"}, {"q": "Plural of 'portfolio'", "a": "portfolios"}, {"q": "Plural of 'studio'", "a": "studios"}, {"q": "Plural of 'secretary of state'", "a": "secretaries of state"}, {"q": "Plural of 'news'", "a": "news (the same in singular and plural)"}, {"q": "Plural of 'hoof'", "a": "hooves"}, {"q": "Plural of 'theory'", "a": "theories"}, {"q": "Plural of 'trousers'", "a": "trousers (used only in the plural)"}, {"q": "Plural of 'hair'", "a": "hair (the same in singular and plural)"}, {"q": "Plural of 'essay'", "a": "essays"}, {"q": "Plural of 'valley'", "a": "valleys"}, {"q": "Plural of 'tooth'", "a": "teeth"}, {"q": "Plural of 'chimney'", "a": "chimneys"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "I saw three big ____ (ox) near the ____ (cliff).", "a": "I saw three big oxen near the cliffs."}, {"q": "There were many ____ (police) near those ____ (house).", "a": "There were many police near those houses."}, {"q": "Please buy some ____ (potato) and ____ (tomato).", "a": "Please buy some potatoes and tomatoes."}, {"q": "Farmer Abdul Raheem has three ____ (sheep) and four ____ (deer) on his farm.", "a": "Farmer Abdul Raheem has three sheep and four deer on his farm."}, {"q": "Mrs. Jahanzaib had to go for ____ (check-up) every week.", "a": "Mrs. Jahanzaib had to go for check-ups every week."}, {"q": "Raja is more than six ____ (foot) tall, but he is afraid of ____ (mouse).", "a": "Raja is more than six feet tall, but he is afraid of mice."}, {"q": "The little ____ (calf) lost their ____ (mother).", "a": "The little calves lost their mothers."}, {"q": "There are three ____ (bank) in the four ____ (city) close to my village.", "a": "There are three banks in the four cities close to my village."}, {"q": "We need more ____ (knife) and ____ (fork).", "a": "We need more knives and forks."}, {"q": "My sister has lost three of her ____ (tooth).", "a": "My sister has lost three of her teeth."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Leaf — plural, and use singular and plural in sentences.", "a": "Plural: leaves. Singular: A green leaf fell from the tree. Plural: The leaves of the trees turned yellow in autumn."}, {"q": "Dish — plural, and use singular and plural in sentences.", "a": "Plural: dishes. Singular: She washed the dish after dinner. Plural: All the dishes are clean now."}, {"q": "Father-in-law — plural, and use singular and plural in sentences.", "a": "Plural: fathers-in-law. Singular: My father-in-law is a kind man. Plural: Our fathers-in-law met at the wedding."}, {"q": "Train — plural, and use singular and plural in sentences.", "a": "Plural: trains. Singular: The train left the station on time. Plural: Many trains stop at this station every day."}, {"q": "Boy — plural, and use singular and plural in sentences.", "a": "Plural: boys. Singular: The boy is playing in the garden. Plural: The boys are playing in the garden."}, {"q": "Witch — plural, and use singular and plural in sentences.", "a": "Plural: witches. Singular: The witch lived in a dark forest. Plural: The witches flew on their broomsticks in the story."}, {"q": "Thief — plural, and use singular and plural in sentences.", "a": "Plural: thieves. Singular: The police caught the thief. Plural: The thieves stole the jewellery from the house."}, {"q": "Donkey — plural, and use singular and plural in sentences.", "a": "Plural: donkeys. Singular: The donkey is carrying a heavy load. Plural: The donkeys are grazing in the field."}, {"q": "Hair — plural, and use singular and plural in sentences.", "a": "Plural: hair (the same in singular and plural). Singular: A single hair fell on the table. Plural: Her hair is long and black."}, {"q": "Child — plural, and use singular and plural in sentences.", "a": "Plural: children. Singular: The child is sleeping. Plural: The children are playing in the park."}]}]}], "words": [{"w": "singular", "sd": "واحد", "syn": "naming one thing"}, {"w": "plural", "sd": "جمع", "syn": "naming more than one thing"}]}, {"cls": "x", "unit": 10, "title": "Requests and Advice", "display": "Requests and Advice", "reading": "Secondary Stage English Book Two, Unit 5, Language Practice", "lesson": [{"t": "h", "x": "Requests and Advice"}, {"t": "p", "x": "A request asks somebody to do something politely. Advice tells somebody what they should do. We use special words to make requests and give advice."}, {"t": "def", "x": "A request is a polite way of asking somebody to do something. Advice is a suggestion about what somebody should do."}, {"t": "h", "x": "Rule 1. Make a request with 'please' and 'could' or 'would'"}, {"t": "rule", "x": "Use 'please' and 'could' or 'would' to make a polite request."}, {"t": "ex", "x": "Please shut the door, as it is windy today. Could you please lend me your pen? Would you please help me?"}, {"t": "h", "x": "Rule 2. Make a request with 'may' and 'can'"}, {"t": "rule", "x": "Use 'may' and 'can' to ask for permission or to make a request."}, {"t": "ex", "x": "May I use your pen? Can I borrow your book? May I come in?"}, {"t": "h", "x": "Rule 3. Give advice with 'should' and 'ought to'"}, {"t": "rule", "x": "Use 'should' and 'ought to' to give advice."}, {"t": "ex", "x": "You should listen to your mother. You ought to work hard. You should not waste time."}, {"t": "h", "x": "Rule 4. Give advice with an imperative sentence"}, {"t": "rule", "x": "We can also give advice with an imperative sentence."}, {"t": "ex", "x": "Listen to your mother. Work hard. Do not waste time. Take care of your health."}, {"t": "rl", "x": "At school, I say, 'Please lend me your pen.' My friend says, 'You should listen to the teacher.'"}, {"t": "rl", "x": "At home, my mother says, 'You should help your sister.' I say, 'May I go out to play?'"}, {"t": "rl", "x": "In the market, I say, 'Could you please show me that shirt?' The shopkeeper says, 'You should buy this one.'"}, {"t": "note", "x": "A request is polite. Use 'please', 'could' or 'would' to make it polite."}], "sections": [{"num": "1", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "Change into a request: Shut the door, as it is windy today.", "a": "Could you shut the door, please? It is windy today."}, {"q": "Change into a request: Send me an email and I'll follow it up.", "a": "Would you send me an email, please, so that I can follow it up?"}, {"q": "Change into a request: Help me finish this assignment.", "a": "Could you help me finish this assignment, please?"}, {"q": "Change into a request: Pass the salt and pepper.", "a": "Could you pass the salt and pepper, please?"}, {"q": "Change into a request: Repeat what you just said.", "a": "Would you repeat what you just said, please?"}, {"q": "Change into a request: Help me find my leather jacket.", "a": "Could you help me find my leather jacket, please?"}, {"q": "Change into a request: Clear the table so that I can put my computer there.", "a": "Would you clear the table, please, so that I can put my computer there?"}, {"q": "Change into a request: Show me how to do fix this problem.", "a": "Could you show me how to fix this problem, please?"}, {"q": "Change into a request: Help her in whatever way you can.", "a": "Could you help her in whatever way you can, please?"}, {"q": "Change into a request: Move this chair in the corner.", "a": "Would you move this chair into the corner, please?"}]}]}, {"num": "2", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Change into advice: Listen to your mother.", "a": "You should listen to your mother."}, {"q": "Change into advice: Give good reason for your absence.", "a": "You should give a good reason for your absence."}, {"q": "Change into advice: Break traffic rules.", "a": "You should not break traffic rules."}, {"q": "Change into advice: Fulfil the promise you made to your mother.", "a": "You ought to fulfil the promise you made to your mother."}, {"q": "Change into advice: Finish your task on time or you'll be in trouble.", "a": "You had better finish your task on time, or you'll be in trouble."}, {"q": "Change into advice: Discuss this matter on the dinner table.", "a": "You should discuss this matter at the dinner table."}, {"q": "Change into advice: Remain seated until the seatbelt sign is turned off.", "a": "You should remain seated until the seatbelt sign is turned off."}, {"q": "Change into advice: Complete these chores by tomorrow.", "a": "You ought to complete these chores by tomorrow."}, {"q": "Change into advice: Talk when others are speaking.", "a": "You should not talk when others are speaking."}, {"q": "Change into advice: Follow the instructions carefully.", "a": "You should follow the instructions carefully."}]}]}, {"num": "3", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "Write a request or advice: You need a pen, and your sister has one.", "a": "Request: Could I borrow your pen, please?"}, {"q": "Write a request or advice: You are spending too much money on buying unnecessary clothes.", "a": "Advice: You should not spend so much money on unnecessary clothes. You ought to save your money."}, {"q": "Write a request or advice: Your friend is leading an unhealthy lifestyle.", "a": "Advice: You should eat healthy food and take regular exercise. You ought to give up junk food."}, {"q": "Write a request or advice: You want a half-day leave from your Principal as there is an emergency in your family.", "a": "Request: May I have a half-day leave, please? There is an emergency in my family."}, {"q": "Write a request or advice: Your brother is going to the stadium to watch a cricket match and you want to go with him.", "a": "Request: Could I go with you to the stadium to watch the cricket match, please?"}, {"q": "Write a request or advice: My friend was telling me a secret about her family.", "a": "Advice: You should keep her secret and not tell it to anyone."}, {"q": "Write a request or advice: What does your mother say if you spend too much time playing games rather than studying?", "a": "Advice (what a mother says): You should spend less time playing games and more time studying. You had better finish your homework first."}, {"q": "Write a request or advice: The phone rings while you are cooking in the kitchen. Your father is near the telephone.", "a": "Request: Could you please answer the phone, Father? I am cooking in the kitchen."}, {"q": "Write a request or advice: It's hot, and you are thirsty.", "a": "Request: Could I have a glass of cold water, please?"}, {"q": "Write a request or advice: You're studying for an exam, but your brother listens to loud music.", "a": "Request: Could you please turn the music down? I am studying for my exam."}]}]}], "words": [{"w": "request", "sd": "گذراش", "syn": "asking somebody politely to do something"}, {"w": "advice", "sd": "صلاح", "syn": "a suggestion about what somebody should do"}]}, {"cls": "x", "unit": 11, "title": "Words Showing Order", "display": "Words Showing Order", "reading": "Secondary Stage English Book Two, Unit 6, Language Practice", "lesson": [{"t": "h", "x": "Words Showing Order"}, {"t": "p", "x": "Words showing order tell us the order of events or steps. They are also called sequence words or connectives."}, {"t": "def", "x": "Words showing order are words like first, then, next, after that, finally, at first, in the end. They show the order of events or steps."}, {"t": "h", "x": "Rule 1. Use 'first', 'then', 'next' and 'finally' for steps"}, {"t": "rule", "x": "Use 'first' for the first step, 'then' and 'next' for the middle steps, and 'finally' for the last step."}, {"t": "ex", "x": "First, I get up early. Then, I brush my teeth. Next, I take a bath. Finally, I go to school."}, {"t": "h", "x": "Rule 2. Use 'at first' and 'in the end' for a story"}, {"t": "rule", "x": "Use 'at first' for the beginning of a story and 'in the end' for the end of a story."}, {"t": "ex", "x": "At first, the boy was sad. In the end, he was happy. At first, I did not like cricket. In the end, I loved it."}, {"t": "h", "x": "Rule 3. Use 'before' and 'after' for time"}, {"t": "rule", "x": "Use 'before' for something that happens earlier and 'after' for something that happens later."}, {"t": "ex", "x": "I brush my teeth before I go to bed. I wash my hands after I eat. She reads a book after lunch."}, {"t": "h", "x": "Rule 4. Use 'meanwhile' and 'in the meantime' for things happening together"}, {"t": "rule", "x": "Use 'meanwhile' and 'in the meantime' for two things that happen at the same time."}, {"t": "ex", "x": "My sister was in the dentist's office for ten minutes. Meanwhile, I sat in the waiting room with an old magazine."}, {"t": "rl", "x": "At school, first I open my book. Then I read the lesson. Next I write the answers. Finally I close my book."}, {"t": "rl", "x": "At home, first my mother cooks the food. Then we eat together. After that, I do my homework. Finally, I go to bed."}, {"t": "rl", "x": "On the cricket ground, first the captain tosses the coin. Then the teams take their places. Finally, the match starts."}, {"t": "note", "x": "Put a comma after 'first', 'then', 'next' and 'finally' when they begin a sentence."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": ". Underline the words showing order in passage 1 (Saturday was a great day...).", "a": "Passage 1 — words showing order: First, Then, Next, After that, As soon as."}, {"q": ". Underline the connectors of reason in passage 2 (Bilal was an hour late...).", "a": "Passage 2 — connectors of reason: because, as, since, Owing to, due to."}]}]}, {"num": "2", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "My sister was in the dentist's office for ten minutes. ____, I sat in the waiting room with an old magazine in my hands. (First, Meanwhile, Later)", "a": "My sister was in the dentist's office for ten minutes. Meanwhile, I sat in the waiting room with an old magazine in my hands."}, {"q": "An hour passed, but there was no sign of Mujahid. ____, we decided to go home. (Until, Before, Finally)", "a": "An hour passed, but there was no sign of Mujahid. Finally, we decided to go home."}, {"q": "We bumped into Salim during our trip to Keenjhar Lake. A few weeks ____, we met him again. (after, then, later)", "a": "We bumped into Salim during our trip to Keenjhar Lake. A few weeks later, we met him again."}, {"q": "She had finished her lunch ____ I had even started. (later than, before, after)", "a": "She had finished her lunch before I had even started."}, {"q": "They went to a nearby restaurant for breakfast, ____, they drove off towards the River Indus. (after that, afterwards, meanwhile)", "a": "They went to a nearby restaurant for breakfast, after that, they drove off towards the River Indus."}, {"q": "The football coach announced to play with Sindh ____, and ____ with Baluchistan. (first-then, later-after, lastly-eventually)", "a": "The football coach announced to play with Sindh first, and then with Baluchistan."}, {"q": "As we are all hungry, we will go to the park ____ taking lunch. (before, after, first)", "a": "As we are all hungry, we will go to the park after taking lunch."}]}]}], "words": [{"w": "sequence word", "sd": "ترتيب ڏيکاريندڙ لفظ", "syn": "a word like first, then or finally that shows order"}, {"w": "connective", "sd": "ڳنڍڻ وارو لفظ", "syn": "a word that joins sentences or ideas"}]}, {"cls": "x", "unit": 12, "title": "Direct and Indirect Speech", "display": "Direct and Indirect Speech", "reading": "Secondary Stage English Book Two, Units 6 and 8, Language Practice", "lesson": [{"t": "h", "x": "Direct and Indirect Speech"}, {"t": "p", "x": "Direct speech gives the exact words of the speaker inside quotation marks. Indirect speech reports what the speaker said, without quotation marks."}, {"t": "def", "x": "Direct speech is the exact words of the speaker. Indirect speech reports the words of the speaker in our own words."}, {"t": "h", "x": "Rule 1. Direct speech uses quotation marks"}, {"t": "rule", "x": "In direct speech, put the speaker's exact words inside quotation marks."}, {"t": "ex", "x": "Ali's friend said, 'Can you spare me your book for a week?' 'When will your results be announced?' said Jason. 'What is your name?' asked the interviewer."}, {"t": "h", "x": "Rule 2. Indirect speech uses 'that' and no quotation marks"}, {"t": "rule", "x": "In indirect speech, use 'that' after the reporting verb and do not use quotation marks."}, {"t": "ex", "x": "Ali's friend asked Ali if he could spare him his book for a week. Jason asked when our results would be announced. The interviewer asked Faiz what his name was."}, {"t": "h", "x": "Rule 3. Change the tense back one step"}, {"t": "rule", "x": "When the reporting verb is in the past, change the tense back one step: present simple becomes past simple, present continuous becomes past continuous, will becomes would, can becomes could."}, {"t": "ex", "x": "Direct: 'I am happy.' Indirect: He said that he was happy. Direct: 'I will come.' Indirect: He said that he would come. Direct: 'I can swim.' Indirect: He said that he could swim."}, {"t": "h", "x": "Rule 4. Questions in indirect speech use 'if' or 'whether'"}, {"t": "rule", "x": "For a yes/no question, use 'if' or 'whether'. For a WH question, use the WH word. Do not use a question mark in indirect speech."}, {"t": "ex", "x": "Direct: 'Can you spare me your book?' Indirect: He asked if I could spare him my book. Direct: 'What is your name?' Indirect: He asked what my name was."}, {"t": "h", "x": "Rule 5. Orders and requests use 'to'"}, {"t": "rule", "x": "For an order or a request, use 'told' or 'asked' with 'to' and the verb."}, {"t": "ex", "x": "Direct: 'Do not talk during the assembly.' Indirect: The teacher told the students not to talk during the assembly. Direct: 'Try to speak gently.' Indirect: The manager asked his staff to speak gently."}, {"t": "rl", "x": "At school, the teacher said, 'Hurry up, class, we are getting late.' I told my friend that the teacher had said to hurry up."}, {"t": "rl", "x": "At home, my mother said, 'Wash your hands.' I told my sister that mother had said to wash our hands."}, {"t": "rl", "x": "On the cricket ground, Ali said, 'I will bat first.' Ahmed told us that Ali would bat first."}, {"t": "note", "x": "In indirect speech, change I to he or she, my to his or her, and we to they, to match the speaker."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "Ali's friend said, 'Can you spare me your book for a week?' (direct to indirect)", "a": "Ali's friend asked if he could spare him his book for a week."}, {"q": "She said to him, 'Do you sell seafood?' (direct to indirect)", "a": "She asked him if he sold seafood."}, {"q": "'Have you visited Mohatta palace in Karachi, Charles?' said Behram. (direct to indirect)", "a": "Behram asked Charles if he had visited Mohatta Palace in Karachi."}, {"q": "Rehan said to his sister, 'Was your friend's birthday on Friday or Saturday?' (direct to indirect)", "a": "Rehan asked his sister whether her friend's birthday was on Friday or Saturday."}, {"q": "The doctor said to his patient, 'Are you taking medicine regularly?' (direct to indirect)", "a": "The doctor asked his patient if he was taking medicine regularly."}, {"q": "'Can we take photographs here?' the students asked the caretaker. (direct to indirect)", "a": "The students asked the caretaker if they could take photographs there."}, {"q": "Ashok said, 'Is there a petrol pump nearby, Sunil?' (direct to indirect)", "a": "Ashok asked Sunil if there was a petrol pump nearby."}, {"q": "Mother said, 'Do they know the date of our visit?' (direct to indirect)", "a": "Mother asked if they knew the date of our visit."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "'When will your results be announced?' said Jason. (direct to indirect)", "a": "Jason asked when my results would be announced."}, {"q": "'What time will the match start, Zaheer?' said Zaman. (direct to indirect)", "a": "Zaman asked Zaheer what time the match would start."}, {"q": "The old woman asked, 'Where is the nearest hospital?' (direct to indirect)", "a": "The old woman asked where the nearest hospital was."}, {"q": "The climber said, 'How quickly can we climb this hill?' (direct to indirect)", "a": "The climber asked how quickly they could climb that hill."}, {"q": "'What is the price of this article?' the customer asked the shopkeeper. (direct to indirect)", "a": "The customer asked the shopkeeper what the price of that article was."}, {"q": "'Why are you angry with me, Zahida?' said Sabiha. (direct to indirect)", "a": "Sabiha asked Zahida why she was angry with her."}, {"q": "The policeman said, 'Whose car is this?' (direct to indirect)", "a": "The policeman asked whose car that was."}, {"q": "The old man said, 'Children, who broke this windowpane?' (direct to indirect)", "a": "The old man asked the children who had broken that windowpane."}]}]}, {"num": "3", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "'What is your name?' (Faiz reports what the interviewer asked him.)", "a": "The interviewer asked me what my name was. (given as example in the book)"}, {"q": "'What is your qualification?' (Faiz reports what the interviewer asked him.)", "a": "She asked me what my qualification was."}, {"q": "'Do you know how to type?' (Faiz reports what the interviewer asked him.)", "a": "She asked me if I knew how to type."}, {"q": "'Can you use the computer?' (Faiz reports what the interviewer asked him.)", "a": "She asked me if I could use the computer."}, {"q": "'How good is your English?' (Faiz reports what the interviewer asked him.)", "a": "She asked me how good my English was."}, {"q": "'Have you worked anywhere else before?' (Faiz reports what the interviewer asked him.)", "a": "She asked me if I had worked anywhere else before."}, {"q": "'Why do you want to work in this factory?' (Faiz reports what the interviewer asked him.)", "a": "She asked me why I wanted to work in that factory."}, {"q": "'Where do you live?' (Faiz reports what the interviewer asked him.)", "a": "She asked me where I lived."}, {"q": "'How far is this factory from your house?' (Faiz reports what the interviewer asked him.)", "a": "She asked me how far that factory was from my house."}, {"q": "'Is there any question that you want to ask?' (Faiz reports what the interviewer asked him.)", "a": "She asked me if there was any question that I wanted to ask."}]}]}, {"num": "4", "name": "Exercise 4", "exercises": [{"label": "Exercise 4", "items": [{"q": "The teacher said to the students, 'Do not talk during the assembly.'", "a": "The teacher told the students not to talk during the assembly."}, {"q": "Mother said to her son, 'Work hard or else you will fail.'", "a": "Mother told her son to work hard or else he would fail."}, {"q": "The guard said to us, 'Stand in the queue and wait for your turn.'", "a": "The guard told us to stand in the queue and wait for our turn."}, {"q": "She said to her maid, 'Bring me a glass of water.'", "a": "She told her maid to bring her a glass of water."}, {"q": "The officer said to the peon, 'Let the visitor come in.'", "a": "The officer told the peon to let the visitor come in."}, {"q": "'Stay indoors during the storm,' the government authorities advised the people.", "a": "The government authorities advised the people to stay indoors during the storm."}]}]}, {"num": "5", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "'Try to speak gently when talking to old people,' the manager said to his staff.", "a": "The manager asked his staff to try to speak gently when talking to old people."}, {"q": "'Please turn out the lights, team, when you leave the room,' said the organizer.", "a": "The organizer requested the team to turn out the lights when they left the room."}, {"q": "'Give me a glass of water, Yusuf,' said grandfather.", "a": "Grandfather asked Yusuf to give him a glass of water."}, {"q": "'Sana, please put this plate on the table,' said Mrs. Sultan.", "a": "Mrs. Sultan requested Sana to put the plate on the table."}, {"q": "'Make sure that the children are in bed by eight o'clock,' said father.", "a": "Father told us to make sure that the children were in bed by eight o'clock."}, {"q": "The doctor said to the patient, 'Take your medicines on time.'", "a": "The doctor told the patient to take his medicines on time."}]}]}, {"num": "6", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "'Go away and never come back again,' said his boss.", "a": "His boss told him to go away and never come back again."}, {"q": "The principal said to the naughty student, 'Come after school hours.'", "a": "The principal told the naughty student to come after school hours."}, {"q": "'Please be seated,' said the announcer.", "a": "The announcer requested the audience to be seated."}, {"q": "'Never say no when someone asks for help,' the preacher said in his speech.", "a": "The preacher advised in his speech never to say no when someone asks for help."}, {"q": "'Be quiet, please, children,' said the mother.", "a": "The mother requested the children to be quiet."}, {"q": "'Aunt Sakina, please tell me where to find the keys,' said Maqbool.", "a": "Maqbool requested Aunt Sakina to tell him where to find the keys."}, {"q": "'Please shut the window,' said the little girl to her sister.", "a": "The little girl requested her sister to shut the window."}, {"q": "'Water the plants before you go,' said my father to the gardener.", "a": "My father told the gardener to water the plants before he went."}, {"q": "'Soldiers, march quickly to the exit,' said the commander.", "a": "The commander ordered the soldiers to march quickly to the exit."}, {"q": "The clerk said to the man, 'Do not disturb me.'", "a": "The clerk told the man not to disturb him."}]}]}], "words": [{"w": "direct speech", "sd": "سڌو ڪلام", "syn": "the exact words of the speaker inside quotation marks"}, {"w": "indirect speech", "sd": "اڻ سڌو ڪلام", "syn": "reporting what the speaker said, without quotation marks"}, {"w": "reporting verb", "sd": "بيان ڪرڻ وارو فعل", "syn": "a verb like said or told that reports speech"}]}, {"cls": "x", "unit": 13, "title": "Prepositions", "display": "Prepositions", "reading": "Secondary Stage English Book Two, Unit 7, Language Practice", "lesson": [{"t": "h", "x": "Prepositions"}, {"t": "p", "x": "A preposition is a word that shows the relation of a noun or pronoun to another word in the sentence. It shows place, time, direction or cause."}, {"t": "def", "x": "A preposition is a word like in, on, at, by, with, from, to, across, under, over, through, behind, between, among, during, before, after, about, against, without. It shows place, time, direction or cause."}, {"t": "h", "x": "Rule 1. Prepositions show place"}, {"t": "rule", "x": "Use in, on, at, under, over, behind, between, among, across, through, by, near to show where a thing is."}, {"t": "ex", "x": "Let's go for a walk across the river. Be careful when you walk across the street. The book is on the table. The cat is under the chair."}, {"t": "h", "x": "Rule 2. Prepositions show time"}, {"t": "rule", "x": "Use in, on, at, before, after, during, since, for, by to show when something happens."}, {"t": "ex", "x": "I was born in 2015. The school opens at 8 o'clock. We have a test on Monday. He came before lunch."}, {"t": "h", "x": "Rule 3. Prepositions show direction and movement"}, {"t": "rule", "x": "Use to, from, towards, into, out of, up, down, across, through, along to show direction and movement."}, {"t": "ex", "x": "He went to school. She came from Karachi. The river flows across the plain. They walked through the forest."}, {"t": "h", "x": "Rule 4. Prepositions show cause and reason"}, {"t": "rule", "x": "Use because of, due to, for, with, by to show the cause or reason."}, {"t": "ex", "x": "He can't perform any more because of his failing health. She was late because of the rain. He succeeded by hard work."}, {"t": "rl", "x": "At school, the book is on my desk. I walk across the ground. The teacher stands in front of the class."}, {"t": "rl", "x": "At home, my mother is in the kitchen. The cat is under the table. I go to school by bus."}, {"t": "rl", "x": "In the market, the shop is near the mosque. The fruit is in the basket. I walk through the market."}, {"t": "note", "x": "Do not use a preposition at the end of a sentence if you can avoid it. Say 'Who are you talking to?' only in spoken English."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "Let's go for a walk ______ (across/under/by) the river.", "a": "across — Let's go for a walk across the river."}, {"q": "I'm going ______ (to/past/around) the shop to buy some grocery.", "a": "to — I'm going to the shop to buy some grocery."}, {"q": "We sailed ______ (over/under/around) the bay today.", "a": "around — We sailed around the bay today."}, {"q": "Let's walk ______ (under/over/through) the forest.", "a": "through — Let's walk through the forest."}, {"q": "I'm going ______ (over/into/to) Paris in May.", "a": "to — I'm going to Paris in May."}, {"q": "We walked all ______ (around/under/to) the city centre but couldn't find the store.", "a": "around — We walked all around the city centre but couldn't find the store."}, {"q": "He put the open book ______ (at/on/in) the desk and asked the child to read.", "a": "on — He put the open book on the desk and asked the child to read."}, {"q": "The lion walked in a circle ______ (across/around/into) the baby giraffe before attacking it.", "a": "around — The lion walked in a circle around the baby giraffe before attacking it."}, {"q": "The train passed ______ (onto/into/through) nine tunnels on the way to Peshawar.", "a": "through — The train passed through nine tunnels on the way to Peshawar."}, {"q": "His dog is always trying to escape ______ (from/on/past) the backyard.", "a": "from — His dog is always trying to escape from the backyard."}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "Be careful when you walk ______ the street. You may encounter stray dogs there. a) Through b) above c) across d) up", "a": "c) across"}, {"q": "The car is going ______ the tunnel to reach the station. a) Around b) below c) at d) through", "a": "d) through"}, {"q": "A flock of birds is flying ______ the trees under the blue sky. a) over b) through c) onto d) on", "a": "a) over"}, {"q": "She walked ______ the kitchen and put her packages on the table. a) in b) into c) onto d) on", "a": "b) into"}, {"q": "River Kunhar flows ______ the lake. a) towards b) over c) up d) on", "a": "a) towards"}, {"q": "While waiting for my train, I took a walk ______ the station. a) on b) around c) onto d) in", "a": "b) around"}, {"q": "A formation of twelve airplanes flew ______ our houses. a) up b) down c) over d) past", "a": "c) over"}, {"q": "The door was locked, so I shoved the letter ______ the door. a) Around b) under c) on d) into", "a": "b) under"}, {"q": "The poachers go ______ the forest to hunt animals for their hide. a) on b) through c) in d) over", "a": "b) through"}, {"q": "I slipped as I stepped ______ the platform. a) into b) onto c) around d) across", "a": "b) onto"}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "He can't perform any more ______ his failing health.", "a": "due to — He can't perform any more due to his failing health."}, {"q": "The villagers had to carry pails of water ______ their work in the fields.", "a": "in addition to — The villagers had to carry pails of water in addition to their work in the fields."}, {"q": "Sameer was never ______ his parents going to the city.", "a": "away from — Sameer was never away from his parents going to the city."}, {"q": "This theory is wrong ______ his philosophy.", "a": "according to — This theory is wrong according to his philosophy."}, {"q": "The match was delayed ______ rain.", "a": "due to — The match was delayed due to rain."}, {"q": "This dog has been sitting ______ me for one hour.", "a": "next to — This dog has been sitting next to me for one hour."}, {"q": "I gave him a new book ______ the one I lost.", "a": "in return for — I gave him a new book in return for the one I lost."}, {"q": "We will inform you later, ______ the situation.", "a": "as to — We will inform you later, as to the situation."}, {"q": "The van stopped ______ the hospital.", "a": "close to — The van stopped close to the hospital."}, {"q": "You will have to leave your position ______ any change in the plan.", "a": "in case of — You will have to leave your position in case of any change in the plan."}]}]}], "words": [{"w": "preposition", "sd": "حرف جر", "syn": "a word that shows the relation of a noun or pronoun to another word"}, {"w": "place", "sd": "جاءِ", "syn": "where a thing is"}, {"w": "direction", "sd": "رخ", "syn": "the way a thing moves"}]}, {"cls": "x", "unit": 14, "title": "Conditionals", "display": "Conditionals", "reading": "Secondary Stage English Book Two, Unit 7, Language Practice", "lesson": [{"t": "h", "x": "Conditionals"}, {"t": "p", "x": "A conditional sentence has two parts: the 'if' part (the condition) and the result part. There are three main kinds: first, second and third conditional."}, {"t": "def", "x": "A conditional sentence talks about a condition and its result. First conditional: If + present simple, will + verb. Second conditional: If + past simple, would + verb."}, {"t": "h", "x": "Rule 1. First conditional: If + present simple, will + verb"}, {"t": "rule", "x": "In the first conditional, the 'if' part uses the present simple and the result part uses 'will' with the verb."}, {"t": "ex", "x": "If you wear dark glasses, you will protect your eyes. If the flight arrives on time, my boss will come to the meeting. We will destroy all our wildlife if we are not careful."}, {"t": "h", "x": "Rule 2. Second conditional: If + past simple, would + verb"}, {"t": "rule", "x": "In the second conditional, the 'if' part uses the past simple and the result part uses 'would' with the verb."}, {"t": "ex", "x": "If I had wings, I would fly. If I were rich, I would help the poor. Reporter: What if you had lost? Sheeba: If I had lost, I would have tried again."}, {"t": "h", "x": "Rule 3. The 'if' part can come first or second"}, {"t": "rule", "x": "The 'if' clause can come first or second. Use a comma when it comes first."}, {"t": "ex", "x": "If you wear dark glasses, you will protect your eyes. You will protect your eyes if you wear dark glasses."}, {"t": "h", "x": "Rule 4. Do not use 'will' or 'would' in the 'if' part"}, {"t": "rule", "x": "Do not use 'will' or 'would' in the 'if' part of a conditional sentence."}, {"t": "ex", "x": "If you wear dark glasses, you will protect your eyes. (Not: If you will wear dark glasses...)"}, {"t": "rl", "x": "At school, if I work hard, I will pass my exams. If I had a computer, I would learn many new things."}, {"t": "rl", "x": "At home, if my mother cooks biryani, I will eat two plates. If it rains, we will stay at home."}, {"t": "rl", "x": "On the cricket ground, if Ali bats well, we will win the match. If it rained, we would stop playing."}, {"t": "note", "x": "The first conditional is about a real future result. The second conditional is about an imaginary situation."}], "sections": [{"num": "1", "name": "Exercise 5", "exercises": [{"label": "Exercise 5", "items": [{"q": "We ______ all our wildlife if we ______ not careful. (destroy/be)", "a": "We will destroy all our wildlife if we are not careful."}, {"q": "If we ______ all sorts of chemicals into rivers, we ______ them. (dump/pollute)", "a": "If we dump all sorts of chemicals into rivers, we will pollute them."}, {"q": "If we ______ trees at the present speed, we ______ our oxygen supply. (cut/endanger)", "a": "If we cut trees at the present speed, we will endanger our oxygen supply."}, {"q": "If the global temperature ______, the sea levels ______. (increase/rise)", "a": "If the global temperature increases, the sea levels will rise."}, {"q": "We'll ______ our own existence if we ______ waste at the present rate. (threaten/produce)", "a": "We'll threaten our own existence if we produce waste at the present rate."}, {"q": "The traffic flow ______ better if everyone ______ the traffic rules. (be/follow)", "a": "The traffic flow will be better if everyone follows the traffic rules."}, {"q": "If I ______ you some of the chocolates, I ______ very few left for the party. (give/have)", "a": "If I give you some of the chocolates, I will have very few left for the party."}, {"q": "You ______ better marks next time if you ______ less time on video games. (get/spend)", "a": "You will get better marks next time if you spend less time on video games."}, {"q": "If you ______ so loudly during the match you ______ our neighbours. (shout/disturb)", "a": "If you shout so loudly during the match you will disturb our neighbours."}, {"q": "We ______ the Eiffel Tower if we ______ to Paris. (visit/go)", "a": "We will visit the Eiffel Tower if we go to Paris."}]}]}, {"num": "2", "name": "Exercise 6", "exercises": [{"label": "Exercise 6", "items": [{"q": "If you ______ dark glasses, you ______ your eyes. (wear/protect)", "a": "If you wore dark glasses, you would protect your eyes."}, {"q": "It ______ impossible to enter the building if the porter ______ us. (be/stop)", "a": "It would be impossible to enter the building if the porter stopped us."}, {"q": "I ______ this work for you if time ______. (do/permit)", "a": "I would do this work for you if time permitted."}, {"q": "If I ______ a lottery I ______ a new computer. (win/buy)", "a": "If I won a lottery I would buy a new computer."}, {"q": "He ______ leave if he ______ cold. (take/catch)", "a": "He would take leave if he caught cold."}, {"q": "If the police ______ hard enough they ______ the thief to prison. (try/send)", "a": "If the police tried hard enough they would send the thief to prison."}, {"q": "My friend ______ you a concession if you ______ the oven from him. (get/purchase)", "a": "My friend would get you a concession if you purchased the oven from him."}, {"q": "If I ______ you, I ______ for the job. (be/apply)", "a": "If I were you, I would apply for the job."}, {"q": "If the doctor ______ him he ______ to work. (allow/go)", "a": "If the doctor allowed him he would go to work."}, {"q": "It ______ me a lot of pleasure if they ______ the gift. (give/accept)", "a": "It would give me a lot of pleasure if they accepted the gift."}]}]}, {"num": "3", "name": "Exercise 7", "exercises": [{"label": "Exercise 7", "items": [{"q": "If the flight ______ on time, my boss ______ to the meeting. (arrive/come)", "a": "If the flight had arrived on time, my boss would have come to the meeting."}, {"q": "They ______ all the food if I ______ it on the table. (eat/keep)", "a": "They would have eaten all the food if I had kept it on the table."}, {"q": "If the driver ______ at the turning, the old woman ______ the road easily. (stop/cross)", "a": "If the driver had stopped at the turning, the old woman would have crossed the road easily."}, {"q": "If you ______ your umbrella, you ______ getting wet in the rain. (take/avoid)", "a": "If you had taken your umbrella, you would have avoided getting wet in the rain."}, {"q": "I ______ the storm if I ______ more cautious. (escape/be)", "a": "I would have escaped the storm if I had been more cautious."}, {"q": "The people ______ if they ______ that there was no food. (leave/know)", "a": "The people would have left if they had known that there was no food."}, {"q": "The child ______ the punishment if the scars ______. (forget/disappear)", "a": "The child would have forgotten the punishment if the scars had disappeared."}, {"q": "If their new player ______ as expected they ______ the match. (perform/win)", "a": "If their new player had performed as expected they would have won the match."}, {"q": "There ______ no fight if the police ______ in time. (be/arrive)", "a": "There would have been no fight if the police had arrived in time."}, {"q": "If he ______ the question the teacher ______ him some marks. (attempt/give)", "a": "If he had attempted the question the teacher would have given him some marks."}]}]}, {"num": "4", "name": "Exercise 8", "exercises": [{"label": "Exercise 8", "items": [{"q": "Reporter: What if you had lost? Sheeba: If I ______, I ______.", "a": "Sheeba: If I had lost, I would have cried."}, {"q": "Reporter: How would your parents have felt? Sheeba: If I ______, my parents ______ very disappointed.", "a": "Sheeba: If I had failed, my parents would have been very disappointed."}, {"q": "Reporter: What about your friends? Sheeba: Some ______ fun of me while a few ______ me to try again.", "a": "Sheeba: Some would have made fun of me while a few would have encouraged me to try again."}, {"q": "Reporter: What could you have done differently to make sure you won? Sheeba: I ______ a different song if I ______ about it.", "a": "Sheeba: I would have selected a different song if I had thought about it."}, {"q": "Reporter: Anything else that you would like to say? Sheeba: My self-esteem ______ badly affected if I ______ badly.", "a": "Sheeba: My self-esteem would have been badly affected if I had performed badly."}]}]}], "words": [{"w": "conditional sentence", "sd": "شرطي جملو", "syn": "a sentence with an 'if' part and a result part"}, {"w": "first conditional", "sd": "پھرين شرطي جملو", "syn": "If + present simple, will + verb"}, {"w": "second conditional", "sd": "ٻيو شرطي جملو", "syn": "If + past simple, would + verb"}]}, {"cls": "x", "unit": 15, "title": "Relative Pronouns", "display": "Relative Pronouns", "reading": "Secondary Stage English Book Two, Unit 8, Language Practice", "lesson": [{"t": "h", "x": "Relative Pronouns"}, {"t": "p", "x": "A relative pronoun joins two sentences. It stands for a noun and begins a clause that tells us more about that noun."}, {"t": "def", "x": "A relative pronoun (who, which, that, whose, whom) joins two sentences. It tells us more about a noun."}, {"t": "h", "x": "Rule 1. Use 'who' for people"}, {"t": "rule", "x": "Use 'who' for people."}, {"t": "ex", "x": "The man who lives next door is my uncle. The boy who won the prize is my friend. The teacher who teaches us English is kind."}, {"t": "h", "x": "Rule 2. Use 'which' for things and animals"}, {"t": "rule", "x": "Use 'which' for things and animals."}, {"t": "ex", "x": "The festival which lasted all day ended with a banquet. The book which is on the table is mine. The dog which barks at night is ours."}, {"t": "h", "x": "Rule 3. Use 'that' for people, things and animals"}, {"t": "rule", "x": "Use 'that' for people, things and animals."}, {"t": "ex", "x": "A pencil is something that every student needs. They sold the house that they had bought last year. I know the maid that broke the new tray."}, {"t": "h", "x": "Rule 4. Use 'whose' to show ownership"}, {"t": "rule", "x": "Use 'whose' to show that something belongs to somebody."}, {"t": "ex", "x": "The boy whose book was lost is crying. The man whose car was stolen is sad. Shahid gave a long and tedious speech. He won the prize. (Shahid, whose speech was long and tedious, won the prize.)"}, {"t": "rl", "x": "At school, the teacher who teaches us English is kind. The book that I bought yesterday is very good."}, {"t": "rl", "x": "At home, my uncle who lives in Karachi visited us. The dog which barks at night is ours."}, {"t": "rl", "x": "In the market, the shopkeeper who sells fruit is my friend. The mangoes that I bought are sweet."}, {"t": "note", "x": "Do not use 'who' for a thing or 'which' for a person."}], "sections": [{"num": "1", "name": "Exercise 1", "exercises": [{"label": "Exercise 1", "items": [{"q": "The festival ______ lasted all day, ended with a banquet. a. that b. who c. which d. what", "a": "c) which"}, {"q": "I am looking for someone ______ can watch my dog while I go on vacation. a. which b. who c. whom d. that", "a": "b) who"}, {"q": "The police needed details ______ could help identify the robber. a. who b. whatever c. that d. what", "a": "c) that"}, {"q": "I'd like to take you to a café ______ serves excellent coffee. a. that b. what c. which d. who", "a": "a) that (which is also correct)"}, {"q": "This is the house ______ Jamil built. a. which b. where c. that d. whom", "a": "c) that"}, {"q": "I cannot say goodbye to one ______ personality I have always liked. a. whose b. that c. which d. whom", "a": "a) whose"}, {"q": "I saw the shoes ______ you bought last week on sale for less this week. a. where b. that c. who d. whom", "a": "b) that"}, {"q": "We met our friend ______ father passed away last month suddenly. a. whose b. who c. when d. that", "a": "a) whose"}, {"q": "This is the person ______ we met last week. a. where b. whom c. who d. that", "a": "b) whom"}, {"q": "I have a watch ______ is ten years old. a. whose b. whom c. whom d. which", "a": "d) which"}]}]}, {"num": "2", "name": "Exercise 2", "exercises": [{"label": "Exercise 2", "items": [{"q": "A pencil is something ______ every student needs.", "a": "that — A pencil is something that every student needs."}, {"q": "Pizza is a popular food ______ was first made in Italy.", "a": "which — Pizza is a popular food which was first made in Italy."}, {"q": "Mr. Liaquat ______ house is next to our house is an engineer.", "a": "whose — Mr. Liaquat whose house is next to our house is an engineer."}, {"q": "I bought a cell phone ______ has 5G internet access.", "a": "that — I bought a cell phone that has 5G internet access."}, {"q": "Mosquitoes are insects ______ like to bite people.", "a": "that — Mosquitoes are insects that like to bite people."}, {"q": "Albert Einstein was a scientist ______ made many important discoveries.", "a": "who — Albert Einstein was a scientist who made many important discoveries."}, {"q": "My uncle ______ we met last night helps us with our homework.", "a": "whom — My uncle whom we met last night helps us with our homework."}, {"q": "A helicopter is a machine ______ can fly.", "a": "that — A helicopter is a machine that can fly."}, {"q": "Shah Inayat Shaheed is a famous Sufi saint ______ has millions of followers.", "a": "who — Shah Inayat Shaheed is a famous Sufi saint who has millions of followers."}, {"q": "A blanket is something ______ people use in winter.", "a": "that — A blanket is something that people use in winter."}]}]}, {"num": "3", "name": "Exercise 3", "exercises": [{"label": "Exercise 3", "items": [{"q": "Shahid gave a long and tedious speech. He won the prize.", "a": "Shahid, who gave a long and tedious speech, won the prize."}, {"q": "A chain of stores wants to open new stores across the province. It does business all over Pakistan.", "a": "A chain of stores, which does business all over Pakistan, wants to open new stores across the province."}, {"q": "Social network sites will change business. They are trendy.", "a": "Social network sites, which are trendy, will change business."}, {"q": "Scientists are working on stem cells. Stem cells will revolutionize medicine.", "a": "Scientists are working on stem cells, which will revolutionize medicine."}, {"q": "Last week, Rizwan interviewed Sana. She is my neighbour.", "a": "Last week, Rizwan interviewed Sana, who is my neighbour."}, {"q": "Yesterday I met a talented man. He works in a circus.", "a": "Yesterday I met a talented man who works in a circus."}, {"q": "Bano signed autographs at tower records yesterday. She is a famous musician.", "a": "Bano, who is a famous musician, signed autographs at Tower Records yesterday."}, {"q": "John F. Kennedy was assassinated in 1963. He was the president of the USA.", "a": "John F. Kennedy, who was the president of the USA, was assassinated in 1963."}, {"q": "The prime minister will inaugurate a new hospital. It is on 6th street.", "a": "The prime minister will inaugurate a new hospital, which is on 6th street."}, {"q": "He sat on the wooden chair. The chair was broken.", "a": "He sat on the wooden chair, which was broken."}]}]}], "words": [{"w": "relative pronoun", "sd": "اضافي ضمير", "syn": "a pronoun like who, which or that that joins two sentences"}, {"w": "clause", "sd": "شق", "syn": "a part of a sentence with a subject and a verb"}]}]};
